INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ffaba97-f314-4143-9ae0-9fb299c59466', '贈友五首 二', '贈友五首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["銀生楚山曲，金生鄱谿濱。","南人棄農業，求之多苦辛。","披砂復鑿石，矻矻無冬春。","手足盡皴胝，愛利不愛身。","畬田既慵斫，稻田亦嬾耘。","相攜作游手，皆道求金銀。","畢竟金與銀，何殊泥與塵。","且非衣食物，不濟飢寒人。","棄本以趨末，日富而歲貧。","所以先聖王，棄藏不爲珍。","誰能反古風，待君秉國鈞。","捐金復抵璧，勿使勞生民。"]', '["銀生楚山曲，金生鄱谿濱。","南人棄農業，求之多苦辛。","披砂复鑿石，矻矻無冬春。","手足尽皴胝，愛利不愛身。","畬田既慵斫，稻田亦嬾耘。","相携作游手，皆道求金銀。","畢竟金與銀，何殊泥與塵。","且非衣食物，不濟飢寒人。","棄本以趨末，日富而歲貧。","所以先聖王，棄藏不爲珍。","誰能反古风，待君秉国鈞。","捐金复抵璧，勿使勞生民。"]', '诗', 'shi', '', NULL, '贈友五首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7004b4a-a7e9-4049-9fe5-24cbf7e1dd1f', '贈友五首 三', '贈友五首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["私家無錢爐，平地無銅山。","胡爲秋夏稅，歲歲輸銅錢。","錢力日已重，農力日已殫。","賤糶粟與麥，賤貿絲與緜。","歲暮衣食盡，焉得無飢寒。","吾聞國之初，有制垂不刊。","庸必算丁口，租必計桑田。","不求土所無，不強人所難。","量入以爲出，上足下亦安。","兵興一變法，兵息遂不還。","使我農桑人，顦顇畎畝間。","誰能革此弊，待君秉利權。","復彼租庸法，令如貞觀年。"]', '["私家無錢爐，平地無銅山。","胡爲秋夏稅，歲歲輸銅錢。","錢力日已重，農力日已殫。","賤糶粟與麦，賤貿絲與緜。","歲暮衣食尽，焉得無飢寒。","吾闻国之初，有制垂不刊。","庸必算丁口，租必計桑田。","不求土所無，不強人所难。","量入以爲出，上足下亦安。","兵兴一变法，兵息遂不還。","使我農桑人，顦顇畎畝间。","誰能革此弊，待君秉利權。","复彼租庸法，令如貞观年。"]', '诗', 'shi', '', NULL, '贈友五首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('281913e9-6157-4bac-974c-50b53d91b471', '贈友五首 四', '贈友五首 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["京師四方則，王化之本根。","長吏久於政，然後風教敦。","如何尹京者，遷次不逡巡。","請君屈指數，十年十五人。","科條日相矯，吏力亦已勤。","寬猛政不一，民心安得淳。","九州雍爲首，羣牧之所遵。","天下率如此，何以安吾民。","誰能變此法，待君贊彌綸。","慎擇循良吏，令其長子孫。"]', '["京師四方則，王化之本根。","长吏久於政，然後风教敦。","如何尹京者，遷次不逡巡。","請君屈指數，十年十五人。","科條日相矯，吏力亦已勤。","寬猛政不一，民心安得淳。","九州雍爲首，羣牧之所遵。","天下率如此，何以安吾民。","誰能变此法，待君贊彌綸。","慎擇循良吏，令其长子孫。"]', '诗', 'shi', '', NULL, '贈友五首 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bb9559d-27eb-4a42-96c2-c8aa8d5e7126', '贈友五首 五', '贈友五首 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三十男有室，二十女有歸。","近代多離亂，婚姻多過期。","嫁娶既不早，生育常苦遲。","兒女未成人，父母已衰羸。","凡人貴達日，多在長大時。","欲報親不待，孝心無所施。","哀哉三牲養，少得及庭闈。","惜哉萬鍾粟，多用飽妻兒。","誰能正婚禮，待君張國維。","庶使孝子心，皆無風樹悲。"]', '["三十男有室，二十女有归。","近代多離亂，婚姻多過期。","嫁娶既不早，生育常苦遲。","兒女未成人，父母已衰羸。","凡人貴達日，多在长大时。","欲報親不待，孝心無所施。","哀哉三牲養，少得及庭闈。","惜哉万鍾粟，多用飽妻兒。","誰能正婚禮，待君張国維。","庶使孝子心，皆無风樹悲。"]', '诗', 'shi', '', NULL, '贈友五首 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('879362e7-25be-4db1-9132-fbe542308ad4', '寓意詩五首 一', '寓意诗五首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["豫樟生深山，七年而後知。","挺高二百尺，本末皆十圍。","天子建明堂，此材獨中規。","匠人執斤墨，采度將有期。","孟冬草木枯，烈火燎山陂。","疾風吹猛燄，從根燒到枝。","養材三十年，方成棟梁姿。","一朝爲灰燼，柯葉無孑遺。","地雖生爾材，天不與爾時。","不如糞土英，猶有人掇之。","已矣勿重陳，重陳令人悲。","不悲焚燒苦，但悲采用遲。"]', '["豫樟生深山，七年而後知。","挺高二百尺，本末皆十圍。","天子建明堂，此材独中規。","匠人執斤墨，采度將有期。","孟冬草木枯，烈火燎山陂。","疾风吹猛燄，從根燒到枝。","養材三十年，方成棟梁姿。","一朝爲灰燼，柯葉無孑遺。","地雖生爾材，天不與爾时。","不如糞土英，猶有人掇之。","已矣勿重陳，重陳令人悲。","不悲焚燒苦，但悲采用遲。"]', '诗', 'shi', '', NULL, '寓意詩五首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea7d6f3a-4f1d-4b58-96d4-1144ce3b2cf3', '寓意詩五首 二', '寓意诗五首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["赫赫京內史，炎炎中書郎。","昨傳徵拜日，恩賜頗殊常。","貂冠水蒼玉，紫綬黃金章。","佩服身未暖，已聞竄遐荒。","親戚不得別，吞聲泣路旁。","賓客亦已散，門前雀羅張。","富貴來不久，倏如瓦溝霜。","權勢去尤速，瞥若石火光。","不如守貧賤，貧賤可久長。","傳語宦遊子，且來歸故鄉。"]', '["赫赫京內史，炎炎中书郎。","昨傳徵拜日，恩賜頗殊常。","貂冠水蒼玉，紫綬黄金章。","佩服身未暖，已闻竄遐荒。","親戚不得別，吞声泣路旁。","賓客亦已散，门前雀羅張。","富貴来不久，倏如瓦溝霜。","權勢去尤速，瞥若石火光。","不如守貧賤，貧賤可久长。","傳語宦游子，且来归故乡。"]', '诗', 'shi', '', NULL, '寓意詩五首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a76290c2-2b24-48b5-94c8-b79a7241bc9d', '寓意詩五首 三', '寓意诗五首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["促織不成章，提壺但聞聲。","嗟哉蟲與鳥，無實有虛名。","與君定交日，久要如弟兄。","何以示誠信，白水指爲盟。","雲雨一爲別，飛沈兩難幷。","君爲得風鵬，我爲失水鯨。","音信日已疎，恩分日已輕。","窮通尚如此，何況死與生。","乃知擇交難，須有知人明。","莫將山上松，結託水上萍。"]', '["促织不成章，提壺但闻声。","嗟哉蟲與鸟，無實有虛名。","與君定交日，久要如弟兄。","何以示誠信，白水指爲盟。","云雨一爲別，飞沈兩难幷。","君爲得风鵬，我爲失水鯨。","音信日已疎，恩分日已轻。","窮通尚如此，何況死與生。","乃知擇交难，須有知人明。","莫將山上松，結託水上萍。"]', '诗', 'shi', '', NULL, '寓意詩五首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30f3ac8e-0437-4266-8476-6d984757957f', '寓意詩五首 四', '寓意诗五首 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["翩翩兩玄鳥，本是同巢燕。","分飛來幾時，秋夏炎涼變。","一宿蓬篳廬，一栖明光殿。","偶因銜泥處，復得重相見。","彼矜杏梁貴，此嗟茅棟賤。","眼看秋社至，兩處俱難戀。","所託各暫時，胡爲相歎羨。"]', '["翩翩兩玄鸟，本是同巢燕。","分飞来幾时，秋夏炎涼变。","一宿蓬篳廬，一栖明光殿。","偶因銜泥处，复得重相见。","彼矜杏梁貴，此嗟茅棟賤。","眼看秋社至，兩处俱难戀。","所託各暫时，胡爲相歎羨。"]', '诗', 'shi', '', NULL, '寓意詩五首 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0415228f-3b68-4682-8da7-4ef9597f5700', '寓意詩五首 五', '寓意诗五首 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["婆娑園中樹，根株大合圍。","蠢爾樹間蟲，形質一何微。","孰謂蟲之微，蟲蠹已無期。","孰謂樹之大，花葉有衰時。","花衰夏未實，葉病秋先萎。","樹心半爲土，觀者安得知。","借問蟲何在，在身不在枝。","借問蟲何食，食心不食皮。","豈無啄木鳥，觜長將何爲。"]', '["婆娑园中樹，根株大合圍。","蠢爾樹间蟲，形質一何微。","孰謂蟲之微，蟲蠹已無期。","孰謂樹之大，花葉有衰时。","花衰夏未實，葉病秋先萎。","樹心半爲土，观者安得知。","借问蟲何在，在身不在枝。","借问蟲何食，食心不食皮。","豈無啄木鸟，觜长將何爲。"]', '诗', 'shi', '', NULL, '寓意詩五首 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f89aa5e5-a703-4956-8fa0-91a512364ee8', '讀史五首 一', '读史五首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["楚懷放靈均，國政亦荒淫。","彷徨未忍決，繞澤行悲吟。","漢文疑賈生，謫置湘之陰。","是時刑方措，此去難爲心。","士生一代間，誰不有浮沈。","良時真可惜，亂世何足欽。","乃知汨羅恨，未抵長沙深。"]', '["楚懷放靈均，国政亦荒淫。","彷徨未忍決，繞澤行悲吟。","漢文疑賈生，謫置湘之陰。","是时刑方措，此去难爲心。","士生一代间，誰不有浮沈。","良时真可惜，亂世何足欽。","乃知汨羅恨，未抵长沙深。"]', '诗', 'shi', '', NULL, '讀史五首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcf35dca-9704-4f15-8798-92bf36cf6886', '讀史五首 二', '读史五首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["禍患如棼絲，其來無端緒。","馬遷下蠶室，嵇康就囹圄。","抱冤志氣屈，忍恥形神沮。","當彼戮辱時，奮飛無翅羽。","商山有黃綺，潁川有巢許。","何不從之遊？超然離網罟。","山林少羈鞅，世路多艱阻。","寄謝伐檀人，慎勿嗟窮處。"]', '["禍患如棼絲，其来無端緒。","马遷下蠶室，嵇康就囹圄。","抱冤志氣屈，忍恥形神沮。","當彼戮辱时，奮飞無翅羽。","商山有黄綺，潁川有巢許。","何不從之游？超然離網罟。","山林少羈鞅，世路多艱阻。","寄謝伐檀人，慎勿嗟窮处。"]', '诗', 'shi', '', NULL, '讀史五首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d6e2206-6a10-4e9a-9c6f-650cc357e9ba', '讀史五首 三', '读史五首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["漢日大江軍，少爲乞食子。","秦時故列侯，老作鋤瓜士。","春華何暐曄，園中發桃李。","秋風忽蕭條，堂上生荆杞。","深谷變爲岸，桑田成海水。","勢去未須悲，時來何足喜。","寄言榮枯者，反復殊未已。"]', '["漢日大江軍，少爲乞食子。","秦时故列侯，老作鋤瓜士。","春华何暐曄，园中發桃李。","秋风忽蕭條，堂上生荆杞。","深谷变爲岸，桑田成海水。","勢去未須悲，时来何足喜。","寄言榮枯者，反复殊未已。"]', '诗', 'shi', '', NULL, '讀史五首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec58cff0-5958-4c6a-a487-dfa4900f96af', '讀史五首 四', '读史五首 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["含沙射人影，雖病人不知。","巧言搆人罪，至死人不疑。","掇蠭殺愛子，掩鼻戮寵姬。","弘恭陷蕭望，趙高謀李斯。","陰德既必報，陰禍豈虛施。","人事雖可罔，天道終難欺。","明則有刑辟，幽則有神祗。","苟免勿私喜，鬼得而誅之。"]', '["含沙射人影，雖病人不知。","巧言搆人罪，至死人不疑。","掇蠭殺愛子，掩鼻戮寵姬。","弘恭陷蕭望，趙高謀李斯。","陰德既必報，陰禍豈虛施。","人事雖可罔，天道終难欺。","明則有刑辟，幽則有神祗。","苟免勿私喜，鬼得而誅之。"]', '诗', 'shi', '', NULL, '讀史五首 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b6865e1-7c8f-48e5-b955-e8b76e183d5c', '讀史五首 五', '读史五首 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["季子顦顇時，婦見不下機。","買臣負薪日，妻亦棄如遺。","一朝黃金多，佩印衣錦歸。","去妻不敢視，婦嫂強依依。","富貴家人重，貧賤妻子欺。","奈何貧富間，可移親愛志。","遂使中人心，汲汲求富貴。","又令下人力，各競錐刀利。","隨分歸舍來，一取妻孥意。"]', '["季子顦顇时，婦见不下機。","買臣負薪日，妻亦棄如遺。","一朝黄金多，佩印衣錦归。","去妻不敢視，婦嫂強依依。","富貴家人重，貧賤妻子欺。","奈何貧富间，可移親愛志。","遂使中人心，汲汲求富貴。","又令下人力，各競錐刀利。","隨分归舍来，一取妻孥意。"]', '诗', 'shi', '', NULL, '讀史五首 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7ba119d-0662-4bce-b1a4-a24f1320dcf3', '和荅詩十首 和思歸樂', '和荅诗十首 和思归乐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["山中不栖鳥，夜半聲嚶嚶。","似道思歸樂，行人掩泣聽。","皆疑此山路，遷客多南征。","憂憤氣不散，結化爲精靈。","我謂此山鳥，本不因人生。","人心自懷土，想作思歸鳴。","孟嘗平居時，娛耳琴泠泠。","雍門一言感，未奏淚霑纓。","魏武銅雀妓，日與歡樂幷。","一旦西陵望，欲歌先涕零。","峽猨亦何意，隴水復何情。","爲入愁人耳，皆爲腸斷聲。","請看元侍御，亦宿此郵亭。","因聽思歸鳥，神氣獨安寧。","問君何以然，道勝心自平。","雖爲南遷客，如在長安城。","云得此道來，何慮復何營。","窮達有前定，憂喜無交爭。","所以事君日，持憲立大庭。","雖有迴天力，撓之終不傾。","況始三十餘，年少有直名。","心中志氣大，眼前爵祿輕。","君恩若雨露，君威若雷霆。","退不苟免難，進不曲求榮。","在火辨玉性，經霜識松貞。","展禽任三黜，靈均長獨醒。","獲戾自東洛，貶官向南荆。","再拜辭闕下，長揖別公卿。","荆州又非遠，驛路半月程。","漢水照天碧，楚山插雲青。","江陵橘似珠，宜城酒如餳。","誰謂譴謫去，未妨遊賞行。","人生百歲內，天地暫寓形。","太倉一稊米，大海一浮萍。","身委逍遙篇，心付頭陀經。","尚達死生觀，寧爲寵辱驚。","中懷苟有主，外物安能縈。","任意思歸樂，聲聲啼到明。"]', '["山中不栖鸟，夜半声嚶嚶。","似道思归乐，行人掩泣听。","皆疑此山路，遷客多南征。","憂憤氣不散，結化爲精靈。","我謂此山鸟，本不因人生。","人心自懷土，想作思归鳴。","孟嘗平居时，娛耳琴泠泠。","雍门一言感，未奏泪霑纓。","魏武銅雀妓，日與歡乐幷。","一旦西陵望，欲歌先涕零。","峽猨亦何意，隴水复何情。","爲入愁人耳，皆爲腸斷声。","請看元侍御，亦宿此郵亭。","因听思归鸟，神氣独安寧。","问君何以然，道勝心自平。","雖爲南遷客，如在长安城。","云得此道来，何慮复何營。","窮達有前定，憂喜無交爭。","所以事君日，持憲立大庭。","雖有迴天力，撓之終不傾。","況始三十餘，年少有直名。","心中志氣大，眼前爵祿轻。","君恩若雨露，君威若雷霆。","退不苟免难，進不曲求榮。","在火辨玉性，經霜識松貞。","展禽任三黜，靈均长独醒。","獲戾自东洛，貶官向南荆。","再拜辞闕下，长揖別公卿。","荆州又非远，驛路半月程。","漢水照天碧，楚山插云青。","江陵橘似珠，宜城酒如餳。","誰謂譴謫去，未妨游賞行。","人生百歲內，天地暫寓形。","太倉一稊米，大海一浮萍。","身委逍遙篇，心付头陀經。","尚達死生观，寧爲寵辱驚。","中懷苟有主，外物安能縈。","任意思归乐，声声啼到明。"]', '诗', 'shi', '', NULL, '和荅詩十首 和思歸樂 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51a33228-723f-466c-821e-6bf6ffabb8c9', '和荅詩十首 和陽城驛', '和荅诗十首 和陽城驛', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["商山陽城驛，中有歎者誰。","云是元監察，江陵謫去時。","忽見此驛名，良久涕欲垂。","何故陽道州，名姓同於斯。","憐君一寸心，寵辱誓不移。","疾惡若巷伯，好賢如緇衣。","沈吟不能去，意者欲改爲。","改爲避賢驛，大署於門楣。","荆人愛羊祜，戶曹改爲辭。","一字不忍道，況兼姓呼之。","因題八百言，言直文甚奇。","詩成寄與我，鏘若金和絲。","上言陽公行，友悌無等夷。","骨肉同衾裯，至死不相離。","次言陽公迹，夏邑始棲遲。","鄉人化其風，少長皆孝慈。","次言陽公道，終日對酒巵。","兄弟笑相顧，醉貌紅怡怡。","次言陽公節，謇謇居諫司。","誓心除國蠹，決死犯天威。","終言陽公命，左遷天一涯。","道州炎瘴地，身不得生歸。","一一皆實錄，事事無孑遺。","凡是爲善者，聞之惻然悲。","道州既已矣，往者不可追。","何世無其人，來者亦可思。","願以君子文，告彼大樂師。","附於雅歌末，奏之白玉墀。","天子聞此章，教化如法施。","直諫從如流，佞臣惡如疵。","宰相聞此章，政柄端正持。","進賢不知倦，去邪勿復疑。","憲臣聞此章，不敢懷依違。","諫官聞此章，不忍縱詭隨。","然後告史氏，舊史有前規。","若作陽公傳，欲令後世知。","不勞敘世家，不用費文辭。","但於國史上，全錄元稹詩。"]', '["商山陽城驛，中有歎者誰。","云是元監察，江陵謫去时。","忽见此驛名，良久涕欲垂。","何故陽道州，名姓同於斯。","怜君一寸心，寵辱誓不移。","疾惡若巷伯，好賢如緇衣。","沈吟不能去，意者欲改爲。","改爲避賢驛，大署於门楣。","荆人愛羊祜，戶曹改爲辞。","一字不忍道，況兼姓呼之。","因題八百言，言直文甚奇。","诗成寄與我，鏘若金和絲。","上言陽公行，友悌無等夷。","骨肉同衾裯，至死不相離。","次言陽公迹，夏邑始棲遲。","乡人化其风，少长皆孝慈。","次言陽公道，終日对酒巵。","兄弟笑相顧，醉貌紅怡怡。","次言陽公節，謇謇居諫司。","誓心除国蠹，決死犯天威。","終言陽公命，左遷天一涯。","道州炎瘴地，身不得生归。","一一皆實錄，事事無孑遺。","凡是爲善者，闻之惻然悲。","道州既已矣，往者不可追。","何世無其人，来者亦可思。","願以君子文，告彼大乐師。","附於雅歌末，奏之白玉墀。","天子闻此章，教化如法施。","直諫從如流，佞臣惡如疵。","宰相闻此章，政柄端正持。","進賢不知倦，去邪勿复疑。","憲臣闻此章，不敢懷依違。","諫官闻此章，不忍縱詭隨。","然後告史氏，旧史有前規。","若作陽公傳，欲令後世知。","不勞敘世家，不用費文辞。","但於国史上，全錄元稹诗。"]', '诗', 'shi', '', NULL, '和荅詩十首 和陽城驛 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1255551e-a812-4e50-81a3-ecc29364273e', '和荅詩十首 荅桐花', '和荅诗十首 荅桐花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["山木多蓊鬱，茲桐獨亭亭。","葉重碧雲片，花簇紫霞英。","是時三月天，春暖山雨晴。","夜色向月淺，闇香隨風輕。","行者多商賈，居者悉黎氓。","無人解賞愛，有客獨屏營。","手攀花枝立，足蹋花影行。","生憐不得所，死欲揚其聲。","截爲天子琴，刻作古人形。","云待我成器，薦之於穆清。","誠是君子心，恐非草木情。","胡爲愛其華，而反傷其生。","老龜被刳腸，不如無神靈。","雄雞自斷尾，不願爲犧牲。","況此好顏色，花紫葉青青。","宜遂天地性，忍加刀斧刑。","我思五丁力，拔入九重城。","當君正殿栽，花葉生光晶。","上對月中桂，下覆階前蓂。","汎拂香爐煙，隱映斧藻屏。","爲君布綠陰，當暑蔭軒楹。","沈沈綠滿地，桃李不敢爭。","爲君發清韻，風來如叩瓊。","泠泠聲滿耳，鄭衛不足聽。","受君封植力，不獨吐芬馨。","助君行春令，開花應晴明。","受君雨露恩，不獨含芳榮。","戒君無戲言，翦葉封弟兄。","受君歲月功，不獨資生成。","爲君長高枝，鳳皇上頭鳴。","一鳴君萬歲，壽如山不傾。","再鳴萬人泰，泰階爲之平。","如何有此用，幽滯在巖坰。","歲月不爾駐，孤芳坐凋零。","請向桐枝上，爲余題姓名。","待余有勢力，移爾獻丹庭。"]', '["山木多蓊鬱，茲桐独亭亭。","葉重碧云片，花簇紫霞英。","是时三月天，春暖山雨晴。","夜色向月淺，闇香隨风轻。","行者多商賈，居者悉黎氓。","無人解賞愛，有客独屏營。","手攀花枝立，足蹋花影行。","生怜不得所，死欲揚其声。","截爲天子琴，刻作古人形。","云待我成器，薦之於穆清。","誠是君子心，恐非草木情。","胡爲愛其华，而反傷其生。","老龟被刳腸，不如無神靈。","雄雞自斷尾，不願爲犧牲。","況此好顏色，花紫葉青青。","宜遂天地性，忍加刀斧刑。","我思五丁力，拔入九重城。","當君正殿栽，花葉生光晶。","上对月中桂，下覆階前蓂。","汎拂香爐煙，隐映斧藻屏。","爲君布綠陰，當暑蔭軒楹。","沈沈綠满地，桃李不敢爭。","爲君發清韻，风来如叩瓊。","泠泠声满耳，鄭衛不足听。","受君封植力，不独吐芬馨。","助君行春令，开花應晴明。","受君雨露恩，不独含芳榮。","戒君無戲言，翦葉封弟兄。","受君歲月功，不独資生成。","爲君长高枝，鳳皇上头鳴。","一鳴君万歲，壽如山不傾。","再鳴万人泰，泰階爲之平。","如何有此用，幽滯在巖坰。","歲月不爾駐，孤芳坐凋零。","請向桐枝上，爲余題姓名。","待余有勢力，移爾獻丹庭。"]', '诗', 'shi', '', NULL, '和荅詩十首 荅桐花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd55ca70-3513-44dc-9aa1-83ac0c333964', '和荅詩十首 和大觜烏', '和荅诗十首 和大觜烏', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["烏者種有二，名同性不同。","觜小者慈孝，觜大者貪庸。","觜大命又長，生來十餘冬。","物老顏色變，頭毛白茸茸。","飛來庭樹上，初但驚兒童。","老巫生奸計，與烏意潛通。","云此非凡鳥，遙見起敬恭。","千歲乃一出，喜賀主人翁。","祥瑞來白日，神聖占知風。","陰作北斗使，能爲人吉凶。","此烏所止家，家產日夜豐。","上以致壽考，下可宜田農。","主人富家子，身老心童蒙。","隨巫拜復祝，婦姑亦相從。","殺雞薦其肉，敬若禋六宗。","烏喜張大觜，飛接在虛空。","烏既飽羶腥，巫亦饗甘濃。","烏巫互相利，不復兩西東。","日日營巢窟，稍稍近房櫳。","雖生八九子，誰辨其雌雄。","羣雛又成長，衆觜逞殘兇。","探巢吞燕卵，入蔟啄蠶蟲。","豈無乘秋隼，羈絆委高墉。","但食烏殘肉，無施搏擊功。","亦有能言鸚，翅碧觜距紅。","暫曾說烏罪，囚閉在深籠。","青青窗前柳，鬱鬱井上桐。","貪烏占栖息，慈烏獨不容。","慈鳥爾奚爲，來往何憧憧。","曉去先晨鼓，暮歸後昏鐘。","辛苦塵土間，飛啄禾黍叢。","得食將哺母，飢腸不自充。","主人憎慈烏，命子削彈弓。","弦續會稽竹，丸鑄荆山銅。","慈烏求母食，飛下爾庭中。","數粒未入口，一丸已中胸。","仰天號一聲，似欲訴蒼穹。","反哺日未足，非是惜微躬。","誰能持此冤，一爲問化工。","胡然大觜烏，竟得天年終。"]', '["烏者種有二，名同性不同。","觜小者慈孝，觜大者貪庸。","觜大命又长，生来十餘冬。","物老顏色变，头毛白茸茸。","飞来庭樹上，初但驚兒童。","老巫生奸計，與烏意潛通。","云此非凡鸟，遙见起敬恭。","千歲乃一出，喜賀主人翁。","祥瑞来白日，神聖占知风。","陰作北斗使，能爲人吉凶。","此烏所止家，家產日夜豐。","上以致壽考，下可宜田農。","主人富家子，身老心童蒙。","隨巫拜复祝，婦姑亦相從。","殺雞薦其肉，敬若禋六宗。","烏喜張大觜，飞接在虛空。","烏既飽羶腥，巫亦饗甘濃。","烏巫互相利，不复兩西东。","日日營巢窟，稍稍近房櫳。","雖生八九子，誰辨其雌雄。","羣雛又成长，衆觜逞殘兇。","探巢吞燕卵，入蔟啄蠶蟲。","豈無乘秋隼，羈絆委高墉。","但食烏殘肉，無施搏擊功。","亦有能言鸚，翅碧觜距紅。","暫曾说烏罪，囚閉在深籠。","青青窗前柳，鬱鬱井上桐。","貪烏占栖息，慈烏独不容。","慈鸟爾奚爲，来往何憧憧。","晓去先晨鼓，暮归後昏鐘。","辛苦塵土间，飞啄禾黍叢。","得食將哺母，飢腸不自充。","主人憎慈烏，命子削彈弓。","弦續會稽竹，丸鑄荆山銅。","慈烏求母食，飞下爾庭中。","數粒未入口，一丸已中胸。","仰天號一声，似欲訴蒼穹。","反哺日未足，非是惜微躬。","誰能持此冤，一爲问化工。","胡然大觜烏，竟得天年終。"]', '诗', 'shi', '', NULL, '和荅詩十首 和大觜烏 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('078b8015-9e4c-4760-a694-778e66ec9113', '和荅詩十首 答四皓廟', '和荅诗十首 答四皓廟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天下有道見，無道卷懷之。","此乃聖人語，吾聞諸仲尼。","矯矯四先生，同稟希世資。","隨時有顯晦，秉道無磷緇。","秦皇肆暴虐，二世遘亂離。","先生相隨去，商嶺采紫芝。","君看秦獄中，戮辱者李斯。","劉項爭天下，謀臣竟悅隨。","先生如鸞鶴，去入冥冥飛。","君看齊鼎中，焦爛者酈其。","子房得沛公，自謂相遇遲。","八難掉舌樞，三略役心機。","辛苦十數年，晝夜形神疲。","竟雜霸者道，徒稱帝者師。","子房爾則能，此非吾所宜。","漢高之季年，嬖寵鍾所私。","冢嫡欲廢奪，骨肉相憂疑。","豈無子房口，口舌無所施。","亦有陳平心，心計將何爲。","皤皤四先生，高冠危映眉。","從容下南山，顧盼入東闈。","前瞻惠太子，左右生羽儀。","却顧戚夫人，楚舞無光輝。","心不畫一計，口不吐一詞。","闇定天下本，遂安劉氏危。","子房吾則能，此非爾所知。","先生道既光，太子禮甚卑。","安車留不住，功成棄如遺。","如彼旱天雲，一雨百穀滋。","澤則在天下，雲復歸稀夷。","勿高巢與由，勿尚呂與伊。","巢由往不返，伊呂去不歸。","豈如四先生，出處兩逶迤。","何必長隱逸，何必長濟時。","由來聖人道，無朕不可窺。","卷之不盈握，舒之亙八陲。","先生道甚明，夫子猶或非。","願子辨其惑，爲予吟此詩。"]', '["天下有道见，無道卷懷之。","此乃聖人語，吾闻諸仲尼。","矯矯四先生，同稟希世資。","隨时有显晦，秉道無磷緇。","秦皇肆暴虐，二世遘亂離。","先生相隨去，商嶺采紫芝。","君看秦獄中，戮辱者李斯。","劉項爭天下，謀臣竟悅隨。","先生如鸾鹤，去入冥冥飞。","君看齊鼎中，焦爛者酈其。","子房得沛公，自謂相遇遲。","八难掉舌樞，三略役心機。","辛苦十數年，晝夜形神疲。","竟杂霸者道，徒稱帝者師。","子房爾則能，此非吾所宜。","漢高之季年，嬖寵鍾所私。","冢嫡欲廢奪，骨肉相憂疑。","豈無子房口，口舌無所施。","亦有陳平心，心計將何爲。","皤皤四先生，高冠危映眉。","從容下南山，顧盼入东闈。","前瞻惠太子，左右生羽儀。","却顧戚夫人，楚舞無光輝。","心不畫一計，口不吐一词。","闇定天下本，遂安劉氏危。","子房吾則能，此非爾所知。","先生道既光，太子禮甚卑。","安车留不住，功成棄如遺。","如彼旱天云，一雨百穀滋。","澤則在天下，云复归稀夷。","勿高巢與由，勿尚呂與伊。","巢由往不返，伊呂去不归。","豈如四先生，出处兩逶迤。","何必长隐逸，何必长濟时。","由来聖人道，無朕不可窺。","卷之不盈握，舒之亙八陲。","先生道甚明，夫子猶或非。","願子辨其惑，爲予吟此诗。"]', '诗', 'shi', '', NULL, '和荅詩十首 答四皓廟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('129c2ddb-caca-4d4b-b9df-697226ecf483', '和荅詩十首 和雉媒', '和荅诗十首 和雉媒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吟君雉媒什，一哂一復歎。","和之一何晚，今日乃成篇。","豈唯鳥有之，抑亦人復然。","張陳刎頸交，竟以勢不完。","至今不平氣，塞絕泜水源。","趙襄骨肉親，亦以利相殘。","至今不善名，高於磨笄山。","況此籠中雉，志在飲啄間。","稻粱暫入口，性已隨人遷。","身苦亦自忘，同族何足言。","但恨爲媒拙，不足以自全。","勸君今日後，養鳥養青鸞。","青鸞一失侶，至死守孤單。","勸君今日後，結客結任安。","主人賓客去，獨住在門闌。"]', '["吟君雉媒什，一哂一复歎。","和之一何晚，今日乃成篇。","豈唯鸟有之，抑亦人复然。","張陳刎頸交，竟以勢不完。","至今不平氣，塞絕泜水源。","趙襄骨肉親，亦以利相殘。","至今不善名，高於磨笄山。","況此籠中雉，志在饮啄间。","稻粱暫入口，性已隨人遷。","身苦亦自忘，同族何足言。","但恨爲媒拙，不足以自全。","勸君今日後，養鸟養青鸾。","青鸾一失侶，至死守孤單。","勸君今日後，結客結任安。","主人賓客去，独住在门闌。"]', '诗', 'shi', '', NULL, '和荅詩十首 和雉媒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65140cb9-a979-4aa2-82a7-850f54c9b0a2', '和荅詩十首 和松樹', '和荅诗十首 和松樹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["亭亭山上松，一一生朝陽。","森聳上參天，柯條百尺長。","漠漠塵中槐，兩兩夾康莊。","婆娑低覆地，枝幹亦尋常。","八月白露降，槐葉次第黃。","歲暮滿山雪，松色鬱青蒼。","彼如君子心，秉操貫冰霜。","此如小人面，變態隨炎涼。","共知松勝槐，誠欲栽道傍。","糞土種瑤草，瑤草終不芳。","尚可以斧斤，伐之爲棟梁。","殺身獲其所，爲君構明堂。","不然終天年，老死在南岡。","不願亞枝葉，低隨槐樹行。"]', '["亭亭山上松，一一生朝陽。","森聳上參天，柯條百尺长。","漠漠塵中槐，兩兩夾康莊。","婆娑低覆地，枝幹亦尋常。","八月白露降，槐葉次第黄。","歲暮满山雪，松色鬱青蒼。","彼如君子心，秉操貫冰霜。","此如小人面，变態隨炎涼。","共知松勝槐，誠欲栽道傍。","糞土種瑤草，瑤草終不芳。","尚可以斧斤，伐之爲棟梁。","殺身獲其所，爲君構明堂。","不然終天年，老死在南岡。","不願亞枝葉，低隨槐樹行。"]', '诗', 'shi', '', NULL, '和荅詩十首 和松樹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4a565e7-0941-4bba-94e0-7a99db5d7a58', '和荅詩十首 荅箭鏃', '和荅诗十首 荅箭鏃', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["矢人職司憂，爲箭恐不精。","精在利其鏃，錯磨鋒鏑成。","插以青竹簳，羽之赤雁翎。","勿言分寸鐵，爲用乃長兵。","聞有狗盜者，晝伏夜潛行。","摩弓拭箭鏃，夜射不待明。","一盜既流血，百犬同吠聲。","狺狺嘷不已，主人爲之驚。","盜心憎主人，主人不知情。","反責鏃太利，矢人獲罪名。","寄言控弦者，願君少留聽。","何不向西射？西天有狼星。","何不向東射？東海有長鯨。","不然學仁貴，三矢平虜庭。","不然學仲連，一發下燕城。","胡爲射小盜，此用無乃輕。","徒霑一點血，虛汚箭頭腥。"]', '["矢人職司憂，爲箭恐不精。","精在利其鏃，錯磨鋒鏑成。","插以青竹簳，羽之赤雁翎。","勿言分寸鐵，爲用乃长兵。","闻有狗盜者，晝伏夜潛行。","摩弓拭箭鏃，夜射不待明。","一盜既流血，百犬同吠声。","狺狺嘷不已，主人爲之驚。","盜心憎主人，主人不知情。","反責鏃太利，矢人獲罪名。","寄言控弦者，願君少留听。","何不向西射？西天有狼星。","何不向东射？东海有长鯨。","不然学仁貴，三矢平虜庭。","不然学仲連，一發下燕城。","胡爲射小盜，此用無乃轻。","徒霑一点血，虛汚箭头腥。"]', '诗', 'shi', '', NULL, '和荅詩十首 荅箭鏃 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bec8a3d5-9621-4c48-8a52-74f9cbabfef1', '和荅詩十首 和古社', '和荅诗十首 和古社', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["廢村多年樹，生在古社隈。","爲作妖狐窟，心空身未摧。","妖狐變美女，社樹成樓臺。","黃昏行人過，見者心裴回。","飢鵰竟不捉，老犬反爲媒。","歲媚少年客，十去九不迴。","昨夜雲雨合，烈風驅迅雷。","風拔樹根出，雷劈社壇開。","飛電化爲火，妖狐燒作灰。","天明至其所，清曠無氛埃。","舊地葺村落，新田闢荒萊。","始知天降火，不必常爲災。","勿謂神默默，勿謂天恢恢。","勿喜犬不捕，勿誇鵰不猜。","寄言狐媚者，天火有時來。"]', '["廢村多年樹，生在古社隈。","爲作妖狐窟，心空身未摧。","妖狐变美女，社樹成楼台。","黄昏行人過，见者心裴回。","飢鵰竟不捉，老犬反爲媒。","歲媚少年客，十去九不迴。","昨夜云雨合，烈风驱迅雷。","风拔樹根出，雷劈社壇开。","飞電化爲火，妖狐燒作灰。","天明至其所，清曠無氛埃。","旧地葺村落，新田闢荒萊。","始知天降火，不必常爲災。","勿謂神默默，勿謂天恢恢。","勿喜犬不捕，勿誇鵰不猜。","寄言狐媚者，天火有时来。"]', '诗', 'shi', '', NULL, '和荅詩十首 和古社 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05c8bb8b-4dc2-4c4b-bec1-a79ee49be091', '和荅詩十首 和分水嶺', '和荅诗十首 和分水嶺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["高嶺峻稜稜，細泉流亹亹。","勢分合不得，東西隨所委。","悠悠草蔓底，濺濺石罅裏。","分流來幾年，晝夜兩如此。","朝宗遠不及，去海三千里。","浸潤小無功，山苗長旱死。","縈紆用無所，奔迫流不已。","唯作嗚咽聲，夜入行人耳。","有源殊不竭，無坎終難止。","同出而異流，君看何所似。","有似骨肉親，派別從茲始。","又似勢利交，波瀾相背起。","所以贈君詩，將君何所比。","不比山上泉，比君井中水。"]', '["高嶺峻稜稜，細泉流亹亹。","勢分合不得，东西隨所委。","悠悠草蔓底，濺濺石罅裏。","分流来幾年，晝夜兩如此。","朝宗远不及，去海三千里。","浸潤小無功，山苗长旱死。","縈紆用無所，奔迫流不已。","唯作嗚咽声，夜入行人耳。","有源殊不竭，無坎終难止。","同出而異流，君看何所似。","有似骨肉親，派別從茲始。","又似勢利交，波瀾相背起。","所以贈君诗，將君何所比。","不比山上泉，比君井中水。"]', '诗', 'shi', '', NULL, '和荅詩十首 和分水嶺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21be930e-da09-4b10-ba1d-040dc84b0905', '有木詩八首 一', '有木诗八首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有木名弱柳，結根近清池。","風煙借顏色，雨露助華滋。","峨峨白雪花，嫋嫋青絲枝。","漸密陰自庇，轉高梢四垂。","截枝扶爲杖，輭弱不自持。","折條用樊圃，柔脆非其宜。","爲樹信可玩，論材何所施。","可惜金堤地，栽之徒爾爲。"]', '["有木名弱柳，結根近清池。","风煙借顏色，雨露助华滋。","峨峨白雪花，嫋嫋青絲枝。","漸密陰自庇，轉高梢四垂。","截枝扶爲杖，輭弱不自持。","折條用樊圃，柔脆非其宜。","爲樹信可玩，論材何所施。","可惜金堤地，栽之徒爾爲。"]', '诗', 'shi', '', NULL, '有木詩八首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10c953de-f7a9-4212-8a4c-4e54f602cdf5', '有木詩八首 二', '有木诗八首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有木名櫻桃，得地早滋茂。","葉密獨承日，花繁偏受露。","迎風闇搖動，引鳥潛來去。","鳥啄子難成，風來枝莫住。","低輭易攀玩，佳人屢迴顧。","色求桃李饒，心向松筠妬。","好是映牆花，本非當軒樹。","所以姓蕭人，曾爲伐櫻賦。"]', '["有木名櫻桃，得地早滋茂。","葉密独承日，花繁偏受露。","迎风闇搖动，引鸟潛来去。","鸟啄子难成，风来枝莫住。","低輭易攀玩，佳人屢迴顧。","色求桃李饒，心向松筠妬。","好是映牆花，本非當軒樹。","所以姓蕭人，曾爲伐櫻賦。"]', '诗', 'shi', '', NULL, '有木詩八首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1be4366-b686-41ad-8219-913dcc386da6', '有木詩八首 三', '有木诗八首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有木秋不凋，青青在江北。","謂爲洞庭橘，美人自移植。","上受顧盼恩，下勤澆溉力。","實成乃是枳，臭苦不堪食。","物有似是者，真僞何由識。","美人默無言，對之長歎息。","中含害物意，外矯凌霜色。","仍向枝葉間，潛生刺如棘。"]', '["有木秋不凋，青青在江北。","謂爲洞庭橘，美人自移植。","上受顧盼恩，下勤澆溉力。","實成乃是枳，臭苦不堪食。","物有似是者，真僞何由識。","美人默無言，对之长歎息。","中含害物意，外矯凌霜色。","仍向枝葉间，潛生刺如棘。"]', '诗', 'shi', '', NULL, '有木詩八首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c51b5f46-e160-4454-96cb-5385b5313062', '有木詩八首 四', '有木诗八首 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有木名杜棃，陰森覆丘壑。","心蠹已空朽，根深尚盤薄。","狐媚言語巧，鳥妖聲音惡。","憑此爲巢穴，往來互棲託。","四傍五六本，葉枝相交錯。","借問因何生，秋風吹子落。","爲長社壇下，無人敢芟斫。","幾度野火來，風迴燒不著。"]', '["有木名杜棃，陰森覆丘壑。","心蠹已空朽，根深尚盤薄。","狐媚言語巧，鸟妖声音惡。","憑此爲巢穴，往来互棲託。","四傍五六本，葉枝相交錯。","借问因何生，秋风吹子落。","爲长社壇下，無人敢芟斫。","幾度野火来，风迴燒不著。"]', '诗', 'shi', '', NULL, '有木詩八首 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('664f01dd-6059-47d7-b5ec-2663adf8cdba', '有木詩八首 五', '有木诗八首 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有木香苒苒，山頭生一蕟。","主人不知名，移種近軒闥。","愛其有芳味，因以調麴糵。","前後曾飲者，十人無一活。","豈徒悔封植，兼亦誤采掇。","試問識藥人，始知名野葛。","年深已滋蔓，刀斧不可伐。","何時猛風來，爲我連根拔。"]', '["有木香苒苒，山头生一蕟。","主人不知名，移種近軒闥。","愛其有芳味，因以調麴糵。","前後曾饮者，十人無一活。","豈徒悔封植，兼亦誤采掇。","試问識藥人，始知名野葛。","年深已滋蔓，刀斧不可伐。","何时猛风来，爲我連根拔。"]', '诗', 'shi', '', NULL, '有木詩八首 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d6dbe20-917b-4697-af0d-9db71ca52d5c', '有木詩八首 六', '有木诗八首 六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有木名水檉，遠望青童童。","根株非勁挺，柯葉多蒙籠。","彩翠色如柏，鱗皴皮似松。","爲同松柏類，得列嘉樹中。","枝弱不勝雪，勢高常懼風。","雪壓低還舉，風吹西復東。","柔芳甚楊柳，早落先梧桐。","惟有一堪賞，中心無蠹蟲。"]', '["有木名水檉，远望青童童。","根株非勁挺，柯葉多蒙籠。","彩翠色如柏，鱗皴皮似松。","爲同松柏類，得列嘉樹中。","枝弱不勝雪，勢高常懼风。","雪壓低還舉，风吹西复东。","柔芳甚楊柳，早落先梧桐。","惟有一堪賞，中心無蠹蟲。"]', '诗', 'shi', '', NULL, '有木詩八首 六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fc8d0f9-b6c1-47d0-8d68-7ff816539a51', '有木詩八首 七', '有木诗八首 七', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有木名凌霄，擢秀非孤標。","偶依一株樹，遂抽百尺條。","託根附樹身，開花寄樹梢。","自謂得其勢，無因有動搖。","一旦樹摧倒，獨立暫飄颻。","疾風從東起，吹折不終朝。","朝爲拂雲花，暮爲委地樵。","寄言立身者，勿學柔弱苗。"]', '["有木名凌霄，擢秀非孤標。","偶依一株樹，遂抽百尺條。","託根附樹身，开花寄樹梢。","自謂得其勢，無因有动搖。","一旦樹摧倒，独立暫飄颻。","疾风從东起，吹折不終朝。","朝爲拂云花，暮爲委地樵。","寄言立身者，勿学柔弱苗。"]', '诗', 'shi', '', NULL, '有木詩八首 七 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7a4bde8-2642-4caa-84e8-c2d0b92ec6fb', '有木詩八首 八', '有木诗八首 八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有木名丹桂，四時香馥馥。","花團夜雪明，葉翦春雲綠。","風影清似水，霜枝冷如玉。","獨占小山幽，不容凡鳥宿。","匠人愛芳直，裁截爲廈屋。","幹細力未成，用之君自速。","重任雖大過，直心終不曲。","縱非梁棟材，猶勝尋常木。"]', '["有木名丹桂，四时香馥馥。","花團夜雪明，葉翦春云綠。","风影清似水，霜枝冷如玉。","独占小山幽，不容凡鸟宿。","匠人愛芳直，裁截爲廈屋。","幹細力未成，用之君自速。","重任雖大過，直心終不曲。","縱非梁棟材，猶勝尋常木。"]', '诗', 'shi', '', NULL, '有木詩八首 八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cb1c15d-61ec-48f1-8df4-f465ff7249f0', '歎魯二首 一', '歎魯二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["季桓心豈忠，其富過周公。","陽貨道豈正，其權執國命。","由來富與權，不繫才與賢。","所託得其地，雖愚亦獲安。","彘肥因糞壤，鼠穩依社壇。","蟲獸尚如是，豈謂無因緣。"]', '["季桓心豈忠，其富過周公。","陽貨道豈正，其權執国命。","由来富與權，不繫才與賢。","所託得其地，雖愚亦獲安。","彘肥因糞壤，鼠穩依社壇。","蟲獸尚如是，豈謂無因緣。"]', '诗', 'shi', '', NULL, '歎魯二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30150c8b-deff-44b6-ba7a-01561f0a0c30', '歎魯二首 二', '歎魯二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["展禽胡爲者，直道竟三黜。","顏子何如人，屢空聊過日。","皆懷王佐道，不踐陪臣秩。","自古無奈何，命爲時所屈。","有如草木分，天各與其一。","荔枝非名花，牡丹無甘實。"]', '["展禽胡爲者，直道竟三黜。","顏子何如人，屢空聊過日。","皆懷王佐道，不踐陪臣秩。","自古無奈何，命爲时所屈。","有如草木分，天各與其一。","荔枝非名花，牡丹無甘實。"]', '诗', 'shi', '', NULL, '歎魯二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('642a9151-3608-4484-920b-b5f359f38142', '反鮑明遠白頭吟', '反鲍明远白头吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["炎炎者烈火，營營者小蠅。","火不熱貞玉，蠅不點清冰。","此苟無所受，彼莫能相仍。","乃知物性中，各有能不能。","古稱怨恨死，則人有所懲。","懲淫或應可，在道未爲弘。","譬如蜩鷃徒，啾啾啅龍鵬。","宜當委之去，寥廓高飛騰。","豈能泥塵下，區區酬怨憎。","胡爲坐自苦，吞悲仍撫膺。"]', '["炎炎者烈火，營營者小蠅。","火不熱貞玉，蠅不点清冰。","此苟無所受，彼莫能相仍。","乃知物性中，各有能不能。","古稱怨恨死，則人有所懲。","懲淫或應可，在道未爲弘。","譬如蜩鷃徒，啾啾啅龙鵬。","宜當委之去，寥廓高飞腾。","豈能泥塵下，區區酬怨憎。","胡爲坐自苦，吞悲仍撫膺。"]', '诗', 'shi', '', NULL, '反鮑明遠白頭吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48d60d89-356a-4a12-b3cf-02dde12b7c6b', '青冢', '青冢', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["上有飢鷹號，下有枯蓬走。","茫茫邊雪裏，一掬沙培塿。","傳是昭君墓，埋閉蛾眉久。","凝脂化爲泥，鉛黛復何有。","唯有陰怨氣，時生墳左右。","鬱鬱如苦霧，不隨骨銷朽。","婦人無他才，榮枯繫妍否。","何乃明妃命，獨懸畫工手。","丹青一詿誤，白黑相紛糾。","遂使君眼中，西施作嫫母。","同儕傾寵幸，異類爲配偶。","禍福安可知，美顏不如醜。","何言一時事，可戒千年後。","特報後來姝，不須倚眉首。","無辭插荆釵，嫁作貧家婦。","不見青冢上，行人爲澆酒。"]', '["上有飢鷹號，下有枯蓬走。","茫茫邊雪裏，一掬沙培塿。","傳是昭君墓，埋閉蛾眉久。","凝脂化爲泥，鉛黛复何有。","唯有陰怨氣，时生墳左右。","鬱鬱如苦霧，不隨骨銷朽。","婦人無他才，榮枯繫妍否。","何乃明妃命，独懸畫工手。","丹青一詿誤，白黑相紛糾。","遂使君眼中，西施作嫫母。","同儕傾寵幸，異類爲配偶。","禍福安可知，美顏不如醜。","何言一时事，可戒千年後。","特報後来姝，不須倚眉首。","無辞插荆釵，嫁作貧家婦。","不见青冢上，行人爲澆酒。"]', '诗', 'shi', '', NULL, '青冢 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a485e66d-16d3-4b84-8eef-1c19c1f654ea', '雜感', '杂感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["君子防悔尤，賢人戒行藏。","嫌疑遠瓜李，言動慎毫芒。","立教固如此，撫事有非常。","爲君持所感，仰面問蒼蒼。","犬齧桃樹根，李樹反見傷。","老龜烹不爛，延禍及枯桑。","城門自焚爇，池魚罹其殃。","陽貨肆兇暴，仲尼畏於匡。","魯酒薄如水，邯鄲開戰場。","伯禽鞭見血，過失由成王。","都尉身降虜，宮刑加子長。","呂安兄不道，都市殺嵇康。","斯人死已久，其事甚昭彰。","是非不由己，禍患安可防。","使我千載後，涕泗滿衣裳。"]', '["君子防悔尤，賢人戒行藏。","嫌疑远瓜李，言动慎毫芒。","立教固如此，撫事有非常。","爲君持所感，仰面问蒼蒼。","犬齧桃樹根，李樹反见傷。","老龟烹不爛，延禍及枯桑。","城门自焚爇，池鱼罹其殃。","陽貨肆兇暴，仲尼畏於匡。","魯酒薄如水，邯鄲开戰場。","伯禽鞭见血，過失由成王。","都尉身降虜，宮刑加子长。","呂安兄不道，都市殺嵇康。","斯人死已久，其事甚昭彰。","是非不由己，禍患安可防。","使我千載後，涕泗满衣裳。"]', '诗', 'shi', '', NULL, '雜感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d89a395a-1449-4082-ad16-2d60993387f3', '新樂府 七德舞	美撥亂，陳王業也', '新乐府 七德舞	美撥亂，陳王業也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["七德舞，七德歌，傳自武德至元和。","元和小臣白居易，觀舞聽歌知樂意。","樂終稽首陳其事，太宗十八舉義兵。","白旄黃鉞定兩京，擒充戮竇四海清。","二十有四功業成，二十有九即帝位。","三十有五致太平，功成理定何神速。","速在推心置人腹，亡卒遺骸散帛收。","飢人賣子分金贖，魏徵夢見子夜泣。","張謹哀聞辰日哭，怨女三千放出宮。","死囚四百來歸獄，翦鬚燒藥賜功臣。","李勣嗚咽思殺身含血吮創撫戰士，思摩奮呼乞効死。","則知不獨善戰善乘時，以心感人人心歸。","爾來一百九十載，天下至今歌舞之。","歌七德，舞七德，聖人有作垂無極。","豈徒耀神武，豈徒誇聖文。","太宗意在陳王業，王業艱難示子孫。"]', '["七德舞，七德歌，傳自武德至元和。","元和小臣白居易，观舞听歌知乐意。","乐終稽首陳其事，太宗十八舉義兵。","白旄黄鉞定兩京，擒充戮竇四海清。","二十有四功業成，二十有九即帝位。","三十有五致太平，功成理定何神速。","速在推心置人腹，亡卒遺骸散帛收。","飢人賣子分金贖，魏徵梦见子夜泣。","張謹哀闻辰日哭，怨女三千放出宮。","死囚四百来归獄，翦鬚燒藥賜功臣。","李勣嗚咽思殺身含血吮創撫戰士，思摩奮呼乞効死。","則知不独善戰善乘时，以心感人人心归。","爾来一百九十載，天下至今歌舞之。","歌七德，舞七德，聖人有作垂無極。","豈徒耀神武，豈徒誇聖文。","太宗意在陳王業，王業艱难示子孫。"]', '诗', 'shi', '', NULL, '新樂府 七德舞	美撥亂，陳王業也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b6aa0ad-b9af-4efe-8045-28330bb5a227', '新樂府 法曲	美列聖，正華聲也', '新乐府 法曲	美列聖，正华声也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["法曲法曲歌大定，積德重熙有餘慶。","永徽之人舞而詠，法曲法曲舞霓裳。","政和世理音洋洋，開元之人樂且康。","法曲法曲歌堂堂，堂堂之慶垂無疆。","中宗肅宗復鴻業，唐祚中興萬萬葉。","法曲法曲合夷歌，夷聲邪亂華聲和。","以亂干和天寶末，明年胡塵犯宮闕。","乃知法曲本華風，苟能審音與政通。","一從胡曲相參錯，不辨興衰與哀樂。","願求牙曠正華音，不令夷夏相交侵。"]', '["法曲法曲歌大定，積德重熙有餘慶。","永徽之人舞而詠，法曲法曲舞霓裳。","政和世理音洋洋，开元之人乐且康。","法曲法曲歌堂堂，堂堂之慶垂無疆。","中宗肅宗复鴻業，唐祚中兴万万葉。","法曲法曲合夷歌，夷声邪亂华声和。","以亂干和天寶末，明年胡塵犯宮闕。","乃知法曲本华风，苟能審音與政通。","一從胡曲相參錯，不辨兴衰與哀乐。","願求牙曠正华音，不令夷夏相交侵。"]', '诗', 'shi', '', NULL, '新樂府 法曲	美列聖，正華聲也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('653388ca-159d-4a7a-8e72-8db997377cc9', '新樂府 二王後	明祖宗之意也', '新乐府 二王後	明祖宗之意也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["二王後，彼何人，介公酅公爲國賓。","周武隋文之子孫，古人有言天下者，非是一人之天下。","周亡天下傳於隋，隋人失之唐得之。","唐興十葉歲二百，介公酅公世爲客。","明堂太廟朝享時，引居賓位備威儀。","備威儀，助郊祭，高祖太宗之遺制。","不獨興滅國，不獨繼絕世。","欲令嗣位守文君，亡國之孫取爲戒。"]', '["二王後，彼何人，介公酅公爲国賓。","周武隋文之子孫，古人有言天下者，非是一人之天下。","周亡天下傳於隋，隋人失之唐得之。","唐兴十葉歲二百，介公酅公世爲客。","明堂太廟朝享时，引居賓位備威儀。","備威儀，助郊祭，高祖太宗之遺制。","不独兴滅国，不独繼絕世。","欲令嗣位守文君，亡国之孫取爲戒。"]', '诗', 'shi', '', NULL, '新樂府 二王後	明祖宗之意也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbddd4e6-86e1-444f-9e4e-09e473f2a306', '新樂府 海漫漫	戒求仙也', '新乐府 海漫漫	戒求仙也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["海漫漫，直下無底傍無邊。","雲濤煙浪最深處，人傳中有三神山。","山上多生不死藥，服之羽化爲天仙。","秦皇漢武信此語，方士年年采藥去。","蓬萊今古但聞名，煙水茫茫無覓處。","海漫漫，風浩浩，眼穿不見蓬萊島。","不見蓬萊不敢歸，童男丱女舟中老。","徐福文成多誑誕，上元太一虛祈禱。","君看驪山頂上茂陵頭，畢竟悲風吹蔓草。","何況玄元聖祖五千言，不言藥，不言仙，不言白日升青天。"]', '["海漫漫，直下無底傍無邊。","云濤煙浪最深处，人傳中有三神山。","山上多生不死藥，服之羽化爲天仙。","秦皇漢武信此語，方士年年采藥去。","蓬萊今古但闻名，煙水茫茫無覓处。","海漫漫，风浩浩，眼穿不见蓬萊島。","不见蓬萊不敢归，童男丱女舟中老。","徐福文成多誑誕，上元太一虛祈禱。","君看驪山頂上茂陵头，畢竟悲风吹蔓草。","何況玄元聖祖五千言，不言藥，不言仙，不言白日升青天。"]', '诗', 'shi', '', NULL, '新樂府 海漫漫	戒求仙也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('318b28a4-48ac-4fd9-9c6c-b478a292fb39', '新樂府 立部伎	刺雅樂之替也', '新乐府 立部伎	刺雅乐之替也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["立部伎，鼓笛諠，舞雙劒，跳七丸，嫋巨索，掉長竿。","太常部伎有等級，堂上者坐堂下立。","堂上坐部笙歌清，堂下立部鼓笛鳴。","笙歌一聲衆側耳，鼓笛萬曲無人聽。","立部賤，坐部貴，坐部退爲立部伎。","擊鼓吹笙和雜戲，立部又退何所任。","始就樂懸操雅音，雅音替壞一至此。","長令爾輩調宮徵，圓丘后土郊祀時。","言將此樂感神祇，欲望鳳來百獸舞。","何異北轅將適楚，工師愚賤安足云。"]', '["立部伎，鼓笛諠，舞雙劒，跳七丸，嫋巨索，掉长竿。","太常部伎有等級，堂上者坐堂下立。","堂上坐部笙歌清，堂下立部鼓笛鳴。","笙歌一声衆側耳，鼓笛万曲無人听。","立部賤，坐部貴，坐部退爲立部伎。","擊鼓吹笙和杂戲，立部又退何所任。","始就乐懸操雅音，雅音替壞一至此。","长令爾輩調宮徵，圓丘后土郊祀时。","言將此乐感神祇，欲望鳳来百獸舞。","何異北轅將適楚，工師愚賤安足云。"]', '诗', 'shi', '', NULL, '新樂府 立部伎	刺雅樂之替也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03d52578-b863-4eb7-9517-08c6fc4daea6', '新樂府 華原磬	刺樂工非其人也', '新乐府 华原磬	刺乐工非其人也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["華原磬，華原磬，古人不聽今人聽。","泗濱石，泗濱石，今人不擊古人擊。","今人古人何不同？用之舍之由樂工。","樂工雖在耳如壁，不分清濁即爲聾。","棃園弟子調律呂，知有新聲不如古。","古稱浮磬出泗濱，立辨致死聲感人。","宮懸一聽華原石，君心遂忘封疆臣。","果然胡寇從燕起，武臣少肯封疆死。","始知樂與時政通，豈聽鏗鏘而已矣。","磬襄入海去不歸，長安市兒爲樂師。","華原磬與泗濱石，清濁兩聲誰得知。"]', '["华原磬，华原磬，古人不听今人听。","泗濱石，泗濱石，今人不擊古人擊。","今人古人何不同？用之舍之由乐工。","乐工雖在耳如壁，不分清濁即爲聾。","棃园弟子調律呂，知有新声不如古。","古稱浮磬出泗濱，立辨致死声感人。","宮懸一听华原石，君心遂忘封疆臣。","果然胡寇從燕起，武臣少肯封疆死。","始知乐與时政通，豈听鏗鏘而已矣。","磬襄入海去不归，长安市兒爲乐師。","华原磬與泗濱石，清濁兩声誰得知。"]', '诗', 'shi', '', NULL, '新樂府 華原磬	刺樂工非其人也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fd74af9-88f7-42bd-875f-57a30bd80868', '新樂府 上陽白髮人	愍怨曠也', '新乐府 上陽白髮人	愍怨曠也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["上陽人，紅顏闇老白髮新。","綠衣監使守宮門，一閉上陽多少春。","玄宗末歲初選入，入時十六今六十。","同時采擇百餘人，零落年深殘此身。","憶昔吞悲別親族，扶入車中不教哭。","皆云入內便承恩，臉似芙蓉胸似玉。","未容君王得見面，已被楊妃遙側目。","妬令潛配上陽宮，一生遂向空房宿。","宿空房，秋夜長，夜長無寐天不明。","耿耿殘燈背壁影，蕭蕭暗雨打窗聲。","春日遲，日遲獨坐天難暮。","宮鶯百囀愁厭聞，梁燕雙栖老休妬。","鶯歸燕去長悄然，春往秋來不記年。","唯向深宮望明月，東西四五百迴圓。","今日宮中年最老，大家遙賜尚書號。","小頭鞋履窄衣裳，青黛點眉眉細長。","外人不見見應笑，天寶末年時世妝。","上陽人，苦最多，少亦苦，老亦苦，少苦老苦兩如何？","君不見昔時呂向美人賦，又不見今日上陽白髮歌。"]', '["上陽人，紅顏闇老白髮新。","綠衣監使守宮门，一閉上陽多少春。","玄宗末歲初選入，入时十六今六十。","同时采擇百餘人，零落年深殘此身。","憶昔吞悲別親族，扶入车中不教哭。","皆云入內便承恩，臉似芙蓉胸似玉。","未容君王得见面，已被楊妃遙側目。","妬令潛配上陽宮，一生遂向空房宿。","宿空房，秋夜长，夜长無寐天不明。","耿耿殘灯背壁影，蕭蕭暗雨打窗声。","春日遲，日遲独坐天难暮。","宮鶯百囀愁厭闻，梁燕雙栖老休妬。","鶯归燕去长悄然，春往秋来不記年。","唯向深宮望明月，东西四五百迴圓。","今日宮中年最老，大家遙賜尚书號。","小头鞋履窄衣裳，青黛点眉眉細长。","外人不见见應笑，天寶末年时世妝。","上陽人，苦最多，少亦苦，老亦苦，少苦老苦兩如何？","君不见昔时呂向美人賦，又不见今日上陽白髮歌。"]', '诗', 'shi', '', NULL, '新樂府 上陽白髮人	愍怨曠也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d29c1368-48c6-474f-b9a4-db596471795e', '新樂府 胡旋女	戒近習也', '新乐府 胡旋女	戒近習也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["胡旋女，胡旋女，心應弦，手應鼓。","弦鼓一聲雙袖舉，迴雪飄颻轉蓬舞。","左旋右轉不知疲，千匝萬周無已時。","人間物類無可比，奔車輪緩旋風遲。","曲終再拜謝天子，天子爲之微啓齒。","胡旋女，出康居，徒勞東來萬里餘。","中原自有胡旋者，鬬妙爭能爾不如。","天寶季年時欲變，臣妾人人學圜轉。","中有太真外祿山，二人最道能胡旋。","棃花園中冊作妃，金雞障下養爲兒。","祿山胡旋迷君眼，兵過黃河疑未反。","貴妃胡旋惑君心，死棄馬嵬念更深。","從茲地軸天維轉，五十年來制不禁。","胡旋女，莫空舞，數唱此歌悟明主。"]', '["胡旋女，胡旋女，心應弦，手應鼓。","弦鼓一声雙袖舉，迴雪飄颻轉蓬舞。","左旋右轉不知疲，千匝万周無已时。","人间物類無可比，奔车輪緩旋风遲。","曲終再拜謝天子，天子爲之微啓齒。","胡旋女，出康居，徒勞东来万里餘。","中原自有胡旋者，鬬妙爭能爾不如。","天寶季年时欲变，臣妾人人学圜轉。","中有太真外祿山，二人最道能胡旋。","棃花园中冊作妃，金雞障下養爲兒。","祿山胡旋迷君眼，兵過黄河疑未反。","貴妃胡旋惑君心，死棄马嵬念更深。","從茲地軸天維轉，五十年来制不禁。","胡旋女，莫空舞，數唱此歌悟明主。"]', '诗', 'shi', '', NULL, '新樂府 胡旋女	戒近習也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ece1ff0c-ab25-41df-adb4-836cf2af908f', '新樂府 新豐折臂翁	戒邊功也', '新乐府 新豐折臂翁	戒邊功也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["新豐老翁八十八，頭鬢眉鬚皆似雪。","玄孫扶向店前行，左臂憑肩右臂折。","問翁臂折來幾年，兼問致折何因緣。","翁云貫屬新豐縣，生逢聖代無征戰。","慣聽棃園歌管聲，不識旗槍與弓箭。","無何天寶大徵兵，戶有三丁點一丁。","點得驅將何處去，五月萬里雲南行。","聞道雲南有瀘水，椒花落時瘴煙起。","大軍徒涉水如湯，未過十人二三死。","村南村北哭聲哀，兒別爺娘夫別妻。","皆云前後征蠻者，千萬人行無一迴。","是時翁年二十四，兵部牒中有名字。","夜深不敢使人知，偷將大石搥折臂。","張弓簸旗俱不堪，從茲始免征雲南。","骨碎筋傷非不苦，且圖揀退歸鄉土。","此臂折來六十年，一肢雖廢一身全。","至今風雨陰寒夜，直到天明痛不眠。","痛不眠，終不悔，且喜老身今獨在。","不然當時瀘水頭，身死魂孤骨不收。","應作雲南望鄉鬼，萬人冢上哭呦呦。","老人言，君聽取。","君不聞開元宰相宋開府，不賞邊功防黷武。","又不聞天寶宰相楊國忠，欲求恩幸立邊功。","邊功未立生人怨，請問新豐折臂翁。"]', '["新豐老翁八十八，头鬢眉鬚皆似雪。","玄孫扶向店前行，左臂憑肩右臂折。","问翁臂折来幾年，兼问致折何因緣。","翁云貫屬新豐縣，生逢聖代無征戰。","慣听棃园歌管声，不識旗槍與弓箭。","無何天寶大徵兵，戶有三丁点一丁。","点得驱將何处去，五月万里云南行。","闻道云南有瀘水，椒花落时瘴煙起。","大軍徒涉水如湯，未過十人二三死。","村南村北哭声哀，兒別爺娘夫別妻。","皆云前後征蠻者，千万人行無一迴。","是时翁年二十四，兵部牒中有名字。","夜深不敢使人知，偷將大石搥折臂。","張弓簸旗俱不堪，從茲始免征云南。","骨碎筋傷非不苦，且圖揀退归乡土。","此臂折来六十年，一肢雖廢一身全。","至今风雨陰寒夜，直到天明痛不眠。","痛不眠，終不悔，且喜老身今独在。","不然當时瀘水头，身死魂孤骨不收。","應作云南望乡鬼，万人冢上哭呦呦。","老人言，君听取。","君不闻开元宰相宋开府，不賞邊功防黷武。","又不闻天寶宰相楊国忠，欲求恩幸立邊功。","邊功未立生人怨，請问新豐折臂翁。"]', '诗', 'shi', '', NULL, '新樂府 新豐折臂翁	戒邊功也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b822af1-c865-49dc-946d-9740691f330f', '新樂府 太行路	借夫婦以諷君臣之不終也', '新乐府 太行路	借夫婦以諷君臣之不終也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["太行之路能摧車，若比人心是坦途。","巫峽之水能覆舟，若比人心是安流。","人心好惡苦不常，好生毛羽惡生瘡。","與君結髮未五載，豈期牛女爲參商。","古稱色衰相棄背，當時美人猶怨悔。","何況如今鸞鏡中，妾顏未改君心改。","爲君熏衣裳，君聞蘭麝不馨香。","爲君盛容飾，君看金翠無顏色。","行路難，難重陳。","人生莫作婦人身，百年苦樂由他人。","行路難，難於山，險於水。","不獨人間夫與妻，近代君臣亦如此。","君不見左納言，右納史，朝承恩，暮賜死。","行路難，不在水，不在山，只在人情反覆間。"]', '["太行之路能摧车，若比人心是坦途。","巫峽之水能覆舟，若比人心是安流。","人心好惡苦不常，好生毛羽惡生瘡。","與君結髮未五載，豈期牛女爲參商。","古稱色衰相棄背，當时美人猶怨悔。","何況如今鸾镜中，妾顏未改君心改。","爲君熏衣裳，君闻蘭麝不馨香。","爲君盛容飾，君看金翠無顏色。","行路难，难重陳。","人生莫作婦人身，百年苦乐由他人。","行路难，难於山，險於水。","不独人间夫與妻，近代君臣亦如此。","君不见左納言，右納史，朝承恩，暮賜死。","行路难，不在水，不在山，只在人情反覆间。"]', '诗', 'shi', '', NULL, '新樂府 太行路	借夫婦以諷君臣之不終也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1a83087-b1e0-4b1f-b68f-7962982e8abf', '新樂府 司天臺	引古以儆今也', '新乐府 司天台	引古以儆今也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["司天臺，仰觀俯察天人際。","羲和死來職事廢，官不求賢空取藝。","昔聞西漢元成間，上陵下替謫見天。","北辰微闇少光色，四星煌煌如火赤。","耀芒動角射三台，上台半滅中台坼。","是時非無太史官，眼見心知不敢言。","明朝趨入明光殿，唯奏慶雲壽星見。","天文時變兩如斯，九重天子不得知。","不得知，安用臺高百尺爲。"]', '["司天台，仰观俯察天人際。","羲和死来職事廢，官不求賢空取藝。","昔闻西漢元成间，上陵下替謫见天。","北辰微闇少光色，四星煌煌如火赤。","耀芒动角射三台，上台半滅中台坼。","是时非無太史官，眼见心知不敢言。","明朝趨入明光殿，唯奏慶云壽星见。","天文时变兩如斯，九重天子不得知。","不得知，安用台高百尺爲。"]', '诗', 'shi', '', NULL, '新樂府 司天臺	引古以儆今也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c41f763-148e-4d85-8dce-366037e0d0d3', '新樂府 捕蝗		刺長吏也', '新乐府 捕蝗		刺长吏也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["捕蝗捕蝗誰家子，天熱日長飢欲死。","興元兵後傷陰陽，和氣蠱蠹化爲蝗。","始自兩河及三輔，薦食如蠶飛似雨。","雨飛蠶食千里間，不見青苗空赤土。","河南長吏言憂農，課人晝夜捕蝗蟲。","是時粟斗錢三百，蝗蟲之價與粟同。","捕蝗捕蝗竟何利，徒使飢人重勞費。","一蟲雖死百蟲來，豈將人力定天災。","我聞古之良吏有善政，以政驅蝗蝗出境。","又聞貞觀之初道欲昌，文皇仰天吞一蝗。","一人有慶兆民賴，是歲雖蝗不爲害。"]', '["捕蝗捕蝗誰家子，天熱日长飢欲死。","兴元兵後傷陰陽，和氣蠱蠹化爲蝗。","始自兩河及三輔，薦食如蠶飞似雨。","雨飞蠶食千里间，不见青苗空赤土。","河南长吏言憂農，課人晝夜捕蝗蟲。","是时粟斗錢三百，蝗蟲之價與粟同。","捕蝗捕蝗竟何利，徒使飢人重勞費。","一蟲雖死百蟲来，豈將人力定天災。","我闻古之良吏有善政，以政驱蝗蝗出境。","又闻貞观之初道欲昌，文皇仰天吞一蝗。","一人有慶兆民賴，是歲雖蝗不爲害。"]', '诗', 'shi', '', NULL, '新樂府 捕蝗		刺長吏也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb024025-9f9a-498d-af5b-7d8729e741c0', '新樂府 昆明春	思王澤之廣被也', '新乐府 昆明春	思王澤之廣被也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昆明春，昆明春，春池岸古春流新。","影浸南山青滉瀁，波沈西日紅奫淪。","往年因旱池枯竭，龜尾曳塗魚喣沫。","詔開八水注恩波，千介萬鱗同日活。","今來淨綠水照天，游魚鱍鱍蓮田田。","洲香杜若抽心短，沙暖鴛鴦鋪翅眠。","動植飛沈皆遂性，皇澤如春無不被。","漁者仍豐網罟資，貧人久獲菰蒲利。","詔以昆明近帝城，官家不得收其征。","菰蒲無租魚無稅，近水之人感君惠。","感君惠，獨何人。","吾聞率土皆王民，遠民何疎近何親。","願推此惠及天下，無遠無近同欣欣。","吳興山中罷榷茗，鄱陽坑裏休封銀。","天涯地角無禁利，熙熙同似昆明春。"]', '["昆明春，昆明春，春池岸古春流新。","影浸南山青滉瀁，波沈西日紅奫淪。","往年因旱池枯竭，龟尾曳塗鱼喣沫。","詔开八水注恩波，千介万鱗同日活。","今来淨綠水照天，游鱼鱍鱍蓮田田。","洲香杜若抽心短，沙暖鴛鴦鋪翅眠。","动植飞沈皆遂性，皇澤如春無不被。","漁者仍豐網罟資，貧人久獲菰蒲利。","詔以昆明近帝城，官家不得收其征。","菰蒲無租鱼無稅，近水之人感君惠。","感君惠，独何人。","吾闻率土皆王民，远民何疎近何親。","願推此惠及天下，無远無近同欣欣。","吳兴山中罷榷茗，鄱陽坑裏休封銀。","天涯地角無禁利，熙熙同似昆明春。"]', '诗', 'shi', '', NULL, '新樂府 昆明春	思王澤之廣被也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55c4a950-e65f-4b14-b3b5-3fc10aa0c1a1', '新樂府 城鹽州	美聖謨而誚邊將也', '新乐府 城鹽州	美聖謨而誚邊將也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["城鹽州，城鹽州，城在五原原上頭。","蕃東節度鉢闡布，忽見新城當要路。","金鳥飛傳贊普聞，建牙傳箭集羣臣。","君臣赬面有憂色，皆言勿謂唐無人。","自築鹽州十餘載，左衽氈裘不犯塞。","晝牧牛羊夜捉生，長去新城百里外。","諸邊急警勞戍人，唯此一道無煙塵。","靈夏潛安誰復辨，秦原闇通何處見。","鄜州驛路好馬來，長安藥肆黃蓍賤。","城鹽州，鹽州未城天子憂。","德宗按圖自定計，非關將略與廟謀。","吾聞高宗中宗世，北虜猖狂最難制。","韓公創築受降城，三城鼎峙屯漢兵。","東西亙絕數千里，耳冷不聞胡馬聲。","如今邊將非無策，心笑韓公築城壁。","相看養寇爲身謀，各握強兵固恩澤。","願分今日邊將恩，褒贈韓公封子孫。","誰能將此鹽州曲，飜作歌詞聞至尊。"]', '["城鹽州，城鹽州，城在五原原上头。","蕃东節度鉢闡布，忽见新城當要路。","金鸟飞傳贊普闻，建牙傳箭集羣臣。","君臣赬面有憂色，皆言勿謂唐無人。","自築鹽州十餘載，左衽氈裘不犯塞。","晝牧牛羊夜捉生，长去新城百里外。","諸邊急警勞戍人，唯此一道無煙塵。","靈夏潛安誰复辨，秦原闇通何处见。","鄜州驛路好马来，长安藥肆黄蓍賤。","城鹽州，鹽州未城天子憂。","德宗按圖自定計，非关將略與廟謀。","吾闻高宗中宗世，北虜猖狂最难制。","韓公創築受降城，三城鼎峙屯漢兵。","东西亙絕數千里，耳冷不闻胡马声。","如今邊將非無策，心笑韓公築城壁。","相看養寇爲身謀，各握強兵固恩澤。","願分今日邊將恩，褒贈韓公封子孫。","誰能將此鹽州曲，飜作歌词闻至尊。"]', '诗', 'shi', '', NULL, '新樂府 城鹽州	美聖謨而誚邊將也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da8402ef-6cf1-4b8b-9a37-feff27fba276', '新樂府 道州民	美臣遇明主也', '新乐府 道州民	美臣遇明主也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["道州民，多侏儒，長者不過三尺餘。","市作矮奴年進送，號爲道州任土貢。","任土貢，寧若斯。","不聞使人生別離，老翁哭孫母哭兒。","一自陽城來守郡，不進矮奴頻詔問。","城云臣按六典書，任土貢有不貢無。","道州水土所生者，只有矮民無矮奴。","吾君感悟璽書下，歲貢矮奴宜悉罷。","道州民，老者幼者何欣欣。","父兄子弟始相保，從此得作良人身。","道州民，民到于今受其賜，欲說使君先下淚。","仍恐兒孫忘使君，生男多以陽爲字。"]', '["道州民，多侏儒，长者不過三尺餘。","市作矮奴年進送，號爲道州任土貢。","任土貢，寧若斯。","不闻使人生別離，老翁哭孫母哭兒。","一自陽城来守郡，不進矮奴頻詔问。","城云臣按六典书，任土貢有不貢無。","道州水土所生者，只有矮民無矮奴。","吾君感悟璽书下，歲貢矮奴宜悉罷。","道州民，老者幼者何欣欣。","父兄子弟始相保，從此得作良人身。","道州民，民到于今受其賜，欲说使君先下泪。","仍恐兒孫忘使君，生男多以陽爲字。"]', '诗', 'shi', '', NULL, '新樂府 道州民	美臣遇明主也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e77ff416-cd6e-4d75-8c2d-098b31872617', '新樂府 馴犀		感爲政之難終也', '新乐府 馴犀		感爲政之难終也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["馴犀馴犀通天犀，軀貌駭人角駭雞。","海蠻聞有明天子，驅犀乘傳來萬里。","一朝得謁大明宮，歡呼拜舞自論功。","五年馴養始堪獻，六譯語言方得通。","上嘉人獸俱來遠，蠻館四方犀入苑。","秣以瑤芻鏁以金，故鄉迢遰君門深。","海鳥不知鐘鼓樂，池魚空結江湖心。","馴犀生處南方熱，秋無白露冬無雪。","一入上林三四年，又逢今歲苦寒月。","飲冰臥霰苦踡跼，角骨凍傷鱗甲蹜。","馴犀死，蠻兒啼，向闕再拜顏色低。","奏乞生歸本國去，恐身凍死似馴犀。","君不見建中初，馴象生還放林邑。","君不見貞元年末，馴犀凍死蠻兒泣。","所嗟建中異貞元，象生犀死何足言。"]', '["馴犀馴犀通天犀，軀貌駭人角駭雞。","海蠻闻有明天子，驱犀乘傳来万里。","一朝得謁大明宮，歡呼拜舞自論功。","五年馴養始堪獻，六譯語言方得通。","上嘉人獸俱来远，蠻館四方犀入苑。","秣以瑤芻鏁以金，故乡迢遰君门深。","海鸟不知鐘鼓乐，池鱼空結江湖心。","馴犀生处南方熱，秋無白露冬無雪。","一入上林三四年，又逢今歲苦寒月。","饮冰臥霰苦踡跼，角骨凍傷鱗甲蹜。","馴犀死，蠻兒啼，向闕再拜顏色低。","奏乞生归本国去，恐身凍死似馴犀。","君不见建中初，馴象生還放林邑。","君不见貞元年末，馴犀凍死蠻兒泣。","所嗟建中異貞元，象生犀死何足言。"]', '诗', 'shi', '', NULL, '新樂府 馴犀		感爲政之難終也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c244da49-5540-4485-9184-3680ab1836a6', '新樂府 五弦彈	惡鄭之奪雅也', '新乐府 五弦彈	惡鄭之奪雅也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["五弦彈，五弦彈，聽者傾耳心寥寥。","趙璧知君入骨愛，五弦一一爲君調。","第一第二弦索索，秋風拂松疎韻落。","第三第四弦泠泠，夜鶴憶子籠中鳴。","第五弦聲最掩抑，隴水凍咽流不得。","五弦竝奏君試聽，淒淒切切復錚錚。","鐵擊珊瑚一兩曲，冰瀉玉盤千萬聲。","鐵聲殺，冰聲寒。","殺聲入耳膚血憯，寒氣中人肌骨酸。","曲終聲盡欲半日，四坐相對愁無言。","座中有一遠方士，唧唧咨咨聲不已。","自歎今朝初得聞，始知孤負平生耳。","唯憂趙璧白髮生，老死人間無此聲。","遠方士，爾聽五弦信爲美，吾聞正始之音不如是。","正始之音其若何，朱弦疏越清廟歌。","一彈一唱再三歎，曲澹節稀聲不多。","融融曳曳召元氣，聽之不覺心平和。","人情重今多賤古，古琴有弦人不撫。","更從趙璧藝成來，二十五弦不如五。"]', '["五弦彈，五弦彈，听者傾耳心寥寥。","趙璧知君入骨愛，五弦一一爲君調。","第一第二弦索索，秋风拂松疎韻落。","第三第四弦泠泠，夜鹤憶子籠中鳴。","第五弦声最掩抑，隴水凍咽流不得。","五弦竝奏君試听，淒淒切切复錚錚。","鐵擊珊瑚一兩曲，冰瀉玉盤千万声。","鐵声殺，冰声寒。","殺声入耳膚血憯，寒氣中人肌骨酸。","曲終声尽欲半日，四坐相对愁無言。","座中有一远方士，唧唧咨咨声不已。","自歎今朝初得闻，始知孤負平生耳。","唯憂趙璧白髮生，老死人间無此声。","远方士，爾听五弦信爲美，吾闻正始之音不如是。","正始之音其若何，朱弦疏越清廟歌。","一彈一唱再三歎，曲澹節稀声不多。","融融曳曳召元氣，听之不覺心平和。","人情重今多賤古，古琴有弦人不撫。","更從趙璧藝成来，二十五弦不如五。"]', '诗', 'shi', '', NULL, '新樂府 五弦彈	惡鄭之奪雅也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffae9a7f-d8fb-47e3-aee1-1ddca03a7958', '新樂府 蠻子朝	刺將驕而相備位也', '新乐府 蠻子朝	刺將驕而相備位也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蠻子朝，泛皮船兮渡繩橋，來自巂州道路遙。","入界先經蜀川過，蜀將收功先表賀。","臣聞雲南六詔蠻，東連牂牁西連蕃。","六詔星居初瑣碎，合爲一詔漸強大。","開元皇帝雖聖神，唯蠻倔強不來賓。","鮮于仲通六萬卒，征蠻一陣全軍沒。","至今西洱河岸邊，箭孔刀痕滿枯骨。","誰知今日慕華風，不勞一人蠻自通。","誠由陛下休明德，亦賴微臣誘諭功。","德宗省表知如此，笑令中使迎蠻子。","蠻子導從者誰何，摩挲俗羽雙隈伽。","清平官持赤藤杖，大將軍繫金呿喈。","異牟尋男尋閤勸，特敕召對延英殿。","上心貴在懷遠蠻，引臨玉座近天顏。","冕旒不垂親勞倈，賜衣賜食移時對。","移時對，不可得，大臣相看有羨色。","可憐宰相拖紫佩金章，朝日唯聞對一刻。"]', '["蠻子朝，泛皮船兮渡繩橋，来自巂州道路遙。","入界先經蜀川過，蜀將收功先表賀。","臣闻云南六詔蠻，东連牂牁西連蕃。","六詔星居初瑣碎，合爲一詔漸強大。","开元皇帝雖聖神，唯蠻倔強不来賓。","鲜于仲通六万卒，征蠻一陣全軍沒。","至今西洱河岸邊，箭孔刀痕满枯骨。","誰知今日慕华风，不勞一人蠻自通。","誠由陛下休明德，亦賴微臣誘諭功。","德宗省表知如此，笑令中使迎蠻子。","蠻子導從者誰何，摩挲俗羽雙隈伽。","清平官持赤藤杖，大將軍繫金呿喈。","異牟尋男尋閤勸，特敕召对延英殿。","上心貴在懷远蠻，引臨玉座近天顏。","冕旒不垂親勞倈，賜衣賜食移时对。","移时对，不可得，大臣相看有羨色。","可怜宰相拖紫佩金章，朝日唯闻对一刻。"]', '诗', 'shi', '', NULL, '新樂府 蠻子朝	刺將驕而相備位也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3678b5ab-47f9-4d7e-ac26-688295c2a2a5', '新樂府 驃國樂	欲王化之先邇後遠也', '新乐府 驃国乐	欲王化之先邇後远也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["驃國樂，驃國樂，出自大海西南角。","雍羌之子舒難陀，來獻南音奉正朔。","德宗立仗御紫庭，黈纊不塞爲爾聽。","玉螺一吹椎髻聳，銅鼓一擊文身踊。","珠纓炫轉星宿搖，花鬘斗藪龍蛇動。","曲終王子啓聖人，臣父願爲唐外臣。","左右歡呼何翕習，至尊德廣之所及。","須臾百辟詣閤門，俯伏拜表賀至尊。","伏見驃人獻新樂，請書國史傳子孫。","時有擊壤老農父，暗測君心閑獨語。","聞君政化甚聖明，欲感人心致太平。","感人在近不在遠，太平由實非由聲。","觀身理國國可濟，君如心兮民如體。","體生疾苦心憯悽，民得和平君愷悌。","貞元之民若未安，驃樂雖聞君不歡。","貞元之民苟無病，驃樂不來君亦聖。","驃樂驃樂徒喧喧，不如聞此芻蕘言。"]', '["驃国乐，驃国乐，出自大海西南角。","雍羌之子舒难陀，来獻南音奉正朔。","德宗立仗御紫庭，黈纊不塞爲爾听。","玉螺一吹椎髻聳，銅鼓一擊文身踊。","珠纓炫轉星宿搖，花鬘斗藪龙蛇动。","曲終王子啓聖人，臣父願爲唐外臣。","左右歡呼何翕習，至尊德廣之所及。","須臾百辟詣閤门，俯伏拜表賀至尊。","伏见驃人獻新乐，請书国史傳子孫。","时有擊壤老農父，暗測君心闲独語。","闻君政化甚聖明，欲感人心致太平。","感人在近不在远，太平由實非由声。","观身理国国可濟，君如心兮民如體。","體生疾苦心憯悽，民得和平君愷悌。","貞元之民若未安，驃乐雖闻君不歡。","貞元之民苟無病，驃乐不来君亦聖。","驃乐驃乐徒喧喧，不如闻此芻蕘言。"]', '诗', 'shi', '', NULL, '新樂府 驃國樂	欲王化之先邇後遠也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e637621-1c10-4d92-93ac-55e41d15875b', '新樂府 縛戎人	達窮民之情也', '新乐府 縛戎人	達窮民之情也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["縛戎人，縛戎人，耳穿面破驅入秦。","天子矜憐不忍殺，詔徙東南吳與越。","黃衣小使錄姓名，領出長安乘遞行。","身被金創面多瘠，扶病徒行日一驛。","朝餐飢渴費杯盤，夜臥腥臊汚牀席。","忽逢江水憶交河，垂手齊聲嗚咽歌。","其中一虜語諸虜，爾苦非多我苦多。","同伴行人因借問，欲說喉中氣憤憤。","自云鄉管本涼原，大曆年中沒落蕃。","一落蕃中四十載，遣著皮裘繫毛帶。","唯許正朝服漢儀，斂衣整巾潛淚垂。","誓心密定歸鄉計，不使蕃中妻子知。","暗思幸有殘筋力，更恐年衰歸不得。","蕃候嚴兵鳥不飛，脫身冒死奔逃歸。","晝伏宵行經大漠，雲陰月黑風沙惡。","驚藏青冢寒草疎，偷渡黃河夜冰薄。","忽聞漢軍鼙鼓聲，路傍走出再拜迎。","游騎不聽能漢語，將軍遂縛作蕃生。","配向東南卑濕地，定無存卹空防備。","念此吞聲仰訴天，若爲辛苦度殘年。","涼原鄉井不得見，胡地妻兒虛棄捐。","沒蕃被囚思漢土，歸漢被劫爲蕃虜。","早知如此悔歸來，兩地寧如一處苦。","縛戎人，戎人之中我苦辛。","自古此冤應未有，漢心漢語吐蕃身。"]', '["縛戎人，縛戎人，耳穿面破驱入秦。","天子矜怜不忍殺，詔徙东南吳與越。","黄衣小使錄姓名，領出长安乘遞行。","身被金創面多瘠，扶病徒行日一驛。","朝餐飢渴費杯盤，夜臥腥臊汚牀席。","忽逢江水憶交河，垂手齊声嗚咽歌。","其中一虜語諸虜，爾苦非多我苦多。","同伴行人因借问，欲说喉中氣憤憤。","自云乡管本涼原，大曆年中沒落蕃。","一落蕃中四十載，遣著皮裘繫毛带。","唯許正朝服漢儀，斂衣整巾潛泪垂。","誓心密定归乡計，不使蕃中妻子知。","暗思幸有殘筋力，更恐年衰归不得。","蕃候嚴兵鸟不飞，脫身冒死奔逃归。","晝伏宵行經大漠，云陰月黑风沙惡。","驚藏青冢寒草疎，偷渡黄河夜冰薄。","忽闻漢軍鼙鼓声，路傍走出再拜迎。","游騎不听能漢語，將軍遂縛作蕃生。","配向东南卑濕地，定無存卹空防備。","念此吞声仰訴天，若爲辛苦度殘年。","涼原乡井不得见，胡地妻兒虛棄捐。","沒蕃被囚思漢土，归漢被劫爲蕃虜。","早知如此悔归来，兩地寧如一处苦。","縛戎人，戎人之中我苦辛。","自古此冤應未有，漢心漢語吐蕃身。"]', '诗', 'shi', '', NULL, '新樂府 縛戎人	達窮民之情也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b4ec8d9-bd6a-499b-9b04-595690b1f548', '新樂府 驪宮高	美天子重惜人之財力也', '新乐府 驪宮高	美天子重惜人之財力也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["高高驪山上有宮，朱樓紫殿三四重。","遲遲兮春日，玉甃暖兮溫泉溢。","嫋嫋兮秋風，山蟬鳴兮宮樹紅。","翠華不來歲月久，牆有衣兮瓦有松。","吾君在位已五載，何不一幸乎其中？","西去都門幾多地，吾君不遊有深意。","一人出兮不容易，六宮從兮百司備。","八十一車千萬騎，朝有宴飫暮有賜。","中人之產數百家，未足充君一日費。","吾君修己人不知，不自逸兮不自嬉。","吾君愛人人不識，不傷財兮不傷力。","驪宮高兮高入雲，君之來兮爲一身，君之不來兮爲萬人。"]', '["高高驪山上有宮，朱楼紫殿三四重。","遲遲兮春日，玉甃暖兮溫泉溢。","嫋嫋兮秋风，山蟬鳴兮宮樹紅。","翠华不来歲月久，牆有衣兮瓦有松。","吾君在位已五載，何不一幸乎其中？","西去都门幾多地，吾君不游有深意。","一人出兮不容易，六宮從兮百司備。","八十一车千万騎，朝有宴飫暮有賜。","中人之產數百家，未足充君一日費。","吾君修己人不知，不自逸兮不自嬉。","吾君愛人人不識，不傷財兮不傷力。","驪宮高兮高入云，君之来兮爲一身，君之不来兮爲万人。"]', '诗', 'shi', '', NULL, '新樂府 驪宮高	美天子重惜人之財力也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa557ad1-5a6f-420a-a22d-77f5bd85d565', '新樂府 百鍊鏡	辨皇王鑒也', '新乐府 百鍊镜	辨皇王鑒也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["百鍊鏡，鎔範非常規，日辰處所靈且祇。","江心波上舟中鑄，五月五日日午時。","瓊粉金膏磨瑩已，化爲一片秋潭水。","鏡成將獻蓬萊宮，揚州長吏手自封。","人間臣妾不合照，背有九五飛天龍。","人人呼爲天子鏡，我有一言聞太宗。","太宗常以人爲鏡，鑒古鑒今不鑒容。","四海安危居掌內，百王治亂懸心中。","乃知天子別有鏡，不是揚州百鍊銅。"]', '["百鍊镜，鎔範非常規，日辰处所靈且祇。","江心波上舟中鑄，五月五日日午时。","瓊粉金膏磨瑩已，化爲一片秋潭水。","镜成將獻蓬萊宮，揚州长吏手自封。","人间臣妾不合照，背有九五飞天龙。","人人呼爲天子镜，我有一言闻太宗。","太宗常以人爲镜，鑒古鑒今不鑒容。","四海安危居掌內，百王治亂懸心中。","乃知天子別有镜，不是揚州百鍊銅。"]', '诗', 'shi', '', NULL, '新樂府 百鍊鏡	辨皇王鑒也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5df437ca-32ec-4efe-872b-0b836f0ab42f', '新樂府 青石		激忠烈也', '新乐府 青石		激忠烈也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["青石出自藍田山，兼車運載來長安。","工人磨琢欲何用，石不能言我代言。","不願作人家墓前神道碣，墳土未乾名已滅。","不願作官家道旁德政碑，不鐫實錄鐫虛辭。","願爲顏氏段氏碑，雕鏤太尉與太師。","刻此兩片堅貞質，狀彼二人忠烈姿。","義心如石屹不轉，死節如石確不移。","如觀奮擊朱泚日，似見叱訶希烈時。","各於其上題名諡，一置高山一沈水。","陵谷雖遷碑獨存，骨化爲塵名不死。","長使不忠不烈臣，觀碑改節慕爲人。","慕爲人，勸事君。"]', '["青石出自藍田山，兼车運載来长安。","工人磨琢欲何用，石不能言我代言。","不願作人家墓前神道碣，墳土未乾名已滅。","不願作官家道旁德政碑，不鐫實錄鐫虛辞。","願爲顏氏段氏碑，雕鏤太尉與太師。","刻此兩片堅貞質，狀彼二人忠烈姿。","義心如石屹不轉，死節如石確不移。","如观奮擊朱泚日，似见叱訶希烈时。","各於其上題名諡，一置高山一沈水。","陵谷雖遷碑独存，骨化爲塵名不死。","长使不忠不烈臣，观碑改節慕爲人。","慕爲人，勸事君。"]', '诗', 'shi', '', NULL, '新樂府 青石		激忠烈也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec6b6d12-1312-470c-b4ea-4eed7386a04d', '新樂府 兩朱閣	刺佛寺寖多也', '新乐府 兩朱閣	刺佛寺寖多也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["兩朱閣，南北相對起。","借問何人家，貞元雙帝子。","帝子吹簫雙得仙，五雲飄颻飛上天。","第宅亭臺不將去，化爲佛寺在人間。","妝閤伎樓何寂靜，柳似舞腰池似鏡。","花落黃昏悄悄時，不聞歌吹聞鐘磬。","寺門敕牓金字書，尼院佛庭寬有餘。","青苔明月多閑地，比屋疲人無處居。","憶昨平陽宅初置，吞幷平人幾家地。","仙去雙雙作梵宮，漸恐人間盡爲寺。"]', '["兩朱閣，南北相对起。","借问何人家，貞元雙帝子。","帝子吹簫雙得仙，五云飄颻飞上天。","第宅亭台不將去，化爲佛寺在人间。","妝閤伎楼何寂静，柳似舞腰池似镜。","花落黄昏悄悄时，不闻歌吹闻鐘磬。","寺门敕牓金字书，尼院佛庭寬有餘。","青苔明月多闲地，比屋疲人無处居。","憶昨平陽宅初置，吞幷平人幾家地。","仙去雙雙作梵宮，漸恐人间尽爲寺。"]', '诗', 'shi', '', NULL, '新樂府 兩朱閣	刺佛寺寖多也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0504d98-1a16-4054-a991-ef932f59d7a6', '新樂府 西涼伎	刺封疆之臣也', '新乐府 西涼伎	刺封疆之臣也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["西涼伎，假面胡人假獅子。","刻木爲頭絲作尾，金鍍眼睛銀帖齒。","奮迅毛衣擺雙耳，如從流沙來萬里。","紫髯深目兩胡兒，鼓舞跳梁前致辭。","應似涼州未陷日，安西都護進來時。","須臾云得新消息，安西路絕歸不得。","泣向獅子涕雙垂，涼州陷沒知不知。","獅子回頭向西望，哀吼一聲觀者悲。","貞元邊將愛此曲，醉坐笑看看不足。","娛賓犒士宴監軍，獅子胡兒長在目。","有一征夫年七十，見弄涼州低面泣。","泣罷斂手白將軍，主憂臣辱昔所聞。","自從天寶兵戈起，犬戎日夜吞西鄙。","涼州陷來四十年，河隴侵將七千里。","平時安西萬里疆，今日邊防在鳳翔。","緣邊空屯十萬卒，飽食溫衣閑過日。","遺民腸斷在涼州，將卒相看無意收。","天子每思長痛惜，將軍欲說合慙羞。","奈何仍看西涼伎，取笑資歡無所媿。","縱無智力未能收，忍取西涼弄爲戲。"]', '["西涼伎，假面胡人假獅子。","刻木爲头絲作尾，金鍍眼睛銀帖齒。","奮迅毛衣擺雙耳，如從流沙来万里。","紫髯深目兩胡兒，鼓舞跳梁前致辞。","應似涼州未陷日，安西都護進来时。","須臾云得新消息，安西路絕归不得。","泣向獅子涕雙垂，涼州陷沒知不知。","獅子回头向西望，哀吼一声观者悲。","貞元邊將愛此曲，醉坐笑看看不足。","娛賓犒士宴監軍，獅子胡兒长在目。","有一征夫年七十，见弄涼州低面泣。","泣罷斂手白將軍，主憂臣辱昔所闻。","自從天寶兵戈起，犬戎日夜吞西鄙。","涼州陷来四十年，河隴侵將七千里。","平时安西万里疆，今日邊防在鳳翔。","緣邊空屯十万卒，飽食溫衣闲過日。","遺民腸斷在涼州，將卒相看無意收。","天子每思长痛惜，將軍欲说合慙羞。","奈何仍看西涼伎，取笑資歡無所媿。","縱無智力未能收，忍取西涼弄爲戲。"]', '诗', 'shi', '', NULL, '新樂府 西涼伎	刺封疆之臣也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e798517-f37f-47cb-b1f4-6b9d3ab3f180', '新樂府 八駿圖	戒奇物懲佚遊也', '新乐府 八駿圖	戒奇物懲佚游也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["穆王八駿天馬駒，後人愛之寫爲圖。","背如龍兮頸如象，骨聳筋高脂肉壯。","日行萬里疾如飛，穆王獨乘何所之。","四荒八極蹋欲徧，三十二蹄無歇時。","屬車軸折趁不及，黃屋草生棄若遺。","瑤池西赴王母宴，七廟經年不親薦。","璧臺南與盛姬遊，明堂不復朝諸侯。","白雲黃竹歌聲動，一人荒樂萬人愁。","周從后稷至文武，積德累功世勤苦。","豈知纔及四代孫，心輕王業如灰土。","由來尤物不在大，能蕩君心則爲害。","文帝却之不肯乘，千里馬去漢道興。","穆王得之不爲戒，八駿駒來周室壞。","至今此物尚稱珍，不知房星之精下爲怪。","八駿圖，君莫愛。"]', '["穆王八駿天马駒，後人愛之寫爲圖。","背如龙兮頸如象，骨聳筋高脂肉壯。","日行万里疾如飞，穆王独乘何所之。","四荒八極蹋欲徧，三十二蹄無歇时。","屬车軸折趁不及，黄屋草生棄若遺。","瑤池西赴王母宴，七廟經年不親薦。","璧台南與盛姬游，明堂不复朝諸侯。","白云黄竹歌声动，一人荒乐万人愁。","周從后稷至文武，積德累功世勤苦。","豈知纔及四代孫，心轻王業如灰土。","由来尤物不在大，能蕩君心則爲害。","文帝却之不肯乘，千里马去漢道兴。","穆王得之不爲戒，八駿駒来周室壞。","至今此物尚稱珍，不知房星之精下爲怪。","八駿圖，君莫愛。"]', '诗', 'shi', '', NULL, '新樂府 八駿圖	戒奇物懲佚遊也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20261028-0474-4ce0-b069-2b1c50c57035', '新樂府 澗底松	念寒儁也', '新乐府 澗底松	念寒儁也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有松百尺大十圍，生在澗底寒且卑。","澗深山險人路絕，老死不逢工度之。","天子明堂欠梁木，此求彼有兩不知。","誰喻蒼蒼造物意，但與之材不與地。","金張世祿原憲貧，牛衣寒賤貂蟬貴。","貂蟬與牛衣，高下雖有殊。","高者未必賢，下者未必愚。","君不見沈沈海底生珊瑚，歷歷天上種白榆。"]', '["有松百尺大十圍，生在澗底寒且卑。","澗深山險人路絕，老死不逢工度之。","天子明堂欠梁木，此求彼有兩不知。","誰喻蒼蒼造物意，但與之材不與地。","金張世祿原憲貧，牛衣寒賤貂蟬貴。","貂蟬與牛衣，高下雖有殊。","高者未必賢，下者未必愚。","君不见沈沈海底生珊瑚，歷歷天上種白榆。"]', '诗', 'shi', '', NULL, '新樂府 澗底松	念寒儁也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c7b03ca-fd0c-463e-816f-aba337f2ae1a', '新樂府 牡丹芳	美天子憂農也', '新乐府 牡丹芳	美天子憂農也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["牡丹芳，牡丹芳，黃金蘂綻紅玉房。","千片赤英霞爛爛，百枝絳點燈煌煌。","照地初開錦繡段，當風不結蘭麝囊。","仙人琪樹白無色，王母桃花小不香。","宿露輕盈泛紫豔，朝陽照耀生紅光。","紅紫二色間深淺，向背萬態隨低昂。","映葉多情隱羞面，臥叢無力含醉妝。","低嬌笑容疑掩口，凝思怨人如斷腸。","穠姿貴彩信奇絕，雜卉亂花無比方。","石竹金錢何細碎，芙蓉芍藥苦尋常。","遂使王公與鄉士，遊花冠蓋日相望。","庳車輭轝貴公主，香衫細馬豪家郎。","衛公宅靜閉東院，西明寺深開北廊。","戲蝶雙舞看人久，殘鶯一聲春日長。","共愁日照芳難駐，仍張帷幕垂陰涼。","花開花落二十日，一城之人皆若狂。","三代以還文勝質，人心重華不重實。","重華直至牡丹芳，其來有漸非今日。","元和天子憂農桑，卹下動天天降祥。","去歲嘉禾生九穗，田中寂莫無人至。","今年瑞麥分兩岐，君心獨喜無人知。","無人知，可歎息，我願暫求造化力。","減却牡丹妖豔色，少迴鄉士愛花心，同似吾君憂稼穡。"]', '["牡丹芳，牡丹芳，黄金蘂綻紅玉房。","千片赤英霞爛爛，百枝絳点灯煌煌。","照地初开錦繡段，當风不結蘭麝囊。","仙人琪樹白無色，王母桃花小不香。","宿露轻盈泛紫豔，朝陽照耀生紅光。","紅紫二色间深淺，向背万態隨低昂。","映葉多情隐羞面，臥叢無力含醉妝。","低嬌笑容疑掩口，凝思怨人如斷腸。","穠姿貴彩信奇絕，杂卉亂花無比方。","石竹金錢何細碎，芙蓉芍藥苦尋常。","遂使王公與乡士，游花冠蓋日相望。","庳车輭轝貴公主，香衫細马豪家郎。","衛公宅静閉东院，西明寺深开北廊。","戲蝶雙舞看人久，殘鶯一声春日长。","共愁日照芳难駐，仍張帷幕垂陰涼。","花开花落二十日，一城之人皆若狂。","三代以還文勝質，人心重华不重實。","重华直至牡丹芳，其来有漸非今日。","元和天子憂農桑，卹下动天天降祥。","去歲嘉禾生九穗，田中寂莫無人至。","今年瑞麦分兩岐，君心独喜無人知。","無人知，可歎息，我願暫求造化力。","減却牡丹妖豔色，少迴乡士愛花心，同似吾君憂稼穡。"]', '诗', 'shi', '', NULL, '新樂府 牡丹芳	美天子憂農也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0732c4d9-21fc-4c0a-8e4a-2c44e5df8833', '新樂府 紅線毯	憂蠶桑之費也', '新乐府 紅線毯	憂蠶桑之費也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紅線毯，擇蠒繰絲清水煮。","揀絲練線紅藍染，染爲紅線紅於藍。","織作披香殿上毯，披香殿廣十丈餘。","紅線織成可殿鋪，綵絲茸茸香拂拂。","線輭花虛不勝物，美人蹋上歌舞來。","羅韤繡鞋隨步沒，太原毯澀毳縷硬。","蜀都褥薄錦花冷，不如此毯溫且柔。","年年十月來宣州，宣城太守加樣織。","自謂爲臣能竭力，百夫同擔進宮中。","線厚絲多卷不得，宣城太守知不知。","一丈毯，千兩絲，地不知寒人要暖，少奪人衣作地衣。"]', '["紅線毯，擇蠒繰絲清水煮。","揀絲練線紅藍染，染爲紅線紅於藍。","织作披香殿上毯，披香殿廣十丈餘。","紅線织成可殿鋪，綵絲茸茸香拂拂。","線輭花虛不勝物，美人蹋上歌舞来。","羅韤繡鞋隨步沒，太原毯澀毳縷硬。","蜀都褥薄錦花冷，不如此毯溫且柔。","年年十月来宣州，宣城太守加樣织。","自謂爲臣能竭力，百夫同擔進宮中。","線厚絲多卷不得，宣城太守知不知。","一丈毯，千兩絲，地不知寒人要暖，少奪人衣作地衣。"]', '诗', 'shi', '', NULL, '新樂府 紅線毯	憂蠶桑之費也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6447c346-b037-46bd-b16f-11b772c1e811', '新樂府 杜陵叟	傷農夫之困也', '新乐府 杜陵叟	傷農夫之困也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["杜陵叟，杜陵居，歲種薄田一頃餘。","三月無雨旱風起，麥苗不秀多黃死。","九月降霜秋早寒，禾穗未熟皆青乾。","長吏明知不申破，急斂暴徵求考課。","典桑賣地納官租，明年衣食將何如。","剝我身上帛，奪我口中粟。","虐人害物即豺狼，何必鉤爪鋸牙食人肉。","不知何人奏皇帝，帝心惻隱知人弊。","白麻紙上書德音，京畿盡放今年稅。","昨日里胥方到門，手持尺牒牓鄉村。","十家租稅九家畢，虛受吾君蠲免恩。"]', '["杜陵叟，杜陵居，歲種薄田一頃餘。","三月無雨旱风起，麦苗不秀多黄死。","九月降霜秋早寒，禾穗未熟皆青乾。","长吏明知不申破，急斂暴徵求考課。","典桑賣地納官租，明年衣食將何如。","剝我身上帛，奪我口中粟。","虐人害物即豺狼，何必鉤爪鋸牙食人肉。","不知何人奏皇帝，帝心惻隐知人弊。","白麻紙上书德音，京畿尽放今年稅。","昨日里胥方到门，手持尺牒牓乡村。","十家租稅九家畢，虛受吾君蠲免恩。"]', '诗', 'shi', '', NULL, '新樂府 杜陵叟	傷農夫之困也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35f446ec-9bd1-4df3-bb94-7b3b45888f24', '新樂府 繚綾		念女工之勞也', '新乐府 繚綾		念女工之勞也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["繚綾繚綾何所似，不似羅綃與紈綺。","應似天台山上月明前，四十五尺瀑布泉。","中有文章又奇絕，地鋪白煙花簇雪。","織者何人衣者誰，越溪寒女漢宮姬。","去年中使宣口敕，天上取樣人間織。","織爲雲外秋雁行，染作江南春水色。","廣裁衫袖長製帬，金斗熨波刀翦紋。","異彩奇文相隱映，轉側看花花不定。","昭陽舞人恩正深，春衣一對直千金。","汗霑粉汙不再著，曳土蹋泥無惜心。","繚綾織成費功績，莫比尋常繒與帛。","絲細繰多女手疼，扎扎千聲不盈尺。","昭陽殿裏歌舞人，若見織時應也惜。"]', '["繚綾繚綾何所似，不似羅綃與紈綺。","應似天台山上月明前，四十五尺瀑布泉。","中有文章又奇絕，地鋪白煙花簇雪。","织者何人衣者誰，越溪寒女漢宮姬。","去年中使宣口敕，天上取樣人间织。","织爲云外秋雁行，染作江南春水色。","廣裁衫袖长製帬，金斗熨波刀翦紋。","異彩奇文相隐映，轉側看花花不定。","昭陽舞人恩正深，春衣一对直千金。","汗霑粉汙不再著，曳土蹋泥無惜心。","繚綾织成費功績，莫比尋常繒與帛。","絲細繰多女手疼，扎扎千声不盈尺。","昭陽殿裏歌舞人，若见织时應也惜。"]', '诗', 'shi', '', NULL, '新樂府 繚綾		念女工之勞也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0677c90-ea54-4de6-94cf-e6af2eea1755', '新樂府 賣炭翁	苦官市也', '新乐府 賣炭翁	苦官市也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["賣炭翁，伐薪燒炭南山中。","滿面塵灰煙火色，兩鬢蒼蒼十指黑。","賣炭得錢何所營，身上衣裳口中食。","可憐身上衣正單，心憂炭賤願天寒。","夜來城上一尺雪，曉駕炭車輾冰轍。","牛困人飢日已高，市南門外泥中歇。","翩翩兩騎來是誰，黃衣使者白衫兒。","手把文書口稱敕，迴車叱牛牽向北。","一車炭，千餘斤，官使驅將惜不得。","半匹紅紗一丈綾，繫向牛頭充炭直。"]', '["賣炭翁，伐薪燒炭南山中。","满面塵灰煙火色，兩鬢蒼蒼十指黑。","賣炭得錢何所營，身上衣裳口中食。","可怜身上衣正單，心憂炭賤願天寒。","夜来城上一尺雪，晓駕炭车輾冰轍。","牛困人飢日已高，市南门外泥中歇。","翩翩兩騎来是誰，黄衣使者白衫兒。","手把文书口稱敕，迴车叱牛牽向北。","一车炭，千餘斤，官使驱將惜不得。","半匹紅紗一丈綾，繫向牛头充炭直。"]', '诗', 'shi', '', NULL, '新樂府 賣炭翁	苦官市也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('572792cc-60ac-4b58-87fa-836f0f7d7b00', '新樂府 母別子	刺新間舊也', '新乐府 母別子	刺新间旧也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["母別子，子別母，白日無光哭聲苦。","關西驃騎大將軍，去年破虜新策勳。","敕賜金錢二百萬，洛陽迎得如花人。","新人迎來舊人棄，掌上蓮花眼中刺。","迎新棄舊未足悲，悲在君家留兩兒。","一始扶行一初坐，坐啼行哭牽人衣。","以汝夫婦新燕婉，使我母子生別離。","不如林中烏與鵲，母不失雛雄伴雌。","應似園中桃李樹，花落隨風子在枝。","新人新人聽我語，洛陽無限紅樓女。","但願將軍重立功，更有新人勝於汝。"]', '["母別子，子別母，白日無光哭声苦。","关西驃騎大將軍，去年破虜新策勳。","敕賜金錢二百万，洛陽迎得如花人。","新人迎来旧人棄，掌上蓮花眼中刺。","迎新棄旧未足悲，悲在君家留兩兒。","一始扶行一初坐，坐啼行哭牽人衣。","以汝夫婦新燕婉，使我母子生別離。","不如林中烏與鵲，母不失雛雄伴雌。","應似园中桃李樹，花落隨风子在枝。","新人新人听我語，洛陽無限紅楼女。","但願將軍重立功，更有新人勝於汝。"]', '诗', 'shi', '', NULL, '新樂府 母別子	刺新間舊也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f81bd1e9-faef-44b9-83a4-1066d6e690f8', '新樂府 陰山道	疾貪虜也', '新乐府 陰山道	疾貪虜也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["陰山道，陰山道，紇邏敦肥水泉好。","每至戎人送馬時，道旁千里無纖草。","草盡泉枯馬病羸，飛龍但印骨與皮。","五十匹縑易一匹，縑去馬來無了日。","養無所用去非宜，每歲死傷十六七。","縑絲不足女工苦，疎織短截充匹數。","藕絲蛛網三丈餘，迴紇訴稱無用處。","咸安公主號可敦，遠爲可汗頻奏論。","元和二年下新敕，內出金帛酬馬直。","仍詔江淮馬價縑，從此不令疎短織。","合羅將軍呼萬歲，捧授金銀與縑綵。","誰知黠虜啓貪心，明年馬多來一倍。","縑漸好，馬漸多，陰山虜，奈爾何。"]', '["陰山道，陰山道，紇邏敦肥水泉好。","每至戎人送马时，道旁千里無纖草。","草尽泉枯马病羸，飞龙但印骨與皮。","五十匹縑易一匹，縑去马来無了日。","養無所用去非宜，每歲死傷十六七。","縑絲不足女工苦，疎织短截充匹數。","藕絲蛛網三丈餘，迴紇訴稱無用处。","咸安公主號可敦，远爲可汗頻奏論。","元和二年下新敕，內出金帛酬马直。","仍詔江淮马價縑，從此不令疎短织。","合羅將軍呼万歲，捧授金銀與縑綵。","誰知黠虜啓貪心，明年马多来一倍。","縑漸好，马漸多，陰山虜，奈爾何。"]', '诗', 'shi', '', NULL, '新樂府 陰山道	疾貪虜也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d48559df-00e3-499c-b62a-e78bf137d86a', '新樂府 時世妝	儆戎也', '新乐府 时世妝	儆戎也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["時世妝，時世妝，出自城中傳四方。","時世流行無遠近，顋不施朱面無粉。","烏膏注脣脣似泥，雙眉畫作八字低。","妍媸黑白失本態，妝成盡似含悲啼。","圓鬟無鬢堆髻樣，斜紅不暈赭面狀。","昔聞被髮伊川中，辛有見之知有戎。","元和妝梳君記取，髻堆面赭非華風。"]', '["时世妝，时世妝，出自城中傳四方。","时世流行無远近，顋不施朱面無粉。","烏膏注脣脣似泥，雙眉畫作八字低。","妍媸黑白失本態，妝成尽似含悲啼。","圓鬟無鬢堆髻樣，斜紅不暈赭面狀。","昔闻被髮伊川中，辛有见之知有戎。","元和妝梳君記取，髻堆面赭非华风。"]', '诗', 'shi', '', NULL, '新樂府 時世妝	儆戎也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29be46eb-568b-419f-b5d3-9110e65dea67', '新樂府 李夫人	鑒嬖惑也', '新乐府 李夫人	鑒嬖惑也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["漢武帝，初喪李夫人。","夫人病時不肯別，死後留得生前恩。","君恩不盡念未已，甘泉殿裏令寫真。","丹青畫出竟何益，不言不笑愁殺人。","又令方士合靈藥，玉釜煎鍊金鑪焚。","九華帳深夜悄悄，反魂香降夫人魂。","夫人之魂在何許，香煙引到焚香處。","既來何苦不須臾，縹緲悠揚還滅去。","去何速兮來何遲，是耶非耶兩不知。","翠蛾髣髴平生貌，不似昭陽寢疾時。","魂之不來君心苦，魂之來兮君亦悲。","背燈隔帳不得語，安用暫來還見違。","傷心不獨漢武帝，自古及今皆若斯。","君不見穆王三日哭，重璧臺前傷盛姬。","又不見泰陵一掬淚，馬嵬坡下念楊妃。","縱令妍姿豔質化爲土，此恨長在無銷期。","生亦惑，死亦惑，尤物惑人忘不得。","人非木石皆有情，不如不遇傾城色。"]', '["漢武帝，初喪李夫人。","夫人病时不肯別，死後留得生前恩。","君恩不尽念未已，甘泉殿裏令寫真。","丹青畫出竟何益，不言不笑愁殺人。","又令方士合靈藥，玉釜煎鍊金鑪焚。","九华帳深夜悄悄，反魂香降夫人魂。","夫人之魂在何許，香煙引到焚香处。","既来何苦不須臾，縹緲悠揚還滅去。","去何速兮来何遲，是耶非耶兩不知。","翠蛾髣髴平生貌，不似昭陽寢疾时。","魂之不来君心苦，魂之来兮君亦悲。","背灯隔帳不得語，安用暫来還见違。","傷心不独漢武帝，自古及今皆若斯。","君不见穆王三日哭，重璧台前傷盛姬。","又不见泰陵一掬泪，马嵬坡下念楊妃。","縱令妍姿豔質化爲土，此恨长在無銷期。","生亦惑，死亦惑，尤物惑人忘不得。","人非木石皆有情，不如不遇傾城色。"]', '诗', 'shi', '', NULL, '新樂府 李夫人	鑒嬖惑也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d47c928-e6dd-4417-a9a5-acb7d4272e84', '新樂府 陵園妾	憐幽閉也', '新乐府 陵园妾	怜幽閉也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["陵園妾，顏色如花命如葉。","命如葉薄將奈何，一奉寢宮年月多。","年月多，時光換，春愁秋思知何限。","青絲髮落叢鬢疎，紅玉膚銷繫帬慢。","憶昔宮中被妬猜，因讒得罪配陵來。","老母啼呼趁車別，中官監送鏁門迴。","山宮一閉無開日，未死此身不令出。","松門到曉月裴回，柏城盡日風蕭瑟。","松門柏城幽閉深，聞蟬聽燕感光陰。","眼看菊蘂重陽淚，手把棃花寒食心。","把花掩淚無人見，綠蕪牆繞青苔院。","四季徒支妝粉錢，三朝不識君王面。","遙想六宮奉至尊，宣徽雪夜浴堂春。","雨露之恩不及者，猶聞不啻三千人。","三千人，我爾君恩何厚薄。","願令輪轉直陵園，三歲一來均苦樂。"]', '["陵园妾，顏色如花命如葉。","命如葉薄將奈何，一奉寢宮年月多。","年月多，时光換，春愁秋思知何限。","青絲髮落叢鬢疎，紅玉膚銷繫帬慢。","憶昔宮中被妬猜，因讒得罪配陵来。","老母啼呼趁车別，中官監送鏁门迴。","山宮一閉無开日，未死此身不令出。","松门到晓月裴回，柏城尽日风蕭瑟。","松门柏城幽閉深，闻蟬听燕感光陰。","眼看菊蘂重陽泪，手把棃花寒食心。","把花掩泪無人见，綠蕪牆繞青苔院。","四季徒支妝粉錢，三朝不識君王面。","遙想六宮奉至尊，宣徽雪夜浴堂春。","雨露之恩不及者，猶闻不啻三千人。","三千人，我爾君恩何厚薄。","願令輪轉直陵园，三歲一来均苦乐。"]', '诗', 'shi', '', NULL, '新樂府 陵園妾	憐幽閉也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88f00440-4d69-468b-b043-7962fa0cf3d1', '新樂府 鹽商婦	惡幸人也', '新乐府 鹽商婦	惡幸人也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鹽商婦，多金帛，不事田農與蠶績。","南北東西不失家，風水爲鄉船作宅。","本是揚州小家女，嫁得西江大商客。","綠鬟富去金釵多，皓腕肥來銀釧窄。","前呼蒼頭後叱婢，問爾因何得如此。","壻作鹽商十五年，不屬州縣屬天子。","每年鹽利入官時，少入官家多入私。","官家利薄私家厚，鹽鐵尚書遠不知。","何況江頭魚米賤，紅膾黃橙香稻飯。","飽食濃妝倚柁樓，兩朵紅顋花欲綻。","鹽商婦，有幸嫁鹽商。","終朝美飯食，終歲好衣裳。","好衣美食來何處，亦須慙媿桑弘羊。","桑弘羊，死已久，不獨漢時今亦有。"]', '["鹽商婦，多金帛，不事田農與蠶績。","南北东西不失家，风水爲乡船作宅。","本是揚州小家女，嫁得西江大商客。","綠鬟富去金釵多，皓腕肥来銀釧窄。","前呼蒼头後叱婢，问爾因何得如此。","壻作鹽商十五年，不屬州縣屬天子。","每年鹽利入官时，少入官家多入私。","官家利薄私家厚，鹽鐵尚书远不知。","何況江头鱼米賤，紅膾黄橙香稻飯。","飽食濃妝倚柁楼，兩朵紅顋花欲綻。","鹽商婦，有幸嫁鹽商。","終朝美飯食，終歲好衣裳。","好衣美食来何处，亦須慙媿桑弘羊。","桑弘羊，死已久，不独漢时今亦有。"]', '诗', 'shi', '', NULL, '新樂府 鹽商婦	惡幸人也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0973992e-aa63-4570-b3be-b0991b326f5c', '新樂府 杏爲梁	刺居處僭也', '新乐府 杏爲梁	刺居处僭也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["杏爲梁，桂爲柱，何人堂室李開府。","碧砌紅軒色未乾，去年身歿今移主。","高其牆，大其門，誰家第宅盧將軍。","素泥朱版光未滅，今日官收別賜人。","開府之堂將軍宅，造未成時頭已白。","逆旅重居逆旅中，心是主人身是客。","更有愚夫念身後，心雖甚長計非久。","窮奢極麗越規模，付子傳孫令保守。","莫教門外過客聞，撫掌回頭笑殺君。","君不見馬家宅，尚猶存，宅門題作奉誠園。","君不見魏家宅，屬他人，詔贖賜還五代孫。","儉存奢失今在目，安用高牆圍大屋。"]', '["杏爲梁，桂爲柱，何人堂室李开府。","碧砌紅軒色未乾，去年身歿今移主。","高其牆，大其门，誰家第宅盧將軍。","素泥朱版光未滅，今日官收別賜人。","开府之堂將軍宅，造未成时头已白。","逆旅重居逆旅中，心是主人身是客。","更有愚夫念身後，心雖甚长計非久。","窮奢極丽越規模，付子傳孫令保守。","莫教门外過客闻，撫掌回头笑殺君。","君不见马家宅，尚猶存，宅门題作奉誠园。","君不见魏家宅，屬他人，詔贖賜還五代孫。","儉存奢失今在目，安用高牆圍大屋。"]', '诗', 'shi', '', NULL, '新樂府 杏爲梁	刺居處僭也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68553c8b-65c4-43d4-939b-d11b27ffa05f', '新樂府 井底引銀缾	止淫奔也', '新乐府 井底引銀缾	止淫奔也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["井底引銀缾，銀缾欲上絲繩絕。","石上磨玉簪，玉簪欲成中央折。","缾沈簪折知奈何，似妾今朝與君別。","憶昔在家爲女時，人言舉動有殊姿。","嬋娟兩鬢秋蟬翼，宛轉雙蛾遠山色。","笑隨戲伴後園中，此時與君未相識。","妾弄青梅憑短牆，君騎白馬傍垂楊。","牆頭馬上遙相顧，一見知君即斷腸。","知君斷腸共君語，君指南山松柏樹。","感君松柏化爲心，闇合雙鬟逐君去。","到君家舍五六年，君家大人頻有言。","聘則爲妻奔是妾，不堪主祀奉蘋蘩。","終知君家不可住，其奈出門無去處。","豈無父母在高堂，亦有親情滿故鄉。","潛來更不通消息，今日悲羞歸不得。","爲君一日恩，誤妾百年身。","寄言癡小人家女，慎勿將身輕許人。"]', '["井底引銀缾，銀缾欲上絲繩絕。","石上磨玉簪，玉簪欲成中央折。","缾沈簪折知奈何，似妾今朝與君別。","憶昔在家爲女时，人言舉动有殊姿。","嬋娟兩鬢秋蟬翼，宛轉雙蛾远山色。","笑隨戲伴後园中，此时與君未相識。","妾弄青梅憑短牆，君騎白马傍垂楊。","牆头马上遙相顧，一见知君即斷腸。","知君斷腸共君語，君指南山松柏樹。","感君松柏化爲心，闇合雙鬟逐君去。","到君家舍五六年，君家大人頻有言。","聘則爲妻奔是妾，不堪主祀奉蘋蘩。","終知君家不可住，其奈出门無去处。","豈無父母在高堂，亦有親情满故乡。","潛来更不通消息，今日悲羞归不得。","爲君一日恩，誤妾百年身。","寄言癡小人家女，慎勿將身轻許人。"]', '诗', 'shi', '', NULL, '新樂府 井底引銀缾	止淫奔也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a987d989-8c70-482d-becf-a79479ca0f68', '新樂府 官牛		諷執政也', '新乐府 官牛		諷執政也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["官牛官牛駕官車，滻水岸邊般載沙。","一石沙，幾斤重，朝載暮載將何用。","載向五門官道西，綠槐陰下鋪沙堤。","昨來新拜右丞相，恐怕泥塗汚馬蹄。","右丞相，馬蹄蹋沙雖淨潔，牛領牽車欲流血。","右丞相，但能濟人治國調陰陽，官牛領穿亦無妨。"]', '["官牛官牛駕官车，滻水岸邊般載沙。","一石沙，幾斤重，朝載暮載將何用。","載向五门官道西，綠槐陰下鋪沙堤。","昨来新拜右丞相，恐怕泥塗汚马蹄。","右丞相，马蹄蹋沙雖淨潔，牛領牽车欲流血。","右丞相，但能濟人治国調陰陽，官牛領穿亦無妨。"]', '诗', 'shi', '', NULL, '新樂府 官牛		諷執政也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88ed338f-17a4-4a27-8f74-fc824b57735b', '新樂府 紫毫筆	譏失職也', '新乐府 紫毫笔	譏失職也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紫毫筆，尖如錐兮利如刀。","江南石上有老兔，喫竹飲泉生紫毫。","宣城之人采爲筆，千萬毛中揀一毫。","毫雖輕，功甚重，管勒工名充歲貢。","君兮臣兮勿輕用，勿輕用，將何如。","願賜東西府御史，願頒左右臺起居。","搦管趨入黃金闕，抽毫立在白玉除。","臣有奸邪正衙奏，君有動言直筆書。","起居郎，侍御史，爾知紫毫不易致。","每歲宣城進筆時，紫毫之價如金貴。","慎勿空將彈失儀，慎勿空將錄制詞。"]', '["紫毫笔，尖如錐兮利如刀。","江南石上有老兔，喫竹饮泉生紫毫。","宣城之人采爲笔，千万毛中揀一毫。","毫雖轻，功甚重，管勒工名充歲貢。","君兮臣兮勿轻用，勿轻用，將何如。","願賜东西府御史，願頒左右台起居。","搦管趨入黄金闕，抽毫立在白玉除。","臣有奸邪正衙奏，君有动言直笔书。","起居郎，侍御史，爾知紫毫不易致。","每歲宣城進笔时，紫毫之價如金貴。","慎勿空將彈失儀，慎勿空將錄制词。"]', '诗', 'shi', '', NULL, '新樂府 紫毫筆	譏失職也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef3c51b2-f0a5-4d9b-8ae3-2a24b342ddee', '新樂府 隋堤柳	憫亡國也', '新乐府 隋堤柳	憫亡国也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["隋堤柳，歲久年深盡衰朽。","風飄飄兮雨蕭蕭，三株兩株汴河口。","老枝病葉愁殺人，曾經大業年中春。","大業年中煬天子，種柳成行夾流水。","西自黃河東至淮，綠陰一千三百里。","大業末年春暮月，柳色如煙絮如雪。","南幸江都恣佚遊，應將此柳繫龍舟。","紫髯郎將護錦纜，青娥御史直迷樓。","海內財力此時竭，舟中歌笑何日休。","上荒下困勢不久，宗社之危如綴旒。","煬天子，自言福祚長無窮，豈知皇子封酅公。","龍舟未過彭城閤，義旗已入長安宮。","蕭牆禍生人事變，晏駕不得歸秦中。","土墳數尺何處葬，吳公臺下多悲風。","二百年來汴河路，沙草和煙朝復暮。","後王何以鑒前王，請看隋堤亡國樹。"]', '["隋堤柳，歲久年深尽衰朽。","风飄飄兮雨蕭蕭，三株兩株汴河口。","老枝病葉愁殺人，曾經大業年中春。","大業年中煬天子，種柳成行夾流水。","西自黄河东至淮，綠陰一千三百里。","大業末年春暮月，柳色如煙絮如雪。","南幸江都恣佚游，應將此柳繫龙舟。","紫髯郎將護錦纜，青娥御史直迷楼。","海內財力此时竭，舟中歌笑何日休。","上荒下困勢不久，宗社之危如綴旒。","煬天子，自言福祚长無窮，豈知皇子封酅公。","龙舟未過彭城閤，義旗已入长安宮。","蕭牆禍生人事变，晏駕不得归秦中。","土墳數尺何处葬，吳公台下多悲风。","二百年来汴河路，沙草和煙朝复暮。","後王何以鑒前王，請看隋堤亡国樹。"]', '诗', 'shi', '', NULL, '新樂府 隋堤柳	憫亡國也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('574d431d-12ab-493d-96d3-41a76871015c', '新樂府 草茫茫	懲厚葬也', '新乐府 草茫茫	懲厚葬也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["草茫茫，土蒼蒼，蒼蒼茫茫在何處，驪山脚下秦皇墓。","墓中下涸二重泉，當時自以爲深固。","下流水銀象江海，上綴珠光作烏兔。","別爲天地於其間，擬將富貴隨身去。","一朝盜掘墳陵破，龍椁神堂三月火。","可憐寶玉歸人間，暫借泉中買身禍。","奢者狼藉儉者安，一凶一吉在眼前。","憑君回首向南望，漢文葬在霸陵原。"]', '["草茫茫，土蒼蒼，蒼蒼茫茫在何处，驪山脚下秦皇墓。","墓中下涸二重泉，當时自以爲深固。","下流水銀象江海，上綴珠光作烏兔。","別爲天地於其间，擬將富貴隨身去。","一朝盜掘墳陵破，龙椁神堂三月火。","可怜寶玉归人间，暫借泉中買身禍。","奢者狼藉儉者安，一凶一吉在眼前。","憑君回首向南望，漢文葬在霸陵原。"]', '诗', 'shi', '', NULL, '新樂府 草茫茫	懲厚葬也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e4acce7-ecde-492c-9935-9a77ea798fdc', '新樂府 古冢狐	戒豔色也', '新乐府 古冢狐	戒豔色也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["古冢狐，妖且老，化爲婦人顏色好。","頭變雲鬟面變妝，大尾曳作長紅裳。","徐徐行傍荒村路，日欲暮時人靜處。","或歌或舞或悲啼，翠眉不舉花顏低。","忽然一笑千萬態，見者十人八九迷。","假色迷人猶若是，真色迷人應過此。","彼真此假俱迷人，人心惡假貴重真。","狐假女妖害猶淺，一朝一夕迷人眼。","女爲狐媚害即深，日長月增溺人心。","何況褒妲之色善蠱惑，能喪人家覆人國。","君看爲害淺深間，豈將假色同真色。"]', '["古冢狐，妖且老，化爲婦人顏色好。","头变云鬟面变妝，大尾曳作长紅裳。","徐徐行傍荒村路，日欲暮时人静处。","或歌或舞或悲啼，翠眉不舉花顏低。","忽然一笑千万態，见者十人八九迷。","假色迷人猶若是，真色迷人應過此。","彼真此假俱迷人，人心惡假貴重真。","狐假女妖害猶淺，一朝一夕迷人眼。","女爲狐媚害即深，日长月增溺人心。","何況褒妲之色善蠱惑，能喪人家覆人国。","君看爲害淺深间，豈將假色同真色。"]', '诗', 'shi', '', NULL, '新樂府 古冢狐	戒豔色也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('228c557f-cab0-4cff-af64-10bc32fe54cb', '新樂府 黑潭龍	疾貪吏也', '新乐府 黑潭龙	疾貪吏也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黑潭水深黑如墨，傳有神龍人不識。","潭上架屋官立祠，龍不能神人神之。","豐凶水旱與疾疫，鄉里皆言龍所爲。","家家養豚漉清酒，朝祈暮賽依巫口。","神之來兮風飄飄，紙錢動兮錦傘搖。","神之去兮風亦靜，香火滅兮杯盤冷。","肉堆潭岸石，酒潑廟前草。","不知龍神享幾多，林鼠山狐長醉飽。","狐何幸，豚何辜，年年殺豚將餧狐。","狐假龍神食豚盡，九重泉底龍知無。"]', '["黑潭水深黑如墨，傳有神龙人不識。","潭上架屋官立祠，龙不能神人神之。","豐凶水旱與疾疫，乡里皆言龙所爲。","家家養豚漉清酒，朝祈暮賽依巫口。","神之来兮风飄飄，紙錢动兮錦傘搖。","神之去兮风亦静，香火滅兮杯盤冷。","肉堆潭岸石，酒潑廟前草。","不知龙神享幾多，林鼠山狐长醉飽。","狐何幸，豚何辜，年年殺豚將餧狐。","狐假龙神食豚尽，九重泉底龙知無。"]', '诗', 'shi', '', NULL, '新樂府 黑潭龍	疾貪吏也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d001c677-bd47-4858-8928-5a772268d514', '新樂府 天可度	惡詐人也', '新乐府 天可度	惡詐人也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天可度，地可量，唯有人心不可防。","但見丹誠赤如血，誰知僞言巧似簧。","勸君掩鼻君莫掩，使君夫婦爲參商。","勸君掇蠭君莫掇，使君父子成豺狼。","海底魚兮天上鳥，高可射兮深可釣。","唯有人心相對時，咫尺之間不能料。","君不見李義府之輩笑欣欣，笑中有刀潛殺人。","陰陽神變皆可測，不測人間笑是瞋。"]', '["天可度，地可量，唯有人心不可防。","但见丹誠赤如血，誰知僞言巧似簧。","勸君掩鼻君莫掩，使君夫婦爲參商。","勸君掇蠭君莫掇，使君父子成豺狼。","海底鱼兮天上鸟，高可射兮深可釣。","唯有人心相对时，咫尺之间不能料。","君不见李義府之輩笑欣欣，笑中有刀潛殺人。","陰陽神变皆可測，不測人间笑是瞋。"]', '诗', 'shi', '', NULL, '新樂府 天可度	惡詐人也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e732b73e-7503-4d41-a34b-40840a9f157f', '新樂府 秦吉了	哀冤民也', '新乐府 秦吉了	哀冤民也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秦吉了，出南中，彩毛青黑花頸紅。","耳聰心慧舌端巧，鳥語人言無不通。","昨日長爪鳶，今朝大觜烏。","鳶捎乳燕一窠覆，烏琢母雞雙眼枯。","雞號墮地燕驚去，然後拾卵攫其雛。","豈無鵰與鶚，嗉中肉飽不肯搏。","亦有鸞鶴羣，閑立高颺如不聞。","秦吉了，人云爾是能言鳥。","豈不見雞燕之冤苦，吾聞鳳皇百鳥主。","爾竟不爲鳳皇之前致一言，安用噪噪閑言語。"]', '["秦吉了，出南中，彩毛青黑花頸紅。","耳聰心慧舌端巧，鸟語人言無不通。","昨日长爪鳶，今朝大觜烏。","鳶捎乳燕一窠覆，烏琢母雞雙眼枯。","雞號墮地燕驚去，然後拾卵攫其雛。","豈無鵰與鶚，嗉中肉飽不肯搏。","亦有鸾鹤羣，闲立高颺如不闻。","秦吉了，人云爾是能言鸟。","豈不见雞燕之冤苦，吾闻鳳皇百鸟主。","爾竟不爲鳳皇之前致一言，安用噪噪闲言語。"]', '诗', 'shi', '', NULL, '新樂府 秦吉了	哀冤民也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31b00468-ec56-421b-916d-bafc8bb50ea7', '新樂府 鵶九劒	思決壅也', '新乐府 鵶九劒	思決壅也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["歐冶子死千年後，精靈闇授張鵶九。","鵶九鑄劒吳山中，天與日時神借功。","金鐵騰精火飜燄，踴躍求爲鏌鎁劒。","劒成未試十餘年，有客持金買一觀。","誰知閉匣長思用，三尺青蛇不肯蟠。","客有心，劒無口，客代劒言告鵶九。","君勿矜我玉可切，君勿誇我鐘可刜。","不如持我決浮雲，無令漫漫蔽白日。","爲君使無私之光及萬物，蟄蟲昭蘇萌草出。"]', '["歐冶子死千年後，精靈闇授張鵶九。","鵶九鑄劒吳山中，天與日时神借功。","金鐵腾精火飜燄，踴躍求爲鏌鎁劒。","劒成未試十餘年，有客持金買一观。","誰知閉匣长思用，三尺青蛇不肯蟠。","客有心，劒無口，客代劒言告鵶九。","君勿矜我玉可切，君勿誇我鐘可刜。","不如持我決浮云，無令漫漫蔽白日。","爲君使無私之光及万物，蟄蟲昭蘇萌草出。"]', '诗', 'shi', '', NULL, '新樂府 鵶九劒	思決壅也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7bac9ba-9db0-43d4-8647-5f921d7db924', '新樂府 采詩官	監前王亂亡之由也', '新乐府 采诗官	監前王亂亡之由也', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["采詩官，采詩聽歌導人言。","言者無罪聞者誡，下流上通上下泰。","周滅秦興至隋氏，十代采詩官不置。","郊廟登歌贊君美，樂府豔詞悅君意。","若求興諭規刺言，萬句千章無一字。","不是章句無規刺，漸及朝廷絕諷議。","諍臣杜口爲冗員，諫鼓高懸作虛器。","一人負扆常端默，百辟入門兩自媚。","夕郎所賀皆德音，春官每奏唯祥瑞。","君之堂兮千里遠，君之門兮九重閟。","君耳唯聞堂上言，君眼不見門前事。","貪吏害民無所忌，奸臣蔽君無所畏。","君不見厲王胡亥之末年，羣臣有利君無利。","君兮君兮願聽此，欲開壅蔽達人情。","先向歌詩求諷刺。"]', '["采诗官，采诗听歌導人言。","言者無罪闻者誡，下流上通上下泰。","周滅秦兴至隋氏，十代采诗官不置。","郊廟登歌贊君美，乐府豔词悅君意。","若求兴諭規刺言，万句千章無一字。","不是章句無規刺，漸及朝廷絕諷議。","諍臣杜口爲冗員，諫鼓高懸作虛器。","一人負扆常端默，百辟入门兩自媚。","夕郎所賀皆德音，春官每奏唯祥瑞。","君之堂兮千里远，君之门兮九重閟。","君耳唯闻堂上言，君眼不见门前事。","貪吏害民無所忌，奸臣蔽君無所畏。","君不见厲王胡亥之末年，羣臣有利君無利。","君兮君兮願听此，欲开壅蔽達人情。","先向歌诗求諷刺。"]', '诗', 'shi', '', NULL, '新樂府 采詩官	監前王亂亡之由也 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('255ad53f-1091-4dbf-94c5-c6041e2d4d0b', '常樂里閑居偶題十六韻兼寄劉十五公輿王十一起呂二炅呂四熲崔十八玄亮元九稹劉三十二敦質張十五仲元時爲校書郎', '常乐里闲居偶題十六韻兼寄劉十五公輿王十一起呂二炅呂四熲崔十八玄亮元九稹劉三十二敦質張十五仲元时爲校书郎', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["帝都名利場，雞鳴無安居。","獨有嬾慢者，日高頭未梳。","工拙性不同，進退迹遂殊。","幸逢太平代，天子好文儒。","小才難大用，典校在祕書。","三旬兩入省，因得養頑疎。","茅屋四五間，一馬二僕夫。","俸錢萬六千，月給亦有餘。","既無衣食牽，亦少人事拘。","遂使少年心，日日常晏如。","勿言無知己，躁靜各有徒。","蘭臺七八人，出處與之俱。","旬時阻談笑，旦夕望軒車。","誰能讎校閑，解帶臥吾廬。","窗前有竹玩，門外有酒酤。","何以待君子，數竿對一壺。"]', '["帝都名利場，雞鳴無安居。","独有嬾慢者，日高头未梳。","工拙性不同，進退迹遂殊。","幸逢太平代，天子好文儒。","小才难大用，典校在祕书。","三旬兩入省，因得養頑疎。","茅屋四五间，一马二僕夫。","俸錢万六千，月給亦有餘。","既無衣食牽，亦少人事拘。","遂使少年心，日日常晏如。","勿言無知己，躁静各有徒。","蘭台七八人，出处與之俱。","旬时阻談笑，旦夕望軒车。","誰能讎校闲，解带臥吾廬。","窗前有竹玩，门外有酒酤。","何以待君子，數竿对一壺。"]', '诗', 'shi', '', NULL, '常樂里閑居偶題十六韻兼寄劉十五公輿王十一起呂二炅呂四熲崔十八玄亮元九稹劉三十二敦質張十五仲元時爲校書郎 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05ac1119-006a-497b-9e1f-574a85f5af26', '荅元八宗簡同遊曲江後明日見贈', '荅元八宗簡同游曲江後明日见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["長安千萬人，出門各有營。","唯我與夫子，信馬悠悠行。","行到曲江頭，反照草樹明。","南山好顏色，病客有心情。","水禽飜白羽，風荷嫋翠莖。","何必滄浪去，即此可濯纓。","時景不重來，賞心難再幷。","坐愁紅塵裏，夕鼓鼕鼕聲。","歸來經一宿，世慮稍復生。","賴聞瑤華唱，再得塵襟清。"]', '["长安千万人，出门各有營。","唯我與夫子，信马悠悠行。","行到曲江头，反照草樹明。","南山好顏色，病客有心情。","水禽飜白羽，风荷嫋翠莖。","何必滄浪去，即此可濯纓。","时景不重来，賞心难再幷。","坐愁紅塵裏，夕鼓鼕鼕声。","归来經一宿，世慮稍复生。","賴闻瑤华唱，再得塵襟清。"]', '诗', 'shi', '', NULL, '荅元八宗簡同遊曲江後明日見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41df6ae1-af90-41af-8e4e-ca4920e2fb1c', '感時', '感时', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝見日上天，暮見日入地。","不覺明鏡中，忽年三十四。","勿言身未老，冉冉行將至。","白髮雖未生，朱顏已先悴。","人生詎幾何，在世猶如寄。","雖有七十期，十人無一二。","今我猶未悟，往往不適意。","胡爲方寸間，不貯浩然氣。","貧賤非不惡，道在何足避。","富貴非不愛，時來當自致。","所以達人心，外物不能累。","唯當飲美酒，終日陶陶醉。","斯言勝金玉，佩服無失墜。"]', '["朝见日上天，暮见日入地。","不覺明镜中，忽年三十四。","勿言身未老，冉冉行將至。","白髮雖未生，朱顏已先悴。","人生詎幾何，在世猶如寄。","雖有七十期，十人無一二。","今我猶未悟，往往不適意。","胡爲方寸间，不貯浩然氣。","貧賤非不惡，道在何足避。","富貴非不愛，时来當自致。","所以達人心，外物不能累。","唯當饮美酒，終日陶陶醉。","斯言勝金玉，佩服無失墜。"]', '诗', 'shi', '', NULL, '感時 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d904c23-d223-46b7-9b05-7eb22c5227eb', '首夏同諸校正遊開元觀因宿玩月', '首夏同諸校正游开元观因宿玩月', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我與二三子，策名在京師。","官小無職事，閑於爲客時。","沈沈道觀中，心賞期在茲。","到門車馬迴，入院巾杖隨。","清和四月初，樹木正華滋。","風清新葉影，鳥戀殘花枝。","向夕天又晴，東南餘霞披。","置酒西廊下，待月杯行遲。","須臾金魄生，若與吾徒期。","光華一照耀，殿角相參差。","終夜清景前，笑歌不知疲。","長安名利地，此興幾人知。"]', '["我與二三子，策名在京師。","官小無職事，闲於爲客时。","沈沈道观中，心賞期在茲。","到门车马迴，入院巾杖隨。","清和四月初，樹木正华滋。","风清新葉影，鸟戀殘花枝。","向夕天又晴，东南餘霞披。","置酒西廊下，待月杯行遲。","須臾金魄生，若與吾徒期。","光华一照耀，殿角相參差。","終夜清景前，笑歌不知疲。","长安名利地，此兴幾人知。"]', '诗', 'shi', '', NULL, '首夏同諸校正遊開元觀因宿玩月 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ea7e704-b9b3-4436-b4a8-2595078dc3e1', '永崇里觀居', '永崇里观居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["季夏中氣侯，煩暑自此收。","蕭颯風雨天，蟬聲暮啾啾。","永崇里巷靜，華陽觀院幽。","軒車不到處，滿地槐花秋。","年光忽冉冉，世事本悠悠。","何必待衰老，然後悟浮休。","真隱豈長遠，至道在冥搜。","身雖世界住，心與虛無遊。","朝飢有蔬食，夜寒有布裘。","幸免凍與餒，此外復何求。","寡慾雖少病，樂天心不憂。","何以明吾志，周易在牀頭。"]', '["季夏中氣侯，煩暑自此收。","蕭颯风雨天，蟬声暮啾啾。","永崇里巷静，华陽观院幽。","軒车不到处，满地槐花秋。","年光忽冉冉，世事本悠悠。","何必待衰老，然後悟浮休。","真隐豈长远，至道在冥搜。","身雖世界住，心與虛無游。","朝飢有蔬食，夜寒有布裘。","幸免凍與餒，此外复何求。","寡慾雖少病，乐天心不憂。","何以明吾志，周易在牀头。"]', '诗', 'shi', '', NULL, '永崇里觀居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c3a41ad-a522-413d-9c26-31f4b8b1294c', '早送舉人入試', '早送舉人入試', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夙駕送舉人，東方猶未明。","自謂出太早，已有車馬行。","騎火高低影，街鼓參差聲。","可憐早朝者，相看意氣生。","日出塵埃飛，羣動互營營。","營營各何求，無非利與名。","而我常晏起，虛住長安城。","春深官又滿，日有歸山情。"]', '["夙駕送舉人，东方猶未明。","自謂出太早，已有车马行。","騎火高低影，街鼓參差声。","可怜早朝者，相看意氣生。","日出塵埃飞，羣动互營營。","營營各何求，無非利與名。","而我常晏起，虛住长安城。","春深官又满，日有归山情。"]', '诗', 'shi', '', NULL, '早送舉人入試 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4325bd07-7a5c-450e-a23d-6cc75932c0a4', '招王質夫', '招王質夫', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["濯足雲水客，折腰簪笏身。","諠閑跡相背，十里別經旬。","忽因乘逸興，莫惜訪囂塵。","窗前故栽竹，與君爲主人。"]', '["濯足云水客，折腰簪笏身。","諠闲跡相背，十里別經旬。","忽因乘逸兴，莫惜訪囂塵。","窗前故栽竹，與君爲主人。"]', '诗', 'shi', '', NULL, '招王質夫 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df162a62-3b63-4e9f-8413-9698ff871d48', '祗役駱口因與王質夫同遊秋山偶題三韻', '祗役駱口因與王質夫同游秋山偶題三韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["石擁百泉合，雲破千峰開。","平生煙霞侶，此地重裴回。","今日勤王意，一半爲山來。"]', '["石擁百泉合，云破千峰开。","平生煙霞侶，此地重裴回。","今日勤王意，一半爲山来。"]', '诗', 'shi', '', NULL, '祗役駱口因與王質夫同遊秋山偶題三韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc7cff00-1c5e-4afc-9088-e440a3f58fcb', '見蕭侍御憶舊山草堂詩因以繼和', '见蕭侍御憶旧山草堂诗因以繼和', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["琢玉以爲架，綴珠以爲籠。","玉架絆野鶴，珠籠鏁冥鴻。","鴻思雲外天，鶴憶松上風。","珠玉信爲美，鳥不戀其中。","臺中蕭侍御，心與鴻鶴同。","晚起慵冠豸，閑行厭避驄。","昨見憶山詩，詩思浩無窮。","歸夢杳何處，舊居茫水東。","秋閑杉桂林，春老芝朮叢。","自云別山後，離抱常忡忡。","衣繡非不榮，持憲非不雄。","所樂不在此，悵望草堂空。"]', '["琢玉以爲架，綴珠以爲籠。","玉架絆野鹤，珠籠鏁冥鴻。","鴻思云外天，鹤憶松上风。","珠玉信爲美，鸟不戀其中。","台中蕭侍御，心與鴻鹤同。","晚起慵冠豸，闲行厭避驄。","昨见憶山诗，诗思浩無窮。","归梦杳何处，旧居茫水东。","秋闲杉桂林，春老芝朮叢。","自云別山後，離抱常忡忡。","衣繡非不榮，持憲非不雄。","所乐不在此，悵望草堂空。"]', '诗', 'shi', '', NULL, '見蕭侍御憶舊山草堂詩因以繼和 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c81d9038-2d96-4d80-8634-ef3fbed89449', '病假中南亭閑望', '病假中南亭闲望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["欹沈不視事，兩日門掩關。","始知吏役身，不病不得閑。","閑意不在遠，小亭方丈間。","西檐竹梢上，坐見太白山。","遙媿峰上雲，對此塵中顏。"]', '["欹沈不視事，兩日门掩关。","始知吏役身，不病不得闲。","闲意不在远，小亭方丈间。","西檐竹梢上，坐见太白山。","遙媿峰上云，对此塵中顏。"]', '诗', 'shi', '', NULL, '病假中南亭閑望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73fde295-039e-4dba-9577-f0e088f1c691', '仙遊寺獨宿', '仙游寺独宿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["沙鶴上階立，潭月當戶開。","此中留我宿，兩夜不能迴。","幸與靜境遇，喜無歸侶催。","從今獨遊後，不擬共人來。"]', '["沙鹤上階立，潭月當戶开。","此中留我宿，兩夜不能迴。","幸與静境遇，喜無归侶催。","從今独游後，不擬共人来。"]', '诗', 'shi', '', NULL, '仙遊寺獨宿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6330e0b-70e6-49c1-9097-22de0dfb4d63', '前庭涼夜', '前庭涼夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["露簟色似玉，風幌影如波。","坐愁樹葉落，中庭明月多。"]', '["露簟色似玉，风幌影如波。","坐愁樹葉落，中庭明月多。"]', '诗', 'shi', '', NULL, '前庭涼夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00fa55d3-0e0f-4c12-bf74-1f54703806d6', '官舍小亭閑望', '官舍小亭闲望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風竹散清韻，煙槐凝綠姿。","日高人吏去，閑坐在茅茨。","葛衣禦時暑，蔬飯療朝飢。","持此聊自足，心力少營爲。","亭上獨吟罷，眼前無事時。","數峰太白雪，一卷陶潛詩。","人心各自是，我是良在茲。","迴謝爭名客，甘從君所嗤。"]', '["风竹散清韻，煙槐凝綠姿。","日高人吏去，闲坐在茅茨。","葛衣禦时暑，蔬飯療朝飢。","持此聊自足，心力少營爲。","亭上独吟罷，眼前無事时。","數峰太白雪，一卷陶潛诗。","人心各自是，我是良在茲。","迴謝爭名客，甘從君所嗤。"]', '诗', 'shi', '', NULL, '官舍小亭閑望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e941849-9edc-4cad-8f88-d466ee755d58', '早秋獨夜', '早秋独夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["井梧涼葉動，鄰杵秋聲發。","獨向檐下眠，覺來半牀月。"]', '["井梧涼葉动，鄰杵秋声發。","独向檐下眠，覺来半牀月。"]', '诗', 'shi', '', NULL, '早秋獨夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cce7b85-d405-4249-a14e-c5327adf9ab8', '聽彈古淥水', '听彈古淥水', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["聞君古淥水，使我心和平。","欲識慢流意，爲聽疎泛聲。","西窗竹陰下，竟日有餘清。"]', '["闻君古淥水，使我心和平。","欲識慢流意，爲听疎泛声。","西窗竹陰下，竟日有餘清。"]', '诗', 'shi', '', NULL, '聽彈古淥水 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d33b371-389e-45ff-9fd8-3e04d8818b7b', '松齋自題', '松斋自題', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["非老亦非少，年過三紀餘。","非賤亦非貴，朝登一命初。","才小分易足，心寬體長舒。","充腸皆美食，容膝即安居。","況此松齋下，一琴數帙書。","書不求甚解，琴聊以自娛。","夜直入君門，晚歸臥吾廬。","形骸委順動，方寸付空虛。","持此將過日，自然多晏如。","昏昏復默默，非智亦非愚。"]', '["非老亦非少，年過三紀餘。","非賤亦非貴，朝登一命初。","才小分易足，心寬體长舒。","充腸皆美食，容膝即安居。","況此松斋下，一琴數帙书。","书不求甚解，琴聊以自娛。","夜直入君门，晚归臥吾廬。","形骸委順动，方寸付空虛。","持此將過日，自然多晏如。","昏昏复默默，非智亦非愚。"]', '诗', 'shi', '', NULL, '松齋自題 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea87aebe-1c09-4911-99dd-02a84078f029', '冬夜與錢員外同直禁中', '冬夜與錢員外同直禁中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜深草詔罷，霜月淒凜凜。","欲臥暖殘杯，燈前相對飲。","連鋪青縑被，對置通中枕。","髣髴百餘宵，與君同此寢。"]', '["夜深草詔罷，霜月淒凜凜。","欲臥暖殘杯，灯前相对饮。","連鋪青縑被，对置通中枕。","髣髴百餘宵，與君同此寢。"]', '诗', 'shi', '', NULL, '冬夜與錢員外同直禁中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bd8cd7b-ab8c-434a-b442-7df532d10fcf', '和錢員外禁中夙興見示', '和錢員外禁中夙兴见示', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["窗白星漢曙，窗暖燈火餘。","坐卷朱裏幕，看封紫泥書。","窅窅鐘漏盡，曈曈霞景初。","樓臺紅照曜，松竹青扶疎。","君愛此時好，回頭特謂余。","不知上清界，曉景復何如。"]', '["窗白星漢曙，窗暖灯火餘。","坐卷朱裏幕，看封紫泥书。","窅窅鐘漏尽，曈曈霞景初。","楼台紅照曜，松竹青扶疎。","君愛此时好，回头特謂余。","不知上清界，晓景复何如。"]', '诗', 'shi', '', NULL, '和錢員外禁中夙興見示 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39a338a5-71a0-48b5-bbae-cf4a01ae1c5f', '夏日獨直寄蕭侍御', '夏日独直寄蕭侍御', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憲臺文法地，翰林清切司。","鷹猜課野鶴，驥德責山麋。","課責雖不同，同歸非所宜。","是以方寸內，忽忽暗相思。","夏日獨上直，日長何所爲。","澹然無他念，虛靜是吾師。","形委有事牽，心與無事期。","中臆一以曠，外累都若遺。","地貴身不覺，意閑境來隨。","但對松與竹，如在山中時。","情性聊自適，吟詠偶成詩。","此意非夫子，餘人多不知。"]', '["憲台文法地，翰林清切司。","鷹猜課野鹤，驥德責山麋。","課責雖不同，同归非所宜。","是以方寸內，忽忽暗相思。","夏日独上直，日长何所爲。","澹然無他念，虛静是吾師。","形委有事牽，心與無事期。","中臆一以曠，外累都若遺。","地貴身不覺，意闲境来隨。","但对松與竹，如在山中时。","情性聊自適，吟詠偶成诗。","此意非夫子，餘人多不知。"]', '诗', 'shi', '', NULL, '夏日獨直寄蕭侍御 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8df86e6-ec70-4b16-94ca-f7dc05d76110', '松聲', '松声', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["月好好獨坐，雙松在前軒。","西南微風來，潛入枝葉間。","蕭寥發爲聲，半夜明月前。","寒山颯颯雨，秋琴泠泠弦。","一聞滌炎暑，再聽破昏煩。","竟夕遂不寐，心體俱翛然。","南陌車馬動，西鄰歌吹繁。","誰知茲檐下，滿耳不爲喧。"]', '["月好好独坐，雙松在前軒。","西南微风来，潛入枝葉间。","蕭寥發爲声，半夜明月前。","寒山颯颯雨，秋琴泠泠弦。","一闻滌炎暑，再听破昏煩。","竟夕遂不寐，心體俱翛然。","南陌车马动，西鄰歌吹繁。","誰知茲檐下，满耳不爲喧。"]', '诗', 'shi', '', NULL, '松聲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca5b3bd9-c96a-4534-8519-b2e4c45add4d', '禁中', '禁中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["門嚴九重靜，窗幽一室閑。","好是修心處，何必在深山。"]', '["门嚴九重静，窗幽一室闲。","好是修心处，何必在深山。"]', '诗', 'shi', '', NULL, '禁中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4015ebaa-bed9-46a2-ab5b-af14ded716f2', '贈吳丹', '贈吳丹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["巧者力苦勞，智者心苦憂。","愛君無巧智，終歲閑悠悠。","嘗登御史府，亦佐東諸候。","手操糾謬簡，心運決勝籌。","宦途似風水，君心如虛舟。","泛然而不有，進退得自由。","今來脫豸冠，時往侍龍樓。","官曹稱心靜，居處隨跡幽。","冬負南榮日，支體甚溫柔。","夏臥北窗風，枕席如涼秋。","南山入舍下，酒甕在牀頭。","人間有閑地，何必隱林丘。","顧我愚且昧，勞生殊未休。","一入金門直，星霜三四周。","主恩信難報，近地徒久留。","終當乞閑官，退與夫子遊。"]', '["巧者力苦勞，智者心苦憂。","愛君無巧智，終歲闲悠悠。","嘗登御史府，亦佐东諸候。","手操糾謬簡，心運決勝籌。","宦途似风水，君心如虛舟。","泛然而不有，進退得自由。","今来脫豸冠，时往侍龙楼。","官曹稱心静，居处隨跡幽。","冬負南榮日，支體甚溫柔。","夏臥北窗风，枕席如涼秋。","南山入舍下，酒甕在牀头。","人间有闲地，何必隐林丘。","顧我愚且昧，勞生殊未休。","一入金门直，星霜三四周。","主恩信难報，近地徒久留。","終當乞闲官，退與夫子游。"]', '诗', 'shi', '', NULL, '贈吳丹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71651a11-e22e-4b14-a375-28ef4eb00c83', '初除戶曹喜而言志', '初除戶曹喜而言志', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["詔授戶曹掾，捧詔感君恩。","感恩非爲己，祿養及吾親。","弟兄俱簪笏，新婦儼衣巾。","羅列高堂下，拜慶正紛紛。","俸錢四五萬，月可奉晨昏。","廩祿二百石，歲可盈倉囷。","喧喧車馬來，賀客滿我門。","不以我爲貪，知我家內貧。","置酒延賀客，客容亦歡欣。","笑云今日後，不復憂空尊。","荅云如君言，願君少逡巡。","我有平生志，醉後爲君陳。","人生百歲期，七十有幾人。","浮榮及虛位，皆是身之賓。","唯有衣與食，此事粗關身。","苟免飢寒外，餘物盡浮雲。"]', '["詔授戶曹掾，捧詔感君恩。","感恩非爲己，祿養及吾親。","弟兄俱簪笏，新婦儼衣巾。","羅列高堂下，拜慶正紛紛。","俸錢四五万，月可奉晨昏。","廩祿二百石，歲可盈倉囷。","喧喧车马来，賀客满我门。","不以我爲貪，知我家內貧。","置酒延賀客，客容亦歡欣。","笑云今日後，不复憂空尊。","荅云如君言，願君少逡巡。","我有平生志，醉後爲君陳。","人生百歲期，七十有幾人。","浮榮及虛位，皆是身之賓。","唯有衣與食，此事粗关身。","苟免飢寒外，餘物尽浮云。"]', '诗', 'shi', '', NULL, '初除戶曹喜而言志 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f40117ce-199c-4d90-9dfd-1e2aec8992b7', '秋居書懷', '秋居书懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["門前少賓客，階下多松竹。","秋景下西牆，涼風入東屋。","有琴慵不弄，有書閑不讀。","盡日方寸中，澹然無所欲。","何須廣居處，不用多積蓄。","丈室可容身，斗儲可充腹。","況無治道術，坐受官家祿。","不種一株桑，不鋤一壠穀。","終朝飽飯餐，卒歲豐衣服。","持此知媿心，自然易爲足。"]', '["门前少賓客，階下多松竹。","秋景下西牆，涼风入东屋。","有琴慵不弄，有书闲不读。","尽日方寸中，澹然無所欲。","何須廣居处，不用多積蓄。","丈室可容身，斗儲可充腹。","況無治道術，坐受官家祿。","不種一株桑，不鋤一壠穀。","終朝飽飯餐，卒歲豐衣服。","持此知媿心，自然易爲足。"]', '诗', 'shi', '', NULL, '秋居書懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b093a901-f11c-4a34-8ff9-f7a70a7b4a56', '禁中曉臥因懷王起居', '禁中晓臥因懷王起居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["遲遲禁漏盡，悄悄暝鵶喧。","夜雨槐花落，微涼臥北軒。","曙燈殘未滅，風簾閑自飜。","每一得靜境，思與故人言。"]', '["遲遲禁漏尽，悄悄暝鵶喧。","夜雨槐花落，微涼臥北軒。","曙灯殘未滅，风簾闲自飜。","每一得静境，思與故人言。"]', '诗', 'shi', '', NULL, '禁中曉臥因懷王起居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f1666cc-532f-4fe4-ae3b-8b4b6d4b8bfa', '養拙', '養拙', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鐵柔不爲劒，木曲不爲轅。","今我亦如此，愚蒙不及門。","甘心謝名利，滅跡歸丘園。","坐臥茅茨中，但對琴與尊。","身去韁鎖累，耳辭朝市喧。","逍遙無所爲，時窺五千言。","無憂樂性場，寡欲清心源。","始知不才者，可以探道根。"]', '["鐵柔不爲劒，木曲不爲轅。","今我亦如此，愚蒙不及门。","甘心謝名利，滅跡归丘园。","坐臥茅茨中，但对琴與尊。","身去韁鎖累，耳辞朝市喧。","逍遙無所爲，时窺五千言。","無憂乐性場，寡欲清心源。","始知不才者，可以探道根。"]', '诗', 'shi', '', NULL, '養拙 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89bcd8ba-60bf-43b9-9a15-cf3a854e5ab3', '寄李十一建', '寄李十一建', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["外事牽我形，外物誘我情。","李君別來久，褊恡從中生。","憶昨訪君時，立馬扣柴荆。","有時君未起，穉子喜先迎。","連步笑出門，衣飜冠或傾。","埽階苔紋綠，拂榻藤陰清。","家醞及春熟，園葵乘露烹。","看山東亭坐，待月南原行。","門靜唯鳥語，坊遠少鼓聲。","相對盡日言，不及利與名。","分手來幾時，明月三四盈。","別時殘花落，及此新蟬鳴。","芳歲忽已晚，離抱悵未平。","豈不思命駕，吏職坐相縈。","前時君有期，訪我來山城。","心賞久云阻，言約無自輕。","相去幸非遠，走馬一日程。"]', '["外事牽我形，外物誘我情。","李君別来久，褊恡從中生。","憶昨訪君时，立马扣柴荆。","有时君未起，穉子喜先迎。","連步笑出门，衣飜冠或傾。","埽階苔紋綠，拂榻藤陰清。","家醞及春熟，园葵乘露烹。","看山东亭坐，待月南原行。","门静唯鸟語，坊远少鼓声。","相对尽日言，不及利與名。","分手来幾时，明月三四盈。","別时殘花落，及此新蟬鳴。","芳歲忽已晚，離抱悵未平。","豈不思命駕，吏職坐相縈。","前时君有期，訪我来山城。","心賞久云阻，言約無自轻。","相去幸非远，走马一日程。"]', '诗', 'shi', '', NULL, '寄李十一建 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5828171a-17ce-4335-8376-14f047f143d1', '旅次華州贈袁右丞', '旅次华州贈袁右丞', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["渭水綠溶溶，華山青崇崇。","山水一何麗，君子在其中。","才與世會合，物隨誠感通。","德星降人福，時雨助歲功。","化行人無訟，囹圄千日空。","政順氣亦和，黍稷三年豐。","客自帝城來，驅馬出關東。","愛此一郡人，如見太古風。","方今天子心，憂人正忡忡。","安得天下守，盡得如袁公。"]', '["渭水綠溶溶，华山青崇崇。","山水一何丽，君子在其中。","才與世會合，物隨誠感通。","德星降人福，时雨助歲功。","化行人無訟，囹圄千日空。","政順氣亦和，黍稷三年豐。","客自帝城来，驱马出关东。","愛此一郡人，如见太古风。","方今天子心，憂人正忡忡。","安得天下守，尽得如袁公。"]', '诗', 'shi', '', NULL, '旅次華州贈袁右丞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62308253-40ca-4e67-94ff-dc9a381d9278', '酬楊九弘貞長安病中見寄', '酬楊九弘貞长安病中见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["伏枕君寂寂，折腰我營營。","所嗟經時別，相去一宿程。","攜手昨何時，昆明春水平。","離郡來幾日，太白夏雲生。","之子未得意，貧病客帝城。","貧堅志士節，病長高人情。","隱几自恬澹，閉門無送迎。","龍臥心有待，鶴瘦貌彌清。","清機發爲文，投我如振瓊。","何以慰飢渴，捧之吟一聲。"]', '["伏枕君寂寂，折腰我營營。","所嗟經时別，相去一宿程。","携手昨何时，昆明春水平。","離郡来幾日，太白夏云生。","之子未得意，貧病客帝城。","貧堅志士節，病长高人情。","隐几自恬澹，閉门無送迎。","龙臥心有待，鹤瘦貌彌清。","清機發爲文，投我如振瓊。","何以慰飢渴，捧之吟一声。"]', '诗', 'shi', '', NULL, '酬楊九弘貞長安病中見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('329e16a3-060d-43ff-9a58-7aefde5c659c', '禁中寓直夢遊仙遊寺', '禁中寓直梦游仙游寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["西軒草詔暇，松竹深寂寂。","月出清風來，忽似山中夕。","因成西南夢，夢作遊仙客。","覺聞宮漏聲，猶謂山泉滴。"]', '["西軒草詔暇，松竹深寂寂。","月出清风来，忽似山中夕。","因成西南梦，梦作游仙客。","覺闻宮漏声，猶謂山泉滴。"]', '诗', 'shi', '', NULL, '禁中寓直夢遊仙遊寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc874339-6253-46db-982b-a5de6f778ff0', '贈王山人', '贈王山人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["聞君減寢食，日聽神仙說。","闇待非常人，潛求長生訣。","言長本對短，未離生死轍。","假使得長生，才能勝夭折。","松樹千年朽，槿花一日歇。","畢竟共虛空，何須誇歲月。","彭殤徒自異，生死終無別。","不如學無生，無生即無滅。"]', '["闻君減寢食，日听神仙说。","闇待非常人，潛求长生訣。","言长本对短，未離生死轍。","假使得长生，才能勝夭折。","松樹千年朽，槿花一日歇。","畢竟共虛空，何須誇歲月。","彭殤徒自異，生死終無別。","不如学無生，無生即無滅。"]', '诗', 'shi', '', NULL, '贈王山人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('755e2c6c-5aa5-4aa7-9b09-6bebb7f9d339', '秋山', '秋山', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["久病曠心賞，今朝一登山。","山秋雲物冷，稱我清羸顏。","白石臥可枕，青蘿行可攀。","意中如有得，盡日不欲還。","人生無幾何，如寄天地間。","心有千載憂，身無一日閑。","何時解塵網，此地來掩關。"]', '["久病曠心賞，今朝一登山。","山秋云物冷，稱我清羸顏。","白石臥可枕，青蘿行可攀。","意中如有得，尽日不欲還。","人生無幾何，如寄天地间。","心有千載憂，身無一日闲。","何时解塵網，此地来掩关。"]', '诗', 'shi', '', NULL, '秋山 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a153de94-91bc-4ec2-a886-35b4e13c76d9', '贈能七倫', '贈能七倫', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["澗松高百尋，四時寒森森。","臨風有清韻，向日無曲陰。","如何時俗人，但賞桃李林。","豈不知堅貞，芳馨誘其心。","能生學爲文，氣高功亦深。","手中一百篇，句句披沙金。","苦節二十年，無人振陸沈。","今我尚貧賤，徒爲爾知音。"]', '["澗松高百尋，四时寒森森。","臨风有清韻，向日無曲陰。","如何时俗人，但賞桃李林。","豈不知堅貞，芳馨誘其心。","能生学爲文，氣高功亦深。","手中一百篇，句句披沙金。","苦節二十年，無人振陸沈。","今我尚貧賤，徒爲爾知音。"]', '诗', 'shi', '', NULL, '贈能七倫 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2fa5c2a-a336-4139-b0d0-b7c1122837ae', '題楊穎士西亭', '題楊穎士西亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["靜得亭上境，遠諧塵外蹤。","憑軒東南望，鳥滅山重重。","竹露冷煩襟，杉風清病容。","曠然宜真趣，道與心相逢。","即此可遺世，何必蓬壺峰。"]', '["静得亭上境，远諧塵外蹤。","憑軒东南望，鸟滅山重重。","竹露冷煩襟，杉风清病容。","曠然宜真趣，道與心相逢。","即此可遺世，何必蓬壺峰。"]', '诗', 'shi', '', NULL, '題楊穎士西亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df44ac30-d450-4f89-8ae9-9b510412d850', '題贈鄭祕書徵君石溝溪隱居', '題贈鄭祕书徵君石溝溪隐居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鄭君得自然，虛白生心胸。","吸彼沆瀣精，凝爲冰雪容。","大君貞元初，求賢致時雍。","蒲輪入翠微，迎下天台峰。","赤城別松喬，黃閤交夔龍。","俛仰受三命，從容辭九重。","出籠鶴翩翩，歸林鳳雝雝。","在火辨良玉，經霜識貞松。","新居寄楚山，山碧溪溶溶。","丹竈燒煙煴，黃精花丰茸。","蕙帳夜琴澹，桂尊春酒濃。","時人不到處，苔石無塵蹤。","我今何爲者，趨世身龍鍾。","不向林壑訪，無由朝市逢。","終當解塵纓，卜築來相從。"]', '["鄭君得自然，虛白生心胸。","吸彼沆瀣精，凝爲冰雪容。","大君貞元初，求賢致时雍。","蒲輪入翠微，迎下天台峰。","赤城別松喬，黄閤交夔龙。","俛仰受三命，從容辞九重。","出籠鹤翩翩，归林鳳雝雝。","在火辨良玉，經霜識貞松。","新居寄楚山，山碧溪溶溶。","丹竈燒煙煴，黄精花丰茸。","蕙帳夜琴澹，桂尊春酒濃。","时人不到处，苔石無塵蹤。","我今何爲者，趨世身龙鍾。","不向林壑訪，無由朝市逢。","終當解塵纓，卜築来相從。"]', '诗', 'shi', '', NULL, '題贈鄭祕書徵君石溝溪隱居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22287c66-40de-4a2f-865f-678144a99da7', '及第後歸覲留別諸同年', '及第後归覲留別諸同年', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["十年常苦學，一上謬成名。","擢第未爲貴，賀親方始榮。","時輩六七人，送我出帝城。","軒車動行色，絲管舉離聲。","得意減別恨，半酣輕遠程。","翩翩馬蹄疾，春日歸鄉情。"]', '["十年常苦学，一上謬成名。","擢第未爲貴，賀親方始榮。","时輩六七人，送我出帝城。","軒车动行色，絲管舉離声。","得意減別恨，半酣轻远程。","翩翩马蹄疾，春日归乡情。"]', '诗', 'shi', '', NULL, '及第後歸覲留別諸同年 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1ca0c5d-f373-4e84-a5d2-dda077f74303', '清夜琴興', '清夜琴兴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["月出鳥栖盡，寂然坐空林。","是時心境閑，可以彈素琴。","清泠由木性，恬澹隨人心。","心積和平氣，木應正始音。","響餘羣動息，曲罷秋夜深。","正聲感元化，天地清沈沈。"]', '["月出鸟栖尽，寂然坐空林。","是时心境闲，可以彈素琴。","清泠由木性，恬澹隨人心。","心積和平氣，木應正始音。","响餘羣动息，曲罷秋夜深。","正声感元化，天地清沈沈。"]', '诗', 'shi', '', NULL, '清夜琴興 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05d65503-db27-49a6-859f-c276c0040d2a', '效陶潛體詩十六首 一', '效陶潛體诗十六首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不動者厚地，不息者高天。","無窮者日月，長在者山川。","松柏與龜鶴，其壽皆千年。","嗟嗟羣物中，而人獨不然。","早出向朝市，暮已歸下泉。","形質及壽命，危脆若浮煙。","堯舜與周孔，古來稱聖賢。","借問今何在，一去亦不還。","我無不死藥，萬萬隨化遷。","所未定知者，修短遲速間。","幸及身健日，當歌一尊前。","何必待人勸，持此自爲歡。"]', '["不动者厚地，不息者高天。","無窮者日月，长在者山川。","松柏與龟鹤，其壽皆千年。","嗟嗟羣物中，而人独不然。","早出向朝市，暮已归下泉。","形質及壽命，危脆若浮煙。","堯舜與周孔，古来稱聖賢。","借问今何在，一去亦不還。","我無不死藥，万万隨化遷。","所未定知者，修短遲速间。","幸及身健日，當歌一尊前。","何必待人勸，持此自爲歡。"]', '诗', 'shi', '', NULL, '效陶潛體詩十六首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd942d20-27df-4f9d-9f01-2d541a697281', '效陶潛體詩十六首 二', '效陶潛體诗十六首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["翳翳踰月陰，沈沈連日雨。","開簾望天色，黃雲暗如土。","行潦毀我墉，疾風壞我宇。","蓬莠生庭院，泥塗失場圃。","村深絕賓客，窗晦無儔侶。","盡日不下牀，跳蛙時入戶。","出門無所往，入室還獨處。","不以酒自娛，塊然與誰語。"]', '["翳翳踰月陰，沈沈連日雨。","开簾望天色，黄云暗如土。","行潦毀我墉，疾风壞我宇。","蓬莠生庭院，泥塗失場圃。","村深絕賓客，窗晦無儔侶。","尽日不下牀，跳蛙时入戶。","出门無所往，入室還独处。","不以酒自娛，塊然與誰語。"]', '诗', 'shi', '', NULL, '效陶潛體詩十六首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eb359a8-212d-4786-a04e-af0f32d99336', '效陶潛體詩十六首 三', '效陶潛體诗十六首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝飲一杯酒，冥心合元化。","兀然無所思，日高尚閑臥。","暮讀一卷書，會意如嘉話。","欣然有所遇，夜深猶獨坐。","又得琴上趣，安弦有餘暇。","復多詩中狂，下筆不能罷。","唯茲三四事，持用度晝夜。","所以陰雨中，經旬不出舍。","始悟獨往人，心安時亦過。"]', '["朝饮一杯酒，冥心合元化。","兀然無所思，日高尚闲臥。","暮读一卷书，會意如嘉話。","欣然有所遇，夜深猶独坐。","又得琴上趣，安弦有餘暇。","复多诗中狂，下笔不能罷。","唯茲三四事，持用度晝夜。","所以陰雨中，經旬不出舍。","始悟独往人，心安时亦過。"]', '诗', 'shi', '', NULL, '效陶潛體詩十六首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ec55f28-85fe-4d72-aa8d-0695bc2657e0', '效陶潛體詩十六首 四', '效陶潛體诗十六首 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["車家采桑婦，雨來苦愁悲。","蔟蠶北堂前，雨冷不成絲。","西家荷鋤叟，雨來亦怨咨。","種豆南山下，雨多落爲萁。","而我獨何幸，醞酒本無期。","及此多雨日，正遇新熟時。","開缾瀉尊中，玉液黃金脂。","持玩已可悅，歡嘗有餘滋。","一酌發好容，再酌開愁眉。","連延四五酌，酣暢入四肢。","忽然遺我物，誰復分是非。","是時連夕雨，酩酊無所知。","人心苦顛倒，反爲憂者嗤。"]', '["车家采桑婦，雨来苦愁悲。","蔟蠶北堂前，雨冷不成絲。","西家荷鋤叟，雨来亦怨咨。","種豆南山下，雨多落爲萁。","而我独何幸，醞酒本無期。","及此多雨日，正遇新熟时。","开缾瀉尊中，玉液黄金脂。","持玩已可悅，歡嘗有餘滋。","一酌發好容，再酌开愁眉。","連延四五酌，酣暢入四肢。","忽然遺我物，誰复分是非。","是时連夕雨，酩酊無所知。","人心苦顛倒，反爲憂者嗤。"]', '诗', 'shi', '', NULL, '效陶潛體詩十六首 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63247af5-fdaf-4f14-9968-f03c387c6a73', '效陶潛體詩十六首 五', '效陶潛體诗十六首 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝亦獨醉歌，暮亦獨醉睡。","未盡一壺酒，已成三獨醉。","勿嫌飲太少，且喜歡易致。","一杯復兩杯，多不過三四。","便得心中適，盡忘身外事。","更復強一杯，陶然遺萬累。","一飲一石者，徒以多爲貴。","及其酩酊時，與我亦無異。","笑謝多飲者，酒錢徒自費。"]', '["朝亦独醉歌，暮亦独醉睡。","未尽一壺酒，已成三独醉。","勿嫌饮太少，且喜歡易致。","一杯复兩杯，多不過三四。","便得心中適，尽忘身外事。","更复強一杯，陶然遺万累。","一饮一石者，徒以多爲貴。","及其酩酊时，與我亦無異。","笑謝多饮者，酒錢徒自費。"]', '诗', 'shi', '', NULL, '效陶潛體詩十六首 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb7b663e-731d-41e2-a5ca-0b7341c09775', '效陶潛體詩十六首 六', '效陶潛體诗十六首 六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天秋無片雲，地靜無纖塵。","團團新晴月，林外生白輪。","憶昨陰霖天，連連三四旬。","賴逢家醞熟，不覺過朝昏。","私言雨霽後，可以罷餘尊。","及對新月色，不醉亦愁人。","牀頭殘酒榼，欲盡味彌淳。","攜置南檐下，舉酌自殷勤。","清光入杯杓，白露生衣巾。","乃知陰與晴，安可無此君。","我有樂府詩，成來人未聞。","今宵醉有興，狂詠驚四鄰。","獨賞猶復爾，何況有交親。"]', '["天秋無片云，地静無纖塵。","團團新晴月，林外生白輪。","憶昨陰霖天，連連三四旬。","賴逢家醞熟，不覺過朝昏。","私言雨霽後，可以罷餘尊。","及对新月色，不醉亦愁人。","牀头殘酒榼，欲尽味彌淳。","携置南檐下，舉酌自殷勤。","清光入杯杓，白露生衣巾。","乃知陰與晴，安可無此君。","我有乐府诗，成来人未闻。","今宵醉有兴，狂詠驚四鄰。","独賞猶复爾，何況有交親。"]', '诗', 'shi', '', NULL, '效陶潛體詩十六首 六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('455c3f96-e76e-4175-89b1-f7db6571c3ed', '效陶潛體詩十六首 七', '效陶潛體诗十六首 七', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["中秋三五夜，明月在前軒。","臨觴忽不飲，憶我平生歡。","我有同心人，邈邈崔與錢。","我有忘形友，迢迢李與元。","或飛青雲上，或落江湖間。","與我不相見，於今四五年。","我無縮地術，君非馭風仙。","安得明月下，四人來晤言。","良夜信難得，佳期杳無緣。","明月又不駐，漸下西南天。","豈無他時會，惜此清景前。"]', '["中秋三五夜，明月在前軒。","臨觴忽不饮，憶我平生歡。","我有同心人，邈邈崔與錢。","我有忘形友，迢迢李與元。","或飞青云上，或落江湖间。","與我不相见，於今四五年。","我無縮地術，君非馭风仙。","安得明月下，四人来晤言。","良夜信难得，佳期杳無緣。","明月又不駐，漸下西南天。","豈無他时會，惜此清景前。"]', '诗', 'shi', '', NULL, '效陶潛體詩十六首 七 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f47c287-251a-4f00-951d-c186f031c95d', '效陶潛體詩十六首 八', '效陶潛體诗十六首 八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["家醞飲已盡，村中無酒酤。","坐愁今夜醒，其奈秋懷何。","有客忽叩門，言語一何佳。","云是南村叟，挈榼來相過。","且喜尊不燥，安問少與多。","重陽雖已過，籬菊有殘花。","歡來苦晝短，不覺夕陽斜。","老人[勿]遽起，且待新月華。","客去有餘趣，竟夕獨酣歌。"]', '["家醞饮已尽，村中無酒酤。","坐愁今夜醒，其奈秋懷何。","有客忽叩门，言語一何佳。","云是南村叟，挈榼来相過。","且喜尊不燥，安问少與多。","重陽雖已過，籬菊有殘花。","歡来苦晝短，不覺夕陽斜。","老人[勿]遽起，且待新月华。","客去有餘趣，竟夕独酣歌。"]', '诗', 'shi', '', NULL, '效陶潛體詩十六首 八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('778d5c9c-8299-4131-ab9c-b0a242561317', '效陶潛體詩十六首 九', '效陶潛體诗十六首 九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["原生衣百結，顏子食一簞。","歡然樂其志，有以忘飢寒。","今我何人哉，德不及先賢。","衣食幸相屬，胡爲不自安。","況茲清渭曲，居處安且閑。","榆柳百餘樹，茅茨十數間。","寒負檐下日，熱濯澗底泉。","日出猶未起，日入已復眠。","西風滿村巷，清涼八月天。","但有雞犬聲，不聞車馬喧。","時傾一尊酒，坐望東南山。","穉姪初學步，牽衣戲我前。","即此自可樂，庶幾顏與原。"]', '["原生衣百結，顏子食一簞。","歡然乐其志，有以忘飢寒。","今我何人哉，德不及先賢。","衣食幸相屬，胡爲不自安。","況茲清渭曲，居处安且闲。","榆柳百餘樹，茅茨十數间。","寒負檐下日，熱濯澗底泉。","日出猶未起，日入已复眠。","西风满村巷，清涼八月天。","但有雞犬声，不闻车马喧。","时傾一尊酒，坐望东南山。","穉姪初学步，牽衣戲我前。","即此自可乐，庶幾顏與原。"]', '诗', 'shi', '', NULL, '效陶潛體詩十六首 九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8b6c8d6-515d-4849-9cac-b4dcf377cbac', '效陶潛體詩十六首 十', '效陶潛體诗十六首 十', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["湛湛尊中酒，有功不自伐。","不伐人不知，我今代其說。","良將臨大敵，前驅千萬卒。","一簞投河飲，赴死心如一。","壯士磨匕首，勇憤氣咆𠷺。","一酣忘報讎，四體如無骨。","東海殺孝婦，天旱踰年月。","一酌酹其魂，通宵雨不歇。","咸陽秦獄氣，冤痛結爲物。","千歲不肯散，一沃亦銷失。","況茲兒女恨，及彼幽憂疾。","快飲無不消，如霜得春日。","方知麴糵靈，萬物無與匹。"]', '["湛湛尊中酒，有功不自伐。","不伐人不知，我今代其说。","良將臨大敵，前驱千万卒。","一簞投河饮，赴死心如一。","壯士磨匕首，勇憤氣咆𠷺。","一酣忘報讎，四體如無骨。","东海殺孝婦，天旱踰年月。","一酌酹其魂，通宵雨不歇。","咸陽秦獄氣，冤痛結爲物。","千歲不肯散，一沃亦銷失。","況茲兒女恨，及彼幽憂疾。","快饮無不消，如霜得春日。","方知麴糵靈，万物無與匹。"]', '诗', 'shi', '', NULL, '效陶潛體詩十六首 十 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72a82b99-99c9-4434-80a6-40603ce695c9', '效陶潛體詩十六首 十一', '效陶潛體诗十六首 十一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["煙霞隔懸圃，風波限瀛州。","我豈不欲往，大海路阻修。","神仙但聞說，靈藥不可求。","長生無得者，舉世如蜉蝣。","逝者不重迴，存者難久留。","踟躕未死間，何苦懷百憂。","念此忽內熱，坐看成白頭。","舉杯還獨飲，顧影自獻酬。","心與口相約，未醉勿言休。","今朝不盡醉，知有明朝不。","不見郭門外，纍纍墳與丘。","月明愁殺人，黃蒿風颼颼。","死者若有知，悔不秉燭遊。"]', '["煙霞隔懸圃，风波限瀛州。","我豈不欲往，大海路阻修。","神仙但闻说，靈藥不可求。","长生無得者，舉世如蜉蝣。","逝者不重迴，存者难久留。","踟躕未死间，何苦懷百憂。","念此忽內熱，坐看成白头。","舉杯還独饮，顧影自獻酬。","心與口相約，未醉勿言休。","今朝不尽醉，知有明朝不。","不见郭门外，纍纍墳與丘。","月明愁殺人，黄蒿风颼颼。","死者若有知，悔不秉燭游。"]', '诗', 'shi', '', NULL, '效陶潛體詩十六首 十一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cc2c275-b879-4096-8b49-14016ce9f08b', '效陶潛體詩十六首 十二', '效陶潛體诗十六首 十二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吾聞潯陽郡，昔有陶徵君。","愛酒不愛名，憂醒不憂貧。","嘗爲彭澤令，在官纔八旬。","愀然忽不樂，挂印著公門。","口吟歸去來，頭戴漉酒巾。","人吏留不得，直入故山雲。","歸來五柳下，還以酒養真。","人間榮與利，擺落如泥塵。","先生去已久，紙墨有遺文。","篇篇勸我飲，此外無所云。","我從老大來，竊慕其爲人。","其他不可及，且傚醉昏昏。"]', '["吾闻潯陽郡，昔有陶徵君。","愛酒不愛名，憂醒不憂貧。","嘗爲彭澤令，在官纔八旬。","愀然忽不乐，挂印著公门。","口吟归去来，头戴漉酒巾。","人吏留不得，直入故山云。","归来五柳下，還以酒養真。","人间榮與利，擺落如泥塵。","先生去已久，紙墨有遺文。","篇篇勸我饮，此外無所云。","我從老大来，竊慕其爲人。","其他不可及，且傚醉昏昏。"]', '诗', 'shi', '', NULL, '效陶潛體詩十六首 十二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf60488c-4043-4cf3-893a-b26755c0596e', '效陶潛體詩十六首 十三', '效陶潛體诗十六首 十三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["楚王疑忠臣，江南放屈平。","晉朝輕高士，林下棄劉伶。","一人常獨醉，一人常獨醒。","醒者多苦志，醉者多歡情。","歡情信獨善，苦志竟何成。","兀傲甕間臥，顦顇澤畔行。","彼憂而此樂，道理甚分明。","願君且飲酒，勿思身後名。"]', '["楚王疑忠臣，江南放屈平。","晉朝轻高士，林下棄劉伶。","一人常独醉，一人常独醒。","醒者多苦志，醉者多歡情。","歡情信独善，苦志竟何成。","兀傲甕间臥，顦顇澤畔行。","彼憂而此乐，道理甚分明。","願君且饮酒，勿思身後名。"]', '诗', 'shi', '', NULL, '效陶潛體詩十六首 十三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e09f4a35-1c1b-41f4-a038-6919770c3d22', '效陶潛體詩十六首 十四', '效陶潛體诗十六首 十四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有一燕趙士，言貌甚奇瓌。","日日酒家去，脫衣典數杯。","問君何落拓，云僕生草萊。","地寒命且薄，徒抱王佐才。","豈無濟時策，君門乏良媒。","三獻寢不報，遲遲空手迴。","亦有同門生，先升青雲梯。","貴賤交道絕，朱門叩不開。","及歸種禾黍，三歲旱爲災。","入山燒黃白，一旦化爲灰。","蹉跎五十餘，生世苦不諧。","處處去不得，却歸酒中來。"]', '["有一燕趙士，言貌甚奇瓌。","日日酒家去，脫衣典數杯。","问君何落拓，云僕生草萊。","地寒命且薄，徒抱王佐才。","豈無濟时策，君门乏良媒。","三獻寢不報，遲遲空手迴。","亦有同门生，先升青云梯。","貴賤交道絕，朱门叩不开。","及归種禾黍，三歲旱爲災。","入山燒黄白，一旦化爲灰。","蹉跎五十餘，生世苦不諧。","处处去不得，却归酒中来。"]', '诗', 'shi', '', NULL, '效陶潛體詩十六首 十四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d208efd-9a44-40e6-9bbe-748626c5a00c', '效陶潛體詩十六首 十五', '效陶潛體诗十六首 十五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南巷有貴人，高蓋駟馬車。","我問何所苦，四十垂白鬚。","荅云君不知，位重多憂虞。","北里有寒士，甕牖繩爲樞。","出扶桑棗杖，入臥蝸牛廬。","散賤無憂患，心安體亦舒。","東鄰有富翁，藏貨徧五都。","東京收粟帛，西市鬻金珠。","朝營暮計算，晝夜不安居。","西舍有貧者，匹婦配匹夫。","布帬行賃舂，裋褐坐傭書。","以此求口食，一飽欣有餘。","貴賤與貧富，高下雖有殊。","憂樂與利害，彼此不相踰。","是以達人觀，萬化同一途。","但未知生死，勝負兩何如。","遲疑未知間，且以酒爲娛。"]', '["南巷有貴人，高蓋駟马车。","我问何所苦，四十垂白鬚。","荅云君不知，位重多憂虞。","北里有寒士，甕牖繩爲樞。","出扶桑棗杖，入臥蝸牛廬。","散賤無憂患，心安體亦舒。","东鄰有富翁，藏貨徧五都。","东京收粟帛，西市鬻金珠。","朝營暮計算，晝夜不安居。","西舍有貧者，匹婦配匹夫。","布帬行賃舂，裋褐坐傭书。","以此求口食，一飽欣有餘。","貴賤與貧富，高下雖有殊。","憂乐與利害，彼此不相踰。","是以達人观，万化同一途。","但未知生死，勝負兩何如。","遲疑未知间，且以酒爲娛。"]', '诗', 'shi', '', NULL, '效陶潛體詩十六首 十五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c3699db-7445-416d-8c1f-2baecbe4654a', '效陶潛體詩十六首 十六', '效陶潛體诗十六首 十六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["濟水澄而潔，河水渾而黃。","交流列四瀆，清濁不相傷。","太公戰牧野，伯夷餓首陽。","同時號賢聖，進退不相妨。","謂天不愛民，胡爲生稻粱。","謂天果愛民，胡爲生豺狼。","謂神福善人，孔聖竟栖遑。","謂神禍淫人，暴秦終霸王。","顏回與黃憲，何辜早夭亡。","蝮蛇與鴆鳥，何得壽延長。","物理不可測，神道亦難量。","舉頭仰問天，天色但蒼蒼。","唯當多種黍，日醉手中觴。"]', '["濟水澄而潔，河水渾而黄。","交流列四瀆，清濁不相傷。","太公戰牧野，伯夷餓首陽。","同时號賢聖，進退不相妨。","謂天不愛民，胡爲生稻粱。","謂天果愛民，胡爲生豺狼。","謂神福善人，孔聖竟栖遑。","謂神禍淫人，暴秦終霸王。","顏回與黄憲，何辜早夭亡。","蝮蛇與鴆鸟，何得壽延长。","物理不可測，神道亦难量。","舉头仰问天，天色但蒼蒼。","唯當多種黍，日醉手中觴。"]', '诗', 'shi', '', NULL, '效陶潛體詩十六首 十六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b25301f-0040-41ae-a94c-58ca372eb88d', '自題寫真', '自題寫真', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我貌不自識，李放寫我真。","靜觀神與骨，合是山中人。","蒲柳質易朽，麋鹿心難馴。","何事赤墀上，五年爲侍臣。","況多剛狷性，難與世同塵。","不惟非貴相，但恐生禍因。","宜當早罷去，收取雲泉身。"]', '["我貌不自識，李放寫我真。","静观神與骨，合是山中人。","蒲柳質易朽，麋鹿心难馴。","何事赤墀上，五年爲侍臣。","況多剛狷性，难與世同塵。","不惟非貴相，但恐生禍因。","宜當早罷去，收取云泉身。"]', '诗', 'shi', '', NULL, '自題寫真 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('646f778f-c4ec-44ce-b7f5-adda355d5d82', '遣懷', '遣懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["寓心身體中，寓性方寸內。","此身是外物，何足苦憂愛。","況有假飾者，華簪及高蓋。","此又疎於身，復在外物外。","操之多惴慄，失之又悲悔。","乃知名與器，得喪俱爲害。","頹然環堵客，蘿蕙爲巾帶。","自得此道來，身窮心甚泰。"]', '["寓心身體中，寓性方寸內。","此身是外物，何足苦憂愛。","況有假飾者，华簪及高蓋。","此又疎於身，复在外物外。","操之多惴慄，失之又悲悔。","乃知名與器，得喪俱爲害。","頹然环堵客，蘿蕙爲巾带。","自得此道来，身窮心甚泰。"]', '诗', 'shi', '', NULL, '遣懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89e6c303-aa37-4256-988b-b49a910cf875', '渭上偶釣', '渭上偶釣', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["渭水如鏡色，中有鯉與魴。","偶持一竿竹，懸釣在其傍。","微風吹釣絲，嫋嫋十尺長。","誰知對魚坐，心在無何鄉。","昔有白頭人，亦釣此渭陽。","釣人不釣魚，七十得文王。","況我垂釣意，人魚又兼忘。","無機兩不得，但弄秋水光。","興盡釣亦罷，歸來飲我觴。"]', '["渭水如镜色，中有鯉與魴。","偶持一竿竹，懸釣在其傍。","微风吹釣絲，嫋嫋十尺长。","誰知对鱼坐，心在無何乡。","昔有白头人，亦釣此渭陽。","釣人不釣鱼，七十得文王。","況我垂釣意，人鱼又兼忘。","無機兩不得，但弄秋水光。","兴尽釣亦罷，归来饮我觴。"]', '诗', 'shi', '', NULL, '渭上偶釣 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4c24922-4611-4d65-a3d5-fd3c8afb0bfa', '隱几', '隐几', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["身適忘四支，心適忘是非。","既適又忘適，不知吾是誰。","百體如槁木，兀然無所知。","方寸如死灰，寂然無所思。","今日復明日，身心忽兩遺。","行年三十九，歲暮日斜時。","四十心不動，吾今其庶幾。"]', '["身適忘四支，心適忘是非。","既適又忘適，不知吾是誰。","百體如槁木，兀然無所知。","方寸如死灰，寂然無所思。","今日复明日，身心忽兩遺。","行年三十九，歲暮日斜时。","四十心不动，吾今其庶幾。"]', '诗', 'shi', '', NULL, '隱几 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('100d4d7b-b17d-4349-af23-b77217a27792', '春眠', '春眠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["新浴肢體暢，獨寢神魂安。","況因夜深坐，遂成日高眠。","春被薄亦暖，朝窗深更閑。","却忘人間事，似得枕上仙。","至適無夢想，大和難名言。","全勝彭澤醉，欲敵曹溪禪。","何物呼我覺，伯勞聲關關。","起來妻子笑，生計春茫然。"]', '["新浴肢體暢，独寢神魂安。","況因夜深坐，遂成日高眠。","春被薄亦暖，朝窗深更闲。","却忘人间事，似得枕上仙。","至適無梦想，大和难名言。","全勝彭澤醉，欲敵曹溪禪。","何物呼我覺，伯勞声关关。","起来妻子笑，生計春茫然。"]', '诗', 'shi', '', NULL, '春眠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9599cedd-119a-4144-bcb6-efc36492bdf7', '閑居', '闲居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["空腹一醆粥，飢食有餘味。","南檐半牀日，暖臥因成睡。","緜袍擁兩膝，竹几支雙臂。","從旦直至昏，身心一無事。","心足即爲富，身閑乃當貴。","富貴在此中，何必居高位。","君看裴相國，金紫光照地。","心苦頭盡白，纔年四十四。","乃知高蓋車，乘者多憂畏。"]', '["空腹一醆粥，飢食有餘味。","南檐半牀日，暖臥因成睡。","緜袍擁兩膝，竹几支雙臂。","從旦直至昏，身心一無事。","心足即爲富，身闲乃當貴。","富貴在此中，何必居高位。","君看裴相国，金紫光照地。","心苦头尽白，纔年四十四。","乃知高蓋车，乘者多憂畏。"]', '诗', 'shi', '', NULL, '閑居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c71310ad-4a41-4943-8b6e-fc6ca3a0232a', '夏日', '夏日', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["東窗晚無熱，北戶涼有風。","盡日坐復臥，不離一室中。","中心本無繫，亦與出門同。"]', '["东窗晚無熱，北戶涼有风。","尽日坐复臥，不離一室中。","中心本無繫，亦與出门同。"]', '诗', 'shi', '', NULL, '夏日 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e2c7980-5c28-43ed-9cf1-eb5a9486dc51', '適意二首 一', '適意二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["十年爲旅客，常有飢寒愁。","三年作諫官，復多尸素羞。","有酒不暇飲，有山不得遊。","豈無平生志，拘牽不自由。","一朝歸渭上，泛如不繫舟。","置心世事外，無喜亦無憂。","終日一蔬食，終年一布裘。","寒來彌嬾放，數日一梳頭。","朝睡足始起，夜酌醉即休。","人心不過適，適外復何求。"]', '["十年爲旅客，常有飢寒愁。","三年作諫官，复多尸素羞。","有酒不暇饮，有山不得游。","豈無平生志，拘牽不自由。","一朝归渭上，泛如不繫舟。","置心世事外，無喜亦無憂。","終日一蔬食，終年一布裘。","寒来彌嬾放，數日一梳头。","朝睡足始起，夜酌醉即休。","人心不過適，適外复何求。"]', '诗', 'shi', '', NULL, '適意二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a20cfc9-c169-4fd9-a3a0-259c0f13915c', '適意二首 二', '適意二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["早歲從旅遊，頗諳時俗意。","中年忝班列，備見朝廷事。","作客誠已難，爲臣尤不易。","況余方且介，舉動多忤累。","直道速我尤，詭遇非吾志。","胸中十年內，消盡浩然氣。","自從返田畝，頓覺無憂媿。","蟠木用難施，浮雲心易遂。","悠悠身與世，從此兩相棄。"]', '["早歲從旅游，頗諳时俗意。","中年忝班列，備见朝廷事。","作客誠已难，爲臣尤不易。","況余方且介，舉动多忤累。","直道速我尤，詭遇非吾志。","胸中十年內，消尽浩然氣。","自從返田畝，頓覺無憂媿。","蟠木用难施，浮云心易遂。","悠悠身與世，從此兩相棄。"]', '诗', 'shi', '', NULL, '適意二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b852ffda-f2fc-490b-8744-f4048c17e7ca', '首夏病間', '首夏病间', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我生來幾時，萬有四千日。","自省於其間，非憂即有疾。","老去慮漸息，年來病初愈。","忽喜身與心，泰然兩無苦。","況茲孟夏月，清和好時節。","微風吹裌衣，不寒復不熱。","移榻樹陰下，竟日何所爲。","或飲一甌茗，或吟兩句詩。","內無憂患迫，外無職役羈。"]', '["我生来幾时，万有四千日。","自省於其间，非憂即有疾。","老去慮漸息，年来病初愈。","忽喜身與心，泰然兩無苦。","況茲孟夏月，清和好时節。","微风吹裌衣，不寒复不熱。","移榻樹陰下，竟日何所爲。","或饮一甌茗，或吟兩句诗。","內無憂患迫，外無職役羈。"]', '诗', 'shi', '', NULL, '首夏病間 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c720ef6c-cdc2-41e5-ad2a-6edffff34ea2', '晚春酤酒', '晚春酤酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["百花落如雪，兩鬢垂作絲。","春去有來日，我老無少時。","人生待富貴，爲樂常苦遲。","不如貧賤日，隨分開愁眉。","賣我所乘馬，典我舊朝衣。","盡將酤酒飲，酩酊步行歸。","名姓日隱晦，形骸日變衰。","醉臥黃公肆，人知我是誰。"]', '["百花落如雪，兩鬢垂作絲。","春去有来日，我老無少时。","人生待富貴，爲乐常苦遲。","不如貧賤日，隨分开愁眉。","賣我所乘马，典我旧朝衣。","尽將酤酒饮，酩酊步行归。","名姓日隐晦，形骸日变衰。","醉臥黄公肆，人知我是誰。"]', '诗', 'shi', '', NULL, '晚春酤酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5e4b04e-04c3-467e-877c-8d3b7ab5e567', '蘭若寓居', '蘭若寓居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["名宦老慵求，退身安草野。","家園病嬾歸，寄居在蘭若。","薜衣換簪組，藜杖代車馬。","行止輒自由，甚覺身瀟灑。","晨遊南塢上，夜息東庵下。","人間千萬事，無有關心者。"]', '["名宦老慵求，退身安草野。","家园病嬾归，寄居在蘭若。","薜衣換簪組，藜杖代车马。","行止輒自由，甚覺身瀟灑。","晨游南塢上，夜息东庵下。","人间千万事，無有关心者。"]', '诗', 'shi', '', NULL, '蘭若寓居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b634dfac-b739-4132-87cb-5f342f75d83a', '麴生訪宿', '麴生訪宿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["西齋寂已暮，叩門聲樀樀。","知是君宿來，自拂塵埃席。","村家何所有，茶果迎來客。","貧靜似僧居，竹林依四壁。","廚燈斜影出，檐雨餘聲滴。"]', '["西斋寂已暮，叩门声樀樀。","知是君宿来，自拂塵埃席。","村家何所有，茶果迎来客。","貧静似僧居，竹林依四壁。","廚灯斜影出，檐雨餘声滴。"]', '诗', 'shi', '', NULL, '麴生訪宿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3db5fae-efc6-4076-a30b-f5844c9fcfee', '聞庾七左降因詠所懷', '闻庾七左降因詠所懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我病臥渭北，君老謫巴東。","相悲一長歎，薄命與君同。","既歎還自哂，哂歎兩未終。","後心誚前意，所見何迷蒙。","人生大塊間，如鴻毛在風。","或飄青雲上，或落泥塗中。","衮服相天下，儻來非我通。","布衣委草莽，偶去非吾窮。","外物不可必，中懷須自空。","無令怏怏氣，留滯在心胸。"]', '["我病臥渭北，君老謫巴东。","相悲一长歎，薄命與君同。","既歎還自哂，哂歎兩未終。","後心誚前意，所见何迷蒙。","人生大塊间，如鴻毛在风。","或飄青云上，或落泥塗中。","衮服相天下，儻来非我通。","布衣委草莽，偶去非吾窮。","外物不可必，中懷須自空。","無令怏怏氣，留滯在心胸。"]', '诗', 'shi', '', NULL, '聞庾七左降因詠所懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdf08941-65a2-4477-845b-61bdd13c9040', '荅卜者', '荅卜者', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["病眼昏似夜，衰鬢颯如秋。","除却須衣食，平生百事休。","知君善易者，問我決疑不。","不卜非他故，人間無所求。"]', '["病眼昏似夜，衰鬢颯如秋。","除却須衣食，平生百事休。","知君善易者，问我決疑不。","不卜非他故，人间無所求。"]', '诗', 'shi', '', NULL, '荅卜者 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2fb4f68-8944-47f0-8ffe-2f8bfc0c874c', '歸田三首 一', '归田三首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人生何所欲，所欲唯兩端。","中人愛富貴，高士慕神仙。","神仙須有籍，富貴亦在天。","莫戀長安道，莫尋方丈山。","西京塵浩浩，東海浪漫漫。","金門不可入，琪樹何由攀。","不如歸山下，如法種春田。"]', '["人生何所欲，所欲唯兩端。","中人愛富貴，高士慕神仙。","神仙須有籍，富貴亦在天。","莫戀长安道，莫尋方丈山。","西京塵浩浩，东海浪漫漫。","金门不可入，琪樹何由攀。","不如归山下，如法種春田。"]', '诗', 'shi', '', NULL, '歸田三首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c73c782a-3f4f-4466-a766-95e6fcd903aa', '歸田三首 二', '归田三首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["種田意已決，決意復何如。","賣馬買犢使，徒步歸田廬。","迎春治耒耜，候雨闢菑畬。","策杖田頭立，躬親課僕夫。","吾聞老農言，爲稼慎在初。","所施不鹵莽，其報必有餘。","上求奉王稅，下望備家儲。","安得放慵惰，拱手而曳裾。","學農未爲鄙，親友勿笑余。","更待明年後，自擬執犂鋤。"]', '["種田意已決，決意复何如。","賣马買犢使，徒步归田廬。","迎春治耒耜，候雨闢菑畬。","策杖田头立，躬親課僕夫。","吾闻老農言，爲稼慎在初。","所施不鹵莽，其報必有餘。","上求奉王稅，下望備家儲。","安得放慵惰，拱手而曳裾。","学農未爲鄙，親友勿笑余。","更待明年後，自擬執犂鋤。"]', '诗', 'shi', '', NULL, '歸田三首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea9c4952-d7e9-4507-8d16-06a6a450c62c', '歸田三首 三', '归田三首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三十爲近臣，腰間鳴佩玉。","四十爲野夫，田中學鋤穀。","何言十年內，變化如此速。","此理固是常，窮通相倚伏。","爲魚有深水，爲鳥有高木。","何必守一方，窘然自牽束。","化吾足爲馬，吾因以行陸。","化吾手爲彈，吾因以求肉。","形骸爲異物，委順心猶足。","幸得且歸農，安知不爲福。","況吾行欲老，瞥若風前燭。","孰能俄頃間，將心繫榮辱。"]', '["三十爲近臣，腰间鳴佩玉。","四十爲野夫，田中学鋤穀。","何言十年內，变化如此速。","此理固是常，窮通相倚伏。","爲鱼有深水，爲鸟有高木。","何必守一方，窘然自牽束。","化吾足爲马，吾因以行陸。","化吾手爲彈，吾因以求肉。","形骸爲異物，委順心猶足。","幸得且归農，安知不爲福。","況吾行欲老，瞥若风前燭。","孰能俄頃间，將心繫榮辱。"]', '诗', 'shi', '', NULL, '歸田三首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('850812cc-ff9b-4b70-b64b-c2252ff1b460', '秋遊原上', '秋游原上', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["七月行已半，早涼天氣清。","清晨起巾櫛，徐步出柴荆。","露杖筇竹冷，風襟越蕉輕。","閑攜弟姪輩，同上秋原行。","新棗未全赤，晚瓜有餘馨。","依依田家叟，設此相逢迎。","自我到此村，往來白髮生。","村中相識久，老幼皆有情。","留連向暮歸，樹樹風蟬聲。","是時新雨足，禾黍夾道青。","見此令人飽，何必待西成。"]', '["七月行已半，早涼天氣清。","清晨起巾櫛，徐步出柴荆。","露杖筇竹冷，风襟越蕉轻。","闲携弟姪輩，同上秋原行。","新棗未全赤，晚瓜有餘馨。","依依田家叟，設此相逢迎。","自我到此村，往来白髮生。","村中相識久，老幼皆有情。","留連向暮归，樹樹风蟬声。","是时新雨足，禾黍夾道青。","见此令人飽，何必待西成。"]', '诗', 'shi', '', NULL, '秋遊原上 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8ce0e24-c5d4-4029-9b42-0bc01ef0692a', '九日登西原宴望', '九日登西原宴望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["病愛枕席涼，日高眠未輟。","弟兄呼我起，今日重陽節。","起登西原望，懷抱同一豁。","移座就菊叢，餻酒前羅列。","雖無絲與管，歌笑隨情發。","白日未及傾，顏酡耳已熱。","酒酣四向望，六合何空闊。","天地自久長，斯人幾時活。","請看原下村，村人死不歇。","一村四十家，哭葬無虛月。","指此各相勉，良辰且歡悅。"]', '["病愛枕席涼，日高眠未輟。","弟兄呼我起，今日重陽節。","起登西原望，懷抱同一豁。","移座就菊叢，餻酒前羅列。","雖無絲與管，歌笑隨情發。","白日未及傾，顏酡耳已熱。","酒酣四向望，六合何空闊。","天地自久长，斯人幾时活。","請看原下村，村人死不歇。","一村四十家，哭葬無虛月。","指此各相勉，良辰且歡悅。"]', '诗', 'shi', '', NULL, '九日登西原宴望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6244ff7-d8a1-42a3-93d7-db4efc6e08c7', '寄同病者', '寄同病者', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三十生二毛，早衰爲沈疴。","四十官七品，拙宦非由他。","年顏日枯槁，時命日蹉跎。","豈獨我如此，聖賢無奈何。","迴觀親舊中，舉目尤可嗟。","或有終老者，沈賤如泥沙。","或有始壯者，飄忽如風花。","窮餓與夭促，不如我者多。","以此反自慰，常得心平和。","寄言同病者，迴歎且爲歌。"]', '["三十生二毛，早衰爲沈疴。","四十官七品，拙宦非由他。","年顏日枯槁，时命日蹉跎。","豈独我如此，聖賢無奈何。","迴观親旧中，舉目尤可嗟。","或有終老者，沈賤如泥沙。","或有始壯者，飄忽如风花。","窮餓與夭促，不如我者多。","以此反自慰，常得心平和。","寄言同病者，迴歎且爲歌。"]', '诗', 'shi', '', NULL, '寄同病者 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52624350-b963-4cd2-85de-22327c0d4f7d', '遊藍田山卜居', '游藍田山卜居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["脫置腰下組，擺落心中塵。","行歌望山去，意似歸鄉人。","朝蹋玉峰下，暮尋藍水濱。","擬求幽僻地，安置疎慵身。","本性便山寺，應須旁悟真。"]', '["脫置腰下組，擺落心中塵。","行歌望山去，意似归乡人。","朝蹋玉峰下，暮尋藍水濱。","擬求幽僻地，安置疎慵身。","本性便山寺，應須旁悟真。"]', '诗', 'shi', '', NULL, '遊藍田山卜居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca89fae6-22a5-48aa-a3fc-a580694efb0d', '村雪夜坐', '村雪夜坐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南窗背燈坐，風霰暗紛紛。","寂莫深村夜，殘雁雪中聞。"]', '["南窗背灯坐，风霰暗紛紛。","寂莫深村夜，殘雁雪中闻。"]', '诗', 'shi', '', NULL, '村雪夜坐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f0fc2c7-01ca-4d6b-93b9-f41de3efca31', '東園玩菊', '东园玩菊', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["少年昨已去，芳歲今又闌。","如何寂莫意，復此荒涼園。","園中獨立久，日澹風露寒。","秋蔬盡蕪沒，好樹亦凋殘。","唯有數叢菊，新開籬落間。","攜觴聊就酌，爲爾一留連。","憶我少小日，易爲興所牽。","見酒無時節，未飲已欣然。","近從年長來，漸覺取樂難。","常恐更衰老，強飲亦無歡。","顧謂爾菊花，後時何獨鮮。","誠知不爲我，借爾暫開顏。"]', '["少年昨已去，芳歲今又闌。","如何寂莫意，复此荒涼园。","园中独立久，日澹风露寒。","秋蔬尽蕪沒，好樹亦凋殘。","唯有數叢菊，新开籬落间。","携觴聊就酌，爲爾一留連。","憶我少小日，易爲兴所牽。","见酒無时節，未饮已欣然。","近從年长来，漸覺取乐难。","常恐更衰老，強饮亦無歡。","顧謂爾菊花，後时何独鲜。","誠知不爲我，借爾暫开顏。"]', '诗', 'shi', '', NULL, '東園玩菊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7da9ea30-865f-4949-b053-7e5d29392c74', '觀稼', '观稼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["世役不我牽，身心常自若。","晚出看田畝，閑行旁村落。","纍纍繞場稼，嘖嘖羣飛雀。","年豐豈獨人，禽鳥聲亦樂。","田翁逢我喜，默起具尊杓。","斂手笑相延，社酒有殘酌。","媿茲勤且敬，藜杖爲淹泊。","言動任天真，未覺農人惡。","停杯問生事，夫種妻兒穫。","筋力苦疲勞，衣食常單薄。","自慙祿仕者，曾不營農作。","飽食無所勞，何殊衛人鶴。"]', '["世役不我牽，身心常自若。","晚出看田畝，闲行旁村落。","纍纍繞場稼，嘖嘖羣飞雀。","年豐豈独人，禽鸟声亦乐。","田翁逢我喜，默起具尊杓。","斂手笑相延，社酒有殘酌。","媿茲勤且敬，藜杖爲淹泊。","言动任天真，未覺農人惡。","停杯问生事，夫種妻兒穫。","筋力苦疲勞，衣食常單薄。","自慙祿仕者，曾不營農作。","飽食無所勞，何殊衛人鹤。"]', '诗', 'shi', '', NULL, '觀稼 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('590e105b-be7e-42d6-98a5-e206ce7a1dc0', '聞哭者', '闻哭者', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昨日南鄰哭，哭聲一何苦。","云是妻哭夫，夫年二十五。","今朝北里哭，哭聲又何切。","云是母哭兒，兒年十七八。","四鄰尚如此，天下多夭折。","乃知浮世人，少得垂白髮。","余今過四十，念彼聊自悅。","從此明鏡中，不嫌頭似雪。"]', '["昨日南鄰哭，哭声一何苦。","云是妻哭夫，夫年二十五。","今朝北里哭，哭声又何切。","云是母哭兒，兒年十七八。","四鄰尚如此，天下多夭折。","乃知浮世人，少得垂白髮。","余今過四十，念彼聊自悅。","從此明镜中，不嫌头似雪。"]', '诗', 'shi', '', NULL, '聞哭者 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ea52501-9638-4dae-be7a-02b8f8010973', '新構亭臺示諸弟姪', '新構亭台示諸弟姪', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["平臺高數尺，臺上結茅茨。","東西疏二牖，南北開兩扉。","蘆簾前後卷，竹簟當中施。","清泠白石枕，疏涼黃葛衣。","開襟向風坐，夏日如秋時。","嘯傲頗有趣，窺臨不知疲。","東窗對華山，三峰碧參差。","南檐當渭水，臥見雲帆飛。","仰摘枝上果，俯折畦中葵。","足以充飢渴，何必慕甘肥。","況有好羣從，旦夕相追隨。"]', '["平台高數尺，台上結茅茨。","东西疏二牖，南北开兩扉。","蘆簾前後卷，竹簟當中施。","清泠白石枕，疏涼黄葛衣。","开襟向风坐，夏日如秋时。","嘯傲頗有趣，窺臨不知疲。","东窗对华山，三峰碧參差。","南檐當渭水，臥见云帆飞。","仰摘枝上果，俯折畦中葵。","足以充飢渴，何必慕甘肥。","況有好羣從，旦夕相追隨。"]', '诗', 'shi', '', NULL, '新構亭臺示諸弟姪 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8872c66-d342-4afc-8833-8ad72889f26d', '自吟拙什因有所懷', '自吟拙什因有所懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["嬾病每多暇，暇來何所爲。","未能拋筆研，時作一篇詩。","詩成澹無味，多被衆人嗤。","上怪落聲韻，下嫌拙言詞。","時時自吟詠，吟罷有所思。","蘇州及彭澤，與我不同時。","此外復誰愛，唯有元微之。","謫向江陵府，三年作判司。","向去二千里，詩成遠不知。"]', '["嬾病每多暇，暇来何所爲。","未能拋笔研，时作一篇诗。","诗成澹無味，多被衆人嗤。","上怪落声韻，下嫌拙言词。","时时自吟詠，吟罷有所思。","蘇州及彭澤，與我不同时。","此外复誰愛，唯有元微之。","謫向江陵府，三年作判司。","向去二千里，诗成远不知。"]', '诗', 'shi', '', NULL, '自吟拙什因有所懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a69536ea-c876-479a-8bfe-b49b07559f56', '東坡秋意寄元八', '东坡秋意寄元八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["寥落野陂畔，獨行思有餘。","秋荷病葉上，白露大如珠。","忽憶同賞地，曲江東北隅。","秋池少遊客，唯我與君俱。","啼蛩隱紅蓼，瘦馬蹋青蕪。","當時與今日，俱是暮秋初。","節物苦相似，時景亦無餘。","唯有人分散，經年不得書。"]', '["寥落野陂畔，独行思有餘。","秋荷病葉上，白露大如珠。","忽憶同賞地，曲江东北隅。","秋池少游客，唯我與君俱。","啼蛩隐紅蓼，瘦马蹋青蕪。","當时與今日，俱是暮秋初。","節物苦相似，时景亦無餘。","唯有人分散，經年不得书。"]', '诗', 'shi', '', NULL, '東坡秋意寄元八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d4e9331-73c1-41c1-955e-99136a295d1e', '閑居', '闲居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["深閉竹間扉，靜埽松下地。","獨嘯晚風前，何人知此意。","看山盡日坐，枕帙移時睡。","誰能從我遊，使君心無事。"]', '["深閉竹间扉，静埽松下地。","独嘯晚风前，何人知此意。","看山尽日坐，枕帙移时睡。","誰能從我游，使君心無事。"]', '诗', 'shi', '', NULL, '閑居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4436f0c3-1c8a-4ba7-9d81-8a63ebc85eda', '詠拙', '詠拙', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["所稟有巧拙，不可改者性。","所賦有厚薄，不可移者命。","我性愚且惷，我命薄且屯。","問我何以知，所知良有因。","亦曾舉兩足，學人蹋紅塵。","從茲知性拙，不解轉如輪。","亦曾奮六翮，高飛到青雲。","從茲知命薄，摧落不逡巡。","慕貴而厭賤，樂富而惡貧。","同此天地間，我豈異於人。","性命苟如此，反則成苦辛。","以此自安分，雖窮每欣欣。","葺茅爲我廬，編蓬爲我門。","縫布作袍被，種穀充盤飧。","靜讀古人書，閑釣清渭濱。","優哉復游哉，聊以終吾身。"]', '["所稟有巧拙，不可改者性。","所賦有厚薄，不可移者命。","我性愚且惷，我命薄且屯。","问我何以知，所知良有因。","亦曾舉兩足，学人蹋紅塵。","從茲知性拙，不解轉如輪。","亦曾奮六翮，高飞到青云。","從茲知命薄，摧落不逡巡。","慕貴而厭賤，乐富而惡貧。","同此天地间，我豈異於人。","性命苟如此，反則成苦辛。","以此自安分，雖窮每欣欣。","葺茅爲我廬，編蓬爲我门。","縫布作袍被，種穀充盤飧。","静读古人书，闲釣清渭濱。","優哉复游哉，聊以終吾身。"]', '诗', 'shi', '', NULL, '詠拙 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a17f6c9-15bb-408e-b948-e2b80b5bff85', '詠慵', '詠慵', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有官慵不選，有田慵不農。","屋穿慵不葺，衣裂慵不縫。","有酒慵不酌，無異尊常空。","有琴慵不彈，亦與無弦同。","家人告飯盡，欲炊慵不舂。","親朋寄書至，欲讀慵開封。","嘗聞嵇叔夜，一生在慵中。","彈琴復鍛鐵，比我未爲慵。"]', '["有官慵不選，有田慵不農。","屋穿慵不葺，衣裂慵不縫。","有酒慵不酌，無異尊常空。","有琴慵不彈，亦與無弦同。","家人告飯尽，欲炊慵不舂。","親朋寄书至，欲读慵开封。","嘗闻嵇叔夜，一生在慵中。","彈琴复鍛鐵，比我未爲慵。"]', '诗', 'shi', '', NULL, '詠慵 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d045d20d-d445-4a36-9d64-e5caa4f44f82', '冬夜', '冬夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["家貧親愛散，身病交遊罷。","眼前無一人，獨掩村齋臥。","冷落燈火闇，離披簾幕破。","策策窗戶前，又聞新雪下。","長年漸省睡，夜半起端坐。","不學坐忘心，寂莫安可過。","兀然身寄世，浩然心委化。","如此來四年，一千三百夜。"]', '["家貧親愛散，身病交游罷。","眼前無一人，独掩村斋臥。","冷落灯火闇，離披簾幕破。","策策窗戶前，又闻新雪下。","长年漸省睡，夜半起端坐。","不学坐忘心，寂莫安可過。","兀然身寄世，浩然心委化。","如此来四年，一千三百夜。"]', '诗', 'shi', '', NULL, '冬夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1721e2a0-689e-4ddc-aaf2-8dbefdae6bf7', '村中留李三固言宿', '村中留李三固言宿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["平生早遊宦，不道無親故。","如我與君心，相知應有數。","春明門前別，金氏陂中遇。","村酒兩三杯，相留寒日暮。","勿嫌村酒薄，聊酌論心素。","請君少踟躕，繫馬門前樹。","明年身若健，便擬江湖去。","他日縱相思，知君無覓處。","後會既茫茫，今宵君且住。"]', '["平生早游宦，不道無親故。","如我與君心，相知應有數。","春明门前別，金氏陂中遇。","村酒兩三杯，相留寒日暮。","勿嫌村酒薄，聊酌論心素。","請君少踟躕，繫马门前樹。","明年身若健，便擬江湖去。","他日縱相思，知君無覓处。","後會既茫茫，今宵君且住。"]', '诗', 'shi', '', NULL, '村中留李三固言宿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd0249f0-c511-4987-8d76-acccc27683bd', '友人夜訪', '友人夜訪', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["檐間清風簟，松下明月杯。","幽意正如此，況乃故人來。"]', '["檐间清风簟，松下明月杯。","幽意正如此，況乃故人来。"]', '诗', 'shi', '', NULL, '友人夜訪 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51f54a42-2690-4866-bb3e-82299e0f5595', '遊悟真寺詩', '游悟真寺诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["元和九年秋，八月月上弦。","我遊悟真寺，寺在王順山。","去山四五里，先聞水潺湲。","自茲舍車馬，始涉藍溪灣。","手拄青竹杖，足蹋白石灘。","漸怪耳目曠，不聞人世喧。","山下望山上，初疑不可攀。","誰知中有路，盤折通巖巔。","一息幡竿下，再休石龕邊。","龕間長丈餘，門戶無扃關。","仰窺不見人，石髮垂若鬟。","驚出白蝙蝠，雙飛如雪飜。","回首寺門望，青崖夾朱軒。","如擘山腹開，置寺於其間。","入門無平地，地窄虛空寬。","房廊與臺殿，高下隨峰巒。","巖崿無撮土，樹木多瘦堅。","根株抱石長，屈曲蟲蛇蟠。","松桂亂無行，四時鬱芊芊。","枝梢嫋青翠，韻若風中弦。","日月光不透，綠陰相交延。","幽鳥時一聲，聞之似寒蟬。","首憩賓位亭，就坐未及安。","須臾開北戶，萬里明豁然。","拂檐虹霏微，繞棟雲迴旋。","赤日間白雨，陰晴同一川。","野綠簇草樹，眼界吞秦原。","渭水細不見，漢陵小於拳。","却顧來時路，縈紆映朱闌。","歷歷上山人，一一遙可觀。","前對多寶墖，風鐸鳴四端。","欒櫨與戶牖，恰恰金碧繁。","云昔迦葉佛，此地坐涅槃。","至今鐵鉢在，當底手跡穿。","西開玉像殿，白佛森比肩。","斗藪塵埃衣，禮拜冰雪顏。","疊霜爲袈裟，貫雹爲華鬘。","逼觀疑鬼功，其跡非雕鐫。","次登觀音堂，未到聞栴檀。","上階脫雙履，斂足升淨筵。","六楹排玉鏡，四座敷金鈿。","黑夜自光明，不待燈燭然。","衆寶互低昂，碧珮珊瑚幡。","風來似天樂，相觸聲珊珊。","白珠垂露凝，赤珠滴血殷。","點綴佛髻上，合爲七寶冠。","雙缾白琉璃，色若秋水寒。","隔缾見舍利，圓轉如金丹。","玉笛何代物，天人施祇園。","吹如秋鶴聲，可以降靈仙。","是時秋方中，三五月正圓。","寶堂豁三門，金魄當其前。","月與寶相射，晶光爭鮮妍。","照人心骨冷，竟夕不欲眠。","曉尋南墖路，亂竹低嬋娟。","林幽不逢人，寒蝶飛翾翾。","山果不識名，離離夾道蕃。","足以療飢乏，摘嘗味甘酸。","道南藍谷神，紫傘白紙錢。","若歲有水旱，詔使修蘋蘩。","以地清淨故，獻奠無葷膻。","危石疊四五，𡾋嵬欹且刓。","造物者何意，堆在巖東偏。","冷滑無人迹，苔點如花牋。","我來登上頭，下臨不測淵。","目眩手足掉，不敢低頭看。","風從石下生，薄人而上摶。","衣服似羽翮，開張欲飛鶱。","𡾼𡾼三面峰，峰尖刀劒攢。","往往白雲過，決開露青天。","西北日落時，夕暉紅團團。","千里翠屏外，走下丹砂丸。","東南月上時，夜氣青漫漫。","百丈碧潭底，寫出黃金盤。","藍水色似藍，日夜長潺潺。","周迴繞山轉，下視如青環。","或鋪爲慢流，或激爲奔湍。","泓澄最深處，浮出蛟龍涎。","側身入其中，懸磴尤險艱。","捫蘿蹋樛木，下逐飲澗猨。","雪迸起白鷺，錦跳驚紅鱣。","歇定方盥漱，濯去支體煩。","淺深皆洞徹，可照腦與肝。","但愛清見底，欲尋不知源。","東崖饒怪石，積甃蒼琅玕。","溫潤發於外，其間韞璵璠。","卞和死已久，良玉多棄捐。","或時洩光彩，夜與星月連。","中頂最高峰，拄天青玉竿。","𪕍𪕌上不得，豈我能攀援。","上有白蓮池，素葩覆清瀾。","聞名不可到，處所非人寰。","又有一片石，大如方尺甎。","插在半壁上，其下萬仞懸。","云有過去師，坐得無生禪。","號爲定心石，長老世相傳。","却上謁仙祠，蔓草生緜緜。","昔聞王氏子，羽化升上玄。","其西曬藥臺，猶對芝朮田。","時復明月夜，上聞黃鶴言。","迴尋畫龍堂，二叟鬢髮斑。","想見聽法時，歡喜禮印壇。","復歸泉窟下，化作龍蜿蜒。","階前石孔在，欲雨生白煙。","往有寫經僧，身靜心精專。","感彼雲外鴿，羣飛千翩翩。","來添研中水，去吸巖底泉。","一日三往復，時節長不愆。","經成號聖僧，弟子名楊難。","誦此蓮花偈，數滿百億千。","身壞口不壞，舌根如紅蓮。","顱骨今不見，石函尚存焉。","粉壁有吳畫，筆彩依舊鮮。","素屏有褚書，墨色如新乾。","靈境與異跡，周覽無不殫。","一遊五晝夜，欲返仍盤桓。","我本山中人，誤爲時網牽。","牽率使讀書，推挽令効官。","既登文字科，又忝諫諍員。","拙直不合時，無益同素餐。","以此自慙惕，戚戚常寡歡。","無成心力盡，未老形骸殘。","今來脫簪組，始覺離憂患。","及爲山水遊，彌得縱疎頑。","野麋斷羈絆，行走無拘攣。","池魚放入海，一往何時還。","身著居士衣，手把南華篇。","終來此山住，永謝區中緣。","我今四十餘，從此終身閑。","若以七十期，猶得三十年。"]', '["元和九年秋，八月月上弦。","我游悟真寺，寺在王順山。","去山四五里，先闻水潺湲。","自茲舍车马，始涉藍溪灣。","手拄青竹杖，足蹋白石灘。","漸怪耳目曠，不闻人世喧。","山下望山上，初疑不可攀。","誰知中有路，盤折通巖巔。","一息幡竿下，再休石龕邊。","龕间长丈餘，门戶無扃关。","仰窺不见人，石髮垂若鬟。","驚出白蝙蝠，雙飞如雪飜。","回首寺门望，青崖夾朱軒。","如擘山腹开，置寺於其间。","入门無平地，地窄虛空寬。","房廊與台殿，高下隨峰巒。","巖崿無撮土，樹木多瘦堅。","根株抱石长，屈曲蟲蛇蟠。","松桂亂無行，四时鬱芊芊。","枝梢嫋青翠，韻若风中弦。","日月光不透，綠陰相交延。","幽鸟时一声，闻之似寒蟬。","首憩賓位亭，就坐未及安。","須臾开北戶，万里明豁然。","拂檐虹霏微，繞棟云迴旋。","赤日间白雨，陰晴同一川。","野綠簇草樹，眼界吞秦原。","渭水細不见，漢陵小於拳。","却顧来时路，縈紆映朱闌。","歷歷上山人，一一遙可观。","前对多寶墖，风鐸鳴四端。","欒櫨與戶牖，恰恰金碧繁。","云昔迦葉佛，此地坐涅槃。","至今鐵鉢在，當底手跡穿。","西开玉像殿，白佛森比肩。","斗藪塵埃衣，禮拜冰雪顏。","叠霜爲袈裟，貫雹爲华鬘。","逼观疑鬼功，其跡非雕鐫。","次登观音堂，未到闻栴檀。","上階脫雙履，斂足升淨筵。","六楹排玉镜，四座敷金鈿。","黑夜自光明，不待灯燭然。","衆寶互低昂，碧珮珊瑚幡。","风来似天乐，相觸声珊珊。","白珠垂露凝，赤珠滴血殷。","点綴佛髻上，合爲七寶冠。","雙缾白琉璃，色若秋水寒。","隔缾见舍利，圓轉如金丹。","玉笛何代物，天人施祇园。","吹如秋鹤声，可以降靈仙。","是时秋方中，三五月正圓。","寶堂豁三门，金魄當其前。","月與寶相射，晶光爭鲜妍。","照人心骨冷，竟夕不欲眠。","晓尋南墖路，亂竹低嬋娟。","林幽不逢人，寒蝶飞翾翾。","山果不識名，離離夾道蕃。","足以療飢乏，摘嘗味甘酸。","道南藍谷神，紫傘白紙錢。","若歲有水旱，詔使修蘋蘩。","以地清淨故，獻奠無葷膻。","危石叠四五，𡾋嵬欹且刓。","造物者何意，堆在巖东偏。","冷滑無人迹，苔点如花牋。","我来登上头，下臨不測淵。","目眩手足掉，不敢低头看。","风從石下生，薄人而上摶。","衣服似羽翮，开張欲飞鶱。","𡾼𡾼三面峰，峰尖刀劒攢。","往往白云過，決开露青天。","西北日落时，夕暉紅團團。","千里翠屏外，走下丹砂丸。","东南月上时，夜氣青漫漫。","百丈碧潭底，寫出黄金盤。","藍水色似藍，日夜长潺潺。","周迴繞山轉，下視如青环。","或鋪爲慢流，或激爲奔湍。","泓澄最深处，浮出蛟龙涎。","側身入其中，懸磴尤險艱。","捫蘿蹋樛木，下逐饮澗猨。","雪迸起白鷺，錦跳驚紅鱣。","歇定方盥漱，濯去支體煩。","淺深皆洞徹，可照腦與肝。","但愛清见底，欲尋不知源。","东崖饒怪石，積甃蒼琅玕。","溫潤發於外，其间韞璵璠。","卞和死已久，良玉多棄捐。","或时洩光彩，夜與星月連。","中頂最高峰，拄天青玉竿。","𪕍𪕌上不得，豈我能攀援。","上有白蓮池，素葩覆清瀾。","闻名不可到，处所非人寰。","又有一片石，大如方尺甎。","插在半壁上，其下万仞懸。","云有過去師，坐得無生禪。","號爲定心石，长老世相傳。","却上謁仙祠，蔓草生緜緜。","昔闻王氏子，羽化升上玄。","其西曬藥台，猶对芝朮田。","时复明月夜，上闻黄鹤言。","迴尋畫龙堂，二叟鬢髮斑。","想见听法时，歡喜禮印壇。","复归泉窟下，化作龙蜿蜒。","階前石孔在，欲雨生白煙。","往有寫經僧，身静心精專。","感彼云外鴿，羣飞千翩翩。","来添研中水，去吸巖底泉。","一日三往复，时節长不愆。","經成號聖僧，弟子名楊难。","誦此蓮花偈，數满百億千。","身壞口不壞，舌根如紅蓮。","顱骨今不见，石函尚存焉。","粉壁有吳畫，笔彩依旧鲜。","素屏有褚书，墨色如新乾。","靈境與異跡，周覽無不殫。","一游五晝夜，欲返仍盤桓。","我本山中人，誤爲时網牽。","牽率使读书，推挽令効官。","既登文字科，又忝諫諍員。","拙直不合时，無益同素餐。","以此自慙惕，戚戚常寡歡。","無成心力尽，未老形骸殘。","今来脫簪組，始覺離憂患。","及爲山水游，彌得縱疎頑。","野麋斷羈絆，行走無拘攣。","池鱼放入海，一往何时還。","身著居士衣，手把南华篇。","終来此山住，永謝區中緣。","我今四十餘，從此終身闲。","若以七十期，猶得三十年。"]', '诗', 'shi', '', NULL, '遊悟真寺詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('637abf28-c2e0-4168-a2a0-001c56c9a175', '酬張十八訪宿見贈', '酬張十八訪宿见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昔我爲近臣，君常稀到門。","今我官職冷，君君來往頻。","我受狷介性，立爲頑拙身。","平生雖寡合，合即無緇磷。","況君秉高義，富貴視如雲。","五侯三相家，眼冷不見君。","問其所與游，獨言韓舍人。","其次即及我，我媿非其倫。","胡爲謬相愛，歲晚逾勤勤。","落然頹檐下，一話夜達晨。","牀單食味薄，亦不嫌我貧。","日高上馬去，相顧猶逡巡。","長安久無雨，日赤風昏昏。","憐君將病眼，爲我犯埃塵。","遠從延康里，來訪曲江濱。","所重君子道，不獨媿相親。"]', '["昔我爲近臣，君常稀到门。","今我官職冷，君君来往頻。","我受狷介性，立爲頑拙身。","平生雖寡合，合即無緇磷。","況君秉高義，富貴視如云。","五侯三相家，眼冷不见君。","问其所與游，独言韓舍人。","其次即及我，我媿非其倫。","胡爲謬相愛，歲晚逾勤勤。","落然頹檐下，一話夜達晨。","牀單食味薄，亦不嫌我貧。","日高上马去，相顧猶逡巡。","长安久無雨，日赤风昏昏。","怜君將病眼，爲我犯埃塵。","远從延康里，来訪曲江濱。","所重君子道，不独媿相親。"]', '诗', 'shi', '', NULL, '酬張十八訪宿見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d0ed699-ddb4-47da-81da-a2e7a645dd87', '朝歸書寄元八', '朝归书寄元八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["進入閤前拜，退就廊下餐。","歸來昭國里，人臥馬歇鞍。","却睡至日午，起坐心浩然。","況當好時節，雨後清和天。","柿樹綠陰合，王家庭院寬。","缾中鄠縣酒，牆上終南山。","獨眠仍獨坐，開襟當風前。","禪師與詩客，次第來相看。","要語連夜語，須眠終日眠。","除非奉朝謁，此外無別牽。","年長身且健，官貧心甚安。","幸無急病痛，不至苦飢寒。","自此聊以適，外緣不能干。","唯應靜者信，難爲動者言。","臺中元侍御，早晚作郎官。","未作郎官際，無人相伴閑。"]', '["進入閤前拜，退就廊下餐。","归来昭国里，人臥马歇鞍。","却睡至日午，起坐心浩然。","況當好时節，雨後清和天。","柿樹綠陰合，王家庭院寬。","缾中鄠縣酒，牆上終南山。","独眠仍独坐，开襟當风前。","禪師與诗客，次第来相看。","要語連夜語，須眠終日眠。","除非奉朝謁，此外無別牽。","年长身且健，官貧心甚安。","幸無急病痛，不至苦飢寒。","自此聊以適，外緣不能干。","唯應静者信，难爲动者言。","台中元侍御，早晚作郎官。","未作郎官際，無人相伴闲。"]', '诗', 'shi', '', NULL, '朝歸書寄元八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50ea363e-57d7-4b60-9e1b-b1e46814f74f', '酬吳七見寄', '酬吳七见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曲江有病客，尋常多掩關。","又聞馬死來，不出身更閑。","聞有送書者，自起出門看。","素緘署丹字，中有瓊瑤篇。","口吟耳自聽，當暑忽翛然。","似漱寒玉冰，如聞商風弦。","首章歎時節，末句思笑言。","嬾慢不相訪，隔街如隔山。","嘗聞陶潛語，心遠地自偏。","君住安邑里，左右車徒喧。","竹藥閉深院，琴尊開小軒。","誰知市南地，轉作壺中天。","君本上清人，名在石堂間。","不知有何過，謫作人間仙。","常恐歲月滿，飄然歸紫煙。","莫忘蜉蝣內，進士有同年。"]', '["曲江有病客，尋常多掩关。","又闻马死来，不出身更闲。","闻有送书者，自起出门看。","素緘署丹字，中有瓊瑤篇。","口吟耳自听，當暑忽翛然。","似漱寒玉冰，如闻商风弦。","首章歎时節，末句思笑言。","嬾慢不相訪，隔街如隔山。","嘗闻陶潛語，心远地自偏。","君住安邑里，左右车徒喧。","竹藥閉深院，琴尊开小軒。","誰知市南地，轉作壺中天。","君本上清人，名在石堂间。","不知有何過，謫作人间仙。","常恐歲月满，飄然归紫煙。","莫忘蜉蝣內，進士有同年。"]', '诗', 'shi', '', NULL, '酬吳七見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('407150e0-898d-4cb8-8f4e-e6567efa2586', '昭國閑居', '昭国闲居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["貧閑日高起，門巷晝寂寂。","時暑放朝參，天陰少人客。","槐花滿田地，僅絕人行跡。","獨在一牀眠，清涼風雨夕。","勿嫌坊曲遠，近即多牽役。","勿嫌祿俸薄，厚即多憂責。","平生尚恬曠，老大宜安適。","何以養吾真，官閑居處僻。"]', '["貧闲日高起，门巷晝寂寂。","时暑放朝參，天陰少人客。","槐花满田地，僅絕人行跡。","独在一牀眠，清涼风雨夕。","勿嫌坊曲远，近即多牽役。","勿嫌祿俸薄，厚即多憂責。","平生尚恬曠，老大宜安適。","何以養吾真，官闲居处僻。"]', '诗', 'shi', '', NULL, '昭國閑居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f58de238-d31a-4ab6-a268-6e05878ef617', '喜陳兄至', '喜陳兄至', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黃鳥啼欲歇，青梅結半成。","坐憐春物盡，起入東園行。","攜觴嬾獨酌，忽聞叩門聲。","閑人猶喜至，何況是陳兄。","從容盡日語，稠疊長年情。","勿輕一醆酒，可以話平生。"]', '["黄鸟啼欲歇，青梅結半成。","坐怜春物尽，起入东园行。","携觴嬾独酌，忽闻叩门声。","闲人猶喜至，何況是陳兄。","從容尽日語，稠叠长年情。","勿轻一醆酒，可以話平生。"]', '诗', 'shi', '', NULL, '喜陳兄至 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b49143d9-0789-4ece-a092-3dbb25d23c98', '贈杓直', '贈杓直', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["世路重祿位，栖栖者孔宣。","人情愛年壽，夭死者顏淵。","二人如何人，不奈命與天。","我今信多幸，撫己媿前賢。","已年四十四，又爲五品官。","況茲知足外，別有所安焉。","早年以身代，直赴逍遙篇。","近歲將心地，迴向南宗禪。","外順世間法，內脫區中緣。","進不厭朝市，退不戀人寰。","自吾得此心，投足無不安。","體非導引適，意無江湖閑。","有興或飲酒，無事多掩關。","寂靜夜深坐，安穩日高眠。","秋不苦長夜，春不惜流年。","委形老小外，忘懷生死間。","昨日共君語，與余心膂然。","此道不可道，因君聊強言。"]', '["世路重祿位，栖栖者孔宣。","人情愛年壽，夭死者顏淵。","二人如何人，不奈命與天。","我今信多幸，撫己媿前賢。","已年四十四，又爲五品官。","況茲知足外，別有所安焉。","早年以身代，直赴逍遙篇。","近歲將心地，迴向南宗禪。","外順世间法，內脫區中緣。","進不厭朝市，退不戀人寰。","自吾得此心，投足無不安。","體非導引適，意無江湖闲。","有兴或饮酒，無事多掩关。","寂静夜深坐，安穩日高眠。","秋不苦长夜，春不惜流年。","委形老小外，忘懷生死间。","昨日共君語，與余心膂然。","此道不可道，因君聊強言。"]', '诗', 'shi', '', NULL, '贈杓直 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffe26ceb-c8c1-4d4f-856c-cebc412e2eab', '寄張十八', '寄張十八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["飢止一簞食，渴止一壺漿。","出入止一馬，寢興止一牀。","此外無長物，於我有若亡。","胡然不知足，名利心遑遑。","念茲彌嬾放，積習遂爲常。","經旬不出門，竟日不下堂。","同病者張生，貧僻住延康。","慵中每相憶，此意未能忘。","迢迢青槐街，相去八九坊。","秋來未相見，應有新詩章。","早晚來同宿，天氣轉清涼。"]', '["飢止一簞食，渴止一壺漿。","出入止一马，寢兴止一牀。","此外無长物，於我有若亡。","胡然不知足，名利心遑遑。","念茲彌嬾放，積習遂爲常。","經旬不出门，竟日不下堂。","同病者張生，貧僻住延康。","慵中每相憶，此意未能忘。","迢迢青槐街，相去八九坊。","秋来未相见，應有新诗章。","早晚来同宿，天氣轉清涼。"]', '诗', 'shi', '', NULL, '寄張十八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2245b36-4dc5-40d4-ac78-41c8548a5c7d', '題玉泉寺', '題玉泉寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["湛湛玉泉色，悠悠浮雲身。","閑心對定水，清靜兩無塵。","手把青筇杖，頭戴白綸巾。","興盡下山去，知我是誰人。"]', '["湛湛玉泉色，悠悠浮云身。","闲心对定水，清静兩無塵。","手把青筇杖，头戴白綸巾。","兴尽下山去，知我是誰人。"]', '诗', 'shi', '', NULL, '題玉泉寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d98a0d7-6ea0-4fea-84ec-f01f8e34c966', '朝回遊城南', '朝回游城南', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝退馬未困，秋初日猶長。","回轡城南去，郊野正清涼。","水竹夾小徑，縈迴繞川岡。","仰看晚山色，俯弄秋泉光。","青松繫我馬，白石爲我牀。","常時簪組累，此日和身忘。","旦隨鵷鷺末，暮遊鷗鶴旁。","機心一以盡，兩處不亂行。","誰辨心與跡，非行亦非藏。"]', '["朝退马未困，秋初日猶长。","回轡城南去，郊野正清涼。","水竹夾小徑，縈迴繞川岡。","仰看晚山色，俯弄秋泉光。","青松繫我马，白石爲我牀。","常时簪組累，此日和身忘。","旦隨鵷鷺末，暮游鷗鹤旁。","機心一以尽，兩处不亂行。","誰辨心與跡，非行亦非藏。"]', '诗', 'shi', '', NULL, '朝回遊城南 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfefb484-4847-4b96-9fa6-b2f6a28b5dbc', '舟行', '舟行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["帆影日漸高，閑眠猶未起。","起問鼓枻人，已行三十里。","船頭有行竈，炊稻烹紅鯉。","飽食起婆娑，盥漱秋江水。","平生滄浪意，一旦來遊此。","何況不失家，舟中載妻子。"]', '["帆影日漸高，闲眠猶未起。","起问鼓枻人，已行三十里。","船头有行竈，炊稻烹紅鯉。","飽食起婆娑，盥漱秋江水。","平生滄浪意，一旦来游此。","何況不失家，舟中載妻子。"]', '诗', 'shi', '', NULL, '舟行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be181d5d-0535-4760-a414-9759a37af389', '湓浦早冬', '湓浦早冬', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["潯陽孟冬月，草木未全衰。","祗抵長安陌，涼風八月時。","日西湓水曲，獨行吟舊詩。","蓼花始零落，蒲葉稍離披。","但作城中想，何異曲江池。"]', '["潯陽孟冬月，草木未全衰。","祗抵长安陌，涼风八月时。","日西湓水曲，独行吟旧诗。","蓼花始零落，蒲葉稍離披。","但作城中想，何異曲江池。"]', '诗', 'shi', '', NULL, '湓浦早冬 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09ddfae1-4bba-405e-a69d-665bfcb5ca4d', '江州雪', '江州雪', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["新雪滿前山，初晴好天氣。","日西騎馬出，忽有京都意。","城柳方綴花，檐冰纔結穗。","須臾風日暖，處處皆飄墜。","行吟賞未足，坐歎銷何易。","猶勝嶺南看，雰雰不到地。"]', '["新雪满前山，初晴好天氣。","日西騎马出，忽有京都意。","城柳方綴花，檐冰纔結穗。","須臾风日暖，处处皆飄墜。","行吟賞未足，坐歎銷何易。","猶勝嶺南看，雰雰不到地。"]', '诗', 'shi', '', NULL, '江州雪 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c80dbc4d-f1d2-4dc2-99ef-505b078a766f', '題潯陽樓', '題潯陽楼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["常愛陶彭澤，文思何高玄。","又怪韋江州，詩情亦清閑。","今朝登此樓，有以知其然。","大江寒見底，匡山青倚天。","深夜湓浦月，平旦鑪峰煙。","清輝與靈氣，日夕供文篇。","我無二人才，孰爲來其間。","因高偶成句，俯仰媿江山。"]', '["常愛陶彭澤，文思何高玄。","又怪韋江州，诗情亦清闲。","今朝登此楼，有以知其然。","大江寒见底，匡山青倚天。","深夜湓浦月，平旦鑪峰煙。","清輝與靈氣，日夕供文篇。","我無二人才，孰爲来其间。","因高偶成句，俯仰媿江山。"]', '诗', 'shi', '', NULL, '題潯陽樓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e861c2e-3d2d-4c3c-a1ae-a781b642c36d', '訪陶公舊宅', '訪陶公旧宅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["垢塵不汚玉，靈鳳不啄羶。","嗚呼陶靖節，生彼晉宋間。","心實有所守，口終不能言。","永惟孤竹子，拂衣首陽山。","夷齊各一身，窮餓未爲難。","先生有五男，與之同飢寒。","腸中食不充，身上衣不完。","連徵竟不起，斯可謂真賢。","我生君之後，相去五百年。","每讀五柳傳，目想心拳拳。","昔常詠遺風，著爲十六篇。","今來訪故宅，森若君在前。","不慕尊有酒，不慕琴無弦。","慕君遺榮利，老死此丘園。","柴桑古村落，栗里舊山川。","不見籬下菊，但餘墟中煙。","子孫雖無聞，族氏猶未遷。","每逢姓陶人，使我心依然。"]', '["垢塵不汚玉，靈鳳不啄羶。","嗚呼陶靖節，生彼晉宋间。","心實有所守，口終不能言。","永惟孤竹子，拂衣首陽山。","夷齊各一身，窮餓未爲难。","先生有五男，與之同飢寒。","腸中食不充，身上衣不完。","連徵竟不起，斯可謂真賢。","我生君之後，相去五百年。","每读五柳傳，目想心拳拳。","昔常詠遺风，著爲十六篇。","今来訪故宅，森若君在前。","不慕尊有酒，不慕琴無弦。","慕君遺榮利，老死此丘园。","柴桑古村落，栗里旧山川。","不见籬下菊，但餘墟中煙。","子孫雖無闻，族氏猶未遷。","每逢姓陶人，使我心依然。"]', '诗', 'shi', '', NULL, '訪陶公舊宅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9528a395-de70-461f-82ed-20328bc69eed', '北亭', '北亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["廬宮山下州，湓浦沙邊宅。","宅北倚高岡，迢迢數千尺。","上有青青竹，竹間多白石。","茅亭居上頭，豁達門四闢。","前楹卷簾箔，北牖施牀席。","江風萬里來，吹我涼淅淅。","日高公府歸，巾笏隨手擲。","脫衣恣搔首，坐臥任所適。","時傾一杯酒，曠望湖天夕。","口詠獨酌謠，目送歸飛翮。","慙無出塵操，未免折腰役。","偶獲此閑居，謬似高人跡。"]', '["廬宮山下州，湓浦沙邊宅。","宅北倚高岡，迢迢數千尺。","上有青青竹，竹间多白石。","茅亭居上头，豁達门四闢。","前楹卷簾箔，北牖施牀席。","江风万里来，吹我涼淅淅。","日高公府归，巾笏隨手擲。","脫衣恣搔首，坐臥任所適。","时傾一杯酒，曠望湖天夕。","口詠独酌謠，目送归飞翮。","慙無出塵操，未免折腰役。","偶獲此闲居，謬似高人跡。"]', '诗', 'shi', '', NULL, '北亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4842e43-b558-4948-bdce-7a46083a6392', '泛湓水', '泛湓水', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["四月未全熱，麥涼江氣秋。","湖山處處好，最愛湓水頭。","湓水從東來，一派入江流。","可憐似縈帶，中有隨風舟。","命酒一臨泛，舍鞍揚櫂謳。","放迴岸傍馬，去逐波間鷗。","煙浪始渺渺，風襟亦悠悠。","初疑上河漢，中若尋瀛洲。","汀樹綠拂地，沙草芳未休。","青蘿與紫葛，枝蔓垂相樛。","繫纜步平岸，迴頭望江州。","城雉映水見，隱隱如蜃樓。","日入意未盡，將歸復少留。","到官行半歲，今日方一遊。","此地來何暮，可以寫吾憂。"]', '["四月未全熱，麦涼江氣秋。","湖山处处好，最愛湓水头。","湓水從东来，一派入江流。","可怜似縈带，中有隨风舟。","命酒一臨泛，舍鞍揚櫂謳。","放迴岸傍马，去逐波间鷗。","煙浪始渺渺，风襟亦悠悠。","初疑上河漢，中若尋瀛洲。","汀樹綠拂地，沙草芳未休。","青蘿與紫葛，枝蔓垂相樛。","繫纜步平岸，迴头望江州。","城雉映水见，隐隐如蜃楼。","日入意未尽，將归复少留。","到官行半歲，今日方一游。","此地来何暮，可以寫吾憂。"]', '诗', 'shi', '', NULL, '泛湓水 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9f3dbae-fce4-47bb-9086-ae7e978312f5', '荅故人', '荅故人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["故人對酒歎，歎我在天涯。","見我昔榮遇，念我今蹉跎。","問我爲司馬，官意復如何。","荅云且勿歎，聽我爲君歌。","我本蓬蓽人，鄙賤劇泥沙。","讀書未百卷，信口嘲風花。","自從筮仕來，六命三登科。","顧慙虛劣姿，所得亦已多。","散員足庇身，薄俸可資家。","省分輒自媿，豈爲不遇耶。","煩君對杯酒，爲我一咨蹉。"]', '["故人对酒歎，歎我在天涯。","见我昔榮遇，念我今蹉跎。","问我爲司马，官意复如何。","荅云且勿歎，听我爲君歌。","我本蓬蓽人，鄙賤劇泥沙。","读书未百卷，信口嘲风花。","自從筮仕来，六命三登科。","顧慙虛劣姿，所得亦已多。","散員足庇身，薄俸可資家。","省分輒自媿，豈爲不遇耶。","煩君对杯酒，爲我一咨蹉。"]', '诗', 'shi', '', NULL, '荅故人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15e9c922-a0dd-4edf-9d85-99c2d1357473', '官舍內新鑿小池', '官舍內新鑿小池', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["簾下開小池，盈盈水方積。","中底鋪白沙，四隅甃青石。","勿言不深廣，但取幽人適。","泛灩微雨朝，泓澄明月夕。","豈無大江水，波浪連天白。","未如牀席間，方丈深盈尺。","清淺可狎弄，昏煩聊漱滌。","最愛曉暝時，一片秋天碧。"]', '["簾下开小池，盈盈水方積。","中底鋪白沙，四隅甃青石。","勿言不深廣，但取幽人適。","泛灩微雨朝，泓澄明月夕。","豈無大江水，波浪連天白。","未如牀席间，方丈深盈尺。","清淺可狎弄，昏煩聊漱滌。","最愛晓暝时，一片秋天碧。"]', '诗', 'shi', '', NULL, '官舍內新鑿小池 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11f9fa17-394b-4c7d-8908-a5728e6a71bc', '宿簡寂觀', '宿簡寂观', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["巖白雲尚屯，林紅葉初隕。","秋光引閑步，不知身遠近。","夕投靈洞宿，臥覺塵機泯。","名利心既忘，市朝夢亦盡。","暫來尚如此，況乃終身隱。","何以療夜飢，一匙雲母粉。"]', '["巖白云尚屯，林紅葉初隕。","秋光引闲步，不知身远近。","夕投靈洞宿，臥覺塵機泯。","名利心既忘，市朝梦亦尽。","暫来尚如此，況乃終身隐。","何以療夜飢，一匙云母粉。"]', '诗', 'shi', '', NULL, '宿簡寂觀 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e40d9e8-6894-423e-a22e-41f78c97937a', '讀謝靈運詩', '读謝靈運诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吾聞達士道，窮通順冥數。","通乃朝廷來，窮即江湖去。","謝公才廓落，與世不相遇。","壯志鬱不用，須有所洩處。","洩爲山水詩，逸韻諧奇趣。","大必籠天海，細不遺草樹。","豈惟玩景物，亦欲攄心素。","往往即事中，未能忘興諭。","因知康樂作，不獨在章句。"]', '["吾闻達士道，窮通順冥數。","通乃朝廷来，窮即江湖去。","謝公才廓落，與世不相遇。","壯志鬱不用，須有所洩处。","洩爲山水诗，逸韻諧奇趣。","大必籠天海，細不遺草樹。","豈惟玩景物，亦欲攄心素。","往往即事中，未能忘兴諭。","因知康乐作，不独在章句。"]', '诗', 'shi', '', NULL, '讀謝靈運詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5165733-096a-420f-a9de-0c11ff563256', '北亭獨宿', '北亭独宿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["悄悄壁下牀，紗籠耿殘燭。","夜半獨眠覺，疑在僧房宿。"]', '["悄悄壁下牀，紗籠耿殘燭。","夜半独眠覺，疑在僧房宿。"]', '诗', 'shi', '', NULL, '北亭獨宿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9339ffc-bd7f-4feb-a534-a006afcc1e3c', '約心', '約心', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黑鬢絲雪侵，青袍塵土涴。","兀兀復騰騰，江城一上佐。","朝就高齋上，熏然負暄臥。","晚下小池前，澹然臨水坐。","已約終身心，長如今日過。"]', '["黑鬢絲雪侵，青袍塵土涴。","兀兀复腾腾，江城一上佐。","朝就高斋上，熏然負暄臥。","晚下小池前，澹然臨水坐。","已約終身心，长如今日過。"]', '诗', 'shi', '', NULL, '約心 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('659307c0-68f1-4fbe-b743-99caeccb3712', '晚望', '晚望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江城寒角動，沙洲夕鳥還。","獨在高亭上，西南望遠山。"]', '["江城寒角动，沙洲夕鸟還。","独在高亭上，西南望远山。"]', '诗', 'shi', '', NULL, '晚望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('226203b3-4d27-49f0-9dea-ffb469c6f364', '早春', '早春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雪消冰又釋，景和風復暄。","滿庭田地濕，薺葉生牆根。","官舍悄無事，日西斜掩門。","不開莊老卷，欲與何人言。"]', '["雪消冰又釋，景和风复暄。","满庭田地濕，薺葉生牆根。","官舍悄無事，日西斜掩门。","不开莊老卷，欲與何人言。"]', '诗', 'shi', '', NULL, '早春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f35edd89-6a81-46b6-b734-cb2db5918609', '春寢', '春寢', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春暄來？微和生血氣。","氣熏肌骨暢，東窗一昏睡。","是時正月晦，假日無公事。","爛熳不能休，自午將及未。","緬思少健日，甘寢常自恣。","一從衰疾來，枕上無此味。"]', '["何处春暄来？微和生血氣。","氣熏肌骨暢，东窗一昏睡。","是时正月晦，假日無公事。","爛熳不能休，自午將及未。","緬思少健日，甘寢常自恣。","一從衰疾来，枕上無此味。"]', '诗', 'shi', '', NULL, '春寢 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed2ffe0c-5054-45a5-847f-b62a61260316', '睡起晏坐', '睡起晏坐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["後亭晝眠足，起坐春景暮。","新覺眼猶昏，無思心正住。","澹寂歸一性，虛閑遺萬慮。","了然此時心，無物可譬喻。","本是無有鄉，亦名不用處。","行禪與坐忘，同歸無異路。"]', '["後亭晝眠足，起坐春景暮。","新覺眼猶昏，無思心正住。","澹寂归一性，虛闲遺万慮。","了然此时心，無物可譬喻。","本是無有乡，亦名不用处。","行禪與坐忘，同归無異路。"]', '诗', 'shi', '', NULL, '睡起晏坐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee84636a-1c29-4967-9a08-951d69408a35', '詠懷', '詠懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["盡日松下坐，有時池畔行。","行立與坐臥，中懷澹無營。","不覺流年過，亦任白髮生。","不爲世所薄，安得遂閑情。"]', '["尽日松下坐，有时池畔行。","行立與坐臥，中懷澹無營。","不覺流年過，亦任白髮生。","不爲世所薄，安得遂闲情。"]', '诗', 'shi', '', NULL, '詠懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba68e8da-a3c1-41de-b093-58d624de3765', '春遊二林寺', '春游二林寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["下馬二林寺，翛然進輕策。","朝爲公府吏，暮作靈山客。","二月匡廬北，冰雪始消釋。","陽叢抽茗芽，陰竇洩泉脈。","熙熙風土暖，藹藹雲嵐積。","散作萬壑春，凝爲一氣碧。","身閑易飄泊，官散無牽迫。","緬彼十八人，古今同此適。","是年淮寇起，處處興兵革。","智士勞思謀，戎臣苦征役。","獨有不才者，山中弄泉石。"]', '["下马二林寺，翛然進轻策。","朝爲公府吏，暮作靈山客。","二月匡廬北，冰雪始消釋。","陽叢抽茗芽，陰竇洩泉脈。","熙熙风土暖，藹藹云嵐積。","散作万壑春，凝爲一氣碧。","身闲易飄泊，官散無牽迫。","緬彼十八人，古今同此適。","是年淮寇起，处处兴兵革。","智士勞思謀，戎臣苦征役。","独有不才者，山中弄泉石。"]', '诗', 'shi', '', NULL, '春遊二林寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('691aeeaf-8447-480f-8d17-4a973d0c51a8', '出山吟', '出山吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝詠遊仙詩，暮歌采薇曲。","臥雲坐白石，山中十五宿。","行隨出洞水，迴別緣巖竹。","早晚重來遊，心期瑤草綠。"]', '["朝詠游仙诗，暮歌采薇曲。","臥云坐白石，山中十五宿。","行隨出洞水，迴別緣巖竹。","早晚重来游，心期瑤草綠。"]', '诗', 'shi', '', NULL, '出山吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bafab5b-a689-405d-b2d2-00b1a82e6a3e', '歲暮', '歲暮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["已任時命去，亦從歲月除。","中心一調伏，外累盡空虛。","名宦意已矣，林泉計何如。","擬近東林寺，溪邊結一廬。"]', '["已任时命去，亦從歲月除。","中心一調伏，外累尽空虛。","名宦意已矣，林泉計何如。","擬近东林寺，溪邊結一廬。"]', '诗', 'shi', '', NULL, '歲暮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca63a7bb-4df6-4377-9084-762bfbced7a9', '聞早鶯', '闻早鶯', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日出眠未起，屋頭聞早鶯。","忽如上林曉，萬年枝上鳴。","憶爲近臣時，秉筆直承明。","春深視草暇，旦暮聞此聲。","今聞在何處，寂莫潯陽城。","鳥聲信如一，分別在人情。","不作天涯意，豈殊禁中聽。"]', '["日出眠未起，屋头闻早鶯。","忽如上林晓，万年枝上鳴。","憶爲近臣时，秉笔直承明。","春深視草暇，旦暮闻此声。","今闻在何处，寂莫潯陽城。","鸟声信如一，分別在人情。","不作天涯意，豈殊禁中听。"]', '诗', 'shi', '', NULL, '聞早鶯 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61506a5d-2957-4a72-9861-7dc54564020f', '栽杉', '栽杉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["勁葉森利劒，孤莖挺端標。","纔高四五尺，勢若干青霄。","移栽東窗前，愛爾寒不凋。","病夫臥相對，日夕閑蕭蕭。","昨爲山中樹，今爲檐下條。","雖然遇賞玩，無乃近塵囂。","猶勝澗谷底，埋沒隨衆樵。","不見鬱鬱松，委質山上苗。"]', '["勁葉森利劒，孤莖挺端標。","纔高四五尺，勢若干青霄。","移栽东窗前，愛爾寒不凋。","病夫臥相对，日夕闲蕭蕭。","昨爲山中樹，今爲檐下條。","雖然遇賞玩，無乃近塵囂。","猶勝澗谷底，埋沒隨衆樵。","不见鬱鬱松，委質山上苗。"]', '诗', 'shi', '', NULL, '栽杉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23bdea01-88fa-4e89-9923-747bdb79e3b5', '過李生', '過李生', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蘋小蒲葉短，南湖春水生。","子近湖邊住，靜境稱高情。","我爲郡司馬，散拙無所營。","使君知性野，衙退任閑行。","行攜小榼出，逢花輒獨傾。","半酣到子舍，下馬扣柴荆。","何以引我步，繞籬竹萬莖。","何以醒我酒，吳音吟一聲。","須臾進野飯，飯稻茹芹英。","白甌青竹箸，儉潔無羶腥。","欲去復裴回，夕鴉已飛鳴。","何當重遊此，待君湖水平。"]', '["蘋小蒲葉短，南湖春水生。","子近湖邊住，静境稱高情。","我爲郡司马，散拙無所營。","使君知性野，衙退任闲行。","行携小榼出，逢花輒独傾。","半酣到子舍，下马扣柴荆。","何以引我步，繞籬竹万莖。","何以醒我酒，吳音吟一声。","須臾進野飯，飯稻茹芹英。","白甌青竹箸，儉潔無羶腥。","欲去复裴回，夕鴉已飞鳴。","何當重游此，待君湖水平。"]', '诗', 'shi', '', NULL, '過李生 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b79cf708-4274-414c-ace1-1caba388e708', '詠意', '詠意', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["常聞南華經，巧勞智憂愁。","不如無能者，飽食但遨遊。","平生愛慕道，今日近此流。","自來潯陽郡，四序忽已周。","不分物黑白，但與時沈浮。","朝餐夕安寢，用是爲身謀。","此外即閑放，時尋山水幽。","春遊慧遠寺，秋上庾公樓。","或吟詩一章，或飲茶一甌。","身心一無繫，浩浩如虛舟。","富貴亦有苦，苦在心危憂。","貧賤亦有樂，樂在身自由。"]', '["常闻南华經，巧勞智憂愁。","不如無能者，飽食但遨游。","平生愛慕道，今日近此流。","自来潯陽郡，四序忽已周。","不分物黑白，但與时沈浮。","朝餐夕安寢，用是爲身謀。","此外即闲放，时尋山水幽。","春游慧远寺，秋上庾公楼。","或吟诗一章，或饮茶一甌。","身心一無繫，浩浩如虛舟。","富貴亦有苦，苦在心危憂。","貧賤亦有乐，乐在身自由。"]', '诗', 'shi', '', NULL, '詠意 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef18d8a8-27b3-4568-a8bb-bc19d1b3d9b2', '食筍', '食筍', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["此州乃竹鄉，春筍滿山谷。","山夫折盈抱，抱來早市鬻。","物以多爲賤，雙錢易一束。","置之炊甑中，與飯同時熟。","紫籜坼故錦，素肌擘新玉。","每日遂加餐，經時不思肉。","久爲京洛客，此味常不足。","且食勿踟躕，南風吹作竹。"]', '["此州乃竹乡，春筍满山谷。","山夫折盈抱，抱来早市鬻。","物以多爲賤，雙錢易一束。","置之炊甑中，與飯同时熟。","紫籜坼故錦，素肌擘新玉。","每日遂加餐，經时不思肉。","久爲京洛客，此味常不足。","且食勿踟躕，南风吹作竹。"]', '诗', 'shi', '', NULL, '食筍 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c61e2df8-6875-48d5-9634-8ca77111bb23', '遊石門澗', '游石门澗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["石門無舊徑，披榛訪遺跡。","時逢山水秋，清輝如古昔。","常聞慧遠輩，題詩此巖壁。","雲覆莓苔封，蒼然無處覓。","蕭疎野生竹，崩剝多年石。","自從東晉後，無復人遊歷。","獨有秋澗聲，潺湲空旦夕。"]', '["石门無旧徑，披榛訪遺跡。","时逢山水秋，清輝如古昔。","常闻慧远輩，題诗此巖壁。","云覆莓苔封，蒼然無处覓。","蕭疎野生竹，崩剝多年石。","自從东晉後，無复人游歷。","独有秋澗声，潺湲空旦夕。"]', '诗', 'shi', '', NULL, '遊石門澗 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12da86e7-43f4-42cd-b5f8-ccbb19b995e7', '招東鄰', '招东鄰', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小榼二升酒，新簟六尺牀。","能來夜話否，池畔欲秋涼。"]', '["小榼二升酒，新簟六尺牀。","能来夜話否，池畔欲秋涼。"]', '诗', 'shi', '', NULL, '招東鄰 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99286590-d563-4a57-8995-712647d24536', '題元十八溪亭', '題元十八溪亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["怪君不喜仕，又不遊州里。","今日到幽居，了然知所以。","宿君石溪亭，潺湲聲滿耳。","飲君螺杯酒，醉臥不能起。","見君五老峰，益悔居城市。","愛君三男兒，始歎身無子。","余方鑪峰下，結室爲居士。","山北與山東，往來從此始。"]', '["怪君不喜仕，又不游州里。","今日到幽居，了然知所以。","宿君石溪亭，潺湲声满耳。","饮君螺杯酒，醉臥不能起。","见君五老峰，益悔居城市。","愛君三男兒，始歎身無子。","余方鑪峰下，結室爲居士。","山北與山东，往来從此始。"]', '诗', 'shi', '', NULL, '題元十八溪亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0f510b7-ec97-41f3-8809-5bb8f7606e46', '香鑪峰下新置草堂即事詠懷題於石上', '香鑪峰下新置草堂即事詠懷題於石上', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["香鑪峰北面，遺愛寺西偏。","白石何鑿鑿，清流亦潺潺。","有松數十株，有竹千餘竿。","松張翠繖蓋，竹倚青琅玕。","其下無人居，悠哉多歲年。","有時聚猨鳥，終日空風煙。","時有沈冥子，姓白字樂天。","平生無所好，見此心依然。","如獲終老地，忽乎不知還。","架巖結茅宇，斵壑開茶園。","何以洗我耳，屋頭飛落泉。","何以淨我眼，砌下生白蓮。","左手攜一壺，右手挈五弦。","傲然意自足，箕踞於其間。","興酣仰天歌，歌中聊寄言。","言我本野夫，誤爲世網牽。","時來昔捧日，老去今歸山。","倦鳥得茂樹，涸魚返清源。","舍此欲焉往，人間多險艱。"]', '["香鑪峰北面，遺愛寺西偏。","白石何鑿鑿，清流亦潺潺。","有松數十株，有竹千餘竿。","松張翠繖蓋，竹倚青琅玕。","其下無人居，悠哉多歲年。","有时聚猨鸟，終日空风煙。","时有沈冥子，姓白字乐天。","平生無所好，见此心依然。","如獲終老地，忽乎不知還。","架巖結茅宇，斵壑开茶园。","何以洗我耳，屋头飞落泉。","何以淨我眼，砌下生白蓮。","左手携一壺，右手挈五弦。","傲然意自足，箕踞於其间。","兴酣仰天歌，歌中聊寄言。","言我本野夫，誤爲世網牽。","时来昔捧日，老去今归山。","倦鸟得茂樹，涸鱼返清源。","舍此欲焉往，人间多險艱。"]', '诗', 'shi', '', NULL, '香鑪峰下新置草堂即事詠懷題於石上 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cae1dc9-23b8-4611-938d-27d143c3781b', '草堂前新開一池養魚種荷日有幽趣', '草堂前新开一池養鱼種荷日有幽趣', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["淙淙三峽水，浩浩萬頃陂。","未如新塘上，微風動漣漪。","小萍加泛泛，初蒲正離離。","紅鯉二三寸，白蓮八九枝。","繞水欲成徑，護堤方插籬。","已被山中客，呼作白家池。"]', '["淙淙三峽水，浩浩万頃陂。","未如新塘上，微风动漣漪。","小萍加泛泛，初蒲正離離。","紅鯉二三寸，白蓮八九枝。","繞水欲成徑，護堤方插籬。","已被山中客，呼作白家池。"]', '诗', 'shi', '', NULL, '草堂前新開一池養魚種荷日有幽趣 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fcb644c-b9a5-43f3-9314-b9eb9df82ce8', '白雲期', '白云期', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三十氣太狀，胷中多是非。","六十身太老，四體不支持。","四十至五十，正是退閑時。","年長識命分，心慵少營爲。","見酒興猶在，登山力未衰。","吾年幸當此，且與白雲期。"]', '["三十氣太狀，胷中多是非。","六十身太老，四體不支持。","四十至五十，正是退闲时。","年长識命分，心慵少營爲。","见酒兴猶在，登山力未衰。","吾年幸當此，且與白云期。"]', '诗', 'shi', '', NULL, '白雲期 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f80596cf-ca88-4264-8ce1-6ad185759789', '登香爐峰頂', '登香爐峰頂', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["迢迢香鑪峰，心存耳目想。","終年牽物役，今日方一往。","攀蘿蹋危石，手足勞俛仰。","同遊三四人，兩人不敢上。","上到峰之頂，目眩神怳怳。","高低有萬尋，闊狹無數丈。","不窮視聽界，焉識宇宙廣。","江水細如繩，湓城小於掌。","紛吾何屑屑，未能脫塵鞅。","歸去思自嗟，低頭入蟻壤。"]', '["迢迢香鑪峰，心存耳目想。","終年牽物役，今日方一往。","攀蘿蹋危石，手足勞俛仰。","同游三四人，兩人不敢上。","上到峰之頂，目眩神怳怳。","高低有万尋，闊狹無數丈。","不窮視听界，焉識宇宙廣。","江水細如繩，湓城小於掌。","紛吾何屑屑，未能脫塵鞅。","归去思自嗟，低头入蟻壤。"]', '诗', 'shi', '', NULL, '登香爐峰頂 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c6df717-e2d0-4f9d-9924-fc2f5ffd47ae', '荅崔侍郎錢舍人書問因繼以詩', '荅崔侍郎錢舍人书问因繼以诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["旦暮兩蔬食，日中一閑眠。","便是了一日，如此已三年。","心不擇時適，足不揀地安。","窮通與遠近，一貫無兩端。","常見今之人，其心或不然。","在勞則念息，處靜已思喧。","如是用身心，無乃自傷殘。","坐輸憂惱便，安得形神全。","吾有二道友，藹藹崔與錢。","同飛青雲路，獨墮黃泥泉。","歲暮物萬變，故情何不遷？","應爲平生心，與我同一源。","帝鄉遠於日，美人高在天。","誰謂萬里別，常若在目前。","泥泉樂者魚，雲路遊者鸞。","勿言雲泥異，同在逍遙間。","因君問心地，書後偶成篇。","慎勿說向人，人多笑此言。"]', '["旦暮兩蔬食，日中一闲眠。","便是了一日，如此已三年。","心不擇时適，足不揀地安。","窮通與远近，一貫無兩端。","常见今之人，其心或不然。","在勞則念息，处静已思喧。","如是用身心，無乃自傷殘。","坐輸憂惱便，安得形神全。","吾有二道友，藹藹崔與錢。","同飞青云路，独墮黄泥泉。","歲暮物万变，故情何不遷？","應爲平生心，與我同一源。","帝乡远於日，美人高在天。","誰謂万里別，常若在目前。","泥泉乐者鱼，云路游者鸾。","勿言云泥異，同在逍遙间。","因君问心地，书後偶成篇。","慎勿说向人，人多笑此言。"]', '诗', 'shi', '', NULL, '荅崔侍郎錢舍人書問因繼以詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c51202ed-3ea2-4e06-bc74-015a50dcaa61', '烹葵', '烹葵', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昨臥不夕食，今起乃朝飢。","貧廚何所有，炊稻烹秋葵。","紅粒香復輭，綠英滑且肥。","飢來止於飽，飽後復何思。","憶昔榮遇日，迨今窮退時。","今亦不凍餒，昔亦無餘資。","口既不減食，身又不減衣。","撫心私自問，何者是榮衰。","勿學常人意，其間分是非。"]', '["昨臥不夕食，今起乃朝飢。","貧廚何所有，炊稻烹秋葵。","紅粒香复輭，綠英滑且肥。","飢来止於飽，飽後复何思。","憶昔榮遇日，迨今窮退时。","今亦不凍餒，昔亦無餘資。","口既不減食，身又不減衣。","撫心私自问，何者是榮衰。","勿学常人意，其间分是非。"]', '诗', 'shi', '', NULL, '烹葵 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4f3937b-b536-4ab4-a1b9-3579663b75f3', '小池二首 一', '小池二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晝倦前齋熱，晚愛小池清。","映林餘景沒，近水微涼生。","坐把蒲葵扇，閑吟三兩聲。"]', '["晝倦前斋熱，晚愛小池清。","映林餘景沒，近水微涼生。","坐把蒲葵扇，闲吟三兩声。"]', '诗', 'shi', '', NULL, '小池二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dab2a9b2-6c75-4116-bbaa-b3621b68d164', '小池二首 二', '小池二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有意不在大，湛湛方丈餘。","荷側瀉清露，萍開見游魚。","每一臨此坐，憶歸青溪居。"]', '["有意不在大，湛湛方丈餘。","荷側瀉清露，萍开见游鱼。","每一臨此坐，憶归青溪居。"]', '诗', 'shi', '', NULL, '小池二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('734a53c9-abf5-4684-b5c2-e47e183b38be', '閉關', '閉关', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我心忘世久，世亦不我干。","遂成一無事，因得長掩關。","掩關來幾時，髣髴二三年。","著書已盈帙，生子欲能言。","始悟身向老，復悲世多艱。","迴顧趨時者，役役塵壤間。","歲暮竟何得，不如且安閑。"]', '["我心忘世久，世亦不我干。","遂成一無事，因得长掩关。","掩关来幾时，髣髴二三年。","著书已盈帙，生子欲能言。","始悟身向老，复悲世多艱。","迴顧趨时者，役役塵壤间。","歲暮竟何得，不如且安闲。"]', '诗', 'shi', '', NULL, '閉關 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ba27eec-9098-4f77-887b-b23649dc427d', '弄龜羅', '弄龟羅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有姪始六歲，字之爲阿龜。","有女生三年，其名曰羅兒。","一始學笑語，一能誦歌詩。","朝戲抱我足，夜眠枕我衣。","汝生何其晚，我年行已衰。","物情小可念，人意老多慈。","酒美竟須壞，月圓終有虧。","亦如恩愛緣，乃是憂惱資。","舉世同此累，吾安能去之。"]', '["有姪始六歲，字之爲阿龟。","有女生三年，其名曰羅兒。","一始学笑語，一能誦歌诗。","朝戲抱我足，夜眠枕我衣。","汝生何其晚，我年行已衰。","物情小可念，人意老多慈。","酒美竟須壞，月圓終有虧。","亦如恩愛緣，乃是憂惱資。","舉世同此累，吾安能去之。"]', '诗', 'shi', '', NULL, '弄龜羅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf293c1d-448f-45f2-ae6f-c5f8853caa68', '截樹', '截樹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["種樹當前軒，樹高柯葉繁。","惜哉遠山色，隱此蒙籠間。","一朝持斧斤，手自截其端。","萬葉落頭上，千峰來面前。","忽似決雲霧，豁達覩青天。","又如所念人，久別一款顏。","始有清風至，稍見飛鳥還。","開懷東南望，目遠心遼然。","人各有偏好，物莫能兩全。","豈不愛柔條，不如見青山。"]', '["種樹當前軒，樹高柯葉繁。","惜哉远山色，隐此蒙籠间。","一朝持斧斤，手自截其端。","万葉落头上，千峰来面前。","忽似決云霧，豁達覩青天。","又如所念人，久別一款顏。","始有清风至，稍见飞鸟還。","开懷东南望，目远心遼然。","人各有偏好，物莫能兩全。","豈不愛柔條，不如见青山。"]', '诗', 'shi', '', NULL, '截樹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d55abb-3959-4e39-b584-667ca99b90a1', '望江樓上作', '望江楼上作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江畔百尺樓，樓前千里道。","憑高望平遠，亦足舒懷抱。","驛路使憧憧，關防兵草草。","及茲多事日，尤覺閑人好。","我年過不惑，休退誠非早。","從此拂塵衣，歸山未爲老。"]', '["江畔百尺楼，楼前千里道。","憑高望平远，亦足舒懷抱。","驛路使憧憧，关防兵草草。","及茲多事日，尤覺闲人好。","我年過不惑，休退誠非早。","從此拂塵衣，归山未爲老。"]', '诗', 'shi', '', NULL, '望江樓上作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf3e94d7-a59b-4662-b9fa-0029f9270ff0', '題座隅', '題座隅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["手不任執殳，肩不能荷鋤。","量力揆所用，曾不敵一夫。","幸因筆研功，得升仕進途。","歷官凡五六，祿俸及妻孥。","左右有兼僕，出入有單車。","自奉雖不厚，亦不至飢劬。","若有人及此，傍觀爲何如。","雖賢亦爲幸，況我鄙且愚。","伯夷古賢人，魯山亦其徒。","時哉無奈何，俱化爲餓殍。","念彼益自媿，不敢忘斯須。","平生榮利心，破滅無遺餘。","猶恐塵妄起，題此於座隅。"]', '["手不任執殳，肩不能荷鋤。","量力揆所用，曾不敵一夫。","幸因笔研功，得升仕進途。","歷官凡五六，祿俸及妻孥。","左右有兼僕，出入有單车。","自奉雖不厚，亦不至飢劬。","若有人及此，傍观爲何如。","雖賢亦爲幸，況我鄙且愚。","伯夷古賢人，魯山亦其徒。","时哉無奈何，俱化爲餓殍。","念彼益自媿，不敢忘斯須。","平生榮利心，破滅無遺餘。","猶恐塵妄起，題此於座隅。"]', '诗', 'shi', '', NULL, '題座隅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73df8fc0-6c14-48f6-8e6c-8089eaaa9efb', '昔與微之在朝日同蓄休退之心迨今十年淪落老人追尋前約且結後期', '昔與微之在朝日同蓄休退之心迨今十年淪落老人追尋前約且結後期', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["往子爲御史，伊余忝拾遺。","皆逢盛明代，俱登清近司。","予繫玉爲佩，子曳繡爲衣。","從容香煙下，同侍白玉墀。","朝見寵者辱，暮見安者危。","紛紛無退者，相顧令人悲。","宦情君早厭，世事我深知。","常於榮顯日，已約林泉期。","況今各流落，身病齒髮衰。","不作臥雲計，攜手欲何之。","待君女嫁後，及我官滿時。","稍無骨肉累，粗有漁樵資。","歲晚青山路，白首期同歸。"]', '["往子爲御史，伊余忝拾遺。","皆逢盛明代，俱登清近司。","予繫玉爲佩，子曳繡爲衣。","從容香煙下，同侍白玉墀。","朝见寵者辱，暮见安者危。","紛紛無退者，相顧令人悲。","宦情君早厭，世事我深知。","常於榮显日，已約林泉期。","況今各流落，身病齒髮衰。","不作臥云計，携手欲何之。","待君女嫁後，及我官满时。","稍無骨肉累，粗有漁樵資。","歲晚青山路，白首期同归。"]', '诗', 'shi', '', NULL, '昔與微之在朝日同蓄休退之心迨今十年淪落老人追尋前約且結後期 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e552449d-5ad2-43b4-9954-2fe152c2ab5d', '垂釣', '垂釣', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["臨水一長嘯，忽思十年初。","三登甲乙第，一入承明廬。","浮生多變化，外事有盈虛。","今來伴江叟，沙頭坐釣魚。"]', '["臨水一长嘯，忽思十年初。","三登甲乙第，一入承明廬。","浮生多变化，外事有盈虛。","今来伴江叟，沙头坐釣鱼。"]', '诗', 'shi', '', NULL, '垂釣 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1dd16f4-eb61-4f25-b50c-fcd7cbd175ca', '晚鷰', '晚鷰', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["百鳥乳雛畢，秋鷰獨蹉跎。","去社日已近，銜泥意如何。","不悟時節晚，徒施工用多。","人間事亦爾，不獨鷰營窠。"]', '["百鸟乳雛畢，秋鷰独蹉跎。","去社日已近，銜泥意如何。","不悟时節晚，徒施工用多。","人间事亦爾，不独鷰營窠。"]', '诗', 'shi', '', NULL, '晚鷰 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd12aaa0-07f2-4b69-8fd4-7dd56c37415b', '贖雞', '贖雞', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["清晨臨江望，水禽正諠繁。","鳧鴈與鷗鷺，游颺戲朝暾。","適有鬻雞者，挈之來遠村。","飛鳴彼何樂，窘束此何冤。","喔喔十四雛，罩縛同一樊。","足傷金距蹜，頭搶花冠飜。","經宿廢飲啄，日高詣屠門。","遲迴未死間，飢渴欲相吞。","常慕古人道，仁信及魚豚。","見茲生惻隱，贖放雙林園。","開籠解索時，雞雞聽我言。","與爾鏹三百，小惠何足論。","莫學銜環雀，崎嶇謾報恩。"]', '["清晨臨江望，水禽正諠繁。","鳧鴈與鷗鷺，游颺戲朝暾。","適有鬻雞者，挈之来远村。","飞鳴彼何乐，窘束此何冤。","喔喔十四雛，罩縛同一樊。","足傷金距蹜，头搶花冠飜。","經宿廢饮啄，日高詣屠门。","遲迴未死间，飢渴欲相吞。","常慕古人道，仁信及鱼豚。","见茲生惻隐，贖放雙林园。","开籠解索时，雞雞听我言。","與爾鏹三百，小惠何足論。","莫学銜环雀，崎嶇謾報恩。"]', '诗', 'shi', '', NULL, '贖雞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf004d7f-6739-4a65-8651-e901393c3cfd', '秋日懷杓直', '秋日懷杓直', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晚來天色好，獨出江邊步。","憶與李舍人，曲江相近住。","常云遇清景，必約同幽趣。","若不訪我來，還須覓君去。","開眉笑相見，把手期何處。","西寺老胡僧，南園亂松樹。","攜持小酒榼，吟詠新詩句。","同出復同歸，從朝直至暮。","風雨忽消散，江山眇回互。","潯陽與涔陽，相望空雲霧。","心期自乖曠，時景還如故。","今日郡齋中，秋光誰共度。"]', '["晚来天色好，独出江邊步。","憶與李舍人，曲江相近住。","常云遇清景，必約同幽趣。","若不訪我来，還須覓君去。","开眉笑相见，把手期何处。","西寺老胡僧，南园亂松樹。","携持小酒榼，吟詠新诗句。","同出复同归，從朝直至暮。","风雨忽消散，江山眇回互。","潯陽與涔陽，相望空云霧。","心期自乖曠，时景還如故。","今日郡斋中，秋光誰共度。"]', '诗', 'shi', '', NULL, '秋日懷杓直 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ef9c4fd-e53a-4093-97e5-4c5f768fafa0', '食後', '食後', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["食罷一覺睡，起來兩甌茶。","舉頭看日影，已復西南斜。","樂人惜日促，憂人厭年賒。","無憂無樂者，長短任生涯。"]', '["食罷一覺睡，起来兩甌茶。","舉头看日影，已复西南斜。","乐人惜日促，憂人厭年賒。","無憂無乐者，长短任生涯。"]', '诗', 'shi', '', NULL, '食後 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1e28db1-6af3-4753-ae9a-1358e42ba146', '齊物二首 一', '齊物二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["青松高百尺，綠蕙低數寸。","同生大塊間，長短各有分。","長者不可退，短者不可進。","若用此理推，窮通兩無悶。"]', '["青松高百尺，綠蕙低數寸。","同生大塊间，长短各有分。","长者不可退，短者不可進。","若用此理推，窮通兩無悶。"]', '诗', 'shi', '', NULL, '齊物二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee6e17ac-f156-411d-81e9-e8b9cc0b1c75', '齊物二首 二', '齊物二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["椿壽八千春，槿花不經宿。","中間復何有，冉冉孤竹生。","竹身三年老，竹色四時綠。","雖謝椿有餘，猶勝槿不足。"]', '["椿壽八千春，槿花不經宿。","中间复何有，冉冉孤竹生。","竹身三年老，竹色四时綠。","雖謝椿有餘，猶勝槿不足。"]', '诗', 'shi', '', NULL, '齊物二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f69bf612-06cc-4b2c-8677-19fcfaed3e72', '山下宿', '山下宿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["獨到山下宿，靜向月中行。","何處水邊碓，夜舂雲母聲。"]', '["独到山下宿，静向月中行。","何处水邊碓，夜舂云母声。"]', '诗', 'shi', '', NULL, '山下宿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dc848eb-e121-4402-ad54-3c18430df5f9', '題舊寫真圖', '題旧寫真圖', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我昔三十六，寫貌在丹青。","我今四十六，衰顇臥江城。","豈比十年老，曾與衆苦幷。","一照舊圖畫，無復昔儀形。","形影默相顧，如弟對老兄。","況使他人見，能不昧平生。","羲和鞭日走，不爲我少停。","形骸屬日月，老去何足驚。","所恨凌煙閣，不得畫功名。"]', '["我昔三十六，寫貌在丹青。","我今四十六，衰顇臥江城。","豈比十年老，曾與衆苦幷。","一照旧圖畫，無复昔儀形。","形影默相顧，如弟对老兄。","況使他人见，能不昧平生。","羲和鞭日走，不爲我少停。","形骸屬日月，老去何足驚。","所恨凌煙閣，不得畫功名。"]', '诗', 'shi', '', NULL, '題舊寫真圖 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bd5568d-d3eb-49ae-bf85-53b1662959dd', '閑居', '闲居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["肺病不飲酒，眼昏不讀書。","端然無所作，身意閑有餘。","雞棲籬落晚，雪映林木疎。","幽獨已云極，何必山中居。"]', '["肺病不饮酒，眼昏不读书。","端然無所作，身意闲有餘。","雞棲籬落晚，雪映林木疎。","幽独已云極，何必山中居。"]', '诗', 'shi', '', NULL, '閑居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4952eb9d-2e38-4209-b8c2-1dc296b44555', '對酒示行簡', '对酒示行簡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今旦一尊酒，歡暢何怡怡。","此樂從中來，他人安得知。","兄弟唯二人，遠別恆苦悲。","今春自巴峽，萬里平安歸。","復有雙幼妹，笄年未結褵。","昨日嫁娶畢，良人皆可依。","憂念兩消釋，如刀斷羈縻。","身輕心無繫，忽欲凌空飛。","人生苟有累，食肉常如飢。","我心既無苦，飲水亦可肥。","行簡勸爾酒，停杯聽我辭。","不歎鄉國遠，不嫌官祿微。","但願我與爾，終老不相離。"]', '["今旦一尊酒，歡暢何怡怡。","此乐從中来，他人安得知。","兄弟唯二人，远別恆苦悲。","今春自巴峽，万里平安归。","复有雙幼妹，笄年未結褵。","昨日嫁娶畢，良人皆可依。","憂念兩消釋，如刀斷羈縻。","身轻心無繫，忽欲凌空飞。","人生苟有累，食肉常如飢。","我心既無苦，饮水亦可肥。","行簡勸爾酒，停杯听我辞。","不歎乡国远，不嫌官祿微。","但願我與爾，終老不相離。"]', '诗', 'shi', '', NULL, '對酒示行簡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78f506f9-3807-4524-9c5d-e8841924b5d0', '詠懷', '詠懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["冉牛與顏淵，卞和與馬遷。","或罹天六極，或被人刑殘。","顧我信爲幸，百骸且完全。","五十不爲夭，吾今欠數年。","知分心自足，委順身常安。","故雖窮退日，而無戚戚顏。","昔有榮先生，從事於其間。","今我不量力，舉心欲攀援。","窮通不由己，歡戚不由天。","命即無奈何，心可使泰然。","且務由己者，省躬諒非難。","勿問由天者，天高難與言。"]', '["冉牛與顏淵，卞和與马遷。","或罹天六極，或被人刑殘。","顧我信爲幸，百骸且完全。","五十不爲夭，吾今欠數年。","知分心自足，委順身常安。","故雖窮退日，而無戚戚顏。","昔有榮先生，從事於其间。","今我不量力，舉心欲攀援。","窮通不由己，歡戚不由天。","命即無奈何，心可使泰然。","且務由己者，省躬諒非难。","勿问由天者，天高难與言。"]', '诗', 'shi', '', NULL, '詠懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67ea017d-2d17-4386-9620-3c53ede786df', '夜琴', '夜琴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蜀[桐]木性實，楚絲音韻清。","調慢彈且緩，夜深十數聲。","入耳澹無味，愜心潛有情。","自弄還自罷，亦不要人聽。"]', '["蜀[桐]木性實，楚絲音韻清。","調慢彈且緩，夜深十數声。","入耳澹無味，愜心潛有情。","自弄還自罷，亦不要人听。"]', '诗', 'shi', '', NULL, '夜琴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a5033fe-52b7-44ef-b084-0fb7ac479bdd', '山中獨吟', '山中独吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人各有一癖，我癖在章句。","萬緣皆已消，此病獨未去。","每逢美風景，或對好親故。","高聲詠一篇，恍若與神遇。","自爲江上客，半在山中住。","有時新詩成，獨上東巖路。","身倚白石崖，手攀青桂樹。","狂吟驚林壑，猿鳥皆窺覰。","恐爲世所嗤，故就無人處。"]', '["人各有一癖，我癖在章句。","万緣皆已消，此病独未去。","每逢美风景，或对好親故。","高声詠一篇，恍若與神遇。","自爲江上客，半在山中住。","有时新诗成，独上东巖路。","身倚白石崖，手攀青桂樹。","狂吟驚林壑，猿鸟皆窺覰。","恐爲世所嗤，故就無人处。"]', '诗', 'shi', '', NULL, '山中獨吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c63f9e1-bfdf-40e2-babe-4122158ad06a', '達理二首 一', '達理二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何物壯不老，何時窮不通。","如彼音與律，宛轉旋爲宮。","我命獨何薄，多悴而少豐。","當壯已先衰，暫泰還長窮。","我無奈命何，委順以待終。","命無奈我何，方寸如虛空。","瞢然與化俱，混然與俗同。","誰能坐自苦，齟齬於其中。"]', '["何物壯不老，何时窮不通。","如彼音與律，宛轉旋爲宮。","我命独何薄，多悴而少豐。","當壯已先衰，暫泰還长窮。","我無奈命何，委順以待終。","命無奈我何，方寸如虛空。","瞢然與化俱，混然與俗同。","誰能坐自苦，齟齬於其中。"]', '诗', 'shi', '', NULL, '達理二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d05c117-d8f0-44c3-a7d4-f1a468de4520', '達理二首 二', '達理二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["舒姑化爲泉，牛哀病作虎。","或柳生肘間，或男變爲女。","鳥獸及水木，本不與民伍。","胡然生變遷，不待死歸土。","百骸是己物，尚不能爲主。","況彼時命間，倚伏何足數。","時來不可遏，命去焉能取。","唯當養浩然，吾聞達人語。"]', '["舒姑化爲泉，牛哀病作虎。","或柳生肘间，或男变爲女。","鸟獸及水木，本不與民伍。","胡然生变遷，不待死归土。","百骸是己物，尚不能爲主。","況彼时命间，倚伏何足數。","时来不可遏，命去焉能取。","唯當養浩然，吾闻達人語。"]', '诗', 'shi', '', NULL, '達理二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40257275-9bd6-4698-a37c-f3a816ffa86e', '湖亭晚望殘水', '湖亭晚望殘水', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["湖上秋泬寥，湖邊晚蕭瑟。","登亭望湖水，水縮湖底出。","清渟得早霜，明滅浮殘日。","流注隨地勢，窪坳無定質。","泓澄白龍臥，宛轉青蛇屈。","破鏡折劒頭，光芒又非一。","久爲山水客，見盡幽奇物。","及來湖亭望，此狀難談悉。","乃知天地間，勝事殊未畢。"]', '["湖上秋泬寥，湖邊晚蕭瑟。","登亭望湖水，水縮湖底出。","清渟得早霜，明滅浮殘日。","流注隨地勢，窪坳無定質。","泓澄白龙臥，宛轉青蛇屈。","破镜折劒头，光芒又非一。","久爲山水客，见尽幽奇物。","及来湖亭望，此狀难談悉。","乃知天地间，勝事殊未畢。"]', '诗', 'shi', '', NULL, '湖亭晚望殘水 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78240bba-291b-4149-84d8-c8c616498188', '郭虛舟相訪', '郭虛舟相訪', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝暖就南軒，暮寒歸後屋。","晚酒一兩杯，夜棊三數局。","寒灰埋暗火，曉燄凝殘燭。","不嫌貧冷人，時來同一宿。"]', '["朝暖就南軒，暮寒归後屋。","晚酒一兩杯，夜棊三數局。","寒灰埋暗火，晓燄凝殘燭。","不嫌貧冷人，时来同一宿。"]', '诗', 'shi', '', NULL, '郭虛舟相訪 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbf5e186-e78c-4e66-9470-5e463f63a1ef', '長慶二年七月自中書舍人出守杭州路次藍溪作', '长慶二年七月自中书舍人出守杭州路次藍溪作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["太原一男子，自顧庸且鄙。","老逢不次恩，洗拔出泥滓。","既居可言地，願助朝廷理。","伏閤三上章，戇愚不稱旨。","聖人存大體，優貸容不死。","鳳詔停舍人，魚書除刺史。","冥懷齊寵辱，委順隨行止。","我自得此心，於茲十年矣。","餘杭乃名郡，郡郭臨江汜。","已想海門山，潮聲來入耳。","昔予貞元末，羇旅曾遊此。","甚覺太守尊，亦諳魚酒美。","因生江海興，每羨滄浪水。","尚擬拂衣行，況今兼祿仕。","青山峰巒接，白日煙塵起。","東道既不通，改轅遂南指。","自秦窮楚越，浩蕩五千里。","聞有賢主人，而多好山水。","是行頗爲愜，所歷良可紀。","策馬度藍溪，勝遊從此始。"]', '["太原一男子，自顧庸且鄙。","老逢不次恩，洗拔出泥滓。","既居可言地，願助朝廷理。","伏閤三上章，戇愚不稱旨。","聖人存大體，優貸容不死。","鳳詔停舍人，鱼书除刺史。","冥懷齊寵辱，委順隨行止。","我自得此心，於茲十年矣。","餘杭乃名郡，郡郭臨江汜。","已想海门山，潮声来入耳。","昔予貞元末，羇旅曾游此。","甚覺太守尊，亦諳鱼酒美。","因生江海兴，每羨滄浪水。","尚擬拂衣行，況今兼祿仕。","青山峰巒接，白日煙塵起。","东道既不通，改轅遂南指。","自秦窮楚越，浩蕩五千里。","闻有賢主人，而多好山水。","是行頗爲愜，所歷良可紀。","策马度藍溪，勝游從此始。"]', '诗', 'shi', '', NULL, '長慶二年七月自中書舍人出守杭州路次藍溪作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cb24eb8-809a-4c32-b4d8-c2729a135d79', '初出城留別', '初出城留別', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝從紫禁歸，暮出青門去。","勿言城東陌，便是江南路。","揚鞭簇車馬，揮手辭親故。","我生本無鄉，心安是歸處。"]', '["朝從紫禁归，暮出青门去。","勿言城东陌，便是江南路。","揚鞭簇车马，揮手辞親故。","我生本無乡，心安是归处。"]', '诗', 'shi', '', NULL, '初出城留別 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74be07be-af29-42b9-9c5e-0f6a7e2f2dcd', '過駱山人野居小池', '過駱山人野居小池', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["茅覆環堵亭，泉添方丈沼。","紅芳照水荷，白頸觀魚鳥。","拳石苔蒼翠，尺波煙杳渺。","但問有意無，勿論池大小。","門前車馬路，奔走無昏曉。","名利驅人心，賢愚同擾擾。","善哉駱處士，安置身心了。","何乃獨多君，丘園居者少。"]', '["茅覆环堵亭，泉添方丈沼。","紅芳照水荷，白頸观鱼鸟。","拳石苔蒼翠，尺波煙杳渺。","但问有意無，勿論池大小。","门前车马路，奔走無昏晓。","名利驱人心，賢愚同擾擾。","善哉駱处士，安置身心了。","何乃独多君，丘园居者少。"]', '诗', 'shi', '', NULL, '過駱山人野居小池 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feff2589-7318-44b3-aa22-895bd04e2db5', '宿清源寺', '宿清源寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["往謫潯陽去，夜憩輞溪曲。","今爲錢塘行，重經茲寺宿。","爾來幾何歲，溪草二八綠。","不見舊房僧，蒼然新樹木。","虛空走日月，世界遷陵谷。","我生寄其間，孰能逃倚伏。","隨緣又南去，好住東廊竹。"]', '["往謫潯陽去，夜憩輞溪曲。","今爲錢塘行，重經茲寺宿。","爾来幾何歲，溪草二八綠。","不见旧房僧，蒼然新樹木。","虛空走日月，世界遷陵谷。","我生寄其间，孰能逃倚伏。","隨緣又南去，好住东廊竹。"]', '诗', 'shi', '', NULL, '宿清源寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('110831cb-d146-4614-9d67-954dbaa50d52', '宿藍溪對月', '宿藍溪对月', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昨夜鳳池頭，今夜藍溪口。","明月本無心，行人自回首。","新秋松影下，半夜鐘聲後。","清影不宜昏，聊將茶代酒。"]', '["昨夜鳳池头，今夜藍溪口。","明月本無心，行人自回首。","新秋松影下，半夜鐘声後。","清影不宜昏，聊將茶代酒。"]', '诗', 'shi', '', NULL, '宿藍溪對月 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0f39920-676a-42ac-b027-6386f449489b', '自秦望赴五松驛馬上偶睡睡覺成吟', '自秦望赴五松驛马上偶睡睡覺成吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["長途發已久，前館行未至。","體倦目已昏，瞌然遂成睡。","右袂尚垂鞭，左手暫委轡。","忽覺問僕夫，纔行百步地。","形神分處所，遲速相乖異。","馬上幾多時，夢中無限事。","誠哉達人語，百齡同一寐。"]', '["长途發已久，前館行未至。","體倦目已昏，瞌然遂成睡。","右袂尚垂鞭，左手暫委轡。","忽覺问僕夫，纔行百步地。","形神分处所，遲速相乖異。","马上幾多时，梦中無限事。","誠哉達人語，百齡同一寐。"]', '诗', 'shi', '', NULL, '自秦望赴五松驛馬上偶睡睡覺成吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa01fd76-539b-44ea-8778-5828aa6d122c', '鄧州路中作', '鄧州路中作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蕭蕭誰家村，秋棃葉半坼。","漠漠誰家園，秋韭花初白。","路逢故里物，使我嗟行役。","不歸渭北村，又作江南客。","去鄉徒自苦，濟世終無益。","自問波上萍，何如澗中石。"]', '["蕭蕭誰家村，秋棃葉半坼。","漠漠誰家园，秋韭花初白。","路逢故里物，使我嗟行役。","不归渭北村，又作江南客。","去乡徒自苦，濟世終無益。","自问波上萍，何如澗中石。"]', '诗', 'shi', '', NULL, '鄧州路中作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ced7b79c-a2b3-4e66-b45c-57c064e448fa', '朱藤杖紫驄吟', '朱藤杖紫驄吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["拄上山之下，騎下山之下。","江州去日朱藤杖，忠州歸日紫驄馬。","天生二物濟我窮，我生合是栖栖者。"]', '["拄上山之下，騎下山之下。","江州去日朱藤杖，忠州归日紫驄马。","天生二物濟我窮，我生合是栖栖者。"]', '诗', 'shi', '', NULL, '朱藤杖紫驄吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb50b096-bba0-4390-8e18-462fc3f75a3b', '桐樹館重題', '桐樹館重題', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["階前下馬時，梁上題詩處。","慘澹病使君，蕭疎老松樹。","自嗟還自哂，又向杭州去。"]', '["階前下马时，梁上題诗处。","慘澹病使君，蕭疎老松樹。","自嗟還自哂，又向杭州去。"]', '诗', 'shi', '', NULL, '桐樹館重題 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a082af8d-f141-4009-afe5-302510c3f93b', '過紫霞蘭若', '過紫霞蘭若', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我愛此山頭，及此三登歷。","紫霞舊精舍，寥落空泉石。","朝市日喧隘，雲林長悄寂。","猶存住寺僧，肯有歸山客。"]', '["我愛此山头，及此三登歷。","紫霞旧精舍，寥落空泉石。","朝市日喧隘，云林长悄寂。","猶存住寺僧，肯有归山客。"]', '诗', 'shi', '', NULL, '過紫霞蘭若 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('131197a4-3c77-46e9-b666-6a469444c1d7', '感舊紗帽', '感旧紗帽', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昔君烏紗帽，贈我白頭翁。","帽今在頂上，君已歸泉中。","物故猶堪用，人亡不可逢。","岐山今夜月，墳樹正秋風。"]', '["昔君烏紗帽，贈我白头翁。","帽今在頂上，君已归泉中。","物故猶堪用，人亡不可逢。","岐山今夜月，墳樹正秋风。"]', '诗', 'shi', '', NULL, '感舊紗帽 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c092e94-17fd-450d-b39d-362438c2c577', '思竹窗', '思竹窗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不憶西省松，不憶南宮菊。","惟憶新昌堂，蕭蕭北窗竹。","窗間枕簟在，來後何人宿。"]', '["不憶西省松，不憶南宮菊。","惟憶新昌堂，蕭蕭北窗竹。","窗间枕簟在，来後何人宿。"]', '诗', 'shi', '', NULL, '思竹窗 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46824eef-0191-4de8-9e84-7a1c7fdb4e3a', '馬上作', '马上作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["處世非不遇，榮身頗有餘。","勳爲上柱國，爵乃朝大夫。","自問有何才，兩入承明廬。","又問有何政，再駕朱輪車。","矧予東山人，自惟樸且疎。","彈琴復有酒，且慕嵇阮徒。","暗被鄉里薦，誤上賢能書。","一列朝士籍，遂爲世網拘。","高有罾繳憂，下有陷穽虞。","每覺宇宙窄，未嘗心體舒。","蹉跎二十年，頷下生白鬚。","何言左遷去，尚獲專城居。","杭州五千里，往若投淵魚。","雖未脫簪組，且來泛江湖。","吳中多詩人，亦不少酒酤。","高聲詠篇什，大笑飛杯盂。","五十未全老，尚可且歡娛。","用茲送日月，君以爲何如。","秋風起江上，白日落路隅。","回首語五馬，去矣勿踟躕。"]', '["处世非不遇，榮身頗有餘。","勳爲上柱国，爵乃朝大夫。","自问有何才，兩入承明廬。","又问有何政，再駕朱輪车。","矧予东山人，自惟樸且疎。","彈琴复有酒，且慕嵇阮徒。","暗被乡里薦，誤上賢能书。","一列朝士籍，遂爲世網拘。","高有罾繳憂，下有陷穽虞。","每覺宇宙窄，未嘗心體舒。","蹉跎二十年，頷下生白鬚。","何言左遷去，尚獲專城居。","杭州五千里，往若投淵鱼。","雖未脫簪組，且来泛江湖。","吳中多诗人，亦不少酒酤。","高声詠篇什，大笑飞杯盂。","五十未全老，尚可且歡娛。","用茲送日月，君以爲何如。","秋风起江上，白日落路隅。","回首語五马，去矣勿踟躕。"]', '诗', 'shi', '', NULL, '馬上作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f80f2e73-c485-486a-b3a6-0bea73275501', '秋蝶', '秋蝶', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秋花紫蒙蒙，秋蝶黃茸茸。","花低蝶新小，飛戲叢西東。","日暮涼風來，紛紛花落叢。","夜深白露冷，蝶已死叢中。","朝生夕俱死，氣類各相從。","不見千年鶴，多棲百丈松。"]', '["秋花紫蒙蒙，秋蝶黄茸茸。","花低蝶新小，飞戲叢西东。","日暮涼风来，紛紛花落叢。","夜深白露冷，蝶已死叢中。","朝生夕俱死，氣類各相從。","不见千年鹤，多棲百丈松。"]', '诗', 'shi', '', NULL, '秋蝶 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19a54dfa-fb1c-4fb6-8fa2-f4d6f10b1852', '登商山最高頂', '登商山最高頂', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["高高此山頂，四望唯煙雲。","下有一條路，通達楚與秦。","或名誘其心，或利牽其身。","乘者及負者，來去何云云。","我亦斯人徒，未能出囂塵。","七年三往復，何得笑他人。"]', '["高高此山頂，四望唯煙云。","下有一條路，通達楚與秦。","或名誘其心，或利牽其身。","乘者及負者，来去何云云。","我亦斯人徒，未能出囂塵。","七年三往复，何得笑他人。"]', '诗', 'shi', '', NULL, '登商山最高頂 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('173699a6-d696-4d20-ad2f-1555ae9e75d8', '枯桑', '枯桑', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["道傍老枯樹，枯來非一朝。","皮黃外尚活，心黑中先焦。","有似多憂者，非因外火燒。"]', '["道傍老枯樹，枯来非一朝。","皮黄外尚活，心黑中先焦。","有似多憂者，非因外火燒。"]', '诗', 'shi', '', NULL, '枯桑 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baa8e467-50f3-430f-aa57-7957ad9c51d6', '山路偶興', '山路偶兴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["筋力未全衰，僕馬不至弱。","又多山水趣，心賞非寂莫。","捫蘿上煙嶺，蹋石穿雲壑。","谷鳥晚仍啼，洞花秋不落。","提籠復攜榼，遇勝時停泊。","泉憩茶數甌，嵐行酒一酌。","獨吟還獨嘯，此興殊未惡。","假使在城時，終年有何樂。"]', '["筋力未全衰，僕马不至弱。","又多山水趣，心賞非寂莫。","捫蘿上煙嶺，蹋石穿云壑。","谷鸟晚仍啼，洞花秋不落。","提籠复携榼，遇勝时停泊。","泉憩茶數甌，嵐行酒一酌。","独吟還独嘯，此兴殊未惡。","假使在城时，終年有何乐。"]', '诗', 'shi', '', NULL, '山路偶興 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7619bb74-39a0-4fff-b258-7bae0c7f5676', '山雉', '山雉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["五步一啄草，十步一飲水。","適性遂其生，時哉山梁雉。","梁上無罾繳，梁下無鷹鸇。","雌雄與羣雛，皆得終天年。","嗟嗟籠下雞，及彼池中鴈。","既有稻粱恩，必有犧牲患。"]', '["五步一啄草，十步一饮水。","適性遂其生，时哉山梁雉。","梁上無罾繳，梁下無鷹鸇。","雌雄與羣雛，皆得終天年。","嗟嗟籠下雞，及彼池中鴈。","既有稻粱恩，必有犧牲患。"]', '诗', 'shi', '', NULL, '山雉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('894ac014-040e-4295-8804-2d9551398996', '初下漢江舟中作寄兩省給舍', '初下漢江舟中作寄兩省給舍', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秋水淅紅粒，朝煙烹白鱗。","一食飽至夜，一臥安達晨。","晨無朝謁勞，夜無直宿勤。","不知兩掖客，何似扁舟人。","尚想到郡日，且稱守土臣。","猶須副憂寄，恤隱安疲民。","朞年庶報政，三年當退身。","終使滄浪水，濯吾纓上塵。"]', '["秋水淅紅粒，朝煙烹白鱗。","一食飽至夜，一臥安達晨。","晨無朝謁勞，夜無直宿勤。","不知兩掖客，何似扁舟人。","尚想到郡日，且稱守土臣。","猶須副憂寄，恤隐安疲民。","朞年庶報政，三年當退身。","終使滄浪水，濯吾纓上塵。"]', '诗', 'shi', '', NULL, '初下漢江舟中作寄兩省給舍 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b7f3d41-bd0a-40a7-8d74-b30e149cacc6', '自蜀江至洞庭湖口有感而作', '自蜀江至洞庭湖口有感而作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江從西南來，浩浩無旦夕。","長波逐若瀉，連山鑿如劈。","千年不壅潰，萬姓無墊溺。","不爾民爲魚，大哉禹之績。","導岷既艱遠，距海無咫尺。","胡爲不訖功，餘水斯委積。","洞庭與青草，大小兩相敵。","混合萬丈深，淼茫千里白。","每歲秋夏時，浩大吞七澤。","水族窟穴多，農人土地窄。","我今尚嗟歎，禹豈不愛惜。","邈未究其由，想古觀遺跡。","疑此苗人頑，恃險不終役。","帝亦無奈何，留患與今昔。","水流天地內，如身有血脈。","滯則爲疽疣，治之在鍼石。","安得禹復生，爲唐水官伯。","手提倚天劒，重來親指畫。","疏河似翦紙，決壅同裂帛。","滲作膏腴田，蹋平魚鼈宅。","龍宮變閭里，水府生禾麥。","坐添百萬戶，書我司徒籍。"]', '["江從西南来，浩浩無旦夕。","长波逐若瀉，連山鑿如劈。","千年不壅潰，万姓無墊溺。","不爾民爲鱼，大哉禹之績。","導岷既艱远，距海無咫尺。","胡爲不訖功，餘水斯委積。","洞庭與青草，大小兩相敵。","混合万丈深，淼茫千里白。","每歲秋夏时，浩大吞七澤。","水族窟穴多，農人土地窄。","我今尚嗟歎，禹豈不愛惜。","邈未究其由，想古观遺跡。","疑此苗人頑，恃險不終役。","帝亦無奈何，留患與今昔。","水流天地內，如身有血脈。","滯則爲疽疣，治之在鍼石。","安得禹复生，爲唐水官伯。","手提倚天劒，重来親指畫。","疏河似翦紙，決壅同裂帛。","滲作膏腴田，蹋平鱼鼈宅。","龙宮变閭里，水府生禾麦。","坐添百万戶，书我司徒籍。"]', '诗', 'shi', '', NULL, '自蜀江至洞庭湖口有感而作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ecf5ff9-e393-42c7-9003-590250b970de', '初領郡政衙退登東樓作', '初領郡政衙退登东楼作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鰥惸心所念，簡牘手自操。","何言符竹貴，未免州縣勞。","賴是餘杭郡，臺榭繞官曹。","凌晨親政事，向晚恣遊遨。","山冷微有雪，波平未生濤。","水心如鏡面，千里無纖毫。","直下江最闊，近東樓更高。","煩襟與滯念，一望皆遁逃。"]', '["鰥惸心所念，簡牘手自操。","何言符竹貴，未免州縣勞。","賴是餘杭郡，台榭繞官曹。","凌晨親政事，向晚恣游遨。","山冷微有雪，波平未生濤。","水心如镜面，千里無纖毫。","直下江最闊，近东楼更高。","煩襟與滯念，一望皆遁逃。"]', '诗', 'shi', '', NULL, '初領郡政衙退登東樓作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f34c11c4-7b8c-4d6c-9073-11c7263ef2c5', '清調吟', '清調吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["索索風戒寒，沈沈日藏耀。","勸君飲濁醪，聽我吟清調。","芳節變窮陰，朝光成夕照。","與君生此世，不合長年少。","今晨從此過，明日安能料。","若不結跏禪，即須開口笑。"]', '["索索风戒寒，沈沈日藏耀。","勸君饮濁醪，听我吟清調。","芳節变窮陰，朝光成夕照。","與君生此世，不合长年少。","今晨從此過，明日安能料。","若不結跏禪，即須开口笑。"]', '诗', 'shi', '', NULL, '清調吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba03df23-9823-419f-8897-45d82bc9ea54', '狂歌詞', '狂歌词', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["明月照君席，白露霑我衣。","勸君酒杯滿，聽我狂歌詞。","五十已後衰，二十已前癡。","晝夜又分半，其間幾何時。","生前不歡樂，死後有餘貲。","焉用黃墟下，珠衾玉匣爲。"]', '["明月照君席，白露霑我衣。","勸君酒杯满，听我狂歌词。","五十已後衰，二十已前癡。","晝夜又分半，其间幾何时。","生前不歡乐，死後有餘貲。","焉用黄墟下，珠衾玉匣爲。"]', '诗', 'shi', '', NULL, '狂歌詞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e45db398-cab9-4305-a827-f1a69334a10a', '郡亭', '郡亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["平旦起視事，亭午臥掩關。","除親簿領外，多在琴書前。","況有虛白亭，坐見海門山。","潮來一凭檻，賓至一開筵。","終朝對雲水，有時聽管弦。","持此聊過日，非忙亦非閑。","山林太寂莫，朝闕空喧煩。","唯茲郡閤內，囂靜得中間。"]', '["平旦起視事，亭午臥掩关。","除親簿領外，多在琴书前。","況有虛白亭，坐见海门山。","潮来一凭檻，賓至一开筵。","終朝对云水，有时听管弦。","持此聊過日，非忙亦非闲。","山林太寂莫，朝闕空喧煩。","唯茲郡閤內，囂静得中间。"]', '诗', 'shi', '', NULL, '郡亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ec181c5-cb7c-4950-b680-2c264e9d4aff', '詠懷', '詠懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昔爲鳳閤郎，今爲二千石。","自覺不如今，人言不如昔。","昔雖居近密，終日多憂惕。","有詩不敢吟，有酒不敢喫。","今雖在疎遠，竟歲無牽役。","飽食坐終朝，長歌醉通夕。","人生百年內，疾速如過隙。","先務身安閑，次要心歡適。","事有得而失，物有損而益。","所以見道人，觀心不觀跡。"]', '["昔爲鳳閤郎，今爲二千石。","自覺不如今，人言不如昔。","昔雖居近密，終日多憂惕。","有诗不敢吟，有酒不敢喫。","今雖在疎远，竟歲無牽役。","飽食坐終朝，长歌醉通夕。","人生百年內，疾速如過隙。","先務身安闲，次要心歡適。","事有得而失，物有損而益。","所以见道人，观心不观跡。"]', '诗', 'shi', '', NULL, '詠懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbfe3f7a-9f95-463a-b90e-934879b5e8b4', '立春後五日', '立春後五日', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["立春後五日，春態紛婀娜。","白日斜漸長，碧雲低欲墮。","殘冰坼玉片，新萼排紅顆。","遇物盡欣欣，愛春非獨我。","迎芳後園立，就暖前檐作。","還有惆悵心，欲別紅爐火。"]', '["立春後五日，春態紛婀娜。","白日斜漸长，碧云低欲墮。","殘冰坼玉片，新萼排紅顆。","遇物尽欣欣，愛春非独我。","迎芳後园立，就暖前檐作。","還有惆悵心，欲別紅爐火。"]', '诗', 'shi', '', NULL, '立春後五日 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ff7a5a9-10ad-43dd-8998-fa65ec646ef7', '郡中即事', '郡中即事', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["漫漫潮初平，熙熙春日至。","空闊遠江山，晴明好天氣。","外有適意物，中無繫心事。","數篇對竹吟，一杯望雲醉。","行攜杖扶力，臥讀書取睡。","久養病形骸，深諳閑氣味。","遙思九城陌，擾擾趨名利。","今朝是雙日，朝謁多軒騎。","寵者防悔尤，權者懷憂畏。","爲報高車蓋，恐非真富貴。"]', '["漫漫潮初平，熙熙春日至。","空闊远江山，晴明好天氣。","外有適意物，中無繫心事。","數篇对竹吟，一杯望云醉。","行携杖扶力，臥读书取睡。","久養病形骸，深諳闲氣味。","遙思九城陌，擾擾趨名利。","今朝是雙日，朝謁多軒騎。","寵者防悔尤，權者懷憂畏。","爲報高车蓋，恐非真富貴。"]', '诗', 'shi', '', NULL, '郡中即事 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ef8d258-11d0-4f0f-ae66-1495b711de9b', '郡齋暇日辱常州陳郎中使君早春晚坐水西館書事詩十六韻見寄亦以十六韻酬之', '郡斋暇日辱常州陳郎中使君早春晚坐水西館书事诗十六韻见寄亦以十六韻酬之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["新年多暇日，晏起褰簾坐。","睡足心更慵，日高頭未裹。","徐傾下藥酒，稍爇煎茶火。","誰伴寂寥身，無弦琴在左。","遙思毘陵館，春深物嫋娜。","波拂黃柳梢，風搖白梅朵。","衙門排曉戟，鈴閣開朝鎖。","太守水西來，朱衣垂素舸。","良辰不易得，佳會無由果。","五馬正相望，雙魚忽前墮。","魚中獲瑰寶，持玩何磊砢。","一百六十言，字字靈珠顆。","上申心款曲，下敘時轗軻。","才富不如君，道孤還似我。","敢辭官遠慢，且貴身安妥。","勿復問榮枯，冥心無不可。"]', '["新年多暇日，晏起褰簾坐。","睡足心更慵，日高头未裹。","徐傾下藥酒，稍爇煎茶火。","誰伴寂寥身，無弦琴在左。","遙思毘陵館，春深物嫋娜。","波拂黄柳梢，风搖白梅朵。","衙门排晓戟，鈴閣开朝鎖。","太守水西来，朱衣垂素舸。","良辰不易得，佳會無由果。","五马正相望，雙鱼忽前墮。","鱼中獲瑰寶，持玩何磊砢。","一百六十言，字字靈珠顆。","上申心款曲，下敘时轗軻。","才富不如君，道孤還似我。","敢辞官远慢，且貴身安妥。","勿复问榮枯，冥心無不可。"]', '诗', 'shi', '', NULL, '郡齋暇日辱常州陳郎中使君早春晚坐水西館書事詩十六韻見寄亦以十六韻酬之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f8886aa-4e9c-4fe9-aaba-348518a30c5f', '官舍', '官舍', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["高樹換新葉，陰陰覆地隅。","何言太守宅，有似幽人居。","太守臥其下，閑慵兩有餘。","起嘗一甌茗，行讀一卷書。","早梅結青實，殘櫻落紅珠。","穉女弄庭果，嬉戲牽人裾。","是日晚彌靜，巢禽下相呼。","嘖嘖護兒鵲，啞啞母子烏。","豈唯云鳥爾，吾亦引吾雛。"]', '["高樹換新葉，陰陰覆地隅。","何言太守宅，有似幽人居。","太守臥其下，闲慵兩有餘。","起嘗一甌茗，行读一卷书。","早梅結青實，殘櫻落紅珠。","穉女弄庭果，嬉戲牽人裾。","是日晚彌静，巢禽下相呼。","嘖嘖護兒鵲，啞啞母子烏。","豈唯云鸟爾，吾亦引吾雛。"]', '诗', 'shi', '', NULL, '官舍 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c250cfa9-a262-432a-827d-d69fe38ca758', '吾雛', '吾雛', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吾雛字阿羅，阿羅纔七齡。","嗟吾不才子，憐爾無弟兄。","撫養雖驕騃，性識頗聰明。","學母畫眉樣，效吾詠詩聲。","我齒今欲墮，汝齒昨始生。","我頭髮盡落，汝頂髻初成。","老幼不相待，父衰汝孩嬰。","緬想古人心，慈愛亦不輕。","蔡邕念文姬，于公歎緹縈。","敢求得汝力，但未忘父情。"]', '["吾雛字阿羅，阿羅纔七齡。","嗟吾不才子，怜爾無弟兄。","撫養雖驕騃，性識頗聰明。","学母畫眉樣，效吾詠诗声。","我齒今欲墮，汝齒昨始生。","我头髮尽落，汝頂髻初成。","老幼不相待，父衰汝孩嬰。","緬想古人心，慈愛亦不轻。","蔡邕念文姬，于公歎緹縈。","敢求得汝力，但未忘父情。"]', '诗', 'shi', '', NULL, '吾雛 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6471155f-3234-40ba-922f-51737a960a7b', '題小橋前新竹招客', '題小橋前新竹招客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鴈齒小紅橋，垂檐低白屋。","橋前何所有，苒苒新生竹。","皮開坼褐錦，節露抽青玉。","筠翠如可餐，粉霜不忍觸。","閑吟聲未已，幽玩心難足。","管領好風煙，輕欺凡草木。","誰能有月夜，伴我林中宿。","爲君傾一杯，狂歌竹枝曲。"]', '["鴈齒小紅橋，垂檐低白屋。","橋前何所有，苒苒新生竹。","皮开坼褐錦，節露抽青玉。","筠翠如可餐，粉霜不忍觸。","闲吟声未已，幽玩心难足。","管領好风煙，轻欺凡草木。","誰能有月夜，伴我林中宿。","爲君傾一杯，狂歌竹枝曲。"]', '诗', 'shi', '', NULL, '題小橋前新竹招客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17a64973-cd58-4910-954d-856d75390941', '病中逢秋招客夜酌', '病中逢秋招客夜酌', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不見詩酒客，臥來半月餘。","合和新藥草，尋檢舊方書。","晚霽煙景度，早涼窗戶虛。","雪生衰鬢久，秋入病心初。","臥簟蘄竹冷，風襟邛葛疎。","夜來身校健，小飲復何如。"]', '["不见诗酒客，臥来半月餘。","合和新藥草，尋檢旧方书。","晚霽煙景度，早涼窗戶虛。","雪生衰鬢久，秋入病心初。","臥簟蘄竹冷，风襟邛葛疎。","夜来身校健，小饮复何如。"]', '诗', 'shi', '', NULL, '病中逢秋招客夜酌 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd60fd5e-b9ef-4c24-b786-ac4e6af48410', '食飽', '食飽', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["食飽拂枕臥，睡足起閑吟。","淺酌一杯酒，緩彈數弄琴。","既可暢情性，亦足傲光陰。","誰知利名盡，無復長安心。"]', '["食飽拂枕臥，睡足起闲吟。","淺酌一杯酒，緩彈數弄琴。","既可暢情性，亦足傲光陰。","誰知利名尽，無复长安心。"]', '诗', 'shi', '', NULL, '食飽 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63ff9c4a-2756-4c82-9c2a-eeb59870194d', '嚴十八郎中在郡日改制東南樓因名清輝未立標牓徵歸郎署予既到郡性愛樓居宴遊其間頗有幽致聊成十韻兼戲寄嚴', '嚴十八郎中在郡日改制东南楼因名清輝未立標牓徵归郎署予既到郡性愛楼居宴游其间頗有幽致聊成十韻兼戲寄嚴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["嚴郎置茲樓，立名曰清輝。","未及署花牓，遽徵還粉闈。","去來三四年，塵土登者稀。","今春新太守，灑埽施簾幃。","院柳煙婀娜，檐花雪霏微。","看山倚前戶，待月闡東扉。","碧窗戛瑤瑟，朱闌飄舞衣。","燒香卷幕坐，風燕雙雙飛。","君作不得住，我來幸因依。","始知天地間，靈境有所歸。"]', '["嚴郎置茲楼，立名曰清輝。","未及署花牓，遽徵還粉闈。","去来三四年，塵土登者稀。","今春新太守，灑埽施簾幃。","院柳煙婀娜，檐花雪霏微。","看山倚前戶，待月闡东扉。","碧窗戛瑤瑟，朱闌飄舞衣。","燒香卷幕坐，风燕雙雙飞。","君作不得住，我来幸因依。","始知天地间，靈境有所归。"]', '诗', 'shi', '', NULL, '嚴十八郎中在郡日改制東南樓因名清輝未立標牓徵歸郎署予既到郡性愛樓居宴遊其間頗有幽致聊成十韻兼戲寄嚴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba12e934-7c19-41f5-b395-5b19c6f92486', '南亭對酒送春', '南亭对酒送春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["含桃實已落，紅薇花尚熏。","冉冉三月盡，晚鶯城上聞。","獨持一杯酒，南亭送殘春。","半酣忽長歌，歌中何所云。","云我五十餘，未是苦老人。","刺史二千石，亦不爲賤貧。","天下三品官，多老於我身。","同年登第者，零落無一分。","親故半爲鬼，僮僕多見孫。","念此聊自解，逢酒且歡欣。"]', '["含桃實已落，紅薇花尚熏。","冉冉三月尽，晚鶯城上闻。","独持一杯酒，南亭送殘春。","半酣忽长歌，歌中何所云。","云我五十餘，未是苦老人。","刺史二千石，亦不爲賤貧。","天下三品官，多老於我身。","同年登第者，零落無一分。","親故半爲鬼，僮僕多见孫。","念此聊自解，逢酒且歡欣。"]', '诗', 'shi', '', NULL, '南亭對酒送春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55779b22-5259-45fa-b988-cbe798935041', '玩新庭樹因詠所懷', '玩新庭樹因詠所懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["靄靄四月初，新樹葉成陰。","動搖風景麗，蓋覆庭院深。","下有無事人，竟日此幽尋。","豈惟玩時物，亦可開煩襟。","時與道人語，或聽詩客吟。","度春足芳色，入夜多鳴禽。","偶得幽閑境，遂忘塵俗心。","始知真隱者，不必在山林。"]', '["靄靄四月初，新樹葉成陰。","动搖风景丽，蓋覆庭院深。","下有無事人，竟日此幽尋。","豈惟玩时物，亦可开煩襟。","时與道人語，或听诗客吟。","度春足芳色，入夜多鳴禽。","偶得幽闲境，遂忘塵俗心。","始知真隐者，不必在山林。"]', '诗', 'shi', '', NULL, '玩新庭樹因詠所懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5620ae9b-f33f-40c8-b2b2-60bfbb54078c', '仲夏齋戒月', '仲夏斋戒月', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["仲夏齋戒月，三旬斷腥羶。","自覺心骨爽，行起身翩翩。","始知絕粒人，四體更輕便。","初能脫病患，久必成神仙。","禦寇馭[泠]風，赤松遊紫煙。","常疑此說謬，今乃知其然。","我今過半百，氣衰神不全。","已垂兩鬢絲，難補三丹田。","但減葷血味，稍結清淨緣。","脫巾且修養，聊以終天年。"]', '["仲夏斋戒月，三旬斷腥羶。","自覺心骨爽，行起身翩翩。","始知絕粒人，四體更轻便。","初能脫病患，久必成神仙。","禦寇馭[泠]风，赤松游紫煙。","常疑此说謬，今乃知其然。","我今過半百，氣衰神不全。","已垂兩鬢絲，难補三丹田。","但減葷血味，稍結清淨緣。","脫巾且修養，聊以終天年。"]', '诗', 'shi', '', NULL, '仲夏齋戒月 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('854faac6-f108-46b7-8ba0-3eb3bfbc52ae', '除官去未間', '除官去未间', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["除官去未間，半月恣遊討。","朝尋霞外寺，暮宿波上島。","新樹少於松，平湖半連草。","躋攀有次第，賞玩無昏早。","有時騎馬醉，兀兀冥天造。","窮通與生死，其奈吾懷抱。","江山信爲美，齒髮行將老。","在郡誠未厭，歸鄉去亦好。"]', '["除官去未间，半月恣游討。","朝尋霞外寺，暮宿波上島。","新樹少於松，平湖半連草。","躋攀有次第，賞玩無昏早。","有时騎马醉，兀兀冥天造。","窮通與生死，其奈吾懷抱。","江山信爲美，齒髮行將老。","在郡誠未厭，归乡去亦好。"]', '诗', 'shi', '', NULL, '除官去未間 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aba03e64-f677-4118-9db0-a949ff266ee6', '三年爲刺史二首 一', '三年爲刺史二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三年爲刺史，無政在人口。","唯向城郡中，題詩十餘首。","慙非甘棠詠，豈有思人不。"]', '["三年爲刺史，無政在人口。","唯向城郡中，題诗十餘首。","慙非甘棠詠，豈有思人不。"]', '诗', 'shi', '', NULL, '三年爲刺史二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2bb10e4-a402-4ca3-9dd8-233944bbb728', '三年爲刺史二首 二', '三年爲刺史二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三年爲刺史，飲冰復食檗。","唯向天竺山，取得兩片石。","此抵有千金，無乃傷清白。"]', '["三年爲刺史，饮冰复食檗。","唯向天竺山，取得兩片石。","此抵有千金，無乃傷清白。"]', '诗', 'shi', '', NULL, '三年爲刺史二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2994cca5-f393-4075-a401-74d5c572e5f6', '別萱桂', '別萱桂', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["使君竟不住，萱桂徒栽種。","桂有留人名，萱無忘憂用。","不如江畔月，步步來相送。"]', '["使君竟不住，萱桂徒栽種。","桂有留人名，萱無忘憂用。","不如江畔月，步步来相送。"]', '诗', 'shi', '', NULL, '別萱桂 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4bf8f1f-24a9-4400-b2ca-d0464705b5d8', '自餘杭歸宿淮口作', '自餘杭归宿淮口作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["爲郡已多暇，猶少勤吏職。","罷郡更安閑，無所勞心力。","舟行明月下，夜泊清淮北。","豈止吾一身，舉家同燕息。","三年請祿俸，頗有餘衣食。","乃至僮僕間，皆無凍餒色。","行行弄雲水，步步近鄉國。","妻子在我前，琴書在我側。","此外吾不知，於焉心自得。"]', '["爲郡已多暇，猶少勤吏職。","罷郡更安闲，無所勞心力。","舟行明月下，夜泊清淮北。","豈止吾一身，舉家同燕息。","三年請祿俸，頗有餘衣食。","乃至僮僕间，皆無凍餒色。","行行弄云水，步步近乡国。","妻子在我前，琴书在我側。","此外吾不知，於焉心自得。"]', '诗', 'shi', '', NULL, '自餘杭歸宿淮口作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ad19230-37d1-462c-967d-6c0186b51e02', '舟中李山人訪宿', '舟中李山人訪宿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日暮舟悄悄，煙生水沈沈。","何以延宿客，夜酒與秋琴。","來客道門子，來自嵩高岑。","軒軒舉雲貌，豁豁開清襟。","得意言語斷，入玄滋味深。","默然相顧哂，心適而忘心。"]', '["日暮舟悄悄，煙生水沈沈。","何以延宿客，夜酒與秋琴。","来客道门子，来自嵩高岑。","軒軒舉云貌，豁豁开清襟。","得意言語斷，入玄滋味深。","默然相顧哂，心適而忘心。"]', '诗', 'shi', '', NULL, '舟中李山人訪宿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c866b9c-1ca3-4c30-83e1-87c977c4ee63', '洛下卜居', '洛下卜居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三年典郡歸，所得非金帛。","天竺石兩片，華亭鶴一隻。","飲啄供稻粱，包裹用茵席。","誠知是勞費，其奈心愛惜。","遠從餘杭郭，同到洛陽陌。","下擔拂雲根，開籠展霜翮。","貞姿不可雜，高性宜其適。","遂就無塵坊，仍求有水宅。","東南得幽境，樹老寒泉碧。","池畔多竹陰，門前少人跡。","未請中庶祿，且脫雙驂易。","豈獨爲身謀，安吾鶴與石。"]', '["三年典郡归，所得非金帛。","天竺石兩片，华亭鹤一隻。","饮啄供稻粱，包裹用茵席。","誠知是勞費，其奈心愛惜。","远從餘杭郭，同到洛陽陌。","下擔拂云根，开籠展霜翮。","貞姿不可杂，高性宜其適。","遂就無塵坊，仍求有水宅。","东南得幽境，樹老寒泉碧。","池畔多竹陰，门前少人跡。","未請中庶祿，且脫雙驂易。","豈独爲身謀，安吾鹤與石。"]', '诗', 'shi', '', NULL, '洛下卜居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d82c10e5-52bc-45f6-ae3c-589ae681de31', '洛中偶作', '洛中偶作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["五年職翰林，四年涖潯陽。","一年巴郡守，半年南宮郎。","二年直綸閤，三年刺史堂。","凡此十五載，有詩千餘章。","境興周萬象，土風備四方。","獨無洛中作，能不心悢悢。","今爲青宮長，始來遊此鄉。","裴回伊澗上，睥睨嵩少傍。","遇物輒一詠，一詠傾一觴。","筆下成釋憾，卷中同補亡。","往往顧自哂，眼昏鬚鬢蒼。","不知老將至，猶自放詩狂。"]', '["五年職翰林，四年涖潯陽。","一年巴郡守，半年南宮郎。","二年直綸閤，三年刺史堂。","凡此十五載，有诗千餘章。","境兴周万象，土风備四方。","独無洛中作，能不心悢悢。","今爲青宮长，始来游此乡。","裴回伊澗上，睥睨嵩少傍。","遇物輒一詠，一詠傾一觴。","笔下成釋憾，卷中同補亡。","往往顧自哂，眼昏鬚鬢蒼。","不知老將至，猶自放诗狂。"]', '诗', 'shi', '', NULL, '洛中偶作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a4d93c4-781f-44a5-a32e-ea35ab45a285', '贈蘇少府', '贈蘇少府', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["籍甚二十年，今日方款顏。","相送嵩洛下，論心杯酒間。","河亞嬾出入，府寮多閉關。","蒼髮彼此老，白日尋常閑。","朝從攜手出，暮思聯騎還。","何當挈一榼，同宿龍門山。"]', '["籍甚二十年，今日方款顏。","相送嵩洛下，論心杯酒间。","河亞嬾出入，府寮多閉关。","蒼髮彼此老，白日尋常闲。","朝從携手出，暮思聯騎還。","何當挈一榼，同宿龙门山。"]', '诗', 'shi', '', NULL, '贈蘇少府 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adbbe50e-2c3c-46e2-acbe-5b94139acaa2', '移家入新宅', '移家入新宅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["移家入新宅，罷郡有餘貲。","既可避燥濕，復免憂寒飢。","疾平未還假，官閑得分司。","幸有俸祿在，而無職役羈。","清旦盥漱畢，開軒卷簾幃。","家人及雞犬，隨我亦熙熙。","取興或寄酒，放情不過詩。","何必苦修道，此即是無爲。","外累信已遣，中懷時有思。","有思一何遠，默坐低雙眉。","十載囚竄客，萬里征戍兒。","春朝鏁籠鳥，冬夜支牀龜。","驛馬走四蹄，痛酸無歇期。","磑牛封兩目，昏閉何人知。","誰能脫放去，四散任所之。","各得適其性，如吾今日時。"]', '["移家入新宅，罷郡有餘貲。","既可避燥濕，复免憂寒飢。","疾平未還假，官闲得分司。","幸有俸祿在，而無職役羈。","清旦盥漱畢，开軒卷簾幃。","家人及雞犬，隨我亦熙熙。","取兴或寄酒，放情不過诗。","何必苦修道，此即是無爲。","外累信已遣，中懷时有思。","有思一何远，默坐低雙眉。","十載囚竄客，万里征戍兒。","春朝鏁籠鸟，冬夜支牀龟。","驛马走四蹄，痛酸無歇期。","磑牛封兩目，昏閉何人知。","誰能脫放去，四散任所之。","各得適其性，如吾今日时。"]', '诗', 'shi', '', NULL, '移家入新宅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7a3f901-b9f6-437b-81e8-7b8864644237', '琴', '琴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["置琴曲几上，慵坐但含情。","何煩故揮弄，風弦自有聲。"]', '["置琴曲几上，慵坐但含情。","何煩故揮弄，风弦自有声。"]', '诗', 'shi', '', NULL, '琴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afbcc14e-9509-40fd-997c-71d62b6b24a6', '鶴', '鹤', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人各有所好，物固無常宜。","誰謂爾能舞，不如閑立時。"]', '["人各有所好，物固無常宜。","誰謂爾能舞，不如闲立时。"]', '诗', 'shi', '', NULL, '鶴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e13290af-8a9e-436b-972f-8cef2c6b4d32', '自詠', '自詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜鏡隱白髮，朝酒發紅顏。","可憐假年少，自笑須臾間。","朱砂賤如土，不解燒爲丹。","玄鬢化爲雪，未聞休得官。","咄哉箇丈夫，心性何墮頑。","但遇詩與酒，便忘寢與餐。","高聲發一吟，似得詩中仙。","引滿飲一醆，盡忘身外緣。","昔有醉先生，席地而幕天。","于今居處在，許我當中眠。","眠罷又一酌，酌罷又一篇。","回面顧妻子，生計方落然。","誠知此事非，又過知非年。","豈不欲自改，改即心不安。","且向安處去，其餘皆老閑。"]', '["夜镜隐白髮，朝酒發紅顏。","可怜假年少，自笑須臾间。","朱砂賤如土，不解燒爲丹。","玄鬢化爲雪，未闻休得官。","咄哉箇丈夫，心性何墮頑。","但遇诗與酒，便忘寢與餐。","高声發一吟，似得诗中仙。","引满饮一醆，尽忘身外緣。","昔有醉先生，席地而幕天。","于今居处在，許我當中眠。","眠罷又一酌，酌罷又一篇。","回面顧妻子，生計方落然。","誠知此事非，又過知非年。","豈不欲自改，改即心不安。","且向安处去，其餘皆老闲。"]', '诗', 'shi', '', NULL, '自詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9f3f08b-5a61-410d-8e84-5c11bfef5b10', '林下閑步寄皇甫庶子', '林下闲步寄皇甫庶子', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["扶杖起病初，策馬力未任。","既嬾出門去，亦無客來尋。","以此遂成閑，閑步繞園林。","天曉煙景澹，樹寒鳥雀深。","一酌池上酒，數聲竹間吟。","寄言東曹長，當知幽獨心。"]', '["扶杖起病初，策马力未任。","既嬾出门去，亦無客来尋。","以此遂成闲，闲步繞园林。","天晓煙景澹，樹寒鸟雀深。","一酌池上酒，數声竹间吟。","寄言东曹长，當知幽独心。"]', '诗', 'shi', '', NULL, '林下閑步寄皇甫庶子 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99ea9770-c3ab-4da9-afa3-4410dfde41cd', '晏起', '晏起', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鳥鳴庭樹上，日照屋檐時。","老去慵轉極，寒來起尤遲。","厚薄被適性，高低枕得宜。","神安體穩暖，此味何人知。","睡足仰頭坐，兀然無所思。","如未鑿七竅，若都遺四肢。","緬想長安客，早朝霜滿衣。","彼此各自適，不知誰是非。"]', '["鸟鳴庭樹上，日照屋檐时。","老去慵轉極，寒来起尤遲。","厚薄被適性，高低枕得宜。","神安體穩暖，此味何人知。","睡足仰头坐，兀然無所思。","如未鑿七竅，若都遺四肢。","緬想长安客，早朝霜满衣。","彼此各自適，不知誰是非。"]', '诗', 'shi', '', NULL, '晏起 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbc0c564-743d-4ded-87a8-0a3b3e2ea9b9', '池畔二首 一', '池畔二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["結構池西廊，疏理池東樹。","此意人不知，欲爲待月處。"]', '["結構池西廊，疏理池东樹。","此意人不知，欲爲待月处。"]', '诗', 'shi', '', NULL, '池畔二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe56b3d6-8caf-4bae-9c41-ca6b00b6c59c', '池畔二首 二', '池畔二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["持刀𠜴密竹，竹少風來多。","此意人不會，欲令池有波。"]', '["持刀𠜴密竹，竹少风来多。","此意人不會，欲令池有波。"]', '诗', 'shi', '', NULL, '池畔二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('345a734b-c2c1-4f2d-ad3a-3c65804fc26a', '春葺新居', '春葺新居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江州司馬日，忠州刺史時。","栽松滿後院，種柳蔭前墀。","彼皆非吾土，栽種尚忘疲。","況茲是我宅，葺藝固其宜。","平旦領僕使，乘春親指揮。","移花夾暖室，徙竹覆寒池。","池水變綠色，池芳動清輝。","尋芳弄水坐，盡日心熙熙。","一物苟可適，萬緣都若遺。","設如宅門外，有事吾不知。"]', '["江州司马日，忠州刺史时。","栽松满後院，種柳蔭前墀。","彼皆非吾土，栽種尚忘疲。","況茲是我宅，葺藝固其宜。","平旦領僕使，乘春親指揮。","移花夾暖室，徙竹覆寒池。","池水变綠色，池芳动清輝。","尋芳弄水坐，尽日心熙熙。","一物苟可適，万緣都若遺。","設如宅门外，有事吾不知。"]', '诗', 'shi', '', NULL, '春葺新居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('482803cb-52e2-49ac-a2a9-bc2be2d5dfc3', '贈言', '贈言', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["捧籯獻千金，彼金何足道。","臨觴贈一言，此言真可寶。","流光我已晚，適意君不早。","況君春風面，柔促如芳草。","二十方長成，三十向衰老。","鏡中桃李色，不得十年好。","胡爲坐脈脈，不肯傾懷抱。"]', '["捧籯獻千金，彼金何足道。","臨觴贈一言，此言真可寶。","流光我已晚，適意君不早。","況君春风面，柔促如芳草。","二十方长成，三十向衰老。","镜中桃李色，不得十年好。","胡爲坐脈脈，不肯傾懷抱。"]', '诗', 'shi', '', NULL, '贈言 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61f15c85-4558-4a0a-a8d0-9629f1c7387d', '泛春池', '泛春池', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白蘋湘渚曲，綠篠剡溪口。","各在天一涯，信美非吾有。","何如此庭內，水竹交左右。","霜竹百千竿，煙波六七畝。","泓澄動階砌，澹泞映戶牖。","蛇皮細有紋，鏡面清無垢。","主人過橋來，雙童扶一叟。","恐汚清泠波，塵纓先抖擻。","波上一葉舟，舟中一尊酒。","酒開舟不繫，去去隨所偶。","或繞蒲浦前，或泊桃島後。","未撥落杯花，低衝拂面柳。","半酣迷所在，倚榜兀回首。","不知此何處，復是人寰否。","誰知始疏鑿，幾主相傳受。","楊家去云遠，田氏將非久。","天與愛水人，終焉落吾手。"]', '["白蘋湘渚曲，綠篠剡溪口。","各在天一涯，信美非吾有。","何如此庭內，水竹交左右。","霜竹百千竿，煙波六七畝。","泓澄动階砌，澹泞映戶牖。","蛇皮細有紋，镜面清無垢。","主人過橋来，雙童扶一叟。","恐汚清泠波，塵纓先抖擻。","波上一葉舟，舟中一尊酒。","酒开舟不繫，去去隨所偶。","或繞蒲浦前，或泊桃島後。","未撥落杯花，低衝拂面柳。","半酣迷所在，倚榜兀回首。","不知此何处，复是人寰否。","誰知始疏鑿，幾主相傳受。","楊家去云远，田氏將非久。","天與愛水人，終焉落吾手。"]', '诗', 'shi', '', NULL, '泛春池 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6112834-34c5-463c-bb0c-6d32c7360980', '西明寺牡丹花時憶元九', '西明寺牡丹花时憶元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["前年題名處，今日看花來。","一作芸香吏，三見牡丹開。","豈獨花堪惜，方知老闇催。","何況尋花伴，東都去未迴。","詎知紅芳側，春盡思悠哉。"]', '["前年題名处，今日看花来。","一作芸香吏，三见牡丹开。","豈独花堪惜，方知老闇催。","何況尋花伴，东都去未迴。","詎知紅芳側，春尽思悠哉。"]', '诗', 'shi', '', NULL, '西明寺牡丹花時憶元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1a57862-f4d1-450e-b606-7fb9932565a5', '傷楊弘貞', '傷楊弘貞', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["顏子昔短命，仲尼惜其賢。","楊生亦好學，不幸復徒然。","誰識天地意，獨與龜鶴年。"]', '["顏子昔短命，仲尼惜其賢。","楊生亦好学，不幸复徒然。","誰識天地意，独與龟鹤年。"]', '诗', 'shi', '', NULL, '傷楊弘貞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3eae8d8-7aa5-4353-bee9-990025e545b7', '權攝昭應早秋書事寄元拾遺兼呈李司錄', '權攝昭應早秋书事寄元拾遺兼呈李司錄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夏閏秋候早，七月風騷騷。","渭川煙景晚，驪山宮殿高。","丹殿子司諫，赤縣我徒勞。","相去半日程，不得同遊遨。","到官來十日，覽鏡生二毛。","可憐趨走吏，塵土滿青袍。","郵傳擁兩驛，簿書堆六曹。","爲問綱紀掾，何必使鉛刀。"]', '["夏閏秋候早，七月风騷騷。","渭川煙景晚，驪山宮殿高。","丹殿子司諫，赤縣我徒勞。","相去半日程，不得同游遨。","到官来十日，覽镜生二毛。","可怜趨走吏，塵土满青袍。","郵傳擁兩驛，簿书堆六曹。","爲问綱紀掾，何必使鉛刀。"]', '诗', 'shi', '', NULL, '權攝昭應早秋書事寄元拾遺兼呈李司錄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7591d16f-6511-4e1a-b950-71a697ccfd7f', '新栽竹', '新栽竹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["佐邑意不適，閉門秋草生。","何以娛野性，種竹百餘莖。","見此溪上色，憶得山中情。","有時公事暇，盡日繞闌行。","勿言根未固，勿言陰未成。","已覺庭宇內，稍稍有餘清。","最愛近窗臥，秋風枝有聲。"]', '["佐邑意不適，閉门秋草生。","何以娛野性，種竹百餘莖。","见此溪上色，憶得山中情。","有时公事暇，尽日繞闌行。","勿言根未固，勿言陰未成。","已覺庭宇內，稍稍有餘清。","最愛近窗臥，秋风枝有声。"]', '诗', 'shi', '', NULL, '新栽竹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2297e849-df3b-40aa-9599-3faa8a1b35c0', '秋霖中過尹縱之仙遊山居', '秋霖中過尹縱之仙游山居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["慘慘八月暮，連連三日霖。","邑居尚愁寂，況乃在山林。","林下有志士，苦學惜光陰。","歲晚千萬慮，幷入方寸心。","巖鳥共旅宿，草蟲伴愁吟。","秋天牀席冷，夜雨燈火深。","憐君寂莫意，攜酒一相尋。"]', '["慘慘八月暮，連連三日霖。","邑居尚愁寂，況乃在山林。","林下有志士，苦学惜光陰。","歲晚千万慮，幷入方寸心。","巖鸟共旅宿，草蟲伴愁吟。","秋天牀席冷，夜雨灯火深。","怜君寂莫意，携酒一相尋。"]', '诗', 'shi', '', NULL, '秋霖中過尹縱之仙遊山居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff5b4af6-0b5a-44de-acd3-a8d564d97a13', '寄江南兄弟', '寄江南兄弟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["分散骨肉戀，趨馳名利牽。","一奔塵埃馬，一泛風波船。","忽憶分手時，憫默秋風前。","別來朝復夕，積日成七年。","花落城中池，春深江上天。","登樓東南望，鳥滅煙蒼然。","相去復幾許，道里近三千。","平地猶難見，況乃隔山川。"]', '["分散骨肉戀，趨驰名利牽。","一奔塵埃马，一泛风波船。","忽憶分手时，憫默秋风前。","別来朝复夕，積日成七年。","花落城中池，春深江上天。","登楼东南望，鸟滅煙蒼然。","相去复幾許，道里近三千。","平地猶难见，況乃隔山川。"]', '诗', 'shi', '', NULL, '寄江南兄弟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c818221-55ea-430b-9c56-94fb4cbf9b7b', '曲江早秋', '曲江早秋', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秋波紅蓼水，夕照青蕪岸。","獨信馬蹄行，曲江池四畔。","早涼晴後至，殘暑暝來散。","方喜炎燠銷，復嗟時節換。","我年三十六，冉冉昏復旦。","人壽七十稀，七十新過半。","且當對酒笑，勿起臨風歎。"]', '["秋波紅蓼水，夕照青蕪岸。","独信马蹄行，曲江池四畔。","早涼晴後至，殘暑暝来散。","方喜炎燠銷，复嗟时節換。","我年三十六，冉冉昏复旦。","人壽七十稀，七十新過半。","且當对酒笑，勿起臨风歎。"]', '诗', 'shi', '', NULL, '曲江早秋 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d68df0bf-18b6-422a-b2aa-1bb730290c90', '寄題盩厔廳前雙松', '寄題盩厔廳前雙松', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憶昨爲吏日，折腰多苦辛。","歸來不自適，無計慰心神。","手栽兩樹松，聊以當嘉賓。","乘春日一溉，生意漸欣欣。","清韻度秋在，綠茸隨日新。","始憐澗底色，不憶城中春。","有時晝掩關，雙影對一身。","盡日不寂莫，意中如三人。","忽奉宣室詔，徵爲文苑臣。","閑來一惆悵，恰似別交親。","早知煙翠前，攀玩不逡巡。","悔從白雲裏，移爾落囂塵。"]', '["憶昨爲吏日，折腰多苦辛。","归来不自適，無計慰心神。","手栽兩樹松，聊以當嘉賓。","乘春日一溉，生意漸欣欣。","清韻度秋在，綠茸隨日新。","始怜澗底色，不憶城中春。","有时晝掩关，雙影对一身。","尽日不寂莫，意中如三人。","忽奉宣室詔，徵爲文苑臣。","闲来一惆悵，恰似別交親。","早知煙翠前，攀玩不逡巡。","悔從白云裏，移爾落囂塵。"]', '诗', 'shi', '', NULL, '寄題盩厔廳前雙松 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('822c5051-4bdf-4408-8b07-9c5fc029bdf2', '翰林院中感秋懷王質夫', '翰林院中感秋懷王質夫', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處感時節，新蟬禁中聞。","宮槐有秋意，風夕花紛紛。","寄跡鴛鷺行，歸心鷗鶴羣。","唯有王居士，知予憶白雲。","何日仙遊寺，潭前秋見君。"]', '["何处感时節，新蟬禁中闻。","宮槐有秋意，风夕花紛紛。","寄跡鴛鷺行，归心鷗鹤羣。","唯有王居士，知予憶白云。","何日仙游寺，潭前秋见君。"]', '诗', 'shi', '', NULL, '翰林院中感秋懷王質夫 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a1f1233-063c-4adb-ba10-66a7ff648f12', '禁中月', '禁中月', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["海水明月出，禁中清夜長。","東南樓殿白，稍稍上宮牆。","淨落金塘水，明浮玉砌霜。","不比人間見，塵土汚清光。"]', '["海水明月出，禁中清夜长。","东南楼殿白，稍稍上宮牆。","淨落金塘水，明浮玉砌霜。","不比人间见，塵土汚清光。"]', '诗', 'shi', '', NULL, '禁中月 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('246b0459-19f8-4397-b839-2c63191412fe', '贈賣松者', '贈賣松者', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一束蒼蒼色，知從澗底來。","斸掘經幾日，枝葉滿塵埃。","不買非他意，城中無地栽。"]', '["一束蒼蒼色，知從澗底来。","斸掘經幾日，枝葉满塵埃。","不買非他意，城中無地栽。"]', '诗', 'shi', '', NULL, '贈賣松者 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8e9a040-c9a9-475e-a5a8-33405b418baa', '初見白髮', '初见白髮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白髮生一莖，朝來明鏡裏。","勿言一莖少，滿頭從此始。","青山方遠別，黃綬初從仕。","未料容鬢間，蹉跎忽如此。"]', '["白髮生一莖，朝来明镜裏。","勿言一莖少，满头從此始。","青山方远別，黄綬初從仕。","未料容鬢间，蹉跎忽如此。"]', '诗', 'shi', '', NULL, '初見白髮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20a89f69-eab6-4d45-a51b-c455dd068e7d', '別元九後詠所懷', '別元九後詠所懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["零落桐葉雨，蕭條槿花風。","悠悠早秋意，生此幽閑中。","況與故人別，中懷正無悰。","勿云不相送，心到青門東。","相知豈在多，但問同不同。","同心一人去，坐覺長安空。"]', '["零落桐葉雨，蕭條槿花风。","悠悠早秋意，生此幽闲中。","況與故人別，中懷正無悰。","勿云不相送，心到青门东。","相知豈在多，但问同不同。","同心一人去，坐覺长安空。"]', '诗', 'shi', '', NULL, '別元九後詠所懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c00802d6-14e0-4611-96e5-700d18a335ef', '禁中秋宿', '禁中秋宿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風飜朱裏幕，雨冷通中枕。","耿耿背斜燈，秋牀一人寢。"]', '["风飜朱裏幕，雨冷通中枕。","耿耿背斜灯，秋牀一人寢。"]', '诗', 'shi', '', NULL, '禁中秋宿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31faed9c-869b-4eb0-9d40-3802f389aa82', '早秋曲江感懷', '早秋曲江感懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["離離暑雲散，嫋嫋涼風起。","池上秋又來，荷花半成子。","朱顏易銷歇，白日無窮已。","人壽不如山，年光忽於水。","青蕪與紅蓼，歲歲秋相似。","去歲此悲秋，今秋復來此。"]', '["離離暑云散，嫋嫋涼风起。","池上秋又来，荷花半成子。","朱顏易銷歇，白日無窮已。","人壽不如山，年光忽於水。","青蕪與紅蓼，歲歲秋相似。","去歲此悲秋，今秋复来此。"]', '诗', 'shi', '', NULL, '早秋曲江感懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da73e6ac-e170-4aa9-8cce-caa9c87fd16e', '寄元九', '寄元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["身爲近密拘，心爲名檢縛。","月夜與花時，少逢杯酒樂。","唯有元夫子，閑來同一酌。","把手或酣歌，展眉時笑謔。","今春除御史，前月之東洛。","別來未開顏，塵埃滿尊杓。","蕙風晚香盡，槐雨餘花落。","秋意一蕭條，離容兩寂莫。","況隨白日老，共負青山約。","誰識相念心，韝鷹與籠鶴。"]', '["身爲近密拘，心爲名檢縛。","月夜與花时，少逢杯酒乐。","唯有元夫子，闲来同一酌。","把手或酣歌，展眉时笑謔。","今春除御史，前月之东洛。","別来未开顏，塵埃满尊杓。","蕙风晚香尽，槐雨餘花落。","秋意一蕭條，離容兩寂莫。","況隨白日老，共負青山約。","誰識相念心，韝鷹與籠鹤。"]', '诗', 'shi', '', NULL, '寄元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f19baaa-24e9-412f-8b3a-9ff0264efaa9', '暮春寄元九', '暮春寄元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["棃花結成實，燕卵化爲雛。","時物又若此，道情復何如。","但覺日月促，不嗟年歲徂。","浮生都是夢，老小亦何殊。","唯與故人別，江陵初謫居。","時時一相見，此意未全除。"]', '["棃花結成實，燕卵化爲雛。","时物又若此，道情复何如。","但覺日月促，不嗟年歲徂。","浮生都是梦，老小亦何殊。","唯與故人別，江陵初謫居。","时时一相见，此意未全除。"]', '诗', 'shi', '', NULL, '暮春寄元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc29f2ec-43f8-4b7c-b5d7-ddecd6fc3327', '早梳頭', '早梳头', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜沐早梳頭，窗明秋鏡曉。","颯然握中髮，一沐知一少。","年事漸蹉跎，世緣方繳繞。","不學空門法，老病何由了。","未得無生心，白頭亦爲夭。"]', '["夜沐早梳头，窗明秋镜晓。","颯然握中髮，一沐知一少。","年事漸蹉跎，世緣方繳繞。","不学空门法，老病何由了。","未得無生心，白头亦爲夭。"]', '诗', 'shi', '', NULL, '早梳頭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9cb1b56-c0e2-460f-aad3-b6cbadaa2e36', '出關路', '出关路', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["山川函谷路，塵土遊子顏。","蕭條去國意，秋風生故關。"]', '["山川函谷路，塵土游子顏。","蕭條去国意，秋风生故关。"]', '诗', 'shi', '', NULL, '出關路 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73bc4f05-7c09-4641-af67-df578c1324bb', '別舍弟後月夜', '別舍弟後月夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["悄悄初別夜，去住兩盤桓。","行子孤燈店，居人明月軒。","平生共貧苦，未必日成歡。","及此暫爲別，懷抱已憂煩。","況是庭葉盡，復思山路寒。","如何爲不念，馬瘦衣裳單。"]', '["悄悄初別夜，去住兩盤桓。","行子孤灯店，居人明月軒。","平生共貧苦，未必日成歡。","及此暫爲別，懷抱已憂煩。","況是庭葉尽，复思山路寒。","如何爲不念，马瘦衣裳單。"]', '诗', 'shi', '', NULL, '別舍弟後月夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d550832-7c18-4a43-973c-22d8824d287f', '新豐路逢故人', '新豐路逢故人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["塵土長路晚，風煙廢宮秋。","相逢立馬語，盡日此橋頭。","知君不得意，鬱鬱來西遊。","惆悵新豐店，何人識馬周。"]', '["塵土长路晚，风煙廢宮秋。","相逢立马語，尽日此橋头。","知君不得意，鬱鬱来西游。","惆悵新豐店，何人識马周。"]', '诗', 'shi', '', NULL, '新豐路逢故人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f943b3e-8779-4855-92d3-cabb46f4e166', '金鑾子晬日', '金鑾子晬日', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["行年欲四十，有女曰金鑾。","生來始周歲，學坐未能言。","慙非達者懷，未免俗情憐。","從此累身外，徒云慰目前。","若無夭折患，則有婚嫁牽。","使我歸山計，應遲十五年。"]', '["行年欲四十，有女曰金鑾。","生来始周歲，学坐未能言。","慙非達者懷，未免俗情怜。","從此累身外，徒云慰目前。","若無夭折患，則有婚嫁牽。","使我归山計，應遲十五年。"]', '诗', 'shi', '', NULL, '金鑾子晬日 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('721cf4b0-fcee-4a61-b71a-60cea3e3c805', '青龍寺早夏', '青龙寺早夏', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["塵埃經小雨，地高倚長坡。","日西寺門外，景氣含清和。","閑有老僧立，靜無凡客過。","殘鶯意思盡，新葉陰涼多。","春去來幾日，夏雲忽嵯峨。","朝朝感時節，年鬢闇蹉跎。","胡爲戀朝市，不去歸煙蘿。","青山寸步地，自問心如何。"]', '["塵埃經小雨，地高倚长坡。","日西寺门外，景氣含清和。","闲有老僧立，静無凡客過。","殘鶯意思尽，新葉陰涼多。","春去来幾日，夏云忽嵯峨。","朝朝感时節，年鬢闇蹉跎。","胡爲戀朝市，不去归煙蘿。","青山寸步地，自问心如何。"]', '诗', 'shi', '', NULL, '青龍寺早夏 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fca5118-ff38-4321-9ac8-4e448590b93e', '秋題牡丹叢', '秋題牡丹叢', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晚叢白露夕，衰葉涼風朝。","紅豔久已歇，碧芳今亦銷。","幽人坐相對，心事共蕭條。"]', '["晚叢白露夕，衰葉涼风朝。","紅豔久已歇，碧芳今亦銷。","幽人坐相对，心事共蕭條。"]', '诗', 'shi', '', NULL, '秋題牡丹叢 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('483540a1-433e-4a6a-8167-fcfda736a28c', '勸酒寄元九', '勸酒寄元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["薤葉有朝露，槿枝無宿花。","君今亦如此，促促生有涯。","既不逐禪僧，林下學楞伽。","又不隨道士，山中鍊丹砂。","百年夜分半，一歲春無多。","何不飲美酒？胡然自悲嗟。","俗號銷愁藥，神速無以加。","一杯驅世慮，兩杯反天和。","三杯即酩酊，或笑任狂歌。","陶陶復兀兀，吾孰知其他。","況在名利途，平生有風波。","深心藏陷穽，巧言織網羅。","舉目非不見，不醉欲如何。"]', '["薤葉有朝露，槿枝無宿花。","君今亦如此，促促生有涯。","既不逐禪僧，林下学楞伽。","又不隨道士，山中鍊丹砂。","百年夜分半，一歲春無多。","何不饮美酒？胡然自悲嗟。","俗號銷愁藥，神速無以加。","一杯驱世慮，兩杯反天和。","三杯即酩酊，或笑任狂歌。","陶陶复兀兀，吾孰知其他。","況在名利途，平生有风波。","深心藏陷穽，巧言织網羅。","舉目非不见，不醉欲如何。"]', '诗', 'shi', '', NULL, '勸酒寄元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1e06ad3-5320-40b3-9007-11a7520d9e2a', '曲江感秋', '曲江感秋', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["沙草新雨地，岸柳涼風枝。","三年感秋意，幷在曲江池。","早蟬已嘹唳，晚荷復離披。","前秋去秋思，一一生此時。","昔人三十二，秋興已云悲。","我今欲四十，秋懷亦可知。","歲月不虛設，此身隨日衰。","闇老不自覺，直到鬢成絲。"]', '["沙草新雨地，岸柳涼风枝。","三年感秋意，幷在曲江池。","早蟬已嘹唳，晚荷复離披。","前秋去秋思，一一生此时。","昔人三十二，秋兴已云悲。","我今欲四十，秋懷亦可知。","歲月不虛設，此身隨日衰。","闇老不自覺，直到鬢成絲。"]', '诗', 'shi', '', NULL, '曲江感秋 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3b3e541-4cce-47ad-87ab-5dfcbd8fdc4e', '酬張太祝晚秋臥病見寄', '酬張太祝晚秋臥病见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["高才淹禮寺，短羽翔禁林。","西街居處遠，北闕官曹深。","君病不來訪，我忙難往尋。","差池終日別，寥落經年心。","露濕綠蕪地，月寒紅樹陰。","況茲獨愁夕，聞彼相思吟。","上歎言笑阻，下嗟時歲侵。","容衰曉窗鏡，思苦秋弦琴。","一章錦繡段，八韻瓊瑤音。","何以報珍重，慙無雙南金。"]', '["高才淹禮寺，短羽翔禁林。","西街居处远，北闕官曹深。","君病不来訪，我忙难往尋。","差池終日別，寥落經年心。","露濕綠蕪地，月寒紅樹陰。","況茲独愁夕，闻彼相思吟。","上歎言笑阻，下嗟时歲侵。","容衰晓窗镜，思苦秋弦琴。","一章錦繡段，八韻瓊瑤音。","何以報珍重，慙無雙南金。"]', '诗', 'shi', '', NULL, '酬張太祝晚秋臥病見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('847c2196-b35c-4735-bd72-5c363ee96c61', '立秋日曲江憶元九', '立秋日曲江憶元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["下馬柳陰下，獨上堤上行。","故人千萬里，新蟬三兩聲。","城中曲江水，江上江陵城。","兩地新秋思，應同此日情。"]', '["下马柳陰下，独上堤上行。","故人千万里，新蟬三兩声。","城中曲江水，江上江陵城。","兩地新秋思，應同此日情。"]', '诗', 'shi', '', NULL, '立秋日曲江憶元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('448335bb-7019-4000-b9e7-12c8b5335d69', '早朝賀雪寄陳山人', '早朝賀雪寄陳山人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["長安盈尺雪，早朝賀君喜。","將赴銀臺門，始出新昌里。","上堤馬蹄滑，中路蠟燭死。","十里向北行，寒風吹破耳。","待漏午門外，候對三殿裏。","鬚鬢凍生冰，衣裳冷如水。","忽思仙遊谷，闇謝陳居士。","暖覆褐裘眠，日高應未起。"]', '["长安盈尺雪，早朝賀君喜。","將赴銀台门，始出新昌里。","上堤马蹄滑，中路蠟燭死。","十里向北行，寒风吹破耳。","待漏午门外，候对三殿裏。","鬚鬢凍生冰，衣裳冷如水。","忽思仙游谷，闇謝陳居士。","暖覆褐裘眠，日高應未起。"]', '诗', 'shi', '', NULL, '早朝賀雪寄陳山人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f79eec1c-d15c-4ca2-a32b-49f98e1c4be9', '初與元九別後忽夢見之及寤而書適至兼寄桐花詩悵然感懷因以此寄', '初與元九別後忽梦见之及寤而书適至兼寄桐花诗悵然感懷因以此寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["永壽寺中語，新昌坊北分。","歸來數行淚，悲事不悲君。","悠悠藍田路，自去無消息。","計君食宿程，已過商山北。","昨夜雲四散，千里同月色。","曉來夢見君，應是君相憶。","夢中握君手，問君意何如。","君言苦相憶，無人可寄書。","覺來未及說，叩門聲冬冬。","言是商州使，送君書一封。","枕上忽驚起，顛倒著衣裳。","開緘見手札，一紙十三行。","上論遷謫心，下說離別腸。","心腸都未盡，不暇敘炎涼。","云作此書夜，夜宿商州東。","獨對孤燈坐，陽城山館中。","夜深作書畢，山月向西斜。","月下何所有，一樹紫桐花。","桐花半落時，復道正相思。","殷勤書背後，兼寄桐花詩。","桐花詩八韻，思緒一何深。","以我今朝意，憶君此夜心。","一章三徧讀，一句十回吟。","珍重八十字，字字化爲金。"]', '["永壽寺中語，新昌坊北分。","归来數行泪，悲事不悲君。","悠悠藍田路，自去無消息。","計君食宿程，已過商山北。","昨夜云四散，千里同月色。","晓来梦见君，應是君相憶。","梦中握君手，问君意何如。","君言苦相憶，無人可寄书。","覺来未及说，叩门声冬冬。","言是商州使，送君书一封。","枕上忽驚起，顛倒著衣裳。","开緘见手札，一紙十三行。","上論遷謫心，下说離別腸。","心腸都未尽，不暇敘炎涼。","云作此书夜，夜宿商州东。","独对孤灯坐，陽城山館中。","夜深作书畢，山月向西斜。","月下何所有，一樹紫桐花。","桐花半落时，复道正相思。","殷勤书背後，兼寄桐花诗。","桐花诗八韻，思緒一何深。","以我今朝意，憶君此夜心。","一章三徧读，一句十回吟。","珍重八十字，字字化爲金。"]', '诗', 'shi', '', NULL, '初與元九別後忽夢見之及寤而書適至兼寄桐花詩悵然感懷因以此寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('016852d0-1d90-4505-a40d-0790a919f615', '和元九悼往', '和元九悼往', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["美人別君去，自去無處尋。","舊物零落盡，此情安可任。","唯有襭紗幌，塵埃日夜侵。","馨香與顏色，不似舊時深。","透影燈耿耿，籠光月沈沈。","中有孤眠客，秋涼生夜衾。","舊宅牡丹院，新墳松柏林。","夢中咸陽淚，覺後江陵心。","含此隔年恨，發爲中夜吟。","無論君自感，聞者欲霑襟。"]', '["美人別君去，自去無处尋。","旧物零落尽，此情安可任。","唯有襭紗幌，塵埃日夜侵。","馨香與顏色，不似旧时深。","透影灯耿耿，籠光月沈沈。","中有孤眠客，秋涼生夜衾。","旧宅牡丹院，新墳松柏林。","梦中咸陽泪，覺後江陵心。","含此隔年恨，發爲中夜吟。","無論君自感，闻者欲霑襟。"]', '诗', 'shi', '', NULL, '和元九悼往 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08ddb320-00e7-48e2-b758-c9d4986a0178', '重到渭上舊居', '重到渭上旧居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["舊居清渭曲，開門當蔡渡。","十年方一還，幾欲迷歸路。","追思昔日行，感傷故游處。","插柳作高林，種桃成老樹。","因驚成人者，盡是舊童孺。","試問舊老人，半爲繞村墓。","浮生同過客，前後遞來去。","白日如弄珠，出沒光不住。","人物日改變，舉目悲所遇。","回念念我身，安得不衰暮。","朱顏銷不歇，白髮生無數。","唯有山門外，三峰色如故。"]', '["旧居清渭曲，开门當蔡渡。","十年方一還，幾欲迷归路。","追思昔日行，感傷故游处。","插柳作高林，種桃成老樹。","因驚成人者，尽是旧童孺。","試问旧老人，半爲繞村墓。","浮生同過客，前後遞来去。","白日如弄珠，出沒光不住。","人物日改变，舉目悲所遇。","回念念我身，安得不衰暮。","朱顏銷不歇，白髮生無數。","唯有山门外，三峰色如故。"]', '诗', 'shi', '', NULL, '重到渭上舊居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2811f42-120f-4b45-b4f7-7d97ba992ef0', '白髮', '白髮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白髮知時節，闇與我有期。","今朝日陽裹，梳落數莖絲。","家人不慣見，憫默爲我悲。","我云何足怪，此意爾不知。","凡人年三十，外壯中已衰。","但思寢食味，已減二十時。","況我今四十，本來形貌羸。","書魔昏兩眼，酒病沈四肢。","親愛日零落，在者仍別離。","身心久如此，白髮生已遲。","由來生老死，三病長相隨。","除却念無生，人間無藥治。"]', '["白髮知时節，闇與我有期。","今朝日陽裹，梳落數莖絲。","家人不慣见，憫默爲我悲。","我云何足怪，此意爾不知。","凡人年三十，外壯中已衰。","但思寢食味，已減二十时。","況我今四十，本来形貌羸。","书魔昏兩眼，酒病沈四肢。","親愛日零落，在者仍別離。","身心久如此，白髮生已遲。","由来生老死，三病长相隨。","除却念無生，人间無藥治。"]', '诗', 'shi', '', NULL, '白髮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7f1fa7e-9a70-40a3-8d1b-62f7389d6b0f', '秋日', '秋日', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["池殘寥落水，窗下悠楊日。","嫋嫋秋風多，槐花半成實。","下有獨立人，年來四十一。"]', '["池殘寥落水，窗下悠楊日。","嫋嫋秋风多，槐花半成實。","下有独立人，年来四十一。"]', '诗', 'shi', '', NULL, '秋日 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('783dbf4f-eaee-419c-a86f-5bba5e8a8370', '將之饒州江浦夜泊', '將之饒州江浦夜泊', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["明月滿深浦，愁人臥孤舟。","煩冤寢不得，夏夜長於秋。","苦乏衣食資，遠爲江海游。","光陰坐遲暮，鄉國行阻修。","身病向鄱陽，家貧寄徐州。","前事與後事，豈堪心幷憂。","憂來起長望，但見江水流。","雲樹靄蒼蒼，煙波澹悠悠。","故園迷處所，一念堪白頭。"]', '["明月满深浦，愁人臥孤舟。","煩冤寢不得，夏夜长於秋。","苦乏衣食資，远爲江海游。","光陰坐遲暮，乡国行阻修。","身病向鄱陽，家貧寄徐州。","前事與後事，豈堪心幷憂。","憂来起长望，但见江水流。","云樹靄蒼蒼，煙波澹悠悠。","故园迷处所，一念堪白头。"]', '诗', 'shi', '', NULL, '將之饒州江浦夜泊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76488b18-9b18-47db-abeb-1c2ba3d98cb3', '思歸', '思归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["養無晨昏膳，隱無伏臘資。","遂求及親祿，僶俛來京師。","薄俸未及親，別家已經時。","冬積溫席戀，春違采蘭期。","夏至一陰生，稍稍夕漏遲。","塊然抱愁者，長夜獨先知。","悠悠鄉關路，夢去身不隨。","坐惜時節變，蟬鳴槐花枝。"]', '["養無晨昏膳，隐無伏臘資。","遂求及親祿，僶俛来京師。","薄俸未及親，別家已經时。","冬積溫席戀，春違采蘭期。","夏至一陰生，稍稍夕漏遲。","塊然抱愁者，长夜独先知。","悠悠乡关路，梦去身不隨。","坐惜时節变，蟬鳴槐花枝。"]', '诗', 'shi', '', NULL, '思歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b687e90b-e200-4a42-9e09-0c05702c2378', '冀城北原作', '冀城北原作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["野色何莽蒼，秋聲亦蕭疎。","風吹黃埃起，落日驅征車。","何代此開國，封疆百里餘。","古今不相待，朝市無常居。","昔人城邑中，今變爲丘墟。","昔人墓田中，今化爲里閭。","廢興相催迫，日月互居諸。","世變無遺風，焉能知其初。","行人千載後，懷古空躊躇。"]', '["野色何莽蒼，秋声亦蕭疎。","风吹黄埃起，落日驱征车。","何代此开国，封疆百里餘。","古今不相待，朝市無常居。","昔人城邑中，今变爲丘墟。","昔人墓田中，今化爲里閭。","廢兴相催迫，日月互居諸。","世变無遺风，焉能知其初。","行人千載後，懷古空躊躇。"]', '诗', 'shi', '', NULL, '冀城北原作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0176e6c7-d4db-4890-9cbb-937f04a351d2', '客路感秋寄明準上人', '客路感秋寄明準上人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日暮天地冷，雨霽山河清。","長風從西來，草木凝秋聲。","已感歲倏忽，復傷物凋零。","孰能不憯悽，天時牽人情。","借問空門子，何法易修行。","使我忘得心，不教煩惱生。"]', '["日暮天地冷，雨霽山河清。","长风從西来，草木凝秋声。","已感歲倏忽，复傷物凋零。","孰能不憯悽，天时牽人情。","借问空门子，何法易修行。","使我忘得心，不教煩惱生。"]', '诗', 'shi', '', NULL, '客路感秋寄明準上人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d9ceb06-f371-490a-bfb9-0687677aabf5', '遊襄陽懷孟浩然', '游襄陽懷孟浩然', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["楚山碧巖巖，漢水碧湯湯。","秀氣結成象，孟氏之文章。","今我諷遺文，思人至其鄉。","清風無人繼，日暮空襄陽。","南望鹿門山，藹若有餘芳。","舊隱不知處，雲深樹蒼蒼。"]', '["楚山碧巖巖，漢水碧湯湯。","秀氣結成象，孟氏之文章。","今我諷遺文，思人至其乡。","清风無人繼，日暮空襄陽。","南望鹿门山，藹若有餘芳。","旧隐不知处，云深樹蒼蒼。"]', '诗', 'shi', '', NULL, '遊襄陽懷孟浩然 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31a7d689-501a-42d0-858b-9a57cefff693', '秋暮西歸途中書情', '秋暮西归途中书情', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["耿耿旅燈下，愁多常少眠。","思鄉貴早發，發在雞鳴前。","九月草木落，平蕪連遠山。","秋陰和曙色，萬木蒼蒼然。","去秋偶東遊，今秋始西旋。","馬瘦衣裳破，別家來二年。","憶歸復愁歸，歸無一囊錢。","心雖非蘭膏，安得不自然。"]', '["耿耿旅灯下，愁多常少眠。","思乡貴早發，發在雞鳴前。","九月草木落，平蕪連远山。","秋陰和曙色，万木蒼蒼然。","去秋偶东游，今秋始西旋。","马瘦衣裳破，別家来二年。","憶归复愁归，归無一囊錢。","心雖非蘭膏，安得不自然。"]', '诗', 'shi', '', NULL, '秋暮西歸途中書情 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('264fac5e-a33e-4c83-8bb8-f80cf8d4fc3d', '秋懷', '秋懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["月出照北堂，光華滿階墀。","涼風從西至，草木日夜衰。","桐柳減綠陰，蕙蘭消碧滋。","感物私自念，我心亦如之。","安得長少壯，盛衰迫天時。","人生如石火，爲樂長苦遲。"]', '["月出照北堂，光华满階墀。","涼风從西至，草木日夜衰。","桐柳減綠陰，蕙蘭消碧滋。","感物私自念，我心亦如之。","安得长少壯，盛衰迫天时。","人生如石火，爲乐长苦遲。"]', '诗', 'shi', '', NULL, '秋懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfa3c78d-8545-4281-885e-1f3818fc01a8', '別楊穎士盧克柔殷堯藩', '別楊穎士盧克柔殷堯藩', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["倦鳥暮歸林，浮雲晴歸山。","獨有行路子，悠悠不知還。","人生苦營營，終日羣動間。","所務雖不同，同歸於不閑。","扁舟來楚鄉，匹馬往秦關。","離憂繞心曲，宛轉如循環。","且持一杯酒，聊以開愁顏。"]', '["倦鸟暮归林，浮云晴归山。","独有行路子，悠悠不知還。","人生苦營營，終日羣动间。","所務雖不同，同归於不闲。","扁舟来楚乡，匹马往秦关。","離憂繞心曲，宛轉如循环。","且持一杯酒，聊以开愁顏。"]', '诗', 'shi', '', NULL, '別楊穎士盧克柔殷堯藩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('936b0dc4-23d8-4b40-bd1e-1e471248c3f5', '題贈定光上人', '題贈定光上人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["二十身出家，四十心離塵。","得徑入大道，乘此不退輪。","一坐十五年，林下秋復春。","春花與秋氣，不感無情人。","我來如有悟，潛以心照身。","誤落聞見中，憂喜傷形神。","安得遺耳目，冥然反天真。"]', '["二十身出家，四十心離塵。","得徑入大道，乘此不退輪。","一坐十五年，林下秋复春。","春花與秋氣，不感無情人。","我来如有悟，潛以心照身。","誤落闻见中，憂喜傷形神。","安得遺耳目，冥然反天真。"]', '诗', 'shi', '', NULL, '題贈定光上人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a53e45ec-bf42-4a8b-ac28-c346640da045', '祇役駱口驛喜蕭侍御書至兼覩新詩吟諷通宵因寄八韻', '祇役駱口驛喜蕭侍御书至兼覩新诗吟諷通宵因寄八韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日暮心無憀，吏役正營營。","忽驚芳信至，復與新詩幷。","是時天無雲，山館有月明。","月下讀數徧，風前吟一聲。","一吟三四歎，聲盡有餘清。","雅哉君子文，詠性不詠情。","使我靈府中，鄙恡不得生。","始知聽韶濩，可使心和平。"]', '["日暮心無憀，吏役正營營。","忽驚芳信至，复與新诗幷。","是时天無云，山館有月明。","月下读數徧，风前吟一声。","一吟三四歎，声尽有餘清。","雅哉君子文，詠性不詠情。","使我靈府中，鄙恡不得生。","始知听韶濩，可使心和平。"]', '诗', 'shi', '', NULL, '祇役駱口驛喜蕭侍御書至兼覩新詩吟諷通宵因寄八韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12cc58c8-a039-480f-9da6-930f3187643f', '酬李少府曹長官舍見贈', '酬李少府曹长官舍见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["低腰復斂手，心體不遑安。","一落風塵下，方知爲吏難。","公事與日長，宦情隨歲闌。","惆悵青袍袖，芸香無半殘。","賴有李夫子，此懷聊自寬。","兩心如止水，彼此無波瀾。","往往簿書暇，相勸強爲歡。","白馬晚蹋雪，淥觴春暖寒。","戀月夜同宿，愛山晴共看。","野性自相近，不是爲同官。"]', '["低腰复斂手，心體不遑安。","一落风塵下，方知爲吏难。","公事與日长，宦情隨歲闌。","惆悵青袍袖，芸香無半殘。","賴有李夫子，此懷聊自寬。","兩心如止水，彼此無波瀾。","往往簿书暇，相勸強爲歡。","白马晚蹋雪，淥觴春暖寒。","戀月夜同宿，愛山晴共看。","野性自相近，不是爲同官。"]', '诗', 'shi', '', NULL, '酬李少府曹長官舍見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb05abc3-afb4-4db4-bc39-d18d65b8575c', '留別', '留別', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秋涼卷朝簟，春暖撤夜衾。","雖是無情物，欲別尚沈吟。","況與有情別，別隨情淺深。","二年歡笑意，一旦東西心。","獨留誠可念，同行力不任。","前事詎能料，後期諒難尋。","唯有潺湲淚，不惜共霑襟。"]', '["秋涼卷朝簟，春暖撤夜衾。","雖是無情物，欲別尚沈吟。","況與有情別，別隨情淺深。","二年歡笑意，一旦东西心。","独留誠可念，同行力不任。","前事詎能料，後期諒难尋。","唯有潺湲泪，不惜共霑襟。"]', '诗', 'shi', '', NULL, '留別 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('141edffd-4350-4fdc-b4f0-2bc2a19d3917', '曉別', '晓別', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曉鼓聲已半，離筵坐難久。","請君斷腸歌，送我和淚酒。","月落欲明前，馬嘶初別後。","浩浩暗塵中，何由見回首。"]', '["晓鼓声已半，離筵坐难久。","請君斷腸歌，送我和泪酒。","月落欲明前，马嘶初別後。","浩浩暗塵中，何由见回首。"]', '诗', 'shi', '', NULL, '曉別 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('732bc81e-d8f9-4313-a6a8-72d3c556adac', '北園', '北园', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["北園東風起，雜花次第開。","心知須臾落，一日三四來。","花下豈無酒，欲酌復遲迴。","所思眇千里，誰勸我一杯。"]', '["北园东风起，杂花次第开。","心知須臾落，一日三四来。","花下豈無酒，欲酌复遲迴。","所思眇千里，誰勸我一杯。"]', '诗', 'shi', '', NULL, '北園 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8212efc-dbeb-45c7-9480-433e10eefcc3', '惜栯李花', '惜栯李花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["樹小花鮮妍，香繁條輭弱。","高低二三尺，重疊千萬萼。","朝豔藹霏霏，夕凋紛漠漠。","辭枝朱粉細，覆地紅綃薄。","由來好顏色，常苦易銷鑠。","不見莨蕩花，狂風吹不落。"]', '["樹小花鲜妍，香繁條輭弱。","高低二三尺，重叠千万萼。","朝豔藹霏霏，夕凋紛漠漠。","辞枝朱粉細，覆地紅綃薄。","由来好顏色，常苦易銷鑠。","不见莨蕩花，狂风吹不落。"]', '诗', 'shi', '', NULL, '惜栯李花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32438154-b246-43e1-9d94-cf3dbece702b', '照鏡', '照镜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["皎皎青銅鏡，斑斑白絲鬢。","豈復更藏年，實年君不信。"]', '["皎皎青銅镜，斑斑白絲鬢。","豈复更藏年，實年君不信。"]', '诗', 'shi', '', NULL, '照鏡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f269f218-4019-4bd1-89d2-84645352fc6f', '新秋', '新秋', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["西風飄一葉，庭前颯已涼。","風池明月水，衰蓮白露房。","其奈江南夜，緜緜自此長。"]', '["西风飄一葉，庭前颯已涼。","风池明月水，衰蓮白露房。","其奈江南夜，緜緜自此长。"]', '诗', 'shi', '', NULL, '新秋 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6d8b0d3-b2d5-452e-b99a-073be0c949b1', '夜雨', '夜雨', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["早蛩啼復歇，殘燈滅又明。","隔窗知夜雨，芭蕉先有聲。"]', '["早蛩啼复歇，殘灯滅又明。","隔窗知夜雨，芭蕉先有声。"]', '诗', 'shi', '', NULL, '夜雨 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3ae22d8-4ffa-40c0-b27b-d7d4a2a5b9a2', '秋江送客', '秋江送客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秋鴻次第過，哀猨朝夕聞。","是日孤舟客，此地亦離羣。","濛濛潤衣雨，漠漠冒帆雲。","不醉潯陽酒，煙波愁殺人。"]', '["秋鴻次第過，哀猨朝夕闻。","是日孤舟客，此地亦離羣。","濛濛潤衣雨，漠漠冒帆云。","不醉潯陽酒，煙波愁殺人。"]', '诗', 'shi', '', NULL, '秋江送客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ed6624c-c86d-4e4c-aeec-70c4fd40beba', '感逝寄遠', '感逝寄远', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昨日聞甲死，今朝聞乙死。","知識三分中，二分化爲鬼。","逝者不復見，悲哉長已矣。","存者今如何，去我皆萬里。","平生知心者，屈指能有幾。","通果澧鳳州，眇然四君子。","相思俱老大，浮世如流水。","應歎舊交遊，凋零日如此。","何當一杯酒，開眼笑相視。"]', '["昨日闻甲死，今朝闻乙死。","知識三分中，二分化爲鬼。","逝者不复见，悲哉长已矣。","存者今如何，去我皆万里。","平生知心者，屈指能有幾。","通果澧鳳州，眇然四君子。","相思俱老大，浮世如流水。","應歎旧交游，凋零日如此。","何當一杯酒，开眼笑相視。"]', '诗', 'shi', '', NULL, '感逝寄遠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28aa0fb5-842b-451f-9f56-f7139050a820', '秋月', '秋月', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜初色蒼然，夜深光浩然。","稍轉西廊下，漸滿南窗前。","況是綠蕪地，復茲清露天。","落葉聲策策，驚鳥影翩翩。","棲禽尚不穩，愁人安可眠。"]', '["夜初色蒼然，夜深光浩然。","稍轉西廊下，漸满南窗前。","況是綠蕪地，复茲清露天。","落葉声策策，驚鸟影翩翩。","棲禽尚不穩，愁人安可眠。"]', '诗', 'shi', '', NULL, '秋月 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0222bb09-1f03-473b-b3d7-bd41709a2643', '朱陳村', '朱陳村', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["徐州古豐縣，有村曰朱陳。","去縣百餘里，桑麻青氛氳。","機梭聲札札，牛驢走紜紜。","女汲澗中水，男采山上薪。","縣遠官事少，山深人俗淳。","有財不行商，有丁不入軍。","家家守村業，頭白不出門。","生爲村之民，死爲村之塵。","田中老與幼，相見何欣欣。","一村唯兩姓，世世爲婚姻。","親疎居有族，少長游有羣。","黃雞與白酒，歡會不隔旬。","生者不遠別，嫁娶先近鄰。","死者不遠葬，墳墓多繞村。","既安生與死，不苦形與神。","所以多壽考，往往見玄孫。","我生禮義鄉，少小孤且貧。","徒學辨是非，祗自取辛勤。","世法貴名教，士人重冠婚。","以此自桎梏，信爲大謬人。","十歲解讀書，十五能屬文。","二十舉秀才，三十爲諫臣。","下有妻子累，上有君親恩。","承家與事國，望此不肖身。","憶昨旅游初，迨今十五春。","孤舟三適楚，羸馬四經秦。","晝行有飢色，夜寢無安魂。","東西不暫住，來往若浮雲。","離亂失故鄉，骨肉多散分。","江南與江北，各有平生親。","平生終日別，逝者隔年聞。","朝憂臥至暮，夕哭坐達晨。","悲火燒心曲，愁霜侵鬢根。","一生苦如此，長羨村中民。"]', '["徐州古豐縣，有村曰朱陳。","去縣百餘里，桑麻青氛氳。","機梭声札札，牛驢走紜紜。","女汲澗中水，男采山上薪。","縣远官事少，山深人俗淳。","有財不行商，有丁不入軍。","家家守村業，头白不出门。","生爲村之民，死爲村之塵。","田中老與幼，相见何欣欣。","一村唯兩姓，世世爲婚姻。","親疎居有族，少长游有羣。","黄雞與白酒，歡會不隔旬。","生者不远別，嫁娶先近鄰。","死者不远葬，墳墓多繞村。","既安生與死，不苦形與神。","所以多壽考，往往见玄孫。","我生禮義乡，少小孤且貧。","徒学辨是非，祗自取辛勤。","世法貴名教，士人重冠婚。","以此自桎梏，信爲大謬人。","十歲解读书，十五能屬文。","二十舉秀才，三十爲諫臣。","下有妻子累，上有君親恩。","承家與事国，望此不肖身。","憶昨旅游初，迨今十五春。","孤舟三適楚，羸马四經秦。","晝行有飢色，夜寢無安魂。","东西不暫住，来往若浮云。","離亂失故乡，骨肉多散分。","江南與江北，各有平生親。","平生終日別，逝者隔年闻。","朝憂臥至暮，夕哭坐達晨。","悲火燒心曲，愁霜侵鬢根。","一生苦如此，长羨村中民。"]', '诗', 'shi', '', NULL, '朱陳村 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72f3a210-bbcb-475a-893e-e503b0a2b2b3', '讀鄧魴詩', '读鄧魴诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["塵架多文集，偶取一卷披。","未及看姓名，疑是陶潛詩。","看名知是君，惻惻令我悲。","詩人多蹇厄，近日誠有之。","京兆杜子美，猶得一拾遺。","襄陽孟浩然，亦聞鬢成絲。","嗟君兩不如，三十在布衣。","擢第祿不及，新婚妻未歸。","少年無疾患，溘死於路岐。","天不與爵壽，唯與好文詞。","此理勿復道，巧曆不能推。"]', '["塵架多文集，偶取一卷披。","未及看姓名，疑是陶潛诗。","看名知是君，惻惻令我悲。","诗人多蹇厄，近日誠有之。","京兆杜子美，猶得一拾遺。","襄陽孟浩然，亦闻鬢成絲。","嗟君兩不如，三十在布衣。","擢第祿不及，新婚妻未归。","少年無疾患，溘死於路岐。","天不與爵壽，唯與好文词。","此理勿复道，巧曆不能推。"]', '诗', 'shi', '', NULL, '讀鄧魴詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46651f37-51e1-42ac-a715-7cc7b371ad9d', '寄元九', '寄元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晨雞纔發聲，夕雀俄斂翼。","晝夜往復來，疾如出入息。","非徒改年貌，漸覺無心力。","自念因念君，俱爲老所逼。","君年雖校少，顦顇謫南國。","三年不放歸，炎瘴消顏色。","山無殺草霜，水有含沙蜮。","健否遠不知，書多隔年得。","願君少愁苦，我亦加餐食。","各保金石軀，以慰長相憶。"]', '["晨雞纔發声，夕雀俄斂翼。","晝夜往复来，疾如出入息。","非徒改年貌，漸覺無心力。","自念因念君，俱爲老所逼。","君年雖校少，顦顇謫南国。","三年不放归，炎瘴消顏色。","山無殺草霜，水有含沙蜮。","健否远不知，书多隔年得。","願君少愁苦，我亦加餐食。","各保金石軀，以慰长相憶。"]', '诗', 'shi', '', NULL, '寄元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62c92c57-888e-4d8a-89a5-ea71ae667588', '秋夕', '秋夕', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["葉聲落如雨，月色白似霜。","夜深方獨臥，誰爲拂塵牀。"]', '["葉声落如雨，月色白似霜。","夜深方独臥，誰爲拂塵牀。"]', '诗', 'shi', '', NULL, '秋夕 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9d53bcc-3270-4d07-8231-c562f2ac6ab1', '夜雨', '夜雨', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我有所念人，隔在遠遠鄉。","我有所感事，結在深深腸。","鄉遠去不得，無日不瞻望。","腸深解不得，無夕不思量。","況此殘燈夜，獨宿在空堂。","秋天殊未曉，風雨正蒼蒼。","不學頭陀法，前心安可忘。"]', '["我有所念人，隔在远远乡。","我有所感事，結在深深腸。","乡远去不得，無日不瞻望。","腸深解不得，無夕不思量。","況此殘灯夜，独宿在空堂。","秋天殊未晓，风雨正蒼蒼。","不学头陀法，前心安可忘。"]', '诗', 'shi', '', NULL, '夜雨 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('248d9898-55a6-4808-9e38-5efc8f42e577', '秋霽', '秋霽', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["金火不相待，炎涼雨中變。","林晴有殘蟬，巢冷無留燕。","沈吟卷長簟，愴惻收團扇。","向夕稍無泥，閑步青苔院。","月出砧杵動，家家擣秋練。","獨對多病妻，不能理鍼線。","冬衣殊未製，夏服行將綻。","何以迎早秋，一杯聊自勸。"]', '["金火不相待，炎涼雨中变。","林晴有殘蟬，巢冷無留燕。","沈吟卷长簟，愴惻收團扇。","向夕稍無泥，闲步青苔院。","月出砧杵动，家家擣秋練。","独对多病妻，不能理鍼線。","冬衣殊未製，夏服行將綻。","何以迎早秋，一杯聊自勸。"]', '诗', 'shi', '', NULL, '秋霽 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4772819b-32a2-4514-8f90-1361d2357843', '歎老三首 一', '歎老三首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晨興照青鏡，形影兩寂莫。","少年辭我去，白髮隨梳落。","萬化成於漸，漸衰看不覺。","但恐鏡中顏，今朝老於昨。","人年少滿百，不得長歡樂。","誰會天地心，千齡與龜鶴。","吾聞善醫者，今古稱扁鵲。","萬病皆可治，唯無治老藥。"]', '["晨兴照青镜，形影兩寂莫。","少年辞我去，白髮隨梳落。","万化成於漸，漸衰看不覺。","但恐镜中顏，今朝老於昨。","人年少满百，不得长歡乐。","誰會天地心，千齡與龟鹤。","吾闻善醫者，今古稱扁鵲。","万病皆可治，唯無治老藥。"]', '诗', 'shi', '', NULL, '歎老三首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5996c15d-b2f7-4a0c-bb8b-65d4a2825b60', '歎老三首 二', '歎老三首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我有一握髮，梳理何稠直。","昔似玄雲光，今如素絲色。","匣中有舊鏡，欲照先歎息。","自從頭白來，不欲明磨拭。","鵶頭與鶴頸，至老常如墨。","獨有人鬢毛，不得終身黑。"]', '["我有一握髮，梳理何稠直。","昔似玄云光，今如素絲色。","匣中有旧镜，欲照先歎息。","自從头白来，不欲明磨拭。","鵶头與鹤頸，至老常如墨。","独有人鬢毛，不得終身黑。"]', '诗', 'shi', '', NULL, '歎老三首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79801027-bbbc-4b2c-a4c7-b21b6a043b03', '歎老三首 三', '歎老三首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["前年種桃核，今歲成花樹。","去歲新嬰兒，今年已學步。","但驚物長成，不覺身衰暮。","去矣欲何如，少年留不住。","因書今日意，徧寄諸親故。","壯歲不歡娛，長年當悔悟。"]', '["前年種桃核，今歲成花樹。","去歲新嬰兒，今年已学步。","但驚物长成，不覺身衰暮。","去矣欲何如，少年留不住。","因书今日意，徧寄諸親故。","壯歲不歡娛，长年當悔悟。"]', '诗', 'shi', '', NULL, '歎老三首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a41a91c-5796-4fdc-b894-09d5bc60104a', '送兄弟迴雪夜', '送兄弟迴雪夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日晦雲氣黃，東北風切切。","時從村南還，新與兄弟別。","離襟淚猶濕，迴馬嘶未歇。","欲歸一室坐，天陰多無月。","夜長火消盡，歲暮雨凝結。","寂莫滿爐灰，飄零上階雪。","對雪畫寒灰，殘燈明復滅。","灰死如我心，雪白如我髮。","所隅皆如此，頃刻堪愁絕。","迴念入坐忘，轉憂作禪悅。","平生洗心法，正爲今宵設。"]', '["日晦云氣黄，东北风切切。","时從村南還，新與兄弟別。","離襟泪猶濕，迴马嘶未歇。","欲归一室坐，天陰多無月。","夜长火消尽，歲暮雨凝結。","寂莫满爐灰，飄零上階雪。","对雪畫寒灰，殘灯明复滅。","灰死如我心，雪白如我髮。","所隅皆如此，頃刻堪愁絕。","迴念入坐忘，轉憂作禪悅。","平生洗心法，正爲今宵設。"]', '诗', 'shi', '', NULL, '送兄弟迴雪夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3ae4cc8-c812-4a1b-8db1-d288eae16cd8', '溪中早春', '溪中早春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南山雪未盡，陰嶺留殘白。","西澗冰已消，春溜含新碧。","東風來幾日，蟄動萌草坼。","潛知陽和功，一日不虛擲。","愛此天氣暖，來拂溪邊石。","一坐欲忘歸，暮禽聲嘖嘖。","蓬蒿隔桑棗，隱映煙火夕。","歸來問夜餐，家人烹薺麥。"]', '["南山雪未尽，陰嶺留殘白。","西澗冰已消，春溜含新碧。","东风来幾日，蟄动萌草坼。","潛知陽和功，一日不虛擲。","愛此天氣暖，来拂溪邊石。","一坐欲忘归，暮禽声嘖嘖。","蓬蒿隔桑棗，隐映煙火夕。","归来问夜餐，家人烹薺麦。"]', '诗', 'shi', '', NULL, '溪中早春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa1d614a-80fe-45d0-9a71-d45504eb7e2a', '同友人尋澗花', '同友人尋澗花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["聞有澗底花，貰得村中酒。","與君來校遲，已逢搖落後。","臨觴有遺恨，悵望空溪口。","記取花發時，期君重攜手。","我生日日老，春色年年有。","且作來歲期，不知身健否。"]', '["闻有澗底花，貰得村中酒。","與君来校遲，已逢搖落後。","臨觴有遺恨，悵望空溪口。","記取花發时，期君重携手。","我生日日老，春色年年有。","且作来歲期，不知身健否。"]', '诗', 'shi', '', NULL, '同友人尋澗花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f5e9ddd-d31b-4114-876f-4c88e68529df', '登村東古冢', '登村东古冢', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["高低古時冢，上有牛羊道。","獨立最高頭，悠哉此懷抱。","回頭向村望，但見荒田草。","村人不愛花，多種栗與棗。","自來此村住，不覺風光好。","花少鶯亦稀，年年春暗老。"]', '["高低古时冢，上有牛羊道。","独立最高头，悠哉此懷抱。","回头向村望，但见荒田草。","村人不愛花，多種栗與棗。","自来此村住，不覺风光好。","花少鶯亦稀，年年春暗老。"]', '诗', 'shi', '', NULL, '登村東古冢 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25aa730e-feeb-4c76-a53d-a01af05b3e81', '夢裴相公', '梦裴相公', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["五年生死隔，一夕魂夢通。","夢中如往日，同直金鑾宮。","髣髴金紫色，分明冰玉容。","勤勤相眷意，亦與平生同。","既寤知是夢，憫然情未終。","追想當時事，何殊昨夜中。","自我學心法，萬緣成一空。","今朝爲君子，流涕一霑胷。"]', '["五年生死隔，一夕魂梦通。","梦中如往日，同直金鑾宮。","髣髴金紫色，分明冰玉容。","勤勤相眷意，亦與平生同。","既寤知是梦，憫然情未終。","追想當时事，何殊昨夜中。","自我学心法，万緣成一空。","今朝爲君子，流涕一霑胷。"]', '诗', 'shi', '', NULL, '夢裴相公 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8b85263-8da7-44f4-8c86-6b9c14fa722e', '晝寢', '晝寢', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["坐整白單衣，起穿黃草屨。","朝餐盥漱畢，徐下階前步。","暑風微變候，晝刻漸加數。","院靜地陰陰，鳥鳴新葉樹。","獨行還獨臥，夏景殊未暮。","不作午時眠，日長安可度。"]', '["坐整白單衣，起穿黄草屨。","朝餐盥漱畢，徐下階前步。","暑风微变候，晝刻漸加數。","院静地陰陰，鸟鳴新葉樹。","独行還独臥，夏景殊未暮。","不作午时眠，日长安可度。"]', '诗', 'shi', '', NULL, '晝寢 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5fa2ff4-32fd-4d08-8b7b-8b0a9648391b', '別行簡', '別行簡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["漠漠病眼花，星星愁鬢雪。","筋骸已衰憊，形影仍分訣。","梓州二千里，劒門五六月。","豈是遠行時，火雲燒棧熱。","何言巾上淚，乃是腸中血。","念此早歸來，莫作經年別。"]', '["漠漠病眼花，星星愁鬢雪。","筋骸已衰憊，形影仍分訣。","梓州二千里，劒门五六月。","豈是远行时，火云燒棧熱。","何言巾上泪，乃是腸中血。","念此早归来，莫作經年別。"]', '诗', 'shi', '', NULL, '別行簡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ad675c6-429f-4c7f-8206-9dad9eb9bf97', '觀兒戲', '观兒戲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["髫齔七八歲，綺紈三四兒。","弄塵復鬭草，盡日樂嬉嬉。","堂上長年客，鬢間新有絲。","一看竹馬戲，每憶童騃時。","童騃饒戲樂，老大多憂悲。","靜念彼與此，不知誰是癡。"]', '["髫齔七八歲，綺紈三四兒。","弄塵复鬭草，尽日乐嬉嬉。","堂上长年客，鬢间新有絲。","一看竹马戲，每憶童騃时。","童騃饒戲乐，老大多憂悲。","静念彼與此，不知誰是癡。"]', '诗', 'shi', '', NULL, '觀兒戲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55a68da0-d388-41e1-b2bc-bc28d7cb5c90', '歎常生', '歎常生', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["西村常氏子，臥疾不須臾。","前旬猶訪我，今日忽云殂。","時我病多暇，與之同野居。","園林青藹藹，相去數里餘。","村鄰無好客，所遇唯農夫。","之子何如者，往還猶勝無。","於今亦已矣，可爲一長吁。"]', '["西村常氏子，臥疾不須臾。","前旬猶訪我，今日忽云殂。","时我病多暇，與之同野居。","园林青藹藹，相去數里餘。","村鄰無好客，所遇唯農夫。","之子何如者，往還猶勝無。","於今亦已矣，可爲一长吁。"]', '诗', 'shi', '', NULL, '歎常生 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8696f17e-1c98-44c7-aea6-ef1e5d77bc81', '寄元九', '寄元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一病經四年，親朋書信斷。","窮通合易交，自笑知何晚。","元君在荆楚，去日唯云遠。","彼獨是何人，心如石不轉。","憂我貧病身，書來唯勸勉。","上言少愁苦，下道加餐飯。","憐君爲謫吏，窮薄家貧褊。","三寄衣食資，數盈二十萬。","豈是貪衣食，感君心繾綣。","念我口中食，分君身上暖。","不因身病久，不因命多蹇。","平生親友心，豈得知深淺。"]', '["一病經四年，親朋书信斷。","窮通合易交，自笑知何晚。","元君在荆楚，去日唯云远。","彼独是何人，心如石不轉。","憂我貧病身，书来唯勸勉。","上言少愁苦，下道加餐飯。","怜君爲謫吏，窮薄家貧褊。","三寄衣食資，數盈二十万。","豈是貪衣食，感君心繾綣。","念我口中食，分君身上暖。","不因身病久，不因命多蹇。","平生親友心，豈得知深淺。"]', '诗', 'shi', '', NULL, '寄元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59961879-b1b9-4b0a-a135-0eee90d9c6df', '以鏡贈別', '以镜贈別', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人言似明月，我道勝明月。","明月非不明，一年十二缺。","豈如玉匣裏，如水常澄澈。","月破天闇時，圓明獨不歇。","我慙貌醜老，繞鬢斑斑雪。","不如贈少年，迴照青絲髮。","因君千里去，持此將爲別。"]', '["人言似明月，我道勝明月。","明月非不明，一年十二缺。","豈如玉匣裏，如水常澄澈。","月破天闇时，圓明独不歇。","我慙貌醜老，繞鬢斑斑雪。","不如贈少年，迴照青絲髮。","因君千里去，持此將爲別。"]', '诗', 'shi', '', NULL, '以鏡贈別 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c0844ef-7bb9-4f46-905c-cd9ec2397780', '城上對月期友人不至', '城上对月期友人不至', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["古人惜晝短，勸令秉燭遊。","況此迢迢夜，明月滿西樓。","復有盈尊酒，置在城上頭。","期君君不至，人月兩悠悠。","照水煙波白，照人肌髮秋。","清光正如此，不醉即須愁。"]', '["古人惜晝短，勸令秉燭游。","況此迢迢夜，明月满西楼。","复有盈尊酒，置在城上头。","期君君不至，人月兩悠悠。","照水煙波白，照人肌髮秋。","清光正如此，不醉即須愁。"]', '诗', 'shi', '', NULL, '城上對月期友人不至 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b80e5559-aae4-4e73-a4d6-17bac3a5861e', '念金鑾子二首 一', '念金鑾子二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["衰病四十身，嬌癡三歲女。","非男猶勝無，慰情時一撫。","一朝舍我去，魂影無處所。","況念夭札時，嘔啞初學語。","始知骨肉愛，乃是憂悲聚。","唯思未有前，以理遣傷苦。","忘懷日已久，三度移寒暑。","今日一傷心，因逢舊乳母。"]', '["衰病四十身，嬌癡三歲女。","非男猶勝無，慰情时一撫。","一朝舍我去，魂影無处所。","況念夭札时，嘔啞初学語。","始知骨肉愛，乃是憂悲聚。","唯思未有前，以理遣傷苦。","忘懷日已久，三度移寒暑。","今日一傷心，因逢旧乳母。"]', '诗', 'shi', '', NULL, '念金鑾子二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a567bce-4469-4608-9276-3b91502f0677', '念金鑾子二首 二', '念金鑾子二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["與爾爲父子，八十有六旬。","忽然又不見，邇來三四春。","形質本非實，氣聚偶成身。","恩愛元是妄，緣合暫爲親。","念茲庶有悟，聊用遣悲辛。","暫將理自奪，不是忘情人。"]', '["與爾爲父子，八十有六旬。","忽然又不见，邇来三四春。","形質本非實，氣聚偶成身。","恩愛元是妄，緣合暫爲親。","念茲庶有悟，聊用遣悲辛。","暫將理自奪，不是忘情人。"]', '诗', 'shi', '', NULL, '念金鑾子二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9adf761-989e-4bc6-9b8c-c03e721acc7e', '對酒', '对酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人生一百歲，通計三萬日。","何況百歲人，人間百無一。","賢愚共零落，貴賤同埋沒。","東岱前後魂，北邙新舊骨。","復聞藥誤者，爲愛延年術。","又有憂死者，爲貪政事筆。","藥誤不得老，憂死非因疾。","誰言人最靈，知得不知失。","何如會親友，飲此杯中物。","能沃煩慮消，能陶真性出。","所以劉阮輩，終年醉兀兀。"]', '["人生一百歲，通計三万日。","何況百歲人，人间百無一。","賢愚共零落，貴賤同埋沒。","东岱前後魂，北邙新旧骨。","复闻藥誤者，爲愛延年術。","又有憂死者，爲貪政事笔。","藥誤不得老，憂死非因疾。","誰言人最靈，知得不知失。","何如會親友，饮此杯中物。","能沃煩慮消，能陶真性出。","所以劉阮輩，終年醉兀兀。"]', '诗', 'shi', '', NULL, '對酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97001933-f16b-4287-8c28-85289dcddc9f', '渭村雨歸', '渭村雨归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["渭水寒漸落，離離蒲稗苗。","閑傍沙邊立，看人刈葦苕。","近水風景冷，晴明猶寂寥。","復茲夕陰起，野色重蕭條。","蕭條獨歸路，暮雨濕村橋。"]', '["渭水寒漸落，離離蒲稗苗。","闲傍沙邊立，看人刈葦苕。","近水风景冷，晴明猶寂寥。","复茲夕陰起，野色重蕭條。","蕭條独归路，暮雨濕村橋。"]', '诗', 'shi', '', NULL, '渭村雨歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('340df5b6-8d20-43a3-98a7-bb34a042c1e4', '諭懷', '諭懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黑頭日已白，白面日已黑。","人生未死間，變化何終極。","常言在己者，莫若形與色。","一朝改變來，止遏不能得。","況彼身外事，悠悠通與塞。"]', '["黑头日已白，白面日已黑。","人生未死间，变化何終極。","常言在己者，莫若形與色。","一朝改变来，止遏不能得。","況彼身外事，悠悠通與塞。"]', '诗', 'shi', '', NULL, '諭懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e47a5ac3-492a-474c-a0e5-77e8c277ab94', '喜友至留宿', '喜友至留宿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["村中少賓客，柴門多不開。","忽聞車馬至，云是故人來。","況值風雨夕，愁心正悠哉。","願君且同宿，盡此手中杯。","人生開口笑，百年都幾回。"]', '["村中少賓客，柴门多不开。","忽闻车马至，云是故人来。","況值风雨夕，愁心正悠哉。","願君且同宿，尽此手中杯。","人生开口笑，百年都幾回。"]', '诗', 'shi', '', NULL, '喜友至留宿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e72b2f1-222f-4aef-9bc4-edc14a398d2b', '西原晚望', '西原晚望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["花菊引閑行，行上西原路。","原上晚無人，因高聊四顧。","南阡有煙火，北陌連墟墓。","村鄰何蕭疎，近者猶百步。","吾廬在其下，寂莫風日暮。","門外轉枯蓬，籬根伏寒兔。","故園汴水上，離亂不堪去。","近歲始移家，飄然此村住。","新屋五六間，古槐八九樹。","便是衰病身，此生終老處。"]', '["花菊引闲行，行上西原路。","原上晚無人，因高聊四顧。","南阡有煙火，北陌連墟墓。","村鄰何蕭疎，近者猶百步。","吾廬在其下，寂莫风日暮。","门外轉枯蓬，籬根伏寒兔。","故园汴水上，離亂不堪去。","近歲始移家，飄然此村住。","新屋五六间，古槐八九樹。","便是衰病身，此生終老处。"]', '诗', 'shi', '', NULL, '西原晚望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8be600f6-3705-4ab5-8275-d4d00877c84e', '感鏡', '感镜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["美人與我別，留鏡在匣中。","自從花顏去，秋水無芙蓉。","經年不開匣，紅埃覆青銅。","今朝一拂拭，自照顦顇容。","照罷重惆悵，背有雙盤龍。"]', '["美人與我別，留镜在匣中。","自從花顏去，秋水無芙蓉。","經年不开匣，紅埃覆青銅。","今朝一拂拭，自照顦顇容。","照罷重惆悵，背有雙盤龙。"]', '诗', 'shi', '', NULL, '感鏡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66bc5dac-9627-4a9a-bf0b-39d8ab28dcb2', '村居臥病三首 一', '村居臥病三首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["戚戚抱羸病，悠悠度朝暮。","夏木纔結陰，秋蘭已含露。","前日巢中卵，化作雛飛去。","昨日穴中蟲，蛻爲蟬上樹。","四時未嘗歇，一物不暫住。","唯有病客心，沈然獨如故。"]', '["戚戚抱羸病，悠悠度朝暮。","夏木纔結陰，秋蘭已含露。","前日巢中卵，化作雛飞去。","昨日穴中蟲，蛻爲蟬上樹。","四时未嘗歇，一物不暫住。","唯有病客心，沈然独如故。"]', '诗', 'shi', '', NULL, '村居臥病三首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ef928b6-a72b-4b6b-92cb-709e011cac16', '村居臥病三首 二', '村居臥病三首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["新秋久病客，起步村南道。","盡日不逢人，蟲聲徧荒草。","西風吹白露，野綠秋仍早。","草木猶爲傷，先傷我懷抱。","朱顏與玄鬢，強健幾時好。","況爲憂病侵，不得依年老。"]', '["新秋久病客，起步村南道。","尽日不逢人，蟲声徧荒草。","西风吹白露，野綠秋仍早。","草木猶爲傷，先傷我懷抱。","朱顏與玄鬢，強健幾时好。","況爲憂病侵，不得依年老。"]', '诗', 'shi', '', NULL, '村居臥病三首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7ce007e-4803-48e5-b087-7a038484c02d', '村居臥病三首 三', '村居臥病三首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["種黍三十畝，雨來苗漸大。","種薤二十畦，秋來欲堪刈。","望黍作冬酒，留薤爲春菜。","荒村百物無，待此養衰瘵。","葺廬備陰雨，補褐防寒歲。","病身知幾時，且作明年計。"]', '["種黍三十畝，雨来苗漸大。","種薤二十畦，秋来欲堪刈。","望黍作冬酒，留薤爲春菜。","荒村百物無，待此養衰瘵。","葺廬備陰雨，補褐防寒歲。","病身知幾时，且作明年計。"]', '诗', 'shi', '', NULL, '村居臥病三首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b1aa844-eb31-4989-ba2e-6d14e9d57c23', '沐浴', '沐浴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["經年不沐浴，塵垢滿肌膚。","今朝一澡濯，衰瘦頗有餘。","老色頭鬢白，病形支體虛。","衣寬有賸帶，髮少不勝梳。","自問今年歲，春秋四十初。","四十已如此，七十復何如。"]', '["經年不沐浴，塵垢满肌膚。","今朝一澡濯，衰瘦頗有餘。","老色头鬢白，病形支體虛。","衣寬有賸带，髮少不勝梳。","自问今年歲，春秋四十初。","四十已如此，七十复何如。"]', '诗', 'shi', '', NULL, '沐浴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8b7495f-8244-4182-b1cd-264e5bcf4e15', '栽松二首 一', '栽松二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小松未盈尺，心愛手自移。","蒼然澗底色，雲濕煙霏霏。","栽植我年晚，長成君性遲。","如何過四十，種此數寸枝。","得見成陰否，人生七十稀。"]', '["小松未盈尺，心愛手自移。","蒼然澗底色，云濕煙霏霏。","栽植我年晚，长成君性遲。","如何過四十，種此數寸枝。","得见成陰否，人生七十稀。"]', '诗', 'shi', '', NULL, '栽松二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe4b141c-4a95-452b-af67-743ab26378dc', '栽松二首 二', '栽松二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["愛君抱晚節，憐君含直文。","欲得朝朝見，階前故種君。","知君死則已，不死會凌雲。"]', '["愛君抱晚節，怜君含直文。","欲得朝朝见，階前故種君。","知君死則已，不死會凌云。"]', '诗', 'shi', '', NULL, '栽松二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccfd07df-3beb-43b8-bec7-945cca87118c', '病中友人相訪', '病中友人相訪', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["臥久不記日，南窗昏復昏。","蕭條草檐下，寒雀朝夕聞。","強扶牀前杖，起向庭中行。","偶逢故人至，便當一逢迎。","移榻就斜日，披裘倚前楹。","閑談勝服藥，稍覺有心情。"]', '["臥久不記日，南窗昏复昏。","蕭條草檐下，寒雀朝夕闻。","強扶牀前杖，起向庭中行。","偶逢故人至，便當一逢迎。","移榻就斜日，披裘倚前楹。","闲談勝服藥，稍覺有心情。"]', '诗', 'shi', '', NULL, '病中友人相訪 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0140c146-0252-485e-a8d3-fc3e41b1d774', '自覺二首 一', '自覺二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["四十未爲老，憂傷早衰惡。","前歲二毛生，今年一齒落。","形骸日損耗，心事同蕭索。","夜寢與朝餐，其間味亦薄。","同歲崔舍人，容光方灼灼。","始知年與貌，衰盛隨憂樂。","畏老老轉迫，憂病病彌縛。","不畏復不憂，是除老病藥。"]', '["四十未爲老，憂傷早衰惡。","前歲二毛生，今年一齒落。","形骸日損耗，心事同蕭索。","夜寢與朝餐，其间味亦薄。","同歲崔舍人，容光方灼灼。","始知年與貌，衰盛隨憂乐。","畏老老轉迫，憂病病彌縛。","不畏复不憂，是除老病藥。"]', '诗', 'shi', '', NULL, '自覺二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('233f44a6-9083-4777-980f-480bc30cafb1', '自覺二首 二', '自覺二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝哭心所愛，暮哭心所親。","親愛零落盡，安用身獨存。","幾許平生歡，無限骨肉恩。","結爲腸間痛，聚作鼻頭辛。","悲來四支緩，泣盡雙眸昏。","所以年四十，心如七十人。","我聞浮屠教，中有解脫門。","置心爲止水，視身如浮雲。","斗擻垢穢衣，度脫生死輪。","胡爲戀此苦，不去猶逡巡。","迴念發弘願，願此見在身。","但受過去報，不結將來因。","誓以智慧水，永洗煩惱塵。","不將恩愛子，更種悲憂根。"]', '["朝哭心所愛，暮哭心所親。","親愛零落尽，安用身独存。","幾許平生歡，無限骨肉恩。","結爲腸间痛，聚作鼻头辛。","悲来四支緩，泣尽雙眸昏。","所以年四十，心如七十人。","我闻浮屠教，中有解脫门。","置心爲止水，視身如浮云。","斗擻垢穢衣，度脫生死輪。","胡爲戀此苦，不去猶逡巡。","迴念發弘願，願此见在身。","但受過去報，不結將来因。","誓以智慧水，永洗煩惱塵。","不將恩愛子，更種悲憂根。"]', '诗', 'shi', '', NULL, '自覺二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a648b50-fe29-43e2-9fba-773a0f8ee498', '夜雨有念', '夜雨有念', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["以道治心氣，終歲得晏然。","何乃戚戚意，忽來風雨天。","既非慕榮顯，又不恤飢寒。","胡爲悄不樂，抱膝殘燈前。","形影闇相問，心默對以言。","骨肉能幾人，各在天一端。","吾兄寄宿州，吾弟客東川。","南北五千里，吾身在中間。","欲去病未能，欲住心不安。","有如波上舟，此縛而彼牽。","自我向道來，於今六七年。","鍊成不二性，消盡千萬緣。","唯有恩愛火，往往猶熬煎。","豈是藥無効，病多難盡蠲。"]', '["以道治心氣，終歲得晏然。","何乃戚戚意，忽来风雨天。","既非慕榮显，又不恤飢寒。","胡爲悄不乐，抱膝殘灯前。","形影闇相问，心默对以言。","骨肉能幾人，各在天一端。","吾兄寄宿州，吾弟客东川。","南北五千里，吾身在中间。","欲去病未能，欲住心不安。","有如波上舟，此縛而彼牽。","自我向道来，於今六七年。","鍊成不二性，消尽千万緣。","唯有恩愛火，往往猶熬煎。","豈是藥無効，病多难尽蠲。"]', '诗', 'shi', '', NULL, '夜雨有念 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c9550da-c246-44cf-ab2d-2433ccc1a379', '寄楊六', '寄楊六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["青宮官冷靜，赤縣事繁劇。","一閑復一忙，動作經時隔。","清觴久廢酌，白日頓虛擲。","念此忽踟躕，悄然心不適。","豈無舊交結，久別或遷易。","亦有新往還，相見多形迹。","唯君於我分，堅久如金石。","何況老大來，人情重姻戚。","會稀歲月急，此事真可惜。","幾回開口笑，便到髭鬚白。","公門苦鞅掌，盡日無閑隙。","猶冀乘暝來，靜言同一夕。"]', '["青宮官冷静，赤縣事繁劇。","一闲复一忙，动作經时隔。","清觴久廢酌，白日頓虛擲。","念此忽踟躕，悄然心不適。","豈無旧交結，久別或遷易。","亦有新往還，相见多形迹。","唯君於我分，堅久如金石。","何況老大来，人情重姻戚。","會稀歲月急，此事真可惜。","幾回开口笑，便到髭鬚白。","公门苦鞅掌，尽日無闲隙。","猶冀乘暝来，静言同一夕。"]', '诗', 'shi', '', NULL, '寄楊六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b868d49c-b4e7-4ef0-989c-97dfc95a9262', '送春', '送春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三月三十日，春歸日復暮。","惆悵問春風，明朝應不住。","送春曲江上，眷眷東西顧。","但見撲水花，紛紛不知數。","人生似行客，兩足無停步。","日日進前程，前程幾多路。","兵刀與水火，盡可違之去。","唯有老到來，人間無避處。","感時良爲已，獨倚池南樹。","今日送春心，心如別親故。"]', '["三月三十日，春归日复暮。","惆悵问春风，明朝應不住。","送春曲江上，眷眷东西顧。","但见撲水花，紛紛不知數。","人生似行客，兩足無停步。","日日進前程，前程幾多路。","兵刀與水火，尽可違之去。","唯有老到来，人间無避处。","感时良爲已，独倚池南樹。","今日送春心，心如別親故。"]', '诗', 'shi', '', NULL, '送春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7d2b816-02aa-441b-aa10-0f9ae1cb001a', '哭李三', '哭李三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["去年渭水曲，秋時訪我來。","今年常樂里，春日哭君迴。","哭君仰問天，天意安在哉。","若必奪其壽，何如不與才。","落然身後事，妻病女嬰孩。"]', '["去年渭水曲，秋时訪我来。","今年常乐里，春日哭君迴。","哭君仰问天，天意安在哉。","若必奪其壽，何如不與才。","落然身後事，妻病女嬰孩。"]', '诗', 'shi', '', NULL, '哭李三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18f47afa-c6d7-474b-a31e-530e4be0b123', '別李十一後重寄', '別李十一後重寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秋日正蕭條，驅車出蓬蓽。","回望青門道，目極心鬱鬱。","豈獨戀鄉土，非關慕簪紱。","所愴別李君，平生同道術。","俱承金馬詔，聯秉諫臣筆。","共上青雲梯，中途一相失。","江湖我方往，朝廷君不出。","蕙帶與華簪，相逢是何日。"]', '["秋日正蕭條，驱车出蓬蓽。","回望青门道，目極心鬱鬱。","豈独戀乡土，非关慕簪紱。","所愴別李君，平生同道術。","俱承金马詔，聯秉諫臣笔。","共上青云梯，中途一相失。","江湖我方往，朝廷君不出。","蕙带與华簪，相逢是何日。"]', '诗', 'shi', '', NULL, '別李十一後重寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1dc6a8f-3f1d-474c-a890-db56f552175f', '初出藍田路作', '初出藍田路作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["停驂問前路，路在秋雲裏。","蒼蒼縣南道，去途從此始。","絕頂忽上盤，衆山皆下視。","下視千萬峰，峰頭如浪起。","朝經韓公坡，夕次藍橋水。","潯陽近四千，始行七十里。","人煩馬蹄跙，勞苦已如此。"]', '["停驂问前路，路在秋云裏。","蒼蒼縣南道，去途從此始。","絕頂忽上盤，衆山皆下視。","下視千万峰，峰头如浪起。","朝經韓公坡，夕次藍橋水。","潯陽近四千，始行七十里。","人煩马蹄跙，勞苦已如此。"]', '诗', 'shi', '', NULL, '初出藍田路作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('048aa681-6d9e-46e7-8c33-e3079b829bfc', '仙娥峰下作', '仙娥峰下作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我爲東南行，始登商山道。","商山無數峰，最愛仙娥好。","參差樹若插，匼匝雲如抱。","渴望寒玉泉，香聞紫芝草。","青崖屏削碧，白石牀鋪縞。","向無如此物，安足留四皓。","感彼私自問，歸山何不早？","可能塵土中，還隨衆人老。"]', '["我爲东南行，始登商山道。","商山無數峰，最愛仙娥好。","參差樹若插，匼匝云如抱。","渴望寒玉泉，香闻紫芝草。","青崖屏削碧，白石牀鋪縞。","向無如此物，安足留四皓。","感彼私自问，归山何不早？","可能塵土中，還隨衆人老。"]', '诗', 'shi', '', NULL, '仙娥峰下作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09cc086c-f5d8-4a81-bcf8-b5e0409102bd', '微雨夜行', '微雨夜行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["漠漠秋雲起，稍稍夜寒生。","但覺衣裳濕，無點亦無聲。"]', '["漠漠秋云起，稍稍夜寒生。","但覺衣裳濕，無点亦無声。"]', '诗', 'shi', '', NULL, '微雨夜行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b71596a-461e-42f8-8b3b-3e008a47ba11', '再到襄陽訪問舊居', '再到襄陽訪问旧居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昔到襄陽日，髯髯初有髭。","今過襄陽日，髭鬢半成絲。","舊遊都是夢，乍到忽如歸。","東郭蓬蒿宅，荒涼今屬誰。","故知多零落，閭井亦遷移。","獨有秋江水，煙波似舊時。"]', '["昔到襄陽日，髯髯初有髭。","今過襄陽日，髭鬢半成絲。","旧游都是梦，乍到忽如归。","东郭蓬蒿宅，荒涼今屬誰。","故知多零落，閭井亦遷移。","独有秋江水，煙波似旧时。"]', '诗', 'shi', '', NULL, '再到襄陽訪問舊居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a07b860-b2a9-400a-bd64-6ae984238e8e', '寄微之三首 一', '寄微之三首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江州望通州，天涯與地末。","有山萬丈高，有江千里闊。","間之以雲霧，飛鳥不可越。","誰知千古險，爲我二人設。","通州君初到，鬱鬱愁如結。","江州我方去，迢迢行未歇。","道路日乖隔，音信日斷絕。","因風欲寄語，地遠聲不徹。","生當復相逢，死當從此別。"]', '["江州望通州，天涯與地末。","有山万丈高，有江千里闊。","间之以云霧，飞鸟不可越。","誰知千古險，爲我二人設。","通州君初到，鬱鬱愁如結。","江州我方去，迢迢行未歇。","道路日乖隔，音信日斷絕。","因风欲寄語，地远声不徹。","生當复相逢，死當從此別。"]', '诗', 'shi', '', NULL, '寄微之三首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4a0f93e-d434-4637-a68d-36c810f7c7b5', '寄微之三首 二', '寄微之三首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["君遊襄陽日，我在長安住。","今君在通州，我過襄陽去。","襄陽九里郭，樓堞連雲樹。","顧此稍依依，是君舊遊處。","蒼茫蒹葭水，中有潯陽路。","此去更相思，江西少親故。"]', '["君游襄陽日，我在长安住。","今君在通州，我過襄陽去。","襄陽九里郭，楼堞連云樹。","顧此稍依依，是君旧游处。","蒼茫蒹葭水，中有潯陽路。","此去更相思，江西少親故。"]', '诗', 'shi', '', NULL, '寄微之三首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7501b5d9-3970-4e2d-9bed-ffc62ecf8fa2', '寄微之三首 三', '寄微之三首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["去國日已遠，喜逢物似人。","如何含此意，江上坐思君。","有如河嶽氣，相合方氛氳。","狂風吹中絕，兩處成孤雲。","風迴終有時，雲合豈無因。","努力各自愛，窮通我爾身。"]', '["去国日已远，喜逢物似人。","如何含此意，江上坐思君。","有如河嶽氣，相合方氛氳。","狂风吹中絕，兩处成孤云。","风迴終有时，云合豈無因。","努力各自愛，窮通我爾身。"]', '诗', 'shi', '', NULL, '寄微之三首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cda6a5a-7b3a-48d9-9b33-5c94a08addbd', '舟中雨夜', '舟中雨夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江雲闇悠悠，江風冷修修。","夜雨滴船背，風浪打船頭。","船中有病客，左降向江州。"]', '["江云闇悠悠，江风冷修修。","夜雨滴船背，风浪打船头。","船中有病客，左降向江州。"]', '诗', 'shi', '', NULL, '舟中雨夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddc5d190-b8ce-4fea-8688-c8207f1dd0a3', '夜聞歌者', '夜闻歌者', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜泊鸚鵡洲，江月秋澄澈。","鄰船有歌者，發詞堪愁絕。","歌罷繼以泣，泣聲通復咽。","尋聲見其人，有婦顏如雪。","獨倚帆檣立，娉婷十七八。","夜淚如真珠，雙雙墮明月。","借問誰家婦，歌泣何淒切。","一問一霑襟，低眉終不說。"]', '["夜泊鸚鵡洲，江月秋澄澈。","鄰船有歌者，發词堪愁絕。","歌罷繼以泣，泣声通复咽。","尋声见其人，有婦顏如雪。","独倚帆檣立，娉婷十七八。","夜泪如真珠，雙雙墮明月。","借问誰家婦，歌泣何淒切。","一问一霑襟，低眉終不说。"]', '诗', 'shi', '', NULL, '夜聞歌者 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0246b2be-ab19-4063-9447-b6658308e987', '江樓聞砧', '江楼闻砧', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江人授衣晚，十月始聞砧。","一夕高樓月，萬里故園心。"]', '["江人授衣晚，十月始闻砧。","一夕高楼月，万里故园心。"]', '诗', 'shi', '', NULL, '江樓聞砧 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('837bb26f-fb51-410f-8450-1d8585163e7b', '宿東林寺', '宿东林寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["經窗燈燄短，僧爐火氣深。","索落廬山夜，風雪宿東林。"]', '["經窗灯燄短，僧爐火氣深。","索落廬山夜，风雪宿东林。"]', '诗', 'shi', '', NULL, '宿東林寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6ff9ad0-43ff-4ebc-97f8-329f854a396a', '憶洛下故園', '憶洛下故园', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["潯陽遷謫地，洛陽離亂年。","煙塵三川上，炎瘴九江邊。","鄉心坐如此，秋風仍颯然。"]', '["潯陽遷謫地，洛陽離亂年。","煙塵三川上，炎瘴九江邊。","乡心坐如此，秋风仍颯然。"]', '诗', 'shi', '', NULL, '憶洛下故園 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('289051f2-c5ae-4d15-a8ad-af047135eafe', '贈別崔五', '贈別崔五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝送南去客，暮迎北來賓。","孰云當大路，少遇心所親。","勞者念息肩，熱者思濯身。","何如愁獨日，忽見平生人。","平生已不淺，是日重殷勤。","問從何處來，及此江亭春。","江天春多陰，夜月隔重雲。","移尊樹間飲，燈照花紛紛。","一會不易得，餘事何足云。","明旦又分手，今夕且歡忻。"]', '["朝送南去客，暮迎北来賓。","孰云當大路，少遇心所親。","勞者念息肩，熱者思濯身。","何如愁独日，忽见平生人。","平生已不淺，是日重殷勤。","问從何处来，及此江亭春。","江天春多陰，夜月隔重云。","移尊樹间饮，灯照花紛紛。","一會不易得，餘事何足云。","明旦又分手，今夕且歡忻。"]', '诗', 'shi', '', NULL, '贈別崔五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c284fc26-a0d0-4613-8098-ab3902dd42f5', '春晚寄微之', '春晚寄微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三月江水闊，悠悠桃花波。","年芳與心事，此地共蹉跎。","南國方譴謫，中原正兵戈。","眼前故人少，頭上白髮多。","通州更迢遰，春盡復如何。"]', '["三月江水闊，悠悠桃花波。","年芳與心事，此地共蹉跎。","南国方譴謫，中原正兵戈。","眼前故人少，头上白髮多。","通州更迢遰，春尽复如何。"]', '诗', 'shi', '', NULL, '春晚寄微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4141d0b8-ba8d-47ce-9557-f67a2c96f247', '漸老', '漸老', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今朝復明日，不覺年齒暮。","白髮逐梳落，朱顏辭鏡去。","當春頗愁寂，對酒寡歡趣。","遇境多愴辛，逢人益敦故。","形質屬天地，推遷從不住。"]', '["今朝复明日，不覺年齒暮。","白髮逐梳落，朱顏辞镜去。","當春頗愁寂，对酒寡歡趣。","遇境多愴辛，逢人益敦故。","形質屬天地，推遷從不住。"]', '诗', 'shi', '', NULL, '漸老 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('816b18c2-ded2-498f-b2ec-e38c089fe2a1', '送幼史', '送幼史', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["淮右寇未散，江西歲再徂。","故里干戈地，行人風雪途。","此時與爾別，江畔立踟躕。"]', '["淮右寇未散，江西歲再徂。","故里干戈地，行人风雪途。","此时與爾別，江畔立踟躕。"]', '诗', 'shi', '', NULL, '送幼史 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1b24e4f-f54b-492d-b36e-32c4657e90eb', '夜雪', '夜雪', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["已訝衾枕冷，復見窗戶明。","夜深知雪重，時聞折竹聲。"]', '["已訝衾枕冷，复见窗戶明。","夜深知雪重，时闻折竹声。"]', '诗', 'shi', '', NULL, '夜雪 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56cd2868-9a01-4826-951e-c8a8dc6c167f', '寄行簡', '寄行簡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鬱鬱眉多斂，默默口寡言。","豈是願如此，舉目誰與歡。","去春爾西征，從事巴蜀間。","今春我南謫，抱疾江海壖。","相去六千里，地絕天邈然。","十書九不達，何以開憂顏。","渴人多夢飲，飢人多夢餐。","春來夢何處，合眼到東川。"]', '["鬱鬱眉多斂，默默口寡言。","豈是願如此，舉目誰與歡。","去春爾西征，從事巴蜀间。","今春我南謫，抱疾江海壖。","相去六千里，地絕天邈然。","十书九不達，何以开憂顏。","渴人多梦饮，飢人多梦餐。","春来梦何处，合眼到东川。"]', '诗', 'shi', '', NULL, '寄行簡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4abf0c4a-d492-4dc2-a274-77ce17def74e', '首夏', '首夏', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["孟夏百物滋，動植一時好。","麋鹿樂深林，蟲蛇喜豐草。","翔禽愛密葉，游鱗悅新藻。","天和遺漏處，而我獨枯槁。","一身在天末，骨肉皆遠道。","舊國無來人，寇戎塵浩浩。","沈憂竟何益，祗自勞懷抱。","不如放身心，冥然任天造。","潯陽多美酒，可使杯不燥。","湓魚賤如泥，烹炙無昏早。","朝飯山下寺，暮醉湖中島。","何必歸故鄉，茲焉可終老。"]', '["孟夏百物滋，动植一时好。","麋鹿乐深林，蟲蛇喜豐草。","翔禽愛密葉，游鱗悅新藻。","天和遺漏处，而我独枯槁。","一身在天末，骨肉皆远道。","旧国無来人，寇戎塵浩浩。","沈憂竟何益，祗自勞懷抱。","不如放身心，冥然任天造。","潯陽多美酒，可使杯不燥。","湓鱼賤如泥，烹炙無昏早。","朝飯山下寺，暮醉湖中島。","何必归故乡，茲焉可終老。"]', '诗', 'shi', '', NULL, '首夏 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26c15679-c698-4827-8a23-1592a0840196', '孟夏思渭村舊居寄舍弟', '孟夏思渭村旧居寄舍弟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["嘖嘖雀引雛，稍稍筍成竹。","時物感人情，憶我故鄉曲。","故園渭水上，十載事樵牧。","手種榆柳成，陰陰覆牆屋。","兔隱豆苗肥，鳥鳴桑椹熟。","前年當此時，與爾同遊矚。","詩書課弟姪，農圃資童僕。","日暮麥登場，天晴蠶坼簇。","弄泉南澗坐，待月東亭宿。","興發飲數杯，悶來棊一局。","一朝忽分散，萬里仍羈束。","井鮒思反泉，籠鶯悔出谷。","九江地卑濕，四月天炎燠。","苦雨初入梅，瘴雲稍含毒。","泥秧水畦稻，灰種畬田粟。","已訝殊歲時，仍嗟異風俗。","閑登郡樓望，日落江山綠。","歸雁拂鄉心，平湖斷人目。","殊方我漂泊，舊里君幽獨。","何時同一瓢，飲水心亦足。"]', '["嘖嘖雀引雛，稍稍筍成竹。","时物感人情，憶我故乡曲。","故园渭水上，十載事樵牧。","手種榆柳成，陰陰覆牆屋。","兔隐豆苗肥，鸟鳴桑椹熟。","前年當此时，與爾同游矚。","诗书課弟姪，農圃資童僕。","日暮麦登場，天晴蠶坼簇。","弄泉南澗坐，待月东亭宿。","兴發饮數杯，悶来棊一局。","一朝忽分散，万里仍羈束。","井鮒思反泉，籠鶯悔出谷。","九江地卑濕，四月天炎燠。","苦雨初入梅，瘴云稍含毒。","泥秧水畦稻，灰種畬田粟。","已訝殊歲时，仍嗟異风俗。","闲登郡楼望，日落江山綠。","归雁拂乡心，平湖斷人目。","殊方我漂泊，旧里君幽独。","何时同一瓢，饮水心亦足。"]', '诗', 'shi', '', NULL, '孟夏思渭村舊居寄舍弟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14ccf041-ae0f-489d-90fa-5ea184a7d8a2', '早蟬', '早蟬', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["六月初七日，江頭蟬始鳴。","石楠深葉裏，薄暮兩三聲。","一催衰鬢色，再動故園情。","西風殊未起，秋思先秋生。","憶昔在東掖，宮槐花下聽。","今朝無限思，雲樹繞湓城。"]', '["六月初七日，江头蟬始鳴。","石楠深葉裏，薄暮兩三声。","一催衰鬢色，再动故园情。","西风殊未起，秋思先秋生。","憶昔在东掖，宮槐花下听。","今朝無限思，云樹繞湓城。"]', '诗', 'shi', '', NULL, '早蟬 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('287580ab-9187-4aec-ba10-33a7cd5f2826', '感情', '感情', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["中庭曬服玩，忽見故鄉履。","昔贈我者誰，東鄰嬋娟子。","因思贈時語，特用結終始。","永願如履綦，雙行復雙止。","自吾謫江郡，漂蕩三千里。","爲感長情人，提攜同到此。","今朝一惆悵，反覆看未已。","人隻履猶雙，何曾得相似。","可嗟復可惜，錦表繡爲裏。","況經梅雨來，色黯花草死。"]', '["中庭曬服玩，忽见故乡履。","昔贈我者誰，东鄰嬋娟子。","因思贈时語，特用結終始。","永願如履綦，雙行复雙止。","自吾謫江郡，漂蕩三千里。","爲感长情人，提携同到此。","今朝一惆悵，反覆看未已。","人隻履猶雙，何曾得相似。","可嗟复可惜，錦表繡爲裏。","況經梅雨来，色黯花草死。"]', '诗', 'shi', '', NULL, '感情 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('842ff974-8346-4805-ad5b-ebec93d13f5f', '南湖晚秋', '南湖晚秋', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["八月白露降，湖中水方老。","旦夕秋風多，衰荷半傾倒。","手攀青楓樹，足蹋黃蘆草。","慘澹老容顏，冷落秋懷抱。","有兄在淮楚，有弟在蜀道。","萬里何時來，煙波白浩浩。"]', '["八月白露降，湖中水方老。","旦夕秋风多，衰荷半傾倒。","手攀青楓樹，足蹋黄蘆草。","慘澹老容顏，冷落秋懷抱。","有兄在淮楚，有弟在蜀道。","万里何时来，煙波白浩浩。"]', '诗', 'shi', '', NULL, '南湖晚秋 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('787e94dc-b15a-42be-b2e8-a2e0b970481c', '郡廳有樹晚榮早凋人不識名因題其上', '郡廳有樹晚榮早凋人不識名因題其上', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["潯陽郡廳後，有樹不知名。","秋先梧桐落，春後桃李榮。","五月始萌動，八月已凋零。","左右皆松桂，四時鬱青青。","豈量雨露恩，霑濡不均平。","榮枯各有分，天地本無情。","顧我亦相類，早衰向晚成。","形骸少多病，三十不豐盈。","毛鬢早改變，四十白髭生。","誰教兩蕭索，相對此江城。"]', '["潯陽郡廳後，有樹不知名。","秋先梧桐落，春後桃李榮。","五月始萌动，八月已凋零。","左右皆松桂，四时鬱青青。","豈量雨露恩，霑濡不均平。","榮枯各有分，天地本無情。","顧我亦相類，早衰向晚成。","形骸少多病，三十不豐盈。","毛鬢早改变，四十白髭生。","誰教兩蕭索，相对此江城。"]', '诗', 'shi', '', NULL, '郡廳有樹晚榮早凋人不識名因題其上 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b250a95-0bf8-4672-a0d8-378158b9cd91', '感秋懷微之', '感秋懷微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["葉下湖又波，秋風此時至。","誰知濩落心，先納蕭條氣。","推移感流歲，漂泊思同志。","昔爲煙霄侶，今作泥塗吏。","白鷗毛羽弱，青鳳文章異。","各閉一籠中，歲晚同顦顇。"]', '["葉下湖又波，秋风此时至。","誰知濩落心，先納蕭條氣。","推移感流歲，漂泊思同志。","昔爲煙霄侶，今作泥塗吏。","白鷗毛羽弱，青鳳文章異。","各閉一籠中，歲晚同顦顇。"]', '诗', 'shi', '', NULL, '感秋懷微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adc7d652-54ba-4845-9d3c-ffe81ad2174f', '因沐感髮寄朗上人二首 一', '因沐感髮寄朗上人二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["年長身轉慵，百事無所欲。","乃至頭上髮，經年方一沐。","沐稀髮苦落，一沐仍半禿。","短鬢經霜蓬，老面辭春木。","強年過猶近，衰相來何速。","應是煩惱多，心焦血不足。"]', '["年长身轉慵，百事無所欲。","乃至头上髮，經年方一沐。","沐稀髮苦落，一沐仍半禿。","短鬢經霜蓬，老面辞春木。","強年過猶近，衰相来何速。","應是煩惱多，心焦血不足。"]', '诗', 'shi', '', NULL, '因沐感髮寄朗上人二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf647d2d-712a-48a0-903b-edb59b12bbb3', '因沐感髮寄朗上人二首 二', '因沐感髮寄朗上人二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["漸少不滿把，漸短不盈尺。","況茲短少中，日夜落復白。","既無神仙術，何除老死籍。","祗有解脫門，能度衰苦厄。","掩鏡望東寺，降心謝禪客。","衰白何足言，剃落猶不惜。"]', '["漸少不满把，漸短不盈尺。","況茲短少中，日夜落复白。","既無神仙術，何除老死籍。","祗有解脫门，能度衰苦厄。","掩镜望东寺，降心謝禪客。","衰白何足言，剃落猶不惜。"]', '诗', 'shi', '', NULL, '因沐感髮寄朗上人二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('278b7df6-83fe-49f6-8447-1790ec5da2c0', '早蟬', '早蟬', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["月出先照山，風生先動水。","亦如早蟬聲，先入閑人耳。","一聞愁意結，再聽鄉心起。","渭上新蟬聲，先聽渾相似。","衡門有誰聽，日暮槐花裏。"]', '["月出先照山，风生先动水。","亦如早蟬声，先入闲人耳。","一闻愁意結，再听乡心起。","渭上新蟬声，先听渾相似。","衡门有誰听，日暮槐花裏。"]', '诗', 'shi', '', NULL, '早蟬 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('377c55a5-da60-42c1-9b58-ab5617744186', '苦熱喜涼', '苦熱喜涼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["經時苦炎暑，心體但煩倦。","白日一何長，清秋不可見。","歲功成者去，天數極則變。","潛知寒燠間，遷次如乘傳。","火雲忽朝斂，金風俄夕扇。","枕簟遂清涼，筋骸稍輕健。","因思望月侶，好卜迎秋宴。","竟夜無客來，引杯還自勸。"]', '["經时苦炎暑，心體但煩倦。","白日一何长，清秋不可见。","歲功成者去，天數極則变。","潛知寒燠间，遷次如乘傳。","火云忽朝斂，金风俄夕扇。","枕簟遂清涼，筋骸稍轻健。","因思望月侶，好卜迎秋宴。","竟夜無客来，引杯還自勸。"]', '诗', 'shi', '', NULL, '苦熱喜涼 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e96bfb7-5878-406d-ba70-f87ad0730c09', '早秋晚望兼呈韋侍郎', '早秋晚望兼呈韋侍郎', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["九派繞孤城，城高生遠思。","人煙半在船，野水多於地。","穿霞日脚直，驅雁風頭利。","去國來幾時，江上秋三至。","夫君亦淪落，此地同飄寄。","憫默向隅心，摧頹觸籠翅。","且謀眼前計，莫問胸中事。","潯陽酒甚濃，相勸時時醉。"]', '["九派繞孤城，城高生远思。","人煙半在船，野水多於地。","穿霞日脚直，驱雁风头利。","去国来幾时，江上秋三至。","夫君亦淪落，此地同飄寄。","憫默向隅心，摧頹觸籠翅。","且謀眼前計，莫问胸中事。","潯陽酒甚濃，相勸时时醉。"]', '诗', 'shi', '', NULL, '早秋晚望兼呈韋侍郎 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98672314-fd63-4678-bfab-8acbbb0e3a66', '司馬宅', '司马宅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雨徑綠蕪合，霜園紅葉多。","蕭條司馬宅，門巷無人過。","唯對大江水，秋風朝夕波。"]', '["雨徑綠蕪合，霜园紅葉多。","蕭條司马宅，门巷無人過。","唯对大江水，秋风朝夕波。"]', '诗', 'shi', '', NULL, '司馬宅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b0e069d-fa3c-4934-9543-661d17d857a2', '司馬廳獨宿', '司马廳独宿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["荒涼滿庭草，偃亞侵檐竹。","府吏下廳簾，家僮開被襆。","數聲城上漏，一點窗間燭。","官曹冷似冰，誰肯來同宿。"]', '["荒涼满庭草，偃亞侵檐竹。","府吏下廳簾，家僮开被襆。","數声城上漏，一点窗间燭。","官曹冷似冰，誰肯来同宿。"]', '诗', 'shi', '', NULL, '司馬廳獨宿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('967dc2ba-b92a-47ea-9cd1-3b414e6b0c66', '夢與李七庾三十三同訪元九', '梦與李七庾三十三同訪元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜夢歸長安，見我故親友。","損之在我左，順之在我右。","云是二月天，春風出攜手。","同過靖安里，下馬尋元九。","元九正獨坐，見我笑開口。","還指西院花，仍開北亭酒。","如言各有故，似惜歡難久。","神合俄頃間，神離欠伸後。","覺來疑在側，求索無所有。","殘燈影閃牆，斜月光穿牖。","天明西北望，萬里君知否。","老去無見期，踟躕搔白首。"]', '["夜梦归长安，见我故親友。","損之在我左，順之在我右。","云是二月天，春风出携手。","同過靖安里，下马尋元九。","元九正独坐，见我笑开口。","還指西院花，仍开北亭酒。","如言各有故，似惜歡难久。","神合俄頃间，神離欠伸後。","覺来疑在側，求索無所有。","殘灯影閃牆，斜月光穿牖。","天明西北望，万里君知否。","老去無见期，踟躕搔白首。"]', '诗', 'shi', '', NULL, '夢與李七庾三十三同訪元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce42dcdc-431b-4d07-86ea-9320bb18d917', '秋槿', '秋槿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風露颯已冷，天色亦黃昏。","中庭有槿花，榮落同一晨。","秋開已寂莫，夕隕何紛紛。","正憐少顏色，復歎不逡巡。","感此因念彼，懷哉聊一陳。","男兒老富貴，女子晚婚姻。","頭白始得志，色衰方事人。","後時不獲已，安得如青春。"]', '["风露颯已冷，天色亦黄昏。","中庭有槿花，榮落同一晨。","秋开已寂莫，夕隕何紛紛。","正怜少顏色，复歎不逡巡。","感此因念彼，懷哉聊一陳。","男兒老富貴，女子晚婚姻。","头白始得志，色衰方事人。","後时不獲已，安得如青春。"]', '诗', 'shi', '', NULL, '秋槿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a88fdc72-c694-4ce8-8f1b-6f99aebff66e', '荅元郎中楊員外喜烏見寄', '荅元郎中楊員外喜烏见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南宮鴛鴦地，何忽烏來止。","故人錦帳郎，聞烏笑相視。","疑烏報消息，望我歸鄉里。","我歸應待烏頭白，慙媿元郎誤歡喜。"]', '["南宮鴛鴦地，何忽烏来止。","故人錦帳郎，闻烏笑相視。","疑烏報消息，望我归乡里。","我归應待烏头白，慙媿元郎誤歡喜。"]', '诗', 'shi', '', NULL, '荅元郎中楊員外喜烏見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f1a8923-5764-4b1e-a250-828e14bdc2ea', '初入峽有感', '初入峽有感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["上有萬仞山，下有千丈水。","蒼蒼兩崖間，闊狹容一葦。","瞿唐呀直瀉，灩澦屹中峙。","未夜黑巖昏，無風白浪起。","大石如刀劒，小石如牙齒。","一步不可行，況千三百里。","苒蒻竹篾𥮘，欹危檝師趾。","一跌無完舟，吾生繫於此。","常聞仗忠信，蠻貊可行矣。","自古漂沈人，豈盡非君子。","況吾時與命，蹇舛不足恃。","常恐不才身，復作無名死。"]', '["上有万仞山，下有千丈水。","蒼蒼兩崖间，闊狹容一葦。","瞿唐呀直瀉，灩澦屹中峙。","未夜黑巖昏，無风白浪起。","大石如刀劒，小石如牙齒。","一步不可行，況千三百里。","苒蒻竹篾𥮘，欹危檝師趾。","一跌無完舟，吾生繫於此。","常闻仗忠信，蠻貊可行矣。","自古漂沈人，豈尽非君子。","況吾时與命，蹇舛不足恃。","常恐不才身，复作無名死。"]', '诗', 'shi', '', NULL, '初入峽有感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ac91fcb-b4d4-4eb8-9000-35d652c92c74', '過昭君村', '過昭君村', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["靈珠產無種，彩雲出無根。","亦如彼姝子，生此遐陋村。","至麗物難掩，遽選入君門。","獨美衆所嫉，終棄出塞垣。","唯此希代色，豈無一顧恩。","事排勢須去，不得由至尊。","白黑既可變，丹青何足論。","竟埋代北骨，不返巴東魂。","慘澹晚雲水，依稀舊鄉園。","妍姿化已久，但有村名存。","村中有遺老，指點爲我言。","不敢往者戒，恐貽來者冤。","至今村女面，燒灼成瘢痕。"]', '["靈珠產無種，彩云出無根。","亦如彼姝子，生此遐陋村。","至丽物难掩，遽選入君门。","独美衆所嫉，終棄出塞垣。","唯此希代色，豈無一顧恩。","事排勢須去，不得由至尊。","白黑既可变，丹青何足論。","竟埋代北骨，不返巴东魂。","慘澹晚云水，依稀旧乡园。","妍姿化已久，但有村名存。","村中有遺老，指点爲我言。","不敢往者戒，恐貽来者冤。","至今村女面，燒灼成瘢痕。"]', '诗', 'shi', '', NULL, '過昭君村 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4acc37b-e7f1-49ce-bed0-2ce8b02b45d9', '自江州至忠州', '自江州至忠州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["前在潯陽日，已歎賓朋寡。","忽忽抱憂懷，出門無處寫。","今來轉深僻，窮峽巔山下。","五月斷行舟，灩堆正如馬。","巴人類猨狖，矍鑠滿山野。","敢望見交親，喜逢似人者。"]', '["前在潯陽日，已歎賓朋寡。","忽忽抱憂懷，出门無处寫。","今来轉深僻，窮峽巔山下。","五月斷行舟，灩堆正如马。","巴人類猨狖，矍鑠满山野。","敢望见交親，喜逢似人者。"]', '诗', 'shi', '', NULL, '自江州至忠州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfd6d686-38b5-4367-b370-4995aeae8574', '初到忠州登東樓寄萬州楊八使君', '初到忠州登东楼寄万州楊八使君', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["山束邑居窄，峽牽氣候偏。","林巒少平地，霧雨多陰天。","隱隱煮鹽火，漠漠燒畬煙。","賴此東樓夕，風月時翛然。","憑軒望所思，目斷心涓涓。","背春有去雁，上水無來船。","我懷巴東守，本是關西賢。","平生已不淺，流落重相憐。","水梗漂萬里，籠禽囚五年。","新恩同雨露，遠郡鄰山川。","書信雖往復，封疆徒接連。","其如美人面，欲見杳無緣。"]', '["山束邑居窄，峽牽氣候偏。","林巒少平地，霧雨多陰天。","隐隐煮鹽火，漠漠燒畬煙。","賴此东楼夕，风月时翛然。","憑軒望所思，目斷心涓涓。","背春有去雁，上水無来船。","我懷巴东守，本是关西賢。","平生已不淺，流落重相怜。","水梗漂万里，籠禽囚五年。","新恩同雨露，远郡鄰山川。","书信雖往复，封疆徒接連。","其如美人面，欲见杳無緣。"]', '诗', 'shi', '', NULL, '初到忠州登東樓寄萬州楊八使君 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38653c12-f754-4dc5-8845-4062ed54fdde', '郡中', '郡中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鄉路音信斷，山城日月遲。","欲知州近遠，階前摘荔枝。"]', '["乡路音信斷，山城日月遲。","欲知州近远，階前摘荔枝。"]', '诗', 'shi', '', NULL, '郡中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d9fc7c8-493a-4dfd-a408-83cb06f4004a', '西樓夜', '西楼夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["悄悄復悄悄，城隅隱林杪。","山郭燈火稀，峽天星漢少。","年光東流水，生計南枝鳥。","月沒江沈沈，西樓殊未曉。"]', '["悄悄复悄悄，城隅隐林杪。","山郭灯火稀，峽天星漢少。","年光东流水，生計南枝鸟。","月沒江沈沈，西楼殊未晓。"]', '诗', 'shi', '', NULL, '西樓夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea5503db-8f38-4f06-b439-0446024f3a05', '東樓曉', '东楼晓', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["脈脈復脈脈，東樓無宿客。","城闇雲霧多，峽深田地窄。","宵燈尚留燄，晨禽初展翮。","欲知山高低，不見東方白。"]', '["脈脈复脈脈，东楼無宿客。","城闇云霧多，峽深田地窄。","宵灯尚留燄，晨禽初展翮。","欲知山高低，不见东方白。"]', '诗', 'shi', '', NULL, '東樓曉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b93ee049-d09e-4cd6-a07f-5bcddbe31df6', '寄王質夫', '寄王質夫', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憶始識君時，愛君世緣薄。","我亦吏王畿，不爲名利著。","春尋仙遊洞，秋上雲居閣。","樓觀水潺潺，龍潭花漠漠。","吟詩石上坐，引酒泉邊酌。","因話出處心，心期老巖壑。","忽從風雨別，遂被簪纓縛。","君作出山雲，我爲入籠鶴。","籠深鶴殘顇，山遠雲飄泊。","去處雖不同，同負平生約。","今來各何在，老去隨所託。","我守巴南城，君佐征西幕。","年顏漸衰颯，生計仍蕭索。","方含去國愁，且羨從軍樂。","舊遊疑是夢，往事思如昨。","相憶春又深，故山花正落。"]', '["憶始識君时，愛君世緣薄。","我亦吏王畿，不爲名利著。","春尋仙游洞，秋上云居閣。","楼观水潺潺，龙潭花漠漠。","吟诗石上坐，引酒泉邊酌。","因話出处心，心期老巖壑。","忽從风雨別，遂被簪纓縛。","君作出山云，我爲入籠鹤。","籠深鹤殘顇，山远云飄泊。","去处雖不同，同負平生約。","今来各何在，老去隨所託。","我守巴南城，君佐征西幕。","年顏漸衰颯，生計仍蕭索。","方含去国愁，且羨從軍乐。","旧游疑是梦，往事思如昨。","相憶春又深，故山花正落。"]', '诗', 'shi', '', NULL, '寄王質夫 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e675e6ae-cd0d-4c09-9d37-9f09ded3847f', '南賓郡齋即事寄楊萬州', '南賓郡斋即事寄楊万州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["山上巴子城，山下巴江水。","中有窮獨人，強名爲刺史。","時時竊自哂，刺史豈如是。","倉粟餧家人，黃縑裹妻子。","莓苔翳冠帶，霧雨霾樓雉。","衙鼓暮復朝，郡齋臥還起。","回頭望南浦，亦在煙波裏。","而我復何嗟，夫君猶滯此。"]', '["山上巴子城，山下巴江水。","中有窮独人，強名爲刺史。","时时竊自哂，刺史豈如是。","倉粟餧家人，黄縑裹妻子。","莓苔翳冠带，霧雨霾楼雉。","衙鼓暮复朝，郡斋臥還起。","回头望南浦，亦在煙波裏。","而我复何嗟，夫君猶滯此。"]', '诗', 'shi', '', NULL, '南賓郡齋即事寄楊萬州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffbb0e4f-6a8d-4cf5-8128-a943e00f1541', '招蕭處士', '招蕭处士', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["峽內豈無人，所逢非所思。","門前亦有客，相對不相知。","仰望但雲樹，俯顧惟妻兒。","寢食起居外，端然無所爲。","東郊蕭處士，聊可與開眉。","能飲滿杯酒，善吟長句詩。","庭前吏散後，江畔路乾時。","請君攜竹杖，一赴郡齋期。"]', '["峽內豈無人，所逢非所思。","门前亦有客，相对不相知。","仰望但云樹，俯顧惟妻兒。","寢食起居外，端然無所爲。","东郊蕭处士，聊可與开眉。","能饮满杯酒，善吟长句诗。","庭前吏散後，江畔路乾时。","請君携竹杖，一赴郡斋期。"]', '诗', 'shi', '', NULL, '招蕭處士 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89024d78-3e78-4e9a-8736-704bfa63cb8d', '庭槐', '庭槐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南方饒竹樹，唯有青槐稀。","十種七八死，縱活亦支離。","何此郡庭下，一株獨華滋。","蒙蒙碧煙葉，嫋嫋黃花枝。","我家渭水上，此樹蔭前墀。","忽向天涯見，憶在故園時。","人生有情感，遇物牽所思。","樹木猶復爾，況見舊親知。"]', '["南方饒竹樹，唯有青槐稀。","十種七八死，縱活亦支離。","何此郡庭下，一株独华滋。","蒙蒙碧煙葉，嫋嫋黄花枝。","我家渭水上，此樹蔭前墀。","忽向天涯见，憶在故园时。","人生有情感，遇物牽所思。","樹木猶复爾，況见旧親知。"]', '诗', 'shi', '', NULL, '庭槐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f059da3-35a7-4735-ae84-9e238d86dfa5', '送客回晚興', '送客回晚兴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["城上雲霧開，沙頭風浪定。","參差亂山出，澹泞平江淨。","行客舟已遠，居人酒初醒。","嫋嫋秋竹梢，巴蟬聲似磬。"]', '["城上云霧开，沙头风浪定。","參差亂山出，澹泞平江淨。","行客舟已远，居人酒初醒。","嫋嫋秋竹梢，巴蟬声似磬。"]', '诗', 'shi', '', NULL, '送客回晚興 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa1af4de-0505-4ca9-aa54-669cc7d1edbf', '東樓竹', '东楼竹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["瀟灑城東樓，繞樓多修竹。","森然一萬竿，白粉封青玉。","卷簾睡初覺，欹枕看未足。","影轉色入樓，牀席生浮綠。","空城絕賓客，向夕彌幽獨。","樓上夜不歸，此君留我宿。"]', '["瀟灑城东楼，繞楼多修竹。","森然一万竿，白粉封青玉。","卷簾睡初覺，欹枕看未足。","影轉色入楼，牀席生浮綠。","空城絕賓客，向夕彌幽独。","楼上夜不归，此君留我宿。"]', '诗', 'shi', '', NULL, '東樓竹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7799166e-7971-4e27-b9a9-653501393dc1', '九日登巴臺', '九日登巴台', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黍香酒初熟，菊暖花未開。","閑聽竹枝曲，淺酌茱萸杯。","去年重陽日，漂泊湓城隈。","今歲重陽日，蕭條巴子臺。","旅鬢尋已白，鄉書久不來。","臨觴一搔首，座客亦裴回。"]', '["黍香酒初熟，菊暖花未开。","闲听竹枝曲，淺酌茱萸杯。","去年重陽日，漂泊湓城隈。","今歲重陽日，蕭條巴子台。","旅鬢尋已白，乡书久不来。","臨觴一搔首，座客亦裴回。"]', '诗', 'shi', '', NULL, '九日登巴臺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1636cc5f-761d-4d17-b8ca-36434a9778ba', '東城尋春', '东城尋春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老色日上面，歡情日去心。","今既不如昔，後當不如今。","今猶未甚衰，每事力可任。","花時仍愛出，酒後尚能吟。","但恐如此興，亦隨日銷沈。","東城春欲老，勉強一來尋。"]', '["老色日上面，歡情日去心。","今既不如昔，後當不如今。","今猶未甚衰，每事力可任。","花时仍愛出，酒後尚能吟。","但恐如此兴，亦隨日銷沈。","东城春欲老，勉強一来尋。"]', '诗', 'shi', '', NULL, '東城尋春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1911556-b763-49e6-b2e2-54550d9c3e7d', '江上送客', '江上送客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江花已萎絕，江草已消歇。","遠客何處歸，孤舟今日發。","杜鵑聲似哭，湘竹斑如血。","共是多感人，仍爲此中別。"]', '["江花已萎絕，江草已消歇。","远客何处归，孤舟今日發。","杜鵑声似哭，湘竹斑如血。","共是多感人，仍爲此中別。"]', '诗', 'shi', '', NULL, '江上送客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30afe17d-a1cf-4c3a-97e2-e89c7084057a', '桐花', '桐花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春令有常候，清明桐始發。","何此巴峽中，桐花開十月。","豈伊物理變，信是土宜別。","地氣反寒暄，天時倒生殺。","草木堅強物，所稟固難奪。","風候一參差，榮枯遂乖剌。","況吾北人性，不耐南方熱。","強羸壽夭間，安得依時節。"]', '["春令有常候，清明桐始發。","何此巴峽中，桐花开十月。","豈伊物理变，信是土宜別。","地氣反寒暄，天时倒生殺。","草木堅強物，所稟固难奪。","风候一參差，榮枯遂乖剌。","況吾北人性，不耐南方熱。","強羸壽夭间，安得依时節。"]', '诗', 'shi', '', NULL, '桐花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c393ae93-e888-4686-b605-0c4ec7080caf', '早祭風伯因懷李十一舍人', '早祭风伯因懷李十一舍人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["遠郡雖褊陋，時祀奉朝經。","夙興祭風伯，天氣曉冥冥。","導騎與從吏，引我出東坰。","水霧重如雨，山火高於星。","忽憶早朝日，與君趨紫庭。","步登龍尾道，却望終南青。","一別身向老，所思心未寧。","至今想在耳，玉音尚玲玲。"]', '["远郡雖褊陋，时祀奉朝經。","夙兴祭风伯，天氣晓冥冥。","導騎與從吏，引我出东坰。","水霧重如雨，山火高於星。","忽憶早朝日，與君趨紫庭。","步登龙尾道，却望終南青。","一別身向老，所思心未寧。","至今想在耳，玉音尚玲玲。"]', '诗', 'shi', '', NULL, '早祭風伯因懷李十一舍人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dd8bc7c-b4a2-4814-904d-8fed313d8fde', '花下對酒二首 一', '花下对酒二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["藹藹江氣春，南賓閏正月。","梅櫻與桃杏，次第城上發。","紅房爛簇火，素豔紛團雪。","香惜委風飄，愁牽壓枝折。","樓中老太守，頭上新白髮。","冷澹病心情，暄和好時節。","故園音信斷，遠郡親賓絕。","欲問花前尊，依然爲誰設。"]', '["藹藹江氣春，南賓閏正月。","梅櫻與桃杏，次第城上發。","紅房爛簇火，素豔紛團雪。","香惜委风飄，愁牽壓枝折。","楼中老太守，头上新白髮。","冷澹病心情，暄和好时節。","故园音信斷，远郡親賓絕。","欲问花前尊，依然爲誰設。"]', '诗', 'shi', '', NULL, '花下對酒二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2bba66b-b9b2-43e8-9913-00304d41e448', '花下對酒二首 二', '花下对酒二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["引手攀紅櫻，紅櫻落似霰。","仰首看白日，白日走如箭。","年芳與時景，頃刻猶衰變。","況是血肉身，安能長強健。","人心苦迷執，慕貴憂貧賤。","愁色常在眉，歡容不上面。","況吾頭半白，把鏡非不見。","何必花下杯，更待他人勸。"]', '["引手攀紅櫻，紅櫻落似霰。","仰首看白日，白日走如箭。","年芳與时景，頃刻猶衰变。","況是血肉身，安能长強健。","人心苦迷執，慕貴憂貧賤。","愁色常在眉，歡容不上面。","況吾头半白，把镜非不见。","何必花下杯，更待他人勸。"]', '诗', 'shi', '', NULL, '花下對酒二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03aad1fa-f31a-47d8-8c54-3fdd6d17c099', '不二門', '不二门', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["兩眼日將闇，四肢漸衰瘦。","束帶賸昔圍，穿衣妨寬袖。","流年似江水，奔注無昏晝。","志氣與形骸，安得長依舊。","亦曾登玉陛，舉措多紕繆。","至今金闕籍，名姓獨遺漏。","亦曾燒大藥，消息乖火候。","至今殘丹砂，燒乾不成就。","行藏事兩失，憂惱心交鬬。","化作顦顇翁，拋身在荒陋。","坐看老病逼，須得醫王救。","唯有不二門，其間無夭壽。"]', '["兩眼日將闇，四肢漸衰瘦。","束带賸昔圍，穿衣妨寬袖。","流年似江水，奔注無昏晝。","志氣與形骸，安得长依旧。","亦曾登玉陛，舉措多紕繆。","至今金闕籍，名姓独遺漏。","亦曾燒大藥，消息乖火候。","至今殘丹砂，燒乾不成就。","行藏事兩失，憂惱心交鬬。","化作顦顇翁，拋身在荒陋。","坐看老病逼，須得醫王救。","唯有不二门，其间無夭壽。"]', '诗', 'shi', '', NULL, '不二門 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52e9618c-832e-439e-9578-00b67188cb18', '我身', '我身', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我身何所似，似彼孤生蓬。","秋霜翦根斷，浩浩隨長風。","昔游秦雍間，今落巴蠻中。","昔爲意氣郎，今作寂寥翁。","外貌雖寂莫，中懷頗沖融。","賦命有厚薄，委心任窮通。","通當爲大鵬，舉翅摩蒼穹。","窮則爲鷦鷯，一枝足自容。","苟知此道者，身窮心不窮。"]', '["我身何所似，似彼孤生蓬。","秋霜翦根斷，浩浩隨长风。","昔游秦雍间，今落巴蠻中。","昔爲意氣郎，今作寂寥翁。","外貌雖寂莫，中懷頗沖融。","賦命有厚薄，委心任窮通。","通當爲大鵬，舉翅摩蒼穹。","窮則爲鷦鷯，一枝足自容。","苟知此道者，身窮心不窮。"]', '诗', 'shi', '', NULL, '我身 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a216688-efb9-44e0-87e0-e2e2ca47464f', '哭王質夫', '哭王質夫', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["仙遊寺前別，別來十年餘。","生別猶怏怏，死別復何如。","客從梓潼來，道君死不虛。","驚疑心未信，欲哭復踟躕。","踟躕寢門側，聲發涕亦俱。","衣上今日淚，篋中前月書。","憐君古人風，重有君子儒。","篇詠陶謝輩，風流嵇阮徒。","出身既蹇屯，生世仍須臾。","誠知天至高，安得不一呼。","江南有毒蟒，江北有妖狐。","皆享千年壽，多於王質夫。","不知彼何德，不識此何辜。"]', '["仙游寺前別，別来十年餘。","生別猶怏怏，死別复何如。","客從梓潼来，道君死不虛。","驚疑心未信，欲哭复踟躕。","踟躕寢门側，声發涕亦俱。","衣上今日泪，篋中前月书。","怜君古人风，重有君子儒。","篇詠陶謝輩，风流嵇阮徒。","出身既蹇屯，生世仍須臾。","誠知天至高，安得不一呼。","江南有毒蟒，江北有妖狐。","皆享千年壽，多於王質夫。","不知彼何德，不識此何辜。"]', '诗', 'shi', '', NULL, '哭王質夫 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b29c04b7-c7d4-49cd-8f60-83863d255b3f', '東坡種花二首 一', '东坡種花二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["持錢買花樹，城東坡上栽。","但購有花者，不限桃杏梅。","百果參雜種，千枝次第開。","天時有早晚，地力無高低。","紅者霞豔豔，白者雪皚皚。","遊蠭逐不去，好鳥亦來栖。","前有長流水，下有小平臺。","時拂臺上石，一舉風前杯。","花枝蔭我頭，花蘂落我懷。","獨酌復獨詠，不覺月平西。","巴俗不愛花，竟春無人來。","唯此醉太守，盡日不能迴。"]', '["持錢買花樹，城东坡上栽。","但購有花者，不限桃杏梅。","百果參杂種，千枝次第开。","天时有早晚，地力無高低。","紅者霞豔豔，白者雪皚皚。","游蠭逐不去，好鸟亦来栖。","前有长流水，下有小平台。","时拂台上石，一舉风前杯。","花枝蔭我头，花蘂落我懷。","独酌复独詠，不覺月平西。","巴俗不愛花，竟春無人来。","唯此醉太守，尽日不能迴。"]', '诗', 'shi', '', NULL, '東坡種花二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dafd5719-d415-4bdf-89cb-0094d28ebe21', '東坡種花二首 二', '东坡種花二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["東坡春向暮，樹木今何如。","漠漠花落盡，翳翳葉生初。","每日領童僕，荷鉏仍決渠。","剗土壅其本，引泉溉其枯。","小樹低數尺，大樹長丈餘。","封植來幾時，高下隨扶疎。","養樹既如此，養民亦何殊。","將欲茂枝葉，必先救根株。","云何救根株，勸農均賦租。","云何茂枝葉，省事寬刑書。","移此爲郡政，庶幾甿俗蘇。"]', '["东坡春向暮，樹木今何如。","漠漠花落尽，翳翳葉生初。","每日領童僕，荷鉏仍決渠。","剗土壅其本，引泉溉其枯。","小樹低數尺，大樹长丈餘。","封植来幾时，高下隨扶疎。","養樹既如此，養民亦何殊。","將欲茂枝葉，必先救根株。","云何救根株，勸農均賦租。","云何茂枝葉，省事寬刑书。","移此爲郡政，庶幾甿俗蘇。"]', '诗', 'shi', '', NULL, '東坡種花二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3acbdf76-d67e-41a1-a9a9-553209ac83ec', '登城東古臺', '登城东古台', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["迢迢東郊上，有土青崔嵬。","不知何代物，疑是巴王臺。","巴歌久無聲，巴宮沒黃埃。","靡靡春草合，牛羊緣四隈。","我來一登眺，目極心悠哉。","始見江山勢，峰疊水環迴。","憑高視聽曠，向遠胷襟開。","唯有故園念，時時東北來。"]', '["迢迢东郊上，有土青崔嵬。","不知何代物，疑是巴王台。","巴歌久無声，巴宮沒黄埃。","靡靡春草合，牛羊緣四隈。","我来一登眺，目極心悠哉。","始见江山勢，峰叠水环迴。","憑高視听曠，向远胷襟开。","唯有故园念，时时东北来。"]', '诗', 'shi', '', NULL, '登城東古臺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee37b756-891c-4d1e-a842-527cb91a2c81', '哭諸故人因寄元八', '哭諸故人因寄元八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昨日哭寢門，今日哭寢門。","借問所哭誰，無非故交親。","偉卿既長往，質夫亦幽淪。","屈指數年世，收涕自思身。","彼皆少於我，先爲泉下人。","我今頭半白，焉得身久存。","好狂元郎中，相識二十春。","昔見君生子，今聞君抱孫。","存者盡老大，逝者已成塵。","早晚升平宅，開眉一見君。"]', '["昨日哭寢门，今日哭寢门。","借问所哭誰，無非故交親。","偉卿既长往，質夫亦幽淪。","屈指數年世，收涕自思身。","彼皆少於我，先爲泉下人。","我今头半白，焉得身久存。","好狂元郎中，相識二十春。","昔见君生子，今闻君抱孫。","存者尽老大，逝者已成塵。","早晚升平宅，开眉一见君。"]', '诗', 'shi', '', NULL, '哭諸故人因寄元八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63e25ab6-0447-4a83-8858-dc040bc51006', '郡中春讌因贈諸客', '郡中春讌因贈諸客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["僕本儒家子，待詔金馬門。","塵忝親近地，孤負聖明恩。","一旦奉優詔，萬里牧遠人。","可憐島夷帥，自稱爲使君。","身騎牂牁馬，口食塗江鱗。","闇澹緋衫故，斕斑白髮新。","是時歲二月，玉曆布春分。","頒條示皇澤，命宴及良辰。","冉冉趨府吏，蚩蚩聚州民。","有如蟄蟲鳥，亦應天地春。","薰草席鋪坐，藤枝酒注樽。","中庭無平地，高下隨所陳。","蠻鼓聲坎坎，巴女舞蹲蹲。","使君居上頭，掩口語衆賓。","勿笑風俗陋，勿欺官府貧。","蠭巢與蟻穴，隨分有君臣。"]', '["僕本儒家子，待詔金马门。","塵忝親近地，孤負聖明恩。","一旦奉優詔，万里牧远人。","可怜島夷帥，自稱爲使君。","身騎牂牁马，口食塗江鱗。","闇澹緋衫故，斕斑白髮新。","是时歲二月，玉曆布春分。","頒條示皇澤，命宴及良辰。","冉冉趨府吏，蚩蚩聚州民。","有如蟄蟲鸟，亦應天地春。","薰草席鋪坐，藤枝酒注樽。","中庭無平地，高下隨所陳。","蠻鼓声坎坎，巴女舞蹲蹲。","使君居上头，掩口語衆賓。","勿笑风俗陋，勿欺官府貧。","蠭巢與蟻穴，隨分有君臣。"]', '诗', 'shi', '', NULL, '郡中春讌因贈諸客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67c4784b-57cb-4c97-bf7c-2322a40fa066', '開元寺東池早春', '开元寺东池早春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["池水暖溫暾，水清波瀲灩。","簇簇青泥中，新蒲葉如劒。","梅房小白裹，柳彩輕黃染。","順氣草熏熏，適情鷗汎汎。","舊遊成夢寐，往事隨陽焱。","芳物感幽懷，一動平生念。"]', '["池水暖溫暾，水清波瀲灩。","簇簇青泥中，新蒲葉如劒。","梅房小白裹，柳彩轻黄染。","順氣草熏熏，適情鷗汎汎。","旧游成梦寐，往事隨陽焱。","芳物感幽懷，一动平生念。"]', '诗', 'shi', '', NULL, '開元寺東池早春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('955c6d5b-fe80-4b54-b527-069a24df1abb', '東溪種柳', '东溪種柳', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["野性愛栽植，植柳水中坻。","乘春持斧斫，裁截而樹之。","長短既不一，高下隨所宜。","倚岸埋大幹，臨流插小枝。","松柏不可待，楩柟固難移。","不如種此樹，此樹易榮滋。","無根亦可活，成陰況非遲。","三年未離郡，可以見依依。","種罷水邊憩，仰頭閑自思。","富貴本非望，功名須待時。","不種東溪柳，端坐欲何爲。"]', '["野性愛栽植，植柳水中坻。","乘春持斧斫，裁截而樹之。","长短既不一，高下隨所宜。","倚岸埋大幹，臨流插小枝。","松柏不可待，楩柟固难移。","不如種此樹，此樹易榮滋。","無根亦可活，成陰況非遲。","三年未離郡，可以见依依。","種罷水邊憩，仰头闲自思。","富貴本非望，功名須待时。","不種东溪柳，端坐欲何爲。"]', '诗', 'shi', '', NULL, '東溪種柳 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9184ab85-6805-4537-ac17-e21cea26fbfd', '臥小齋', '臥小斋', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝起視事畢，晏坐飽食終。","散步長廊下，臥退小齋中。","拙政自多暇，幽情誰與同。","孰云二千石，心如田野翁。"]', '["朝起視事畢，晏坐飽食終。","散步长廊下，臥退小斋中。","拙政自多暇，幽情誰與同。","孰云二千石，心如田野翁。"]', '诗', 'shi', '', NULL, '臥小齋 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e63eecb5-9d61-481a-90e6-40f382ecfc0f', '步東坡', '步东坡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝上東坡步，夕上東坡步。","東坡何所愛，愛此新成樹。","種植當歲初，滋榮及春暮。","信意取次栽，無行亦無數。","綠陰斜景轉，芳氣微風度。","新葉鳥下來，萎花蝶飛去。","閑攜斑竹杖，徐曳黃麻屨。","欲識往來頻，青蕪成白路。"]', '["朝上东坡步，夕上东坡步。","东坡何所愛，愛此新成樹。","種植當歲初，滋榮及春暮。","信意取次栽，無行亦無數。","綠陰斜景轉，芳氣微风度。","新葉鸟下来，萎花蝶飞去。","闲携斑竹杖，徐曳黄麻屨。","欲識往来頻，青蕪成白路。"]', '诗', 'shi', '', NULL, '步東坡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16c5152f-1b45-480e-9c0c-0812dc42c4ce', '徵秋稅畢題郡南亭', '徵秋稅畢題郡南亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["高城直下視，蠢蠢見巴蠻。","安可施政教，尚不通語言。","且喜賦斂畢，幸聞閭井安。","豈伊循良化，賴此豐登年。","案牘既簡少，池館亦清閑。","秋雨檐果落，夕鐘林鳥還。","南亭日瀟灑，偃臥恣疎頑。"]', '["高城直下視，蠢蠢见巴蠻。","安可施政教，尚不通語言。","且喜賦斂畢，幸闻閭井安。","豈伊循良化，賴此豐登年。","案牘既簡少，池館亦清闲。","秋雨檐果落，夕鐘林鸟還。","南亭日瀟灑，偃臥恣疎頑。"]', '诗', 'shi', '', NULL, '徵秋稅畢題郡南亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84f056c8-56dd-4b6c-9cc7-4ec78f9c7551', '蚊蟆', '蚊蟆', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["巴徼炎毒早，二月蚊蟆生。","咂膚拂不去，繞耳薨薨聲。","斯物頗微細，中人初甚輕。","如有膚受譖，久則瘡痏成。","痏成無奈何，所要防其萌。","麼蟲何足道，潛喻儆人情。"]', '["巴徼炎毒早，二月蚊蟆生。","咂膚拂不去，繞耳薨薨声。","斯物頗微細，中人初甚轻。","如有膚受譖，久則瘡痏成。","痏成無奈何，所要防其萌。","麼蟲何足道，潛喻儆人情。"]', '诗', 'shi', '', NULL, '蚊蟆 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2cf4ca2-c6f4-4c14-9684-68bfd570da45', '登龍昌上寺望江南山懷錢舍人', '登龙昌上寺望江南山懷錢舍人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["騎馬出西郭，悠悠欲何之。","獨上高寺去，一與白雲期。","虛檻晚瀟灑，前山碧參差。","忽似青龍閤，同望玉峰時。","因詠松雪句，永懷鸞鶴姿。","六年不相見，況乃隔榮衰。"]', '["騎马出西郭，悠悠欲何之。","独上高寺去，一與白云期。","虛檻晚瀟灑，前山碧參差。","忽似青龙閤，同望玉峰时。","因詠松雪句，永懷鸾鹤姿。","六年不相见，況乃隔榮衰。"]', '诗', 'shi', '', NULL, '登龍昌上寺望江南山懷錢舍人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2ebce80-29bb-493b-b99f-ffe64a25d6a4', '郊下', '郊下', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["西日照高樹，樹頭子規鳴。","東風吹野水，水畔江蘺生。","盡日看山立，有時尋澗行。","兀兀長如此，何許似專城。"]', '["西日照高樹，樹头子規鳴。","东风吹野水，水畔江蘺生。","尽日看山立，有时尋澗行。","兀兀长如此，何許似專城。"]', '诗', 'shi', '', NULL, '郊下 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc717baa-dade-4fc8-8fc5-eaae1fb90a07', '遣懷', '遣懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["樂往必悲生，泰來由否極。","誰言此數然，吾道何終塞。","嘗求詹尹卜，拂龜竟默默。","亦曾仰問天，天但蒼蒼色。","自茲唯委命，名利心雙息。","近日轉安閑，鄉園亦休憶。","回看世間苦，苦在求不得。","我今無所求，庶離憂悲域。"]', '["乐往必悲生，泰来由否極。","誰言此數然，吾道何終塞。","嘗求詹尹卜，拂龟竟默默。","亦曾仰问天，天但蒼蒼色。","自茲唯委命，名利心雙息。","近日轉安闲，乡园亦休憶。","回看世间苦，苦在求不得。","我今無所求，庶離憂悲域。"]', '诗', 'shi', '', NULL, '遣懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5c0311c-cbfc-46e7-bb25-df5607eb8f52', '歲晚', '歲晚', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["霜降水返壑，風落木歸山。","冉冉歲將宴，物皆復本源。","何此南遷客，五年獨未還。","命屯分已定，日久心彌安。","亦嘗心與口，靜念私自言。","去國固非樂，歸鄉未必歡。","何須自生苦，舍易求其難。"]', '["霜降水返壑，风落木归山。","冉冉歲將宴，物皆复本源。","何此南遷客，五年独未還。","命屯分已定，日久心彌安。","亦嘗心與口，静念私自言。","去国固非乐，归乡未必歡。","何須自生苦，舍易求其难。"]', '诗', 'shi', '', NULL, '歲晚 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e766207-5407-4502-b41f-064e72ec8a9a', '負冬日', '負冬日', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["杲杲冬日出，照我屋南隅。","負暄閉目坐，和氣生肌膚。","初似飲醇醪，又如蟄者蘇。","外融百骸暢，中適一念無。","曠然忘所在，心與虛空俱。"]', '["杲杲冬日出，照我屋南隅。","負暄閉目坐，和氣生肌膚。","初似饮醇醪，又如蟄者蘇。","外融百骸暢，中適一念無。","曠然忘所在，心與虛空俱。"]', '诗', 'shi', '', NULL, '負冬日 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e6a3dfe-dc72-4904-9888-a3797fdc2872', '委順', '委順', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["山城雖荒蕪，竹樹有嘉色。","郡俸誠不多，亦足充衣食。","外累由心起，心寧累自息。","尚欲忘家鄉，誰能算官職。","宜懷齊遠近，委順隨南北。","歸去誠可憐，天涯住亦得。"]', '["山城雖荒蕪，竹樹有嘉色。","郡俸誠不多，亦足充衣食。","外累由心起，心寧累自息。","尚欲忘家乡，誰能算官職。","宜懷齊远近，委順隨南北。","归去誠可怜，天涯住亦得。"]', '诗', 'shi', '', NULL, '委順 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66bded42-156a-4f06-9d76-c3aed2807748', '宿溪翁', '宿溪翁', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["衆心愛金玉，衆口貪酒肉。","何如此溪翁，飲瓢亦自足。","溪南刈薪草，溪北修牆屋。","歲種一頃田，春驅兩黃犢。","於中甚安適，此外無營欲。","溪畔偶相逢，菴中遂同宿。","醉翁向朝市，問我何官祿。","虛言笑殺翁，郎官應列宿。"]', '["衆心愛金玉，衆口貪酒肉。","何如此溪翁，饮瓢亦自足。","溪南刈薪草，溪北修牆屋。","歲種一頃田，春驱兩黄犢。","於中甚安適，此外無營欲。","溪畔偶相逢，菴中遂同宿。","醉翁向朝市，问我何官祿。","虛言笑殺翁，郎官應列宿。"]', '诗', 'shi', '', NULL, '宿溪翁 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bcabd4c-e483-4d43-858d-9b2affc9d1d4', '重過壽泉憶與楊九別時因題店壁', '重過壽泉憶與楊九別时因題店壁', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["商州南十里，有水名壽泉。","湧出石崖下，流經山店前。","憶昔相送日，我去君言還。","寒波與老淚，此地共潺湲。","一去歷萬里，再來經六年。","形容已變改，處所猶依然。","他日君過此，慇懃吟此篇。"]', '["商州南十里，有水名壽泉。","湧出石崖下，流經山店前。","憶昔相送日，我去君言還。","寒波與老泪，此地共潺湲。","一去歷万里，再来經六年。","形容已变改，处所猶依然。","他日君過此，慇懃吟此篇。"]', '诗', 'shi', '', NULL, '重過壽泉憶與楊九別時因題店壁 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f937828a-ee5b-4a42-9717-dee2529ab0b0', '西掖早秋直夜書意', '西掖早秋直夜书意', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["涼風起禁掖，新月生宮沼。","夜半秋闇來，萬年枝嫋嫋。","炎涼遞時節，鐘鼓交昏曉。","遇聖惜年衰，報恩愁力小。","素餐無補益，朱綬虛纏繞。","冠蓋栖野雲，稻粱養山鳥。","量能私自省，所得已非少。","五品不爲賤，五十不爲夭。","若無知足心，貪求何日了。"]', '["涼风起禁掖，新月生宮沼。","夜半秋闇来，万年枝嫋嫋。","炎涼遞时節，鐘鼓交昏晓。","遇聖惜年衰，報恩愁力小。","素餐無補益，朱綬虛纏繞。","冠蓋栖野云，稻粱養山鸟。","量能私自省，所得已非少。","五品不爲賤，五十不爲夭。","若無知足心，貪求何日了。"]', '诗', 'shi', '', NULL, '西掖早秋直夜書意 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fa9056a-e756-4b11-a51d-fddcbb46df15', '庭松', '庭松', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["堂下何所有，十松當我階。","亂立無行次，高下亦不齊。","高者三丈長，下者十尺低。","有如野生物，不知何人栽。","接以青瓦屋，承之白沙臺。","朝昏有風月，燥濕無塵泥。","疎韻秋槭槭，涼陰夏淒淒。","春深微雨夕，滿葉珠蓑蓑。","歲暮大雪天，壓枝玉皚皚。","四時各有趣，萬木非其儕。","去年買此宅，多爲人所咍。","一家二十口，移轉就松來。","移來有何得，但得煩襟開。","即此是益友，豈必交賢才。","顧我猶俗士，冠帶走塵埃。","未稱爲松主，時時一媿懷。"]', '["堂下何所有，十松當我階。","亂立無行次，高下亦不齊。","高者三丈长，下者十尺低。","有如野生物，不知何人栽。","接以青瓦屋，承之白沙台。","朝昏有风月，燥濕無塵泥。","疎韻秋槭槭，涼陰夏淒淒。","春深微雨夕，满葉珠蓑蓑。","歲暮大雪天，壓枝玉皚皚。","四时各有趣，万木非其儕。","去年買此宅，多爲人所咍。","一家二十口，移轉就松来。","移来有何得，但得煩襟开。","即此是益友，豈必交賢才。","顧我猶俗士，冠带走塵埃。","未稱爲松主，时时一媿懷。"]', '诗', 'shi', '', NULL, '庭松 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('969edf06-789e-4f14-a899-d55c61fcc946', '竹窗', '竹窗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["常愛輞川寺，竹窗東北廊。","一別十餘載，見竹未曾忘。","今春二月初，卜居在新昌。","未暇作廐庫，且先營一堂。","開窗不糊紙，種竹不依行。","意取北檐下，窗與竹相當。","繞屋聲淅淅，逼人色蒼蒼。","煙通杳藹氣，月透玲瓏光。","是時三伏天，天氣熱如湯。","獨此竹窗下，朝迴解衣裳。","輕紗一幅巾，小簟六尺牀。","無客盡日靜，有風終夜涼。","乃知前古人，言事頗諳詳。","清風北窗臥，可以傲羲皇。"]', '["常愛輞川寺，竹窗东北廊。","一別十餘載，见竹未曾忘。","今春二月初，卜居在新昌。","未暇作廐庫，且先營一堂。","开窗不糊紙，種竹不依行。","意取北檐下，窗與竹相當。","繞屋声淅淅，逼人色蒼蒼。","煙通杳藹氣，月透玲瓏光。","是时三伏天，天氣熱如湯。","独此竹窗下，朝迴解衣裳。","轻紗一幅巾，小簟六尺牀。","無客尽日静，有风終夜涼。","乃知前古人，言事頗諳詳。","清风北窗臥，可以傲羲皇。"]', '诗', 'shi', '', NULL, '竹窗 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31debc88-7cae-4121-80a0-46a24e47b296', '同韓侍郎遊鄭家池吟詩小飲', '同韓侍郎游鄭家池吟诗小饮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["野艇容三人，晚池流浼浼。","悠然依櫂坐，水思如江海。","宿雨洗沙塵，晴風蕩煙靄。","殘陽上竹樹，枝葉生光彩。","我本偶然來，景物如相待。","白鷗驚不起，綠芡行堪采。","齒髮雖已衰，性靈未云改。","逢詩遇杯酒，尚有心情在。"]', '["野艇容三人，晚池流浼浼。","悠然依櫂坐，水思如江海。","宿雨洗沙塵，晴风蕩煙靄。","殘陽上竹樹，枝葉生光彩。","我本偶然来，景物如相待。","白鷗驚不起，綠芡行堪采。","齒髮雖已衰，性靈未云改。","逢诗遇杯酒，尚有心情在。"]', '诗', 'shi', '', NULL, '同韓侍郎遊鄭家池吟詩小飲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63d05382-1fc9-4d2c-9d36-c30856dd8b2b', '晚歸有感', '晚归有感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝弔李家孤，暮問崔家疾。","回馬獨歸來，低眉心鬱鬱。","平生所善者，多不過六七。","如何十年間，零落三無一。","劉曾夢中見，元向花前失。","漸老與誰遊，春城好風日。"]', '["朝弔李家孤，暮问崔家疾。","回马独归来，低眉心鬱鬱。","平生所善者，多不過六七。","如何十年间，零落三無一。","劉曾梦中见，元向花前失。","漸老與誰游，春城好风日。"]', '诗', 'shi', '', NULL, '晚歸有感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb9cd0a9-99a6-4044-8bbd-ff24ef3317e6', '曲江感秋二首 一', '曲江感秋二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["元和二年秋，我年三十七。","長慶二年秋，我年五十一。","中間十四年，六年居譴黜。","窮通與榮悴，委運隨外物。","遂師廬山遠，重弔湘江屈。","夜聽竹枝愁，秋看灩堆沒。","近辭巴郡印，又秉綸闈筆。","晚遇何足言，白髮映朱紱。","銷沈昔意氣，改換舊容質。","獨有曲江秋，風煙如往日。"]', '["元和二年秋，我年三十七。","长慶二年秋，我年五十一。","中间十四年，六年居譴黜。","窮通與榮悴，委運隨外物。","遂師廬山远，重弔湘江屈。","夜听竹枝愁，秋看灩堆沒。","近辞巴郡印，又秉綸闈笔。","晚遇何足言，白髮映朱紱。","銷沈昔意氣，改換旧容質。","独有曲江秋，风煙如往日。"]', '诗', 'shi', '', NULL, '曲江感秋二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7769baae-b823-4ec1-ba57-614726034320', '曲江感秋二首 二', '曲江感秋二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["疎蕪南岸草，蕭颯西風樹。","秋到未幾時，蟬聲又無數。","莎平綠茸合，蓮落青房露。","今日臨望時，往年感秋處。","池中水依舊，城上山如故。","獨我鬢間毛，昔黑今垂素。","榮名與壯齒，相避如朝暮。","時命始欲來，年顏已先去。","當春不歡樂，臨老徒驚誤。","故作詠懷詩，題於曲江路。"]', '["疎蕪南岸草，蕭颯西风樹。","秋到未幾时，蟬声又無數。","莎平綠茸合，蓮落青房露。","今日臨望时，往年感秋处。","池中水依旧，城上山如故。","独我鬢间毛，昔黑今垂素。","榮名與壯齒，相避如朝暮。","时命始欲来，年顏已先去。","當春不歡乐，臨老徒驚誤。","故作詠懷诗，題於曲江路。"]', '诗', 'shi', '', NULL, '曲江感秋二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1d2cdbd-5919-40f4-b357-105ea49ccbf4', '玩松竹二首 一', '玩松竹二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["龍蛇隱大澤，麋鹿遊豐草。","栖鳳安於梧，潛魚樂於藻。","吾亦愛吾廬，廬中樂吾道。","前松後修竹，偃臥可終老。","各附其所安，不知他物好。"]', '["龙蛇隐大澤，麋鹿游豐草。","栖鳳安於梧，潛鱼乐於藻。","吾亦愛吾廬，廬中乐吾道。","前松後修竹，偃臥可終老。","各附其所安，不知他物好。"]', '诗', 'shi', '', NULL, '玩松竹二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12f11d46-6c33-4697-8d64-edb6822ed456', '玩松竹二首 二', '玩松竹二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["坐愛前檐前，臥愛北窗北。","窗竹多好風，檐松有嘉色。","幽懷一以合，俗念隨緣息。","在爾雖無情，於予即有得。","乃知性相近，不必動與植。"]', '["坐愛前檐前，臥愛北窗北。","窗竹多好风，檐松有嘉色。","幽懷一以合，俗念隨緣息。","在爾雖無情，於予即有得。","乃知性相近，不必动與植。"]', '诗', 'shi', '', NULL, '玩松竹二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95cc8031-c40f-42f2-be9b-680a26c048fc', '衰病無趣因吟所懷', '衰病無趣因吟所懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝餐多不飽，夜臥常少睡。","自覺寢食間，多無少年味。","平生好詩酒，今亦將舍棄。","酒唯下藥飲，無復曾歡醉。","詩多聽人吟，自不題一字。","病姿與衰相，日夜相繼至。","況當尚少朝，彌慙居近侍。","終當求一郡，聚少漁樵費。","合口便歸山，不問人間事。"]', '["朝餐多不飽，夜臥常少睡。","自覺寢食间，多無少年味。","平生好诗酒，今亦將舍棄。","酒唯下藥饮，無复曾歡醉。","诗多听人吟，自不題一字。","病姿與衰相，日夜相繼至。","況當尚少朝，彌慙居近侍。","終當求一郡，聚少漁樵費。","合口便归山，不问人间事。"]', '诗', 'shi', '', NULL, '衰病無趣因吟所懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78cc6d2f-786b-4545-93b5-5704dde8a0ef', '逍遙詠', '逍遙詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["亦莫戀此身，亦莫厭此身。","此身何足戀，萬劫煩惱根。","此身何足厭，一聚虛空塵。","無戀亦無厭，始是逍遙人。"]', '["亦莫戀此身，亦莫厭此身。","此身何足戀，万劫煩惱根。","此身何足厭，一聚虛空塵。","無戀亦無厭，始是逍遙人。"]', '诗', 'shi', '', NULL, '逍遙詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e99d354-961e-438b-b52f-5b07d963c253', '短歌行', '短歌行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曈曈太陽如火色，上行千里下一刻。","出爲白晝入爲夜，圓轉如珠住不得。","住不得，可奈何，爲君舉酒歌短歌。","歌聲苦，詞亦苦，四座少年君聽取。","今夕未竟明夕催，秋風纔往春風回。","人無根蔕時不駐，朱顏白日相隳頹。","勸君且強笑一面，勸君且強飲一杯。","人生不得長歡樂，年少須臾老到來。"]', '["曈曈太陽如火色，上行千里下一刻。","出爲白晝入爲夜，圓轉如珠住不得。","住不得，可奈何，爲君舉酒歌短歌。","歌声苦，词亦苦，四座少年君听取。","今夕未竟明夕催，秋风纔往春风回。","人無根蔕时不駐，朱顏白日相隳頹。","勸君且強笑一面，勸君且強饮一杯。","人生不得长歡乐，年少須臾老到来。"]', '诗', 'shi', '', NULL, '短歌行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4232ae1-1468-44a2-88c1-ba10c77627ce', '生離別', '生離別', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["食檗不易食梅難，檗能苦兮梅能酸。","未如生別之爲難，苦在心兮酸在肝。","晨雞再鳴殘月沒，征馬連嘶行人出。","回看骨肉哭一聲，梅酸檗苦甘如蜜。","黃河水白黃雲秋，行人河邊相對愁。","天寒野曠何處宿？棠棃葉戰風颼颼。","生離別，生離別，憂從中來無斷絕。","憂極心勞血氣衰，未年三十生白髮。"]', '["食檗不易食梅难，檗能苦兮梅能酸。","未如生別之爲难，苦在心兮酸在肝。","晨雞再鳴殘月沒，征马連嘶行人出。","回看骨肉哭一声，梅酸檗苦甘如蜜。","黄河水白黄云秋，行人河邊相对愁。","天寒野曠何处宿？棠棃葉戰风颼颼。","生離別，生離別，憂從中来無斷絕。","憂極心勞血氣衰，未年三十生白髮。"]', '诗', 'shi', '', NULL, '生離別 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5767690-7d09-4cbc-8b7d-6b28e4dcc1bc', '浩歌行', '浩歌行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天長地久無終畢，昨夜今朝又明日。","鬢髮蒼浪牙齒疎，不覺身年四十七。","前去五十有幾年，把鏡照面心茫然。","既無長繩繫白日，又無大藥駐朱顏。","朱顏日漸不如故，青史功名在何處？","欲留年少待富貴，富貴不來年少去。","去復去兮如長河，東流赴海無迴波。","賢愚貴賤同歸盡，北邙冢墓高嵯峨。","古來如此非獨我，未死有酒且高歌。","顏回短命伯夷餓，我今所得亦已多。","功名富貴須待命，命若不來知奈何。"]', '["天长地久無終畢，昨夜今朝又明日。","鬢髮蒼浪牙齒疎，不覺身年四十七。","前去五十有幾年，把镜照面心茫然。","既無长繩繫白日，又無大藥駐朱顏。","朱顏日漸不如故，青史功名在何处？","欲留年少待富貴，富貴不来年少去。","去复去兮如长河，东流赴海無迴波。","賢愚貴賤同归尽，北邙冢墓高嵯峨。","古来如此非独我，未死有酒且高歌。","顏回短命伯夷餓，我今所得亦已多。","功名富貴須待命，命若不来知奈何。"]', '诗', 'shi', '', NULL, '浩歌行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e971330-6463-4711-83aa-1d0da96589e1', '王夫子', '王夫子', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["王夫子，送君爲一尉，東南三千五百里。","道途雖遠位雖卑，月俸猶堪活妻子。","男兒口讀古人書，束帶斂手來從事。","近將徇祿給一家，遠則行道佐時理。","行道佐時須待命，委身下位無爲恥。","命苟未來且求食，官無卑高及遠邇。","男兒上既未能濟天下，下又不至飢寒死。","吾觀九品至一品，其間氣味都相似。","紫綬朱紱青布衫，顏色不同而已矣。","王夫子，別有一事欲勸君，遇酒逢春且歡喜。"]', '["王夫子，送君爲一尉，东南三千五百里。","道途雖远位雖卑，月俸猶堪活妻子。","男兒口读古人书，束带斂手来從事。","近將徇祿給一家，远則行道佐时理。","行道佐时須待命，委身下位無爲恥。","命苟未来且求食，官無卑高及远邇。","男兒上既未能濟天下，下又不至飢寒死。","吾观九品至一品，其间氣味都相似。","紫綬朱紱青布衫，顏色不同而已矣。","王夫子，別有一事欲勸君，遇酒逢春且歡喜。"]', '诗', 'shi', '', NULL, '王夫子 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0129589a-6416-4fb0-960a-48e58ae4f8b4', '江南遇天寶樂叟', '江南遇天寶乐叟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白頭病叟泣且言，祿山未亂入棃園。","能彈琵琶和法曲，多在華清隨至尊。","是時天下太平久，年年十月坐朝元。","千官起居環珮合，萬國會同車馬奔。","金鈿照耀石甕寺，蘭麝熏煮溫湯源。","貴妃宛轉侍君側，體弱不勝珠翠繁。","冬雪飄颻錦袍暖，春風蕩漾霓裳飜。","歡娛未足燕寇至，弓勁馬肥胡語喧。","豳土人遷避夷狄，鼎湖龍去哭軒轅。","從此漂淪落南土，萬人死盡一身存。","秋風江上浪無限，暮雨舟中酒一尊。","涸魚久失風波勢，枯草曾霑雨露恩。","我自秦來君莫問，驪山渭水如荒村。","新豐樹老籠明月，長生殿闇鎖春雲。","紅葉紛紛蓋欹瓦，綠苔重重封壞垣。","唯有中官作宮使，每年寒食一開門。"]', '["白头病叟泣且言，祿山未亂入棃园。","能彈琵琶和法曲，多在华清隨至尊。","是时天下太平久，年年十月坐朝元。","千官起居环珮合，万国會同车马奔。","金鈿照耀石甕寺，蘭麝熏煮溫湯源。","貴妃宛轉侍君側，體弱不勝珠翠繁。","冬雪飄颻錦袍暖，春风蕩漾霓裳飜。","歡娛未足燕寇至，弓勁马肥胡語喧。","豳土人遷避夷狄，鼎湖龙去哭軒轅。","從此漂淪落南土，万人死尽一身存。","秋风江上浪無限，暮雨舟中酒一尊。","涸鱼久失风波勢，枯草曾霑雨露恩。","我自秦来君莫问，驪山渭水如荒村。","新豐樹老籠明月，长生殿闇鎖春云。","紅葉紛紛蓋欹瓦，綠苔重重封壞垣。","唯有中官作宮使，每年寒食一开门。"]', '诗', 'shi', '', NULL, '江南遇天寶樂叟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ec1aa75-831a-46ff-873f-98c40ce01e46', '送張山人歸嵩陽', '送張山人归嵩陽', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黃昏慘慘天微雪，修行坊西鼓聲絕。","張生馬瘦衣且單，夜扣柴門與我別。","媿君冒寒來別我，爲君酤酒張燈火。","酒酣火煖與君言，何事入關又出關。","荅云前年偶下山，四十餘月客長安。","長安古來名利地，空手無金行路難。","朝遊九城陌，肥馬輕車欺殺客。","暮宿五侯門，殘茶冷酒愁殺人。","春明門，門前便是嵩山路。","幸有雲泉容此身，明日辭君且歸去。"]', '["黄昏慘慘天微雪，修行坊西鼓声絕。","張生马瘦衣且單，夜扣柴门與我別。","媿君冒寒来別我，爲君酤酒張灯火。","酒酣火煖與君言，何事入关又出关。","荅云前年偶下山，四十餘月客长安。","长安古来名利地，空手無金行路难。","朝游九城陌，肥马轻车欺殺客。","暮宿五侯门，殘茶冷酒愁殺人。","春明门，门前便是嵩山路。","幸有云泉容此身，明日辞君且归去。"]', '诗', 'shi', '', NULL, '送張山人歸嵩陽 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d498e59-1ff8-4f16-8e5f-a33b9bcb6046', '醉後走筆酬劉五主簿長句之贈兼簡張大賈二十四先輩昆季', '醉後走笔酬劉五主簿长句之贈兼簡張大賈二十四先輩昆季', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["劉兄文高行孤立，十五年前名翕習。","是時相遇在符離，我年二十君三十。","得意忘年心迹親，寓居同縣日知聞。","衡門寂莫朝尋我，古寺蕭條暮訪君。","朝來暮去多攜手，窮巷貧居何所有。","秋燈夜寫聯句詩，春雪朝傾煖寒酒。","陴湖綠愛白鷗飛，濉水清憐紅鯉肥。","偶語閑攀芳樹立，相扶醉蹋落花歸。","張賈弟兄同里巷，乘閑數數來相訪。","雨天連宿草堂中，月夜徐行石橋上。","我年漸長忽自驚，鏡中冉冉髭鬚生。","心畏後時同勵志，身牽前事各求名。","問我栖栖何所適，鄉人薦爲鹿鳴客。","二千里別謝交遊，三十韻詩慰行役。","出門可憐唯一身，敝裘瘦馬入咸秦。","鼕鼕街鼓紅塵闇，晚到長安無主人。","二賈二張與余弟，軀車邐迤來相繼。","操詞握賦爲干戈，鋒銳森然勝氣多。","齊入文場同苦戰，五人十載九登科。","二張得雋名居甲，美退爭雄重告捷。","棠棣輝榮竝桂枝，芝蘭芳馥和荆葉。","唯有沅犀屈未伸，握中自謂駭雞珍。","三年不鳴鳴必大，豈獨駭雞當駭人。","元和運啓千年聖，同遇明時余最幸。","始辭祕閣吏王畿，遽列諫垣升禁闈。","蹇步何堪鳴珮玉，衰容不稱著朝衣。","閶闔晨開朝百辟，冕旒不動香煙碧。","步登龍尾上虛空，立去天顏無咫尺。","宮花似雪從乘輿，禁月如霜坐直廬。","身賤每驚隨內宴，才微常媿草天書。","晚松寒竹新昌第，職居密近門多閉。","日暮銀臺下直回，故人到門門暫開。","回頭下馬一相顧，塵土滿衣何處來？","斂手炎涼敘未畢，先說舊山今悔出。","岐陽旅宦少歡娛，江左羇遊費時日。","贈我一篇行路吟，吟之句句披沙金。","歲月徒催白髮貌，泥塗不屈青雲心。","誰會茫茫天地意，短才獲用長才棄。","我隨鵷鷺入煙雲，謬上丹墀爲近臣。","君同鸞鳳棲荆棘，猶著青袍作選人。","惆悵知賢不能薦，徒爲出入蓬萊殿。","月慙諫紙二百張，歲媿俸錢三十萬。","大底浮榮何足道，幾度相逢即身老。","且傾斗酒慰羇愁，重話符離問舊遊。","北巷鄰居幾家去，東林舊院何人住。","武里村花落復開，流溝山色應如故。","感此酬君千字詩，醉中分手又何之。","須知通塞尋常事，莫歎浮沈先後時。","慷慨臨歧重相勉，殷勤別後加餐飯。","君不見買臣衣錦還故鄉，五十身榮未爲晚。"]', '["劉兄文高行孤立，十五年前名翕習。","是时相遇在符離，我年二十君三十。","得意忘年心迹親，寓居同縣日知闻。","衡门寂莫朝尋我，古寺蕭條暮訪君。","朝来暮去多携手，窮巷貧居何所有。","秋灯夜寫聯句诗，春雪朝傾煖寒酒。","陴湖綠愛白鷗飞，濉水清怜紅鯉肥。","偶語闲攀芳樹立，相扶醉蹋落花归。","張賈弟兄同里巷，乘闲數數来相訪。","雨天連宿草堂中，月夜徐行石橋上。","我年漸长忽自驚，镜中冉冉髭鬚生。","心畏後时同勵志，身牽前事各求名。","问我栖栖何所適，乡人薦爲鹿鳴客。","二千里別謝交游，三十韻诗慰行役。","出门可怜唯一身，敝裘瘦马入咸秦。","鼕鼕街鼓紅塵闇，晚到长安無主人。","二賈二張與余弟，軀车邐迤来相繼。","操词握賦爲干戈，鋒銳森然勝氣多。","齊入文場同苦戰，五人十載九登科。","二張得雋名居甲，美退爭雄重告捷。","棠棣輝榮竝桂枝，芝蘭芳馥和荆葉。","唯有沅犀屈未伸，握中自謂駭雞珍。","三年不鳴鳴必大，豈独駭雞當駭人。","元和運啓千年聖，同遇明时余最幸。","始辞祕閣吏王畿，遽列諫垣升禁闈。","蹇步何堪鳴珮玉，衰容不稱著朝衣。","閶闔晨开朝百辟，冕旒不动香煙碧。","步登龙尾上虛空，立去天顏無咫尺。","宮花似雪從乘輿，禁月如霜坐直廬。","身賤每驚隨內宴，才微常媿草天书。","晚松寒竹新昌第，職居密近门多閉。","日暮銀台下直回，故人到门门暫开。","回头下马一相顧，塵土满衣何处来？","斂手炎涼敘未畢，先说旧山今悔出。","岐陽旅宦少歡娛，江左羇游費时日。","贈我一篇行路吟，吟之句句披沙金。","歲月徒催白髮貌，泥塗不屈青云心。","誰會茫茫天地意，短才獲用长才棄。","我隨鵷鷺入煙云，謬上丹墀爲近臣。","君同鸾鳳棲荆棘，猶著青袍作選人。","惆悵知賢不能薦，徒爲出入蓬萊殿。","月慙諫紙二百張，歲媿俸錢三十万。","大底浮榮何足道，幾度相逢即身老。","且傾斗酒慰羇愁，重話符離问旧游。","北巷鄰居幾家去，东林旧院何人住。","武里村花落复开，流溝山色應如故。","感此酬君千字诗，醉中分手又何之。","須知通塞尋常事，莫歎浮沈先後时。","慷慨臨歧重相勉，殷勤別後加餐飯。","君不见買臣衣錦還故乡，五十身榮未爲晚。"]', '诗', 'shi', '', NULL, '醉後走筆酬劉五主簿長句之贈兼簡張大賈二十四先輩昆季 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6d4ea3d-eae6-4187-86b0-573f353a859e', '和錢員外荅盧員外早春獨遊曲江見寄長句', '和錢員外荅盧員外早春独游曲江见寄长句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春來有色闇融融，先到詩情酒思中。","柳岸霏微裛塵雨，杏園澹蕩開花風。","聞君獨遊心鬱鬱，薄晚新晴騎馬出。","醉思詩侶有同年，春歎翰林無暇日。","雲夫首倡寒玉音，蔚章繼和春搜吟。","此時我亦閉門坐，一日風光三處心。"]', '["春来有色闇融融，先到诗情酒思中。","柳岸霏微裛塵雨，杏园澹蕩开花风。","闻君独游心鬱鬱，薄晚新晴騎马出。","醉思诗侶有同年，春歎翰林無暇日。","云夫首倡寒玉音，蔚章繼和春搜吟。","此时我亦閉门坐，一日风光三处心。"]', '诗', 'shi', '', NULL, '和錢員外荅盧員外早春獨遊曲江見寄長句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23f6be13-844f-4db1-bf1d-2011ff467bf1', '東墟晚歇', '东墟晚歇', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["涼風冷露蕭索天，黃蒿紫菊荒涼田。","繞冢秋花少顏色，細蟲小蝶飛飜飜。","中有騰騰獨行者，手拄漁竿不騎馬。","晚從南澗釣魚回，歇此墟中白楊下。","褐衣半故白髮新，人逢知我是何人。","誰言渭浦棲遲客，曾作甘泉侍從臣。"]', '["涼风冷露蕭索天，黄蒿紫菊荒涼田。","繞冢秋花少顏色，細蟲小蝶飞飜飜。","中有腾腾独行者，手拄漁竿不騎马。","晚從南澗釣鱼回，歇此墟中白楊下。","褐衣半故白髮新，人逢知我是何人。","誰言渭浦棲遲客，曾作甘泉侍從臣。"]', '诗', 'shi', '', NULL, '東墟晚歇 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('125c752d-23ff-4ce8-a975-e476c244e3ea', '客中月', '客中月', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["客從江南來，來時月上弦。","悠悠行旅中，三見清光圓。","曉隨殘月行，夕與新月宿。","誰謂月無情，千里遠相逐。","朝發渭水橋，暮入長安陌。","不知今夜月，又作誰家客。"]', '["客從江南来，来时月上弦。","悠悠行旅中，三见清光圓。","晓隨殘月行，夕與新月宿。","誰謂月無情，千里远相逐。","朝發渭水橋，暮入长安陌。","不知今夜月，又作誰家客。"]', '诗', 'shi', '', NULL, '客中月 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a16e1400-1726-48b2-8e22-ba8bb0e9e275', '輓歌詞', '輓歌词', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["丹旐何飛揚，素驂亦悲鳴。","晨光照閭巷，輀車儼欲行。","蕭條九月天，哀輓出重城。","借問送者誰，妻子與弟兄。","蒼蒼上古原，峨峨開新塋。","含酸一慟哭，異口同哀聲。","舊隴轉蕪絕，新墳日羅列。","春風草綠北邙山，此地年年生死別。"]', '["丹旐何飞揚，素驂亦悲鳴。","晨光照閭巷，輀车儼欲行。","蕭條九月天，哀輓出重城。","借问送者誰，妻子與弟兄。","蒼蒼上古原，峨峨开新塋。","含酸一慟哭，異口同哀声。","旧隴轉蕪絕，新墳日羅列。","春风草綠北邙山，此地年年生死別。"]', '诗', 'shi', '', NULL, '輓歌詞 白居易 shi');
